--
-- Name: auto_close_periods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_close_periods() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_today DATE; v_day INT; v_prior DATE; v_year INT; v_month INT; v_count INT := 0; v_row RECORD;
BEGIN
  v_today := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::DATE;
  v_day := EXTRACT(DAY FROM v_today)::INT;
  v_prior := (date_trunc('month', v_today) - INTERVAL '1 month')::DATE;
  v_year := EXTRACT(YEAR FROM v_prior)::INT;
  v_month := EXTRACT(MONTH FROM v_prior)::INT;
  IF v_day < 5 THEN RETURN 0; END IF;
  FOR v_row IN SELECT id FROM public.tenants LOOP
    INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at)
    VALUES (v_row.id, v_year, v_month, now())
    ON CONFLICT (tenant_id, year, month) DO UPDATE
      SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at);
    v_count := v_count + 1;
  END LOOP;
  IF v_day >= 15 THEN
    FOR v_row IN SELECT id FROM public.tenants LOOP
      UPDATE public.accounting_periods SET hard_closed_at = COALESCE(hard_closed_at, now())
       WHERE tenant_id = v_row.id AND year = v_year AND month = v_month;
    END LOOP;
  END IF;
  RETURN v_count;
END; $$;


--
-- Name: FUNCTION auto_close_periods(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_close_periods() IS 'Daily automation — day 5+ soft close, day 15+ hard close. Idempotent.';


--
-- Name: branch_manager_approve_consumption_report(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.branch_manager_approve_consumption_report(p_tenant_id bigint, p_report_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_report record;
  v_line record;
  v_issue_id bigint;
  v_issue_number text;
  v_source_location_id bigint;
  v_current_quantity numeric(15,3);
  v_wac numeric(15,2);
  v_line_count integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_tenant IS NULL OR v_tenant <> p_tenant_id THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT r.*
  INTO v_report
  FROM public.attendance_consumption_reports r
  WHERE r.id = p_report_id
    AND r.tenant_id = p_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'consumption_report_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_report.branch_id, 'hr:approve_checkout') THEN
    RAISE EXCEPTION 'forbidden_checkout_approval' USING ERRCODE = '42501';
  END IF;

  IF v_report.status IN ('approved', 'applied') THEN
    RETURN jsonb_build_object(
      'ok', true,
      'report_id', p_report_id,
      'stock_issue_id', v_report.stock_issue_id,
      'status', v_report.status
    );
  END IF;

  IF v_report.status <> 'submitted' THEN
    RAISE EXCEPTION 'consumption_report_not_submitted' USING ERRCODE = '22023';
  END IF;

  SELECT count(*)
  INTO v_line_count
  FROM public.attendance_consumption_report_lines
  WHERE tenant_id = p_tenant_id
    AND report_id = p_report_id;

  IF v_report.no_consumption = true AND v_line_count = 0 THEN
    UPDATE public.attendance_consumption_reports
    SET status = 'approved',
        reviewed_by = v_uid,
        reviewed_at = now(),
        review_note = NULL
    WHERE id = p_report_id
      AND tenant_id = p_tenant_id;

    RETURN jsonb_build_object(
      'ok', true,
      'report_id', p_report_id,
      'stock_issue_id', NULL,
      'no_consumption', true,
      'line_count', 0
    );
  END IF;

  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'consumption_lines_required' USING ERRCODE = '22023';
  END IF;

  SELECT il.id
  INTO v_source_location_id
  FROM public.inventory_locations il
  WHERE il.tenant_id = p_tenant_id
    AND il.branch_id = v_report.branch_id
    AND il.is_active = true
    AND (
      il.is_default_issue = true
      OR il.location_kind = 'warehouse'
    )
  ORDER BY
    il.is_default_issue DESC,
    CASE il.location_kind WHEN 'warehouse' THEN 0 ELSE 1 END,
    il.sort_order NULLS LAST,
    il.id
  LIMIT 1;

  IF v_source_location_id IS NULL THEN
    RAISE EXCEPTION 'consumption_location_missing' USING ERRCODE = '23502';
  END IF;

  v_issue_number := 'THB-' || p_report_id::text;

  INSERT INTO public.stock_issues (
    tenant_id,
    branch_id,
    issue_number,
    issue_type,
    status,
    notes,
    issued_at,
    created_by,
    source_location_id,
    target_location_id,
    approval_status,
    approved_by,
    approved_at,
    source_type,
    source_ref
  )
  VALUES (
    p_tenant_id,
    v_report.branch_id,
    v_issue_number,
    'consumption',
    'draft',
    COALESCE(v_report.note, 'Tiêu hao bếp trong ngày'),
    now(),
    v_uid,
    v_source_location_id,
    NULL,
    'approved',
    v_uid,
    now(),
    'hrm_consumption',
    jsonb_build_object(
      'source', 'attendance_consumption_report',
      'source_label', 'HRM - Tiêu hao bếp trong ngày',
      'report_id', p_report_id,
      'attendance_record_id', v_report.attendance_record_id,
      'employee_id', v_report.employee_id,
      'branch_id', v_report.branch_id,
      'reviewed_by', v_uid,
      'reviewed_at', now()
    )
  )
  RETURNING id INTO v_issue_id;

  FOR v_line IN
    SELECT l.*, i.name AS ingredient_name
    FROM public.attendance_consumption_report_lines l
    JOIN public.ingredients i
      ON i.id = l.ingredient_id
     AND i.tenant_id = l.tenant_id
     AND i.is_active = true
    WHERE l.tenant_id = p_tenant_id
      AND l.report_id = p_report_id
    ORDER BY l.sort_order, l.id
  LOOP
    SELECT sl.current_quantity, sl.avg_unit_cost
    INTO v_current_quantity, v_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id = p_tenant_id
      AND sl.branch_id = v_report.branch_id
      AND sl.location_id = v_source_location_id
      AND sl.ingredient_id = v_line.ingredient_id
    FOR UPDATE;

    IF NOT FOUND OR v_wac IS NULL THEN
      RAISE EXCEPTION 'wac_not_ready_for_%', v_line.ingredient_id
        USING ERRCODE = '22023';
    END IF;

    IF v_current_quantity < v_line.quantity THEN
      RAISE EXCEPTION 'insufficient_stock_for_%', v_line.ingredient_id
        USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.stock_issue_items (
      tenant_id,
      issue_id,
      ingredient_id,
      quantity,
      unit,
      unit_cost,
      reason
    )
    VALUES (
      p_tenant_id,
      v_issue_id,
      v_line.ingredient_id,
      v_line.quantity,
      v_line.unit,
      v_wac,
      v_line.note
    );

    INSERT INTO public.stock_movements (
      tenant_id,
      branch_id,
      ingredient_id,
      type,
      movement_subtype,
      quantity_change,
      unit_cost,
      reason,
      created_by,
      issue_id,
      location_id
    )
    VALUES (
      p_tenant_id,
      v_report.branch_id,
      v_line.ingredient_id,
      'consumption',
      'sale_consumption',
      -v_line.quantity,
      v_wac,
      COALESCE(v_line.note, v_report.note, 'Tiêu hao bếp trong ngày'),
      v_uid,
      v_issue_id,
      v_source_location_id
    );
  END LOOP;

  UPDATE public.stock_issues
  SET status = 'confirmed',
      updated_at = now()
  WHERE id = v_issue_id
    AND tenant_id = p_tenant_id;

  UPDATE public.attendance_consumption_reports
  SET status = 'applied',
      reviewed_by = v_uid,
      reviewed_at = now(),
      review_note = NULL,
      stock_issue_id = v_issue_id
  WHERE id = p_report_id
    AND tenant_id = p_tenant_id;

  RETURN jsonb_build_object(
    'ok', true,
    'report_id', p_report_id,
    'stock_issue_id', v_issue_id,
    'line_count', v_line_count
  );
END;
$$;


--
-- Name: FUNCTION branch_manager_approve_consumption_report(p_tenant_id bigint, p_report_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.branch_manager_approve_consumption_report(p_tenant_id bigint, p_report_id bigint) IS 'Checkout approver approves a submitted consumption report and atomically posts Inventory consumption movements.';


--
-- Name: branch_manager_approve_employee_clock_out(bigint, bigint, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.branch_manager_approve_employee_clock_out(p_tenant_id bigint, p_branch_id bigint, p_attendance_id bigint, p_approved_by uuid, p_note text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_record_branch_id bigint;
  v_requester_profile_id uuid;
  v_requester_role text;
  v_approver_branch_id bigint;
  v_approver_role text;
  v_requested_at timestamptz;
  v_check_out timestamptz;
BEGIN
  SELECT
    ar.branch_id,
    e.profile_id,
    COALESCE(ar.checkout_requested_by_role, private.staff_role_from_position_code(po.code), 'office'),
    ar.checkout_requested_at
  INTO
    v_record_branch_id,
    v_requester_profile_id,
    v_requester_role,
    v_requested_at
  FROM public.attendance_records ar
  JOIN public.employees e
    ON e.id = ar.employee_id
   AND e.tenant_id = ar.tenant_id
  LEFT JOIN public.profiles p
    ON p.id = e.profile_id
   AND p.tenant_id = e.tenant_id
  LEFT JOIN public.positions po
    ON po.id = p.position_id
   AND po.tenant_id = p.tenant_id
  WHERE ar.id = p_attendance_id
    AND ar.tenant_id = p_tenant_id
    AND ar.branch_id = p_branch_id
    AND ar.check_out IS NULL
    AND ar.checkout_requested_at IS NOT NULL
  FOR UPDATE OF ar;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'checkout_request_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_requester_profile_id = p_approved_by THEN
    RAISE EXCEPTION 'cannot_approve_own_checkout' USING ERRCODE = '42501';
  END IF;

  SELECT
    p.branch_id,
    private.staff_role_from_position_code(po.code)
  INTO v_approver_branch_id, v_approver_role
  FROM public.profiles p
  JOIN public.positions po
    ON po.id = p.position_id
   AND po.tenant_id = p.tenant_id
  WHERE p.id = p_approved_by
    AND p.tenant_id = p_tenant_id
    AND COALESCE(p.is_active, true) = true;

  IF NOT FOUND OR v_approver_role IS NULL THEN
    RAISE EXCEPTION 'checkout_approver_not_found' USING ERRCODE = '42501';
  END IF;

  v_requester_role := COALESCE(v_requester_role, 'office');

  IF v_requester_role = 'branch_manager' THEN
    IF v_approver_role NOT IN ('owner') THEN
      RAISE EXCEPTION 'checkout_requires_upper_manager' USING ERRCODE = '42501';
    END IF;
  ELSIF v_approver_role = 'branch_manager' THEN
    IF v_approver_branch_id IS DISTINCT FROM p_branch_id THEN
      RAISE EXCEPTION 'checkout_approver_wrong_branch' USING ERRCODE = '42501';
    END IF;

    IF v_requester_role NOT IN ('cashier', 'waiter', 'chef') THEN
      RAISE EXCEPTION 'branch_manager_can_only_approve_branch_staff' USING ERRCODE = '42501';
    END IF;
  ELSIF v_approver_role NOT IN ('owner') THEN
    RAISE EXCEPTION 'checkout_approver_not_allowed' USING ERRCODE = '42501';
  END IF;

  UPDATE public.attendance_records
  SET
    check_out = v_requested_at,
    check_out_code_verified = false,
    checkout_approved_at = now(),
    checkout_approved_by = p_approved_by,
    checkout_approval_note = NULLIF(btrim(p_note), ''),
    updated_at = now()
  WHERE id = p_attendance_id
    AND tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND check_out IS NULL
  RETURNING check_out INTO v_check_out;

  RETURN v_check_out;
END;
$$;


--
-- Name: branch_manager_request_consumption_adjustment(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.branch_manager_request_consumption_adjustment(p_tenant_id bigint, p_report_id bigint, p_review_note text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_report record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_tenant IS NULL OR v_tenant <> p_tenant_id THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(btrim(COALESCE(p_review_note, '')), '') IS NULL THEN
    RAISE EXCEPTION 'review_note_required' USING ERRCODE = '22023';
  END IF;

  SELECT r.*, ar.id AS attendance_id
  INTO v_report
  FROM public.attendance_consumption_reports r
  JOIN public.attendance_records ar
    ON ar.id = r.attendance_record_id
   AND ar.tenant_id = r.tenant_id
  WHERE r.id = p_report_id
    AND r.tenant_id = p_tenant_id
  FOR UPDATE OF r, ar;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'consumption_report_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_report.branch_id, 'hr:approve_checkout') THEN
    RAISE EXCEPTION 'forbidden_checkout_approval' USING ERRCODE = '42501';
  END IF;

  IF v_report.status NOT IN ('submitted', 'needs_changes') THEN
    RAISE EXCEPTION 'consumption_report_not_reviewable' USING ERRCODE = '22023';
  END IF;

  UPDATE public.attendance_consumption_reports
  SET status = 'needs_changes',
      reviewed_by = v_uid,
      reviewed_at = now(),
      review_note = NULLIF(btrim(p_review_note), '')
  WHERE id = p_report_id
    AND tenant_id = p_tenant_id;

  UPDATE public.attendance_records
  SET checkout_requested_at = NULL,
      checkout_requested_by_role = NULL,
      checkout_approval_target_roles = ARRAY[]::text[],
      updated_at = now()
  WHERE id = v_report.attendance_id
    AND tenant_id = p_tenant_id
    AND check_out IS NULL;

  UPDATE public.attendance_checklist_items
  SET is_done = false,
      completed_at = NULL
  WHERE tenant_id = p_tenant_id
    AND attendance_record_id = v_report.attendance_id
    AND task_kind = 'consumption_report';

  RETURN p_report_id;
END;
$$;


--
-- Name: FUNCTION branch_manager_request_consumption_adjustment(p_tenant_id bigint, p_report_id bigint, p_review_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.branch_manager_request_consumption_adjustment(p_tenant_id bigint, p_report_id bigint, p_review_note text) IS 'Checkout approver requests correction, reopens the consumption checklist item, and clears pending checkout for employee resubmission.';


--
-- Name: bump_kds_ticket(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_kds_ticket(p_ticket_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket    RECORD;
  v_new_status TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('kds:mark_ready') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT id, tenant_id, branch_id, station_id, order_id, status
  INTO v_ticket
  FROM public.kds_tickets
  WHERE id = p_ticket_id
    AND tenant_id = public.auth_tenant_id()
    AND public.can_access_branch(branch_id)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_ticket.status = 'pending' THEN
    v_new_status := 'preparing';
  ELSIF v_ticket.status = 'preparing' THEN
    v_new_status := 'ready';
  ELSE
    RAISE EXCEPTION 'Ticket cannot be bumped from status %', v_ticket.status
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.kds_tickets
  SET status    = v_new_status,
      bumped_at = now(),
      bumped_by = auth.uid()
  WHERE id = p_ticket_id;

  IF v_new_status = 'ready' THEN
    PERFORM public.check_order_ready(v_ticket.order_id);
  END IF;

  RETURN v_new_status;
END;
$$;


--
-- Name: can_access_branch(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_branch(p_branch_id bigint) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN public.auth_role() IN ('owner') THEN true
    ELSE p_branch_id = public.auth_branch_id()
  END;
$$;


--
-- Name: FUNCTION can_access_branch(p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_access_branch(p_branch_id bigint) IS 'Branch access helper after intermediate scope removal. Tenant-level roles access all branches; other roles are limited to their JWT branch.';


--
-- Name: cancel_leave_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_leave_request(p_request_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_user_id   UUID   := auth.uid();
  v_request   public.leave_requests%ROWTYPE;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'cancel_leave_request: missing auth context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_request
  FROM public.leave_requests
  WHERE id = p_request_id
    AND tenant_id = v_tenant_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'cancel_leave_request: request not found'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = v_request.employee_id
      AND e.profile_id = v_user_id
      AND e.tenant_id = v_tenant_id
  ) THEN
    RAISE EXCEPTION 'cancel_leave_request: not the request owner'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'cancel_leave_request: request is %, not pending', v_request.status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.leave_requests
  SET status = 'cancelled',
      reviewed_by = v_user_id,
      reviewed_at = now()
  WHERE id = p_request_id;

  PERFORM public.log_audit(
    'cancel'::TEXT,
    'leave_request'::TEXT,
    p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'cancelled')
  );
END;
$$;


--
-- Name: FUNCTION cancel_leave_request(p_request_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_leave_request(p_request_id bigint) IS 'Employee cancels own pending leave request. Caller must own the underlying employee row.';


--
-- Name: cancel_order(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_order(p_order_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid              UUID;
  v_prof_tenant      BIGINT;
  v_prof_branch      BIGINT;
  v_prof_role        TEXT;
  v_order            RECORD;
  v_item_id          BIGINT;
  v_print_res        JSONB;
  v_tickets_enqueued INT := 0;
  v_tickets_skipped  INT := 0;
  v_skip_reasons     TEXT[] := ARRAY[]::TEXT[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT id, tenant_id, branch_id, status, table_id, order_type,
         service_charge, discount_type, discount_value
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = p_reason,
      updated_at = now()
  WHERE order_id = p_order_id AND status <> 'cancelled';

  UPDATE public.kds_tickets
  SET status = 'cancelled', updated_at = now()
  WHERE order_id = p_order_id AND tenant_id = v_order.tenant_id;

  UPDATE public.orders
  SET
    status          = 'cancelled',
    subtotal        = 0,
    discount_type   = NULL,
    discount_value  = NULL,
    discount_note   = NULL,
    discount_amount = 0,
    total_amount    = 0 + COALESCE(service_charge, 0),
    updated_at      = now()
  WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id, p_order_id, v_order.status, 'cancelled', v_uid, p_reason
  );

  FOR v_item_id IN
    SELECT id FROM public.order_items
    WHERE order_id = p_order_id
      AND sent_to_kitchen_at IS NOT NULL
    ORDER BY id
  LOOP
    BEGIN
      v_print_res := public.enqueue_cancel_ticket_print(v_item_id, p_reason);
      IF (v_print_res ? 'skipped') AND (v_print_res->>'skipped')::boolean THEN
        v_tickets_skipped := v_tickets_skipped + 1;
        v_skip_reasons := v_skip_reasons || COALESCE(v_print_res->>'reason', 'unknown');
      ELSE
        v_tickets_enqueued := v_tickets_enqueued + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_tickets_skipped := v_tickets_skipped + 1;
      v_skip_reasons := v_skip_reasons || ('error:' || SQLERRM);
      RAISE NOTICE '[cancel_order] cancel-ticket enqueue raised for item %: %',
        v_item_id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'order_id',         p_order_id,
    'status',           'cancelled',
    'cancel_tickets',   v_tickets_enqueued,
    'cancel_skipped',   v_tickets_skipped,
    'skip_reasons',     to_jsonb(v_skip_reasons)
  );
END;
$$;


--
-- Name: cancel_pending_payment(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_pending_payment(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_payment RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'permission denied: pos:use' USING ERRCODE = '42501';
  END IF;

  SELECT id, order_id, status
  INTO v_payment
  FROM public.payments
  WHERE id        = p_payment_id
    AND tenant_id = p_tenant_id
    AND branch_id = p_branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0001';
  END IF;

  IF v_payment.status <> 'pending' THEN
    RAISE EXCEPTION 'payment_not_pending' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.payments
  SET status     = 'failed',
      updated_at = now()
  WHERE id = p_payment_id;

  UPDATE public.orders
  SET payment_status = 'unpaid',
      payment_method = NULL,
      updated_at     = now()
  WHERE id             = v_payment.order_id
    AND payment_status <> 'paid';
END;
$$;


--
-- Name: FUNCTION cancel_pending_payment(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_pending_payment(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint) IS 'Cancels a pending MoMo payment and resets order payment fields. Tenant/branch params guard against IDOR.';


--
-- Name: cancel_production_order(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_production_order(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant BIGINT := public.auth_tenant_id();
  v_order  RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission_any('inventory:production_confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_order FROM public.production_orders
  WHERE id = p_order_id AND tenant_id = v_tenant FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.has_permission(v_order.branch_id, 'inventory:production_confirm') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF v_order.status <> 'draft' THEN
    RAISE EXCEPTION 'production_order_not_draft' USING ERRCODE = '22023';
  END IF;

  UPDATE public.production_orders
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_order_id AND tenant_id = v_tenant;

  RETURN jsonb_build_object('production_order_id', p_order_id, 'status', 'cancelled');
END;
$$;


--
-- Name: check_branch_required(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_branch_required() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_access_bucket text;
BEGIN
  SELECT private.staff_role_from_position_code(po.code)
  INTO v_access_bucket
  FROM public.positions po
  WHERE po.id = NEW.position_id
    AND po.tenant_id = NEW.tenant_id;

  IF v_access_bucket IN (
    'cashier',
    'waiter',
    'chef',
    'branch_manager',
    'warehouse_manager',
    'production_manager'
  )
  AND NEW.branch_id IS NULL THEN
    RAISE EXCEPTION 'branch_required_for_operational_position: position_id=%', NEW.position_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION check_branch_required(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_branch_required() IS 'Profiles branch-required guard. SECURITY DEFINER because it uses the private staff-role mapper.';


--
-- Name: check_menu_item_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_menu_item_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.menu_categories
    WHERE id = NEW.category_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'category does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_order_ready(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_order_ready(p_order_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pending_count INT;
  v_current_status TEXT;
BEGIN
  SELECT status INTO v_current_status
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = public.auth_tenant_id()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_current_status IN ('ready', 'served', 'completed', 'cancelled') THEN
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_pending_count
  FROM public.kds_tickets
  WHERE order_id = p_order_id
    AND tenant_id = public.auth_tenant_id()
    AND status NOT IN ('ready', 'served', 'cancelled');

  IF v_pending_count = 0 THEN
    UPDATE public.orders
    SET status = 'ready',
        updated_at = now()
    WHERE id = p_order_id
      AND tenant_id = public.auth_tenant_id();

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by
    )
    SELECT tenant_id, id, v_current_status, 'ready', auth.uid()
    FROM public.orders
    WHERE id = p_order_id
      AND tenant_id = public.auth_tenant_id();
  END IF;
END;
$$;


--
-- Name: check_sides_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_sides_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.main_item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'main item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.side_item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'side item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: check_table_zone_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_table_zone_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.zone_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.branch_zones
    WHERE id = NEW.zone_id
      AND tenant_id = NEW.tenant_id
      AND branch_id = NEW.branch_id
  ) THEN
    RAISE EXCEPTION 'zone does not belong to tenant/branch'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_variant_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_variant_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.menu_items
    WHERE id = NEW.item_id AND tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'item does not belong to tenant'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: claim_print_job(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_print_job(p_job_id bigint, p_agent_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated INT;
  v_is_service BOOLEAN := (auth.role() = 'service_role');
  v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  UPDATE public.print_jobs
    SET status = 'processing',
        claimed_by_agent = p_agent_id,
        claimed_at = now(),
        attempts = attempts + 1
    WHERE id = p_job_id
      AND status = 'pending'
      AND (v_is_service OR tenant_id = v_tenant);
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated = 1;
END;
$$;


--
-- Name: cleanup_abandoned_payments(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_abandoned_payments(p_threshold interval DEFAULT '24:00:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE public.payments
  SET
    status = 'failed',
    provider_data = COALESCE(provider_data, '{}'::jsonb) || jsonb_build_object(
      'cleanup_reason', 'abandoned',
      'cleanup_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'cleanup_threshold', extract(epoch FROM p_threshold)::int
    ),
    updated_at = now()
  WHERE status = 'pending'
    AND created_at < now() - p_threshold;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION cleanup_abandoned_payments(p_threshold interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_abandoned_payments(p_threshold interval) IS 'POS payment janitor: marks pending rows older than p_threshold (default 24h) as failed and stamps cleanup metadata into provider_data. Cron-scheduled hourly; safe to call manually for ad-hoc cleanup.';


--
-- Name: cleanup_kds_tickets_as_system(timestamp with time zone, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_kds_tickets_as_system(p_older_than timestamp with time zone, p_reset_before_local_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted_total INT := 0;
  v_by_status JSONB := '{}'::jsonb;
  v_by_branch JSONB := '[]'::jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  IF p_older_than IS NULL AND p_reset_before_local_date IS NULL THEN
    RAISE EXCEPTION 'cleanup_cutoff_required' USING ERRCODE = '22023';
  END IF;

  WITH candidates AS (
    SELECT
      kt.id,
      kt.tenant_id,
      kt.branch_id,
      kt.status
    FROM public.kds_tickets kt
    JOIN public.branches b
      ON b.id = kt.branch_id
     AND b.tenant_id = kt.tenant_id
    LEFT JOIN public.kitchen_send_batches ksb
      ON ksb.id = kt.kitchen_send_batch_id
     AND ksb.tenant_id = kt.tenant_id
    WHERE kt.status IN ('pending', 'preparing', 'ready')
      AND b.branch_kind = 'branch'
      AND (
        (
          p_older_than IS NOT NULL
          AND COALESCE(ksb.created_at, kt.created_at) < p_older_than
        )
        OR (
          p_reset_before_local_date IS NOT NULL
          AND (
            COALESCE(ksb.created_at, kt.created_at)
              AT TIME ZONE 'Asia/Ho_Chi_Minh'
          )::date < p_reset_before_local_date
        )
      )
  ),
  deleted AS (
    DELETE FROM public.kds_tickets kt
    USING candidates c
    WHERE kt.id = c.id
    RETURNING kt.tenant_id, kt.branch_id, kt.status
  ),
  status_counts AS (
    SELECT status, count(*)::int AS deleted_count
    FROM deleted
    GROUP BY status
  ),
  branch_counts AS (
    SELECT tenant_id, branch_id, count(*)::int AS deleted_count
    FROM deleted
    GROUP BY tenant_id, branch_id
  )
  SELECT
    COALESCE((SELECT count(*)::int FROM deleted), 0),
    COALESCE(
      (SELECT jsonb_object_agg(status, deleted_count) FROM status_counts),
      '{}'::jsonb
    ),
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'tenant_id', tenant_id,
            'branch_id', branch_id,
            'deleted_count', deleted_count
          )
          ORDER BY tenant_id, branch_id
        )
        FROM branch_counts
      ),
      '[]'::jsonb
    )
  INTO v_deleted_total, v_by_status, v_by_branch;

  RETURN jsonb_build_object(
    'deleted_total', v_deleted_total,
    'by_status', v_by_status,
    'by_branch', v_by_branch,
    'older_than', p_older_than,
    'reset_before_local_date', p_reset_before_local_date
  );
END;
$$;


--
-- Name: FUNCTION cleanup_kds_tickets_as_system(p_older_than timestamp with time zone, p_reset_before_local_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_kds_tickets_as_system(p_older_than timestamp with time zone, p_reset_before_local_date date) IS 'Service-role-only KDS board cleanup. Deletes active queue tickets older than the cutoff or before the current Asia/Ho_Chi_Minh local date; does not mutate orders, order_items, kitchen batches, or counters.';


--
-- Name: clear_branch_menu_daily_limit(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_role      TEXT   := public.auth_role();
  v_branch    BIGINT := public.auth_branch_id();
  v_today     DATE   := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_deleted   INT;
BEGIN
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF v_role NOT IN ('owner',
                    'branch_manager', 'cashier', 'chef') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('branch_manager', 'cashier', 'chef')
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.branch_menu_item_daily_limits
   WHERE tenant_id = v_tenant_id
     AND branch_id = p_branch_id
     AND menu_item_id = p_menu_item_id
     AND limit_date = v_today;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object('deleted', v_deleted);
END;
$$;


--
-- Name: clear_order_discount(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_order_discount(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order RECORD;
  v_updated_order RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'waiter')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status,
         o.discount_amount, o.order_discount_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.orders
     SET discount_type  = NULL,
         discount_value = NULL,
         discount_note  = NULL,
         updated_at     = now()
   WHERE id = p_order_id
   RETURNING order_discount_amount, item_discount_amount,
             discount_amount, total_amount
   INTO v_updated_order;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_order.tenant_id, p_order_id, v_order.status, v_order.status, v_uid,
    'discount_cleared (was '
      || COALESCE(v_order.order_discount_amount::TEXT, '0') || 'đ order-level)'
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'order_discount_amount', v_updated_order.order_discount_amount,
    'item_discount_amount', v_updated_order.item_discount_amount,
    'total_discount_amount', v_updated_order.discount_amount,
    'total_amount', v_updated_order.total_amount
  );
END;
$$;


--
-- Name: FUNCTION clear_order_discount(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_order_discount(p_order_id bigint) IS 'Clear order-level discount only; item-level discounts remain active. Total discount is normalized by triggers.';


--
-- Name: clear_order_item_discount(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_order_item_discount(p_order_item_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_row RECORD;
  v_reason_trim TEXT;
  v_order_totals RECORD;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  v_reason_trim := COALESCE(trim(p_reason), '');
  IF length(v_reason_trim) < 3 THEN
    RAISE EXCEPTION 'discount_note_required' USING ERRCODE = '22023';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'waiter')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT oi.id AS order_item_id, oi.order_id, oi.tenant_id, oi.status AS item_status,
         oi.discount_amount AS old_discount_amount,
         o.branch_id, o.status AS order_status, o.payment_status
  INTO v_row
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id AND o.tenant_id = oi.tenant_id
  WHERE oi.id = p_order_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_row.order_id);

  SELECT oi.id AS order_item_id, oi.order_id, oi.tenant_id, oi.status AS item_status,
         oi.discount_amount AS old_discount_amount,
         o.branch_id, o.status AS order_status, o.payment_status
  INTO v_row
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id AND o.tenant_id = oi.tenant_id
  WHERE oi.id = p_order_item_id
  FOR UPDATE OF oi, o;

  IF v_row.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_row.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_row.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_row.order_status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_row.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
     SET discount_type = NULL,
         discount_value = NULL,
         discount_note = NULL,
         updated_at = now()
   WHERE id = p_order_item_id;

  SELECT discount_amount, item_discount_amount, order_discount_amount, total_amount
  INTO v_order_totals
  FROM public.orders
  WHERE id = v_row.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_row.tenant_id, v_row.order_id, v_row.order_status, v_row.order_status, v_uid,
    'item_discount_cleared: item ' || p_order_item_id::TEXT
      || ' (was ' || COALESCE(v_row.old_discount_amount::TEXT, '0') || 'đ)'
      || ' :: ' || v_reason_trim
  );

  RETURN jsonb_build_object(
    'order_id', v_row.order_id,
    'order_item_id', p_order_item_id,
    'order_discount_amount', v_order_totals.order_discount_amount,
    'item_discount_amount', v_order_totals.item_discount_amount,
    'total_discount_amount', v_order_totals.discount_amount,
    'total_amount', v_order_totals.total_amount
  );
END;
$$;


--
-- Name: FUNCTION clear_order_item_discount(p_order_item_id bigint, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_order_item_discount(p_order_item_id bigint, p_reason text) IS 'Clear item-level discount with required reason. Blocks paid/terminal orders. Order total is normalized by triggers.';


--
-- Name: close_period_hard(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_period_hard(p_tenant_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'cross-tenant close forbidden' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at, hard_closed_at, closed_by)
  VALUES (p_tenant_id, p_year, p_month, now(), now(), v_uid)
  ON CONFLICT (tenant_id, year, month) DO UPDATE
    SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at),
        hard_closed_at = COALESCE(public.accounting_periods.hard_closed_at, EXCLUDED.hard_closed_at),
        closed_by = EXCLUDED.closed_by;
END; $$;


--
-- Name: close_period_soft(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_period_soft(p_tenant_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'cross-tenant close forbidden' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.accounting_periods (tenant_id, year, month, soft_closed_at, closed_by)
  VALUES (p_tenant_id, p_year, p_month, now(), v_uid)
  ON CONFLICT (tenant_id, year, month) DO UPDATE
    SET soft_closed_at = COALESCE(public.accounting_periods.soft_closed_at, EXCLUDED.soft_closed_at),
        closed_by = COALESCE(public.accounting_periods.closed_by, EXCLUDED.closed_by);
END; $$;


--
-- Name: close_pos_session(bigint, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_pos_session(p_session_id bigint, p_closing_cash numeric, p_note text DEFAULT NULL::text, p_variance_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session RECORD;
  v_paid_count INT;
  v_unpaid_count INT;
  v_cash_revenue NUMERIC(15,2);
  v_noncash_revenue NUMERIC(15,2);
  v_expected_cash NUMERIC(15,2);
  v_cash_difference NUMERIC(15,2);
  v_threshold NUMERIC(15,2);
  v_closed_by UUID;
  v_variance_trim TEXT;
BEGIN
  IF p_closing_cash IS NULL OR p_closing_cash < 0 THEN
    RAISE EXCEPTION 'closing_cash must be non-negative' USING ERRCODE = '22023';
  END IF;

  v_closed_by := auth.uid();
  IF v_closed_by IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, opening_cash, opened_at, status
  INTO v_session
  FROM public.pos_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_session.status <> 'open' THEN
    RAISE EXCEPTION 'session_already_closed' USING ERRCODE = 'P0001';
  END IF;

  -- expected_cash = opening_cash + cash-only paid revenue.
  -- VietQR/MoMo settle to bank, không vào két (POS-CLOSE-SHIFT-CASH-ONLY-EXPECTED).
  -- Unpaid orders carry forward to next session (D1).
  SELECT
    COUNT(*) FILTER (WHERE payment_status = 'paid'),
    COUNT(*) FILTER (WHERE payment_status <> 'paid'),
    COALESCE(SUM(total_amount) FILTER (
      WHERE payment_status = 'paid' AND payment_method = 'cash'
    ), 0),
    COALESCE(SUM(total_amount) FILTER (
      WHERE payment_status = 'paid'
        AND (payment_method IS NULL OR payment_method <> 'cash')
    ), 0)
  INTO v_paid_count, v_unpaid_count, v_cash_revenue, v_noncash_revenue
  FROM public.orders
  WHERE pos_session_id = p_session_id
    AND status NOT IN ('cancelled');

  v_expected_cash := v_session.opening_cash + v_cash_revenue;
  v_cash_difference := p_closing_cash - v_expected_cash;
  v_threshold := GREATEST(50000::NUMERIC, ROUND(v_expected_cash * 0.005, 2));

  -- D8 (2026-04-27): KHÔNG block close khi |diff| > threshold.
  -- Variance > threshold → trigger notify_pos_shift_variance gửi alert
  -- cho manager (xem trigger AFTER UPDATE phía dưới).
  --
  -- variance_approval_note vẫn được record nếu caller truyền (audit
  -- optional). Không validate độ dài, không gate quyền — UI mới đã bỏ
  -- ô input này. Giữ tham số để backward-compat với client cũ chưa update.
  v_variance_trim := NULLIF(btrim(COALESCE(p_variance_note, '')), '');

  UPDATE public.pos_sessions
  SET
    status = 'closed',
    closed_at = now(),
    closed_by = v_closed_by,
    closing_cash = p_closing_cash,
    expected_cash = v_expected_cash,
    cash_difference = v_cash_difference,
    note = p_note,
    variance_approval_note = v_variance_trim,
    -- variance_approver_user_id = NULL (D8 retired approval flow)
    variance_approver_user_id = NULL
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'session_id',         p_session_id,
    'opening_cash',       v_session.opening_cash,
    'closing_cash',       p_closing_cash,
    'expected_cash',      v_expected_cash,
    'cash_revenue',       v_cash_revenue,
    'noncash_revenue',    v_noncash_revenue,
    'cash_difference',    v_cash_difference,
    'variance_threshold', v_threshold,
    'variance_breached',  abs(v_cash_difference) > v_threshold,
    'order_count',        v_paid_count + v_unpaid_count,
    'paid_order_count',   v_paid_count,
    'unpaid_order_count', v_unpaid_count,
    'opened_at',          v_session.opened_at,
    'closed_at',          now()
  );
END;
$$;


--
-- Name: FUNCTION close_pos_session(p_session_id bigint, p_closing_cash numeric, p_note text, p_variance_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.close_pos_session(p_session_id bigint, p_closing_cash numeric, p_note text, p_variance_note text) IS 'Close cashier session — KHÔNG block khi variance vượt ngưỡng (D8 2026-04-27). Variance breach trigger notification về manager qua trg_notify_pos_shift_variance. expected_cash = opening + SUM(paid AND payment_method=cash). Unpaid orders carry forward to next session (D1). JSONB result thêm variance_breached flag để UI hiện toast "đã gửi alert".';


--
-- Name: close_recount_round(bigint, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_recount_round(p_session_id bigint, p_round_no smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD; v_need INT := 0; v_final INT := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_recount') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_round_no <> v_ss.current_round THEN RAISE EXCEPTION 'round % does not match current_round %', p_round_no, v_ss.current_round USING ERRCODE = '22023'; END IF;

  WITH latest AS (
    SELECT sl.id, sl.ingredient_id, sl.counted_quantity, sl.system_quantity, sl.abc_class,
      COALESCE(sl.counted_quantity, 0) - COALESCE(sl.system_quantity, 0) AS delta,
      CASE WHEN sl.system_quantity IS NULL OR sl.system_quantity = 0 THEN NULL
           ELSE ABS(COALESCE(sl.counted_quantity, 0) - sl.system_quantity) / sl.system_quantity END AS pct
    FROM public.stocktake_lines sl WHERE sl.session_id = p_session_id AND sl.round_no = p_round_no
  ),
  decided AS (
    SELECT l.*,
      CASE WHEN l.counted_quantity IS NULL THEN false
           WHEN l.abc_class = 'A' THEN
                COALESCE(l.pct, 0) > v_ss.variance_threshold_pct_class_a / 100.0
             OR ABS(l.delta) > v_ss.variance_threshold_vnd_class_a / GREATEST((SELECT avg_unit_cost FROM public.stock_levels WHERE ingredient_id = l.ingredient_id AND branch_id = v_ss.branch_id LIMIT 1), 1)
           ELSE
                COALESCE(l.pct, 0) > v_ss.variance_threshold_pct / 100.0
             OR ABS(l.delta) > v_ss.variance_threshold_vnd / GREATEST((SELECT avg_unit_cost FROM public.stock_levels WHERE ingredient_id = l.ingredient_id AND branch_id = v_ss.branch_id LIMIT 1), 1)
      END AS needs_rc FROM latest l
  )
  UPDATE public.stocktake_lines sl SET needs_recount = d.needs_rc, is_final = NOT d.needs_rc
  FROM decided d WHERE sl.id = d.id;

  IF p_round_no > 1 THEN
    -- Propagate median + is_final to round-1 for converged ingredients
    WITH converged AS (
      SELECT DISTINCT sl.ingredient_id
      FROM public.stocktake_lines sl
      WHERE sl.session_id = p_session_id AND sl.round_no = p_round_no AND NOT sl.needs_recount
    ),
    medians AS (
      SELECT sl.ingredient_id, percentile_cont(0.5) WITHIN GROUP (ORDER BY sl.counted_quantity) AS med
      FROM public.stocktake_lines sl
      WHERE sl.session_id = p_session_id AND sl.counted_quantity IS NOT NULL
        AND sl.ingredient_id IN (SELECT ingredient_id FROM converged)
      GROUP BY sl.ingredient_id HAVING COUNT(*) >= 2
    )
    UPDATE public.stocktake_lines sl
       SET counted_quantity = m.med, is_final = true, needs_recount = false
    FROM medians m
    WHERE sl.session_id = p_session_id AND sl.ingredient_id = m.ingredient_id AND sl.round_no = 1;
  END IF;

  SELECT COUNT(*) FILTER (WHERE needs_recount), COUNT(*) FILTER (WHERE is_final) INTO v_need, v_final
  FROM public.stocktake_lines WHERE session_id = p_session_id AND round_no = p_round_no;

  IF v_need > 0 AND v_ss.current_round < 4 THEN
    UPDATE public.stocktake_sessions SET current_round = v_ss.current_round + 1 WHERE id = p_session_id;
  END IF;

  RETURN jsonb_build_object('round_no', p_round_no, 'needs_recount_count', v_need, 'final_count', v_final,
    'next_round', CASE WHEN v_need > 0 AND v_ss.current_round < 4 THEN v_ss.current_round + 1 ELSE NULL END,
    'round_4_escalation_required', v_need > 0 AND v_ss.current_round >= 3);
END; $$;


