--
-- Name: complete_kds_tickets(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_kds_tickets(p_branch_id bigint, p_ticket_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_ticket_ids BIGINT[] := ARRAY[]::BIGINT[];
  v_updated_ticket_ids BIGINT[] := ARRAY[]::BIGINT[];
  v_order_ids BIGINT[] := ARRAY[]::BIGINT[];
  v_requested_count INT := 0;
  v_locked_count INT := 0;
  v_completed_count INT := 0;
  v_group_count INT := 0;
  v_order_id BIGINT;
  v_print_result JSONB := jsonb_build_object(
    'jobs', '[]'::jsonb,
    'requested_ticket_count', 0,
    'printed_ticket_count', 0,
    'skipped_ticket_count', 0
  );
  v_print_warning TEXT := NULL;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_branch_id IS NULL OR p_branch_id <= 0 THEN
    RAISE EXCEPTION 'invalid_branch' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission_any('kds:mark_ready') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT ticket_id), ARRAY[]::BIGINT[])
  INTO v_ticket_ids
  FROM unnest(COALESCE(p_ticket_ids, ARRAY[]::BIGINT[])) AS input(ticket_id)
  WHERE ticket_id IS NOT NULL AND ticket_id > 0;

  v_requested_count := COALESCE(array_length(v_ticket_ids, 1), 0);

  IF v_requested_count = 0 THEN
    RAISE EXCEPTION 'no_tickets' USING ERRCODE = '22023';
  END IF;

  WITH locked AS (
    SELECT kt.id
    FROM public.kds_tickets kt
    WHERE kt.id = ANY(v_ticket_ids)
      AND kt.tenant_id = public.auth_tenant_id()
      AND kt.branch_id = p_branch_id
      AND public.can_access_branch(kt.branch_id)
    FOR UPDATE
  )
  SELECT COUNT(*) INTO v_locked_count
  FROM locked;

  IF v_locked_count <> v_requested_count THEN
    RAISE EXCEPTION 'ticket_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COUNT(DISTINCT COALESCE(
    'batch:' || kt.kitchen_send_batch_id::TEXT,
    'order:' || kt.order_id::TEXT
  ))
  INTO v_group_count
  FROM public.kds_tickets kt
  WHERE kt.id = ANY(v_ticket_ids)
    AND kt.tenant_id = public.auth_tenant_id()
    AND kt.branch_id = p_branch_id;

  IF v_group_count <> 1 THEN
    RAISE EXCEPTION 'mixed_kds_card' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT kt.order_id), ARRAY[]::BIGINT[])
  INTO v_order_ids
  FROM public.kds_tickets kt
  WHERE kt.id = ANY(v_ticket_ids)
    AND kt.tenant_id = public.auth_tenant_id()
    AND kt.branch_id = p_branch_id;

  WITH updated AS (
    UPDATE public.kds_tickets kt
    SET status = 'ready',
        bumped_at = now(),
        bumped_by = v_uid,
        updated_at = now()
    WHERE kt.id = ANY(v_ticket_ids)
      AND kt.tenant_id = public.auth_tenant_id()
      AND kt.branch_id = p_branch_id
      AND kt.status IN ('pending', 'preparing')
    RETURNING kt.id
  )
  SELECT
    COALESCE(array_agg(id), ARRAY[]::BIGINT[]),
    COUNT(*)
  INTO v_updated_ticket_ids, v_completed_count
  FROM updated;

  IF v_completed_count > 0 THEN
    BEGIN
      v_print_result := private.enqueue_kitchen_completion_print_internal(
        p_branch_id,
        v_updated_ticket_ids,
        v_uid
      );

      IF COALESCE((v_print_result->>'skipped_ticket_count')::INT, 0) > 0 THEN
        v_print_warning := 'kitchen_print_skipped';
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_print_warning := 'kitchen_print_enqueue_failed';
        v_print_result := jsonb_build_object(
          'jobs', '[]'::jsonb,
          'requested_ticket_count', v_completed_count,
          'printed_ticket_count', 0,
          'skipped_ticket_count', v_completed_count
        );
        RAISE LOG 'complete_kds_tickets print enqueue skipped branch_id=%, ticket_ids=%, sqlstate=%, error=%',
          p_branch_id,
          v_updated_ticket_ids,
          SQLSTATE,
          SQLERRM;
    END;
  END IF;

  FOREACH v_order_id IN ARRAY v_order_ids LOOP
    PERFORM public.check_order_ready(v_order_id);
  END LOOP;

  RETURN jsonb_build_object(
    'requested_count', v_requested_count,
    'completed_count', v_completed_count,
    'print_jobs', COALESCE(v_print_result->'jobs', '[]'::jsonb),
    'printed_ticket_count', COALESCE((v_print_result->>'printed_ticket_count')::INT, 0),
    'skipped_ticket_count', COALESCE((v_print_result->>'skipped_ticket_count')::INT, 0),
    'print_warning', v_print_warning
  );
END;
$$;


--
-- Name: FUNCTION complete_kds_tickets(p_branch_id bigint, p_ticket_ids bigint[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_kds_tickets(p_branch_id bigint, p_ticket_ids bigint[]) IS 'Atomically marks visible pending/preparing KDS tickets ready and queues matching kitchen print jobs for the completed tickets only. Does not close POS/payment/table state.';


--
-- Name: complete_payment_and_consume_stock(bigint, numeric, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_payment_and_consume_stock(p_payment_id bigint, p_expected_amount numeric DEFAULT NULL::numeric, p_provider_data jsonb DEFAULT NULL::jsonb, p_actor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(status text, payment_id bigint, order_id bigint, stock_consumed boolean, detail text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_payment          RECORD;
  v_order            RECORD;
  v_line_subtotal    NUMERIC(15,2) := 0;
  v_recomputed_total NUMERIC(15,2) := 0;
BEGIN
  SELECT p.id, p.order_id, p.tenant_id, p.branch_id, p.amount, p.status
  INTO v_payment
  FROM public.payments p
  WHERE p.id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'not_found'::TEXT, p_payment_id, NULL::BIGINT, FALSE,
      ('payment ' || p_payment_id || ' does not exist')::TEXT;
    RETURN;
  END IF;

  IF v_payment.status = 'completed' THEN
    RETURN QUERY SELECT
      'already_completed'::TEXT, v_payment.id, v_payment.order_id, FALSE,
      'payment was previously completed; no-op'::TEXT;
    RETURN;
  END IF;

  IF v_payment.status <> 'pending' THEN
    RETURN QUERY SELECT
      'failed'::TEXT, v_payment.id, v_payment.order_id, FALSE,
      ('payment status=' || v_payment.status || ' cannot transition to completed')::TEXT;
    RETURN;
  END IF;

  SELECT o.id, o.tenant_id, o.branch_id, o.tax_amount, o.service_charge,
         o.discount_amount, o.total_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_payment.order_id
    AND o.tenant_id = v_payment.tenant_id
    AND o.branch_id = v_payment.branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'failed'::TEXT, v_payment.id, v_payment.order_id, FALSE,
      'order_not_found'::TEXT;
    RETURN;
  END IF;

  SELECT COALESCE(SUM(oi.quantity::NUMERIC * oi.unit_price), 0)::NUMERIC(15,2)
  INTO v_line_subtotal
  FROM public.order_items oi
  WHERE oi.order_id = v_order.id
    AND oi.tenant_id = v_order.tenant_id
    AND oi.status <> 'cancelled';

  v_recomputed_total := ROUND(
    v_line_subtotal
    + COALESCE(v_order.tax_amount, 0)
    + COALESCE(v_order.service_charge, 0)
    - COALESCE(v_order.discount_amount, 0),
    2
  );

  IF ABS(v_payment.amount - v_recomputed_total) > 1 THEN
    UPDATE public.payments
       SET status = 'failed',
           provider_data = COALESCE(p_provider_data, provider_data),
           updated_at = now()
     WHERE id = v_payment.id;

    RETURN QUERY SELECT
      'amount_mismatch_recomputed'::TEXT, v_payment.id, v_payment.order_id, FALSE,
      ('stored=' || v_payment.amount || ' recomputed=' || v_recomputed_total)::TEXT;
    RETURN;
  END IF;

  IF p_expected_amount IS NOT NULL AND ABS(p_expected_amount - v_recomputed_total) > 1 THEN
    UPDATE public.payments
       SET status = 'failed',
           provider_data = COALESCE(p_provider_data, provider_data),
           updated_at = now()
     WHERE id = v_payment.id;

    RETURN QUERY SELECT
      'amount_mismatch_recomputed'::TEXT, v_payment.id, v_payment.order_id, FALSE,
      ('expected=' || p_expected_amount || ' recomputed=' || v_recomputed_total)::TEXT;
    RETURN;
  END IF;

  -- Nhánh trừ kho đã gỡ theo chính sách owner 2026-05-28 "không trừ kho khi
  -- thanh toán". stock_consumed_status để NULL (đồng nhất cash/VietQR =
  -- "không trừ kho"); 'stock_failed' không còn là kết quả khả dĩ.

  UPDATE public.payments
     SET status        = 'completed',
         paid_at       = COALESCE(paid_at, now()),
         provider_data = COALESCE(p_provider_data, provider_data),
         updated_at    = now()
   WHERE id = v_payment.id;

  UPDATE public.orders
     SET payment_status = 'paid',
         updated_at     = now()
   WHERE id = v_payment.order_id
     AND tenant_id = v_payment.tenant_id;

  PERFORM public.finalize_paid_order(v_payment.order_id, p_actor_id);

  RETURN QUERY SELECT
    'completed'::TEXT,
    v_payment.id,
    v_payment.order_id,
    FALSE,
    'stock=skipped_per_policy_2026-05-28'::TEXT;
END;
$$;


--
-- Name: FUNCTION complete_payment_and_consume_stock(p_payment_id bigint, p_expected_amount numeric, p_provider_data jsonb, p_actor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_payment_and_consume_stock(p_payment_id bigint, p_expected_amount numeric, p_provider_data jsonb, p_actor_id uuid) IS 'Recomputes order total at payment time and marks paid. Stock leg REMOVED per owner policy 2026-05-28 (không trừ kho); stock_consumed always false, stock_consumed_status left NULL. Name kept for caller compatibility.';


--
-- Name: complete_print_job(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_print_job(p_job_id bigint, p_success boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_service BOOLEAN := (auth.role() = 'service_role');
  v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  UPDATE public.print_jobs
    SET status = CASE WHEN p_success THEN 'printed' ELSE 'failed' END,
        printed_at = CASE WHEN p_success THEN now() ELSE printed_at END,
        last_error = CASE WHEN p_success THEN NULL ELSE p_error END
    WHERE id = p_job_id
      AND (v_is_service OR tenant_id = v_tenant);
END;
$$;


--
-- Name: complete_stocktake(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_stocktake(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid           UUID := auth.uid();
  v_tenant        BIGINT := public.auth_tenant_id();
  v_session       RECORD;
  v_line          RECORD;
  v_fresh_qty     NUMERIC(15,3);
  v_adjustment    NUMERIC(15,3);
  v_total_lines   INT := 0;
  v_adjusted      INT := 0;
  v_total_var_abs NUMERIC(15,3) := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT s.* INTO v_session
  FROM public.stocktake_sessions s
  WHERE s.id = p_session_id AND s.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_session.branch_id, 'inventory:stocktake_complete') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_session.status <> 'in_progress' THEN
    RAISE EXCEPTION 'session_not_in_progress' USING ERRCODE = '22023';
  END IF;

  IF v_session.location_id IS NULL THEN
    RAISE EXCEPTION 'session_location_missing' USING ERRCODE = '23502';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.stocktake_lines sl
    WHERE sl.session_id = p_session_id
      AND sl.tenant_id = v_tenant
      AND sl.counted_quantity IS NULL
  ) THEN
    RAISE EXCEPTION 'uncounted_lines_exist' USING ERRCODE = '22023';
  END IF;

  FOR v_line IN
    SELECT * FROM public.stocktake_lines sl
    WHERE sl.session_id = p_session_id AND sl.tenant_id = v_tenant
  LOOP
    v_total_lines := v_total_lines + 1;

    SELECT COALESCE(stl.current_quantity, 0) INTO v_fresh_qty
    FROM public.stock_levels stl
    WHERE stl.tenant_id     = v_tenant
      AND stl.branch_id     = v_session.branch_id
      AND stl.location_id   = v_session.location_id
      AND stl.ingredient_id = v_line.ingredient_id;

    IF NOT FOUND THEN
      v_fresh_qty := 0;
    END IF;

    v_adjustment := v_line.counted_quantity - v_fresh_qty;

    IF v_adjustment <> 0 THEN
      v_adjusted := v_adjusted + 1;
      v_total_var_abs := v_total_var_abs + abs(v_adjustment);

      INSERT INTO public.stock_movements (
        tenant_id, branch_id, ingredient_id, type, quantity_change,
        reason, created_by, location_id
      ) VALUES (
        v_tenant,
        v_session.branch_id,
        v_line.ingredient_id,
        'count_adjustment',
        v_adjustment,
        COALESCE(v_line.variance_reason, 'Stocktake #' || p_session_id::text),
        v_uid,
        v_session.location_id
      );
    END IF;
  END LOOP;

  UPDATE public.stocktake_sessions
  SET status = 'completed', completed_at = now()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', p_session_id,
    'total_lines', v_total_lines,
    'adjusted_lines', v_adjusted,
    'total_variance_abs', v_total_var_abs
  );
END;
$$;


--
-- Name: FUNCTION complete_stocktake(p_session_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_stocktake(p_session_id bigint) IS 'Completes classic stocktake and writes count_adjustment stock movements. SECURITY DEFINER with tenant and inventory:stocktake_complete gate.';


--
-- Name: compute_branch_daily_waste_caps(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_branch_daily_waste_caps() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pct CONSTANT NUMERIC := 0.025; v_floor CONSTANT NUMERIC := 500000; v_ceiling CONSTANT NUMERIC := 5000000; v_count INT;
BEGIN
  WITH daily AS (
    SELECT o.branch_id, DATE(o.created_at AT TIME ZONE COALESCE(b.timezone, 'Asia/Ho_Chi_Minh')) AS day,
           SUM(COALESCE(o.total_amount, 0)) AS daily_total
    FROM public.orders o JOIN public.branches b ON b.id = o.branch_id
    WHERE o.status = 'completed' AND o.created_at >= now() - INTERVAL '7 days'
    GROUP BY o.branch_id, DATE(o.created_at AT TIME ZONE COALESCE(b.timezone, 'Asia/Ho_Chi_Minh'))
  ), avg_rev AS (SELECT branch_id, AVG(daily_total) AS avg_rev FROM daily GROUP BY branch_id)
  INSERT INTO public.branch_daily_waste_cap (branch_id, cap_vnd, avg_revenue_7d, computed_at)
  SELECT b.id, GREATEST(v_floor, LEAST(v_ceiling, v_pct * COALESCE(a.avg_rev, 0))), COALESCE(a.avg_rev, 0), now()
  FROM public.branches b LEFT JOIN avg_rev a ON a.branch_id = b.id
  WHERE b.is_active = true
  ON CONFLICT (branch_id) DO UPDATE SET cap_vnd = EXCLUDED.cap_vnd, avg_revenue_7d = EXCLUDED.avg_revenue_7d, computed_at = EXCLUDED.computed_at;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END; $$;


--
-- Name: compute_discount_amount(text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_discount_amount(p_type text, p_value numeric, p_subtotal numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_subtotal NUMERIC := COALESCE(p_subtotal, 0);
  v_value    NUMERIC := COALESCE(p_value, 0);
BEGIN
  IF p_type IS NULL OR v_value <= 0 OR v_subtotal <= 0 THEN
    RETURN 0;
  END IF;

  IF p_type = 'pct' THEN
    -- Clamp pct to [0,100]; FLOOR nguyên VND.
    RETURN FLOOR(v_subtotal * LEAST(v_value, 100) / 100);
  ELSIF p_type = 'vnd' THEN
    -- Clamp tiền giảm về subtotal (void món xong, vnd-discount cũ có thể
    -- vượt subtotal mới — kéo về subtotal để total_amount không âm).
    RETURN LEAST(v_value, v_subtotal);
  END IF;

  RETURN 0;
END;
$$;


--
-- Name: FUNCTION compute_discount_amount(p_type text, p_value numeric, p_subtotal numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compute_discount_amount(p_type text, p_value numeric, p_subtotal numeric) IS 'Single source of truth for discount math. pct => FLOOR(subtotal*pct/100) clamped to subtotal; vnd => LEAST(value, subtotal). NULL/0 inputs => 0. Called by apply_order_discount, append_order_items, void_order_item, cancel_order on every recalc path.';


--
-- Name: compute_user_trust_score(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_user_trust_score(p_user_id uuid, p_branch_id bigint) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant BIGINT; v_good_grn INT; v_incidents INT; v_score NUMERIC;
BEGIN
  SELECT tenant_id INTO v_tenant FROM public.branches WHERE id = p_branch_id;
  IF v_tenant IS NULL THEN RETURN 50; END IF;
  SELECT COUNT(*) INTO v_good_grn FROM public.goods_received_notes
   WHERE created_by = p_user_id AND branch_id = p_branch_id AND status = 'confirmed'
     AND received_date > now() - INTERVAL '60 days';
  SELECT COUNT(*) INTO v_incidents FROM public.grn_hardblock_overrides
   WHERE overridden_by = p_user_id AND branch_id = p_branch_id AND overridden_at > now() - INTERVAL '60 days';
  IF v_good_grn < 20 THEN
    v_score := 50 + v_good_grn * 1.0 - v_incidents * 20;
  ELSE
    v_score := 70 + (v_good_grn - 20) * 0.5 - v_incidents * 20;
  END IF;
  IF v_incidents > 0 THEN v_score := LEAST(v_score, 85); END IF;
  v_score := GREATEST(0, LEAST(100, v_score))::NUMERIC(5,2);
  INSERT INTO public.user_trust_score (tenant_id, branch_id, user_id, score, grn_count_30d,
    variance_incidents_30d, last_incident_at, updated_at)
  VALUES (v_tenant, p_branch_id, p_user_id, v_score, v_good_grn, v_incidents,
    (SELECT MAX(overridden_at) FROM public.grn_hardblock_overrides
      WHERE overridden_by = p_user_id AND branch_id = p_branch_id
        AND overridden_at > now() - INTERVAL '60 days'),
    now())
  ON CONFLICT (tenant_id, branch_id, user_id) DO UPDATE
    SET score = EXCLUDED.score, grn_count_30d = EXCLUDED.grn_count_30d,
        variance_incidents_30d = EXCLUDED.variance_incidents_30d,
        last_incident_at = EXCLUDED.last_incident_at, updated_at = EXCLUDED.updated_at;
  RETURN v_score;
END; $$;


--
-- Name: FUNCTION compute_user_trust_score(p_user_id uuid, p_branch_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compute_user_trust_score(p_user_id uuid, p_branch_id bigint) IS 'Q4b real formula, VOLATILE (writes cache). Warmup 50+n (first 20 clean/60d), post 70+(n-20)*0.5, incident -20, cap 85 if incident. Threshold 70.';


--
-- Name: configure_express_window(bigint, boolean, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.configure_express_window(p_branch_id bigint, p_enabled boolean, p_start_time time without time zone DEFAULT '06:00:00'::time without time zone, p_end_time time without time zone DEFAULT '09:00:00'::time without time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:grn_express_configure') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_start_time >= p_end_time THEN RAISE EXCEPTION 'start_time must be before end_time' USING ERRCODE = '22023'; END IF;
  INSERT INTO public.branch_express_window (branch_id, enabled, start_time, end_time, updated_at, updated_by)
  VALUES (p_branch_id, p_enabled, p_start_time, p_end_time, now(), v_uid)
  ON CONFLICT (branch_id) DO UPDATE SET enabled=EXCLUDED.enabled, start_time=EXCLUDED.start_time, end_time=EXCLUDED.end_time, updated_at=EXCLUDED.updated_at, updated_by=EXCLUDED.updated_by;
END; $$;


--
-- Name: confirm_cash_payment(bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_cash_payment(p_order_id bigint, p_cash_received numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID;
  v_order        public.orders%ROWTYPE;
  v_existing_id  BIGINT;
  v_existing_st  TEXT;
  v_payment_id   BIGINT;
  v_cash_change  NUMERIC(15,2);
  v_complete_res RECORD;
  v_receipt_res  JSONB;
  v_print_warning TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:confirm_payment') THEN
    RAISE EXCEPTION 'permission denied: pos:confirm_payment' USING ERRCODE = '42501';
  END IF;

  IF p_cash_received IS NULL THEN
    RAISE EXCEPTION 'cash_received required' USING ERRCODE = 'P0001';
  END IF;
  IF p_cash_received < v_order.total_amount THEN
    RAISE EXCEPTION 'cash_received (%) must be >= total_amount (%)',
      p_cash_received, v_order.total_amount
      USING ERRCODE = 'P0001';
  END IF;

  IF p_cash_received > GREATEST(v_order.total_amount * 10, 50000000) THEN
    RAISE EXCEPTION 'cash_received (%) exceeds sane upper bound for total (%)',
      p_cash_received, v_order.total_amount
      USING ERRCODE = 'P0001';
  END IF;

  v_cash_change := p_cash_received - v_order.total_amount;

  SELECT id, status INTO v_existing_id, v_existing_st
  FROM public.payments
  WHERE order_id = p_order_id
    AND status <> 'failed'
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_st = 'completed' THEN
    v_payment_id := v_existing_id;
  ELSIF v_existing_id IS NOT NULL THEN
    UPDATE public.payments
       SET method        = 'cash',
           amount        = v_order.total_amount,
           status        = 'pending',
           provider_ref  = NULL,
           provider_data = NULL,
           updated_at    = now()
     WHERE id = v_existing_id;
    v_payment_id := v_existing_id;
  ELSE
    INSERT INTO public.payments (
      tenant_id, branch_id, order_id, method, amount, status, created_by
    ) VALUES (
      v_order.tenant_id, v_order.branch_id, p_order_id, 'cash',
      v_order.total_amount, 'pending', v_uid
    )
    RETURNING id INTO v_payment_id;
  END IF;

  UPDATE public.orders
     SET payment_method = 'cash',
         updated_at     = now()
   WHERE id = p_order_id;

  IF v_existing_st = 'completed' THEN
    RETURN jsonb_build_object(
      'status',        'already_completed',
      'order_id',      p_order_id,
      'payment_id',    v_payment_id,
      'cash_received', COALESCE(v_order.cash_received, p_cash_received),
      'cash_change',   COALESCE(v_order.cash_change, v_cash_change),
      'print_job_id',  NULL,
      'idempotent',    true
    );
  END IF;

  SELECT * INTO v_complete_res
  FROM public.complete_payment_and_consume_stock(
    v_payment_id,
    v_order.total_amount,
    jsonb_build_object('cash_received', p_cash_received, 'cash_change', v_cash_change),
    v_uid
  );

  IF v_complete_res.status = 'stock_failed' THEN
    RETURN jsonb_build_object(
      'status',      'stock_failed',
      'order_id',    p_order_id,
      'payment_id',  v_payment_id,
      'error_code',  'stock_consumption_failed',
      'detail',      v_complete_res.detail
    );
  END IF;

  IF v_complete_res.status = 'amount_mismatch_recomputed' THEN
    RETURN jsonb_build_object(
      'status',      'amount_mismatch_recomputed',
      'order_id',    p_order_id,
      'payment_id',  v_payment_id,
      'error_code',  'amount_mismatch_recomputed',
      'detail',      v_complete_res.detail
    );
  END IF;

  IF v_complete_res.status NOT IN ('completed', 'already_completed') THEN
    RAISE EXCEPTION 'payment completion failed: % (detail: %)',
      v_complete_res.status, v_complete_res.detail
      USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    v_receipt_res := public.enqueue_receipt_print(
      p_order_id,
      p_cash_received,
      v_cash_change
    );
  EXCEPTION WHEN OTHERS THEN
    v_print_warning := SQLERRM;
    v_receipt_res := jsonb_build_object('error', SQLERRM);
    RAISE NOTICE '[confirm_cash_payment] receipt enqueue skipped for order %: %',
      p_order_id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'status',        'completed',
    'order_id',      p_order_id,
    'payment_id',    v_payment_id,
    'cash_received', p_cash_received,
    'cash_change',   v_cash_change,
    'print_job_id',  v_receipt_res->>'job_id',
    'print_warning', v_print_warning
  );
END;
$$;


--
-- Name: FUNCTION confirm_cash_payment(p_order_id bigint, p_cash_received numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_cash_payment(p_order_id bigint, p_cash_received numeric) IS 'Cash payment confirmation. Reuses active payment slot, allows zero-total comp orders, delegates server recompute + stock fail-hard to complete_payment_and_consume_stock, and keeps receipt printing fail-soft.';


--
-- Name: confirm_goods_receipt_note(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_goods_receipt_note(p_grn_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID   := auth.uid();
  v_tenant          BIGINT := public.auth_tenant_id();
  v_grn             RECORD;
  v_item            RECORD;
  v_branch          RECORD;
  v_old_q           NUMERIC(15,3);
  v_old_wac         NUMERIC(15,2);
  v_recv            NUMERIC(15,3);
  v_cost            NUMERIC(15,2);
  v_new_q           NUMERIC(15,3);
  v_new_wac         NUMERIC(15,2);
  v_location_id     BIGINT;
  v_all_fulfilled   BOOLEAN;
  v_po_status       TEXT;
  v_review_pct      NUMERIC(5,2);
  v_review_count    INT := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT g.* INTO v_grn
  FROM public.goods_received_notes g
  WHERE g.id = p_grn_id AND g.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_grn.branch_id, 'procurement:grn_confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_grn.status <> 'draft' THEN
    RAISE EXCEPTION 'grn_not_draft' USING ERRCODE = '22023';
  END IF;

  SELECT b.id, b.branch_kind INTO v_branch
  FROM public.branches b
  WHERE b.id = v_grn.branch_id
    AND b.tenant_id = v_tenant
    AND b.branch_kind IN ('branch', 'central_supply', 'central_kitchen');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_branch_must_be_operational' USING ERRCODE = '23514';
  END IF;

  SELECT il.id INTO v_location_id
  FROM public.inventory_locations il
  WHERE il.branch_id = v_grn.branch_id
    AND il.tenant_id = v_tenant
    AND il.is_default_receive = TRUE
    AND il.is_active = TRUE
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'grn_default_receive_location_missing' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(qc.price_variance_review_pct, 15.0)
  INTO v_review_pct
  FROM public.inventory_qc_settings qc
  WHERE qc.tenant_id = v_tenant;
  IF NOT FOUND THEN
    v_review_pct := 15.0;
  END IF;

  FOR v_item IN
    SELECT * FROM public.grn_items gi
    WHERE gi.grn_id = p_grn_id AND gi.tenant_id = v_tenant
  LOOP
    IF v_item.price_variance_pct IS NOT NULL
       AND ABS(v_item.price_variance_pct) > v_review_pct THEN
      UPDATE public.grn_items
      SET requires_review = TRUE
      WHERE id = v_item.id;
      v_review_count := v_review_count + 1;
    END IF;

    v_recv := v_item.received_quantity - COALESCE(v_item.rejected_quantity, 0);

    IF v_item.quality_status = 'rejected' OR v_recv <= 0 THEN
      CONTINUE;
    END IF;

    v_cost := v_item.unit_cost;

    SELECT sl.current_quantity, sl.avg_unit_cost
    INTO v_old_q, v_old_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id     = v_tenant
      AND sl.branch_id     = v_grn.branch_id
      AND sl.location_id   = v_location_id
      AND sl.ingredient_id = v_item.ingredient_id;

    IF NOT FOUND THEN
      v_old_q := 0;
      v_old_wac := NULL;
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, grn_id, unit_cost, location_id
    ) VALUES (
      v_tenant, v_grn.branch_id, v_item.ingredient_id, 'grn_receipt', v_recv,
      'GRN ' || v_grn.grn_number, v_uid, p_grn_id, v_cost, v_location_id
    );

    v_new_q := COALESCE(v_old_q, 0) + v_recv;
    IF v_new_q > 0 THEN
      v_new_wac := (
        COALESCE(v_old_q, 0) * COALESCE(v_old_wac, 0) + v_recv * v_cost
      ) / v_new_q;
    ELSE
      v_new_wac := v_cost;
    END IF;

    UPDATE public.stock_levels sl
    SET avg_unit_cost = v_new_wac, updated_at = now()
    WHERE sl.tenant_id     = v_tenant
      AND sl.branch_id     = v_grn.branch_id
      AND sl.location_id   = v_location_id
      AND sl.ingredient_id = v_item.ingredient_id;

    UPDATE public.ingredients i
    SET unit_cost = v_cost, updated_at = now()
    WHERE i.id = v_item.ingredient_id AND i.tenant_id = v_tenant;
  END LOOP;

  UPDATE public.goods_received_notes
  SET status = 'confirmed', updated_at = now()
  WHERE id = p_grn_id;

  IF v_grn.po_id IS NOT NULL THEN
    PERFORM 1
    FROM public.purchase_orders
    WHERE id = v_grn.po_id AND tenant_id = v_tenant
    FOR UPDATE;

    WITH ordered AS (
      SELECT poi.ingredient_id, SUM(poi.quantity)::NUMERIC(15,3) AS qty
      FROM public.purchase_order_items poi
      WHERE poi.po_id = v_grn.po_id
        AND poi.tenant_id = v_tenant
      GROUP BY poi.ingredient_id
    ),
    received AS (
      SELECT gi.ingredient_id,
             SUM(gi.received_quantity - COALESCE(gi.rejected_quantity, 0))::NUMERIC(15,3) AS qty
      FROM public.grn_items gi
      JOIN public.goods_received_notes g
        ON g.id = gi.grn_id AND g.status = 'confirmed'
      WHERE g.po_id = v_grn.po_id
        AND gi.tenant_id = v_tenant
      GROUP BY gi.ingredient_id
    )
    SELECT bool_and(COALESCE(r.qty, 0) >= o.qty * 0.95)
    INTO v_all_fulfilled
    FROM ordered o
    LEFT JOIN received r USING (ingredient_id)
    WHERE o.qty > 0;

    UPDATE public.purchase_orders po
    SET status = CASE
          WHEN COALESCE(v_all_fulfilled, TRUE) THEN 'received'
          WHEN EXISTS (
            SELECT 1 FROM public.grn_items gi2
            JOIN public.goods_received_notes g2 ON g2.id = gi2.grn_id
            WHERE g2.po_id = v_grn.po_id
              AND g2.tenant_id = v_tenant
              AND gi2.short_delivery_action = 'accept_and_close'
          ) THEN 'received'
          ELSE 'partially_received'
        END,
        updated_at = now()
    WHERE po.id = v_grn.po_id
      AND po.tenant_id = v_tenant
      AND po.status IN ('sent', 'partially_received')
    RETURNING po.status INTO v_po_status;
  END IF;

  RETURN jsonb_build_object(
    'grn_id', p_grn_id,
    'status', 'confirmed',
    'po_id', v_grn.po_id,
    'po_status', v_po_status,
    'review_count', v_review_count
  );
END;
$$;


--
-- Name: FUNCTION confirm_goods_receipt_note(p_grn_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_goods_receipt_note(p_grn_id bigint) IS 'Atomic confirm GRN. Stock += (received_quantity − rejected_quantity). PO fulfillment aggregate dùng net. GL journal posts net × unit_cost. Permission: procurement:grn_confirm.';


--
-- Name: confirm_payment_and_post(bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_payment_and_post(p_payment_id bigint, p_tenant_id bigint, p_branch_id bigint, p_provider_ref text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid           UUID := auth.uid();
  v_payment       RECORD;
  v_order         RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.* INTO v_payment
  FROM public.payments p
  WHERE p.id = p_payment_id
    AND p.tenant_id = p_tenant_id
    AND p.branch_id = p_branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_payment.status <> 'pending' THEN
    RAISE EXCEPTION 'payment_not_pending' USING ERRCODE = '22023';
  END IF;

  SELECT o.id, o.total_amount, o.tax_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_payment.order_id
    AND o.tenant_id = p_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.payments
  SET status = 'completed',
      provider_ref = COALESCE(p_provider_ref, provider_ref),
      paid_at = now(),
      updated_at = now()
  WHERE id = p_payment_id;

  UPDATE public.orders
  SET payment_status = 'paid',
      updated_at = now()
  WHERE id = v_payment.order_id
    AND tenant_id = p_tenant_id;

  PERFORM public.finalize_paid_order(v_payment.order_id, v_uid);

  RETURN jsonb_build_object(
    'payment_id', p_payment_id,
    'status', 'completed'
  );
END;
$$;


--
-- Name: confirm_production_order(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_production_order(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_order RECORD; v_item RECORD; v_recipe RECORD;
  v_raw_need_measure NUMERIC(15,3); v_raw_need_purchase NUMERIC(15,3);
  v_conversion_factor NUMERIC(18,6); v_output_cost NUMERIC(15,2);
  v_old_q NUMERIC(15,3); v_old_wac NUMERIC(15,2);
  v_new_q NUMERIC(15,3); v_new_wac NUMERIC(15,2);
  v_need_map JSONB := '{}'::JSONB; v_cost_map JSONB := '{}'::JSONB;
  v_key TEXT; v_need_qty NUMERIC(15,3); v_cost_total NUMERIC(15,2); v_has_recipe BOOLEAN;
  v_location_id BIGINT;
  v_shortages JSONB := '[]'::JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('inventory:production_confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT po.*, b.branch_kind INTO v_order
  FROM public.production_orders po JOIN public.branches b ON b.id = po.branch_id
  WHERE po.id = p_order_id AND po.tenant_id = v_tenant FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'production_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_order.status <> 'draft' THEN
    RAISE EXCEPTION 'production_order_not_draft' USING ERRCODE = '22023';
  END IF;
  IF v_order.branch_kind NOT IN ('branch', 'central_kitchen') THEN
    RAISE EXCEPTION 'branch_must_be_operational' USING ERRCODE = '23514';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'inventory:production_confirm') THEN
    RAISE EXCEPTION 'branch_scope_violation' USING ERRCODE = '42501';
  END IF;

  SELECT il.id INTO v_location_id
  FROM public.inventory_locations il
  WHERE il.branch_id = v_order.branch_id
    AND il.tenant_id = v_tenant
    AND il.is_default_receive = TRUE
    AND il.is_active = TRUE
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'production_location_missing:%', v_order.branch_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.production_order_items poi
    WHERE poi.production_order_id = p_order_id AND poi.tenant_id = v_tenant
  ) THEN
    RAISE EXCEPTION 'production_order_empty' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN
    SELECT poi.*, fg.item_kind
    FROM public.production_order_items poi
    JOIN public.ingredients fg ON fg.id = poi.finished_good_id
    WHERE poi.production_order_id = p_order_id AND poi.tenant_id = v_tenant
  LOOP
    IF v_item.item_kind <> 'finished_good' THEN
      RAISE EXCEPTION 'production_item_must_be_finished_good' USING ERRCODE = '23514';
    END IF;
    v_output_cost := 0; v_has_recipe := FALSE;
    FOR v_recipe IN
      SELECT pr.ingredient_id, pr.quantity, pr.yield_factor,
             ing.purchase_to_measure_factor,
             COALESCE(sl.avg_unit_cost, ing.unit_cost, 0) AS raw_unit_cost
      FROM public.production_recipes pr
      JOIN public.ingredients ing ON ing.id = pr.ingredient_id
      LEFT JOIN public.stock_levels sl
        ON sl.tenant_id     = v_tenant
       AND sl.branch_id     = v_order.branch_id
       AND sl.location_id   = v_location_id
       AND sl.ingredient_id = pr.ingredient_id
      WHERE pr.tenant_id = v_tenant AND pr.finished_good_id = v_item.finished_good_id
    LOOP
      v_has_recipe := TRUE;
      v_conversion_factor := COALESCE(v_recipe.purchase_to_measure_factor, 1);
      IF v_conversion_factor <= 0 THEN
        RAISE EXCEPTION 'production_conversion_factor_invalid:%', v_recipe.ingredient_id USING ERRCODE = '22023';
      END IF;

      v_raw_need_measure := (v_item.quantity * v_recipe.quantity) / COALESCE(v_recipe.yield_factor, 1.0);
      v_raw_need_purchase := ROUND((v_raw_need_measure / v_conversion_factor)::NUMERIC, 3);
      v_key := v_recipe.ingredient_id::text;
      v_need_map := jsonb_set(v_need_map, ARRAY[v_key],
        to_jsonb(COALESCE((v_need_map ->> v_key)::numeric, 0) + v_raw_need_purchase), TRUE);
      v_cost_map := jsonb_set(v_cost_map, ARRAY[v_key],
        to_jsonb(COALESCE((v_cost_map ->> v_key)::numeric, 0) + (v_raw_need_purchase * COALESCE(v_recipe.raw_unit_cost, 0))), TRUE);
      v_output_cost := v_output_cost + (v_raw_need_purchase * COALESCE(v_recipe.raw_unit_cost, 0));
    END LOOP;
    IF NOT v_has_recipe THEN
      RAISE EXCEPTION 'production_recipe_missing' USING ERRCODE = 'P0001';
    END IF;
    IF v_output_cost < 0 THEN
      RAISE EXCEPTION 'production_cost_invalid' USING ERRCODE = '22023';
    END IF;
    v_cost_total := v_output_cost;
    UPDATE public.production_order_items
    SET unit_cost_at_production = CASE WHEN v_item.quantity > 0 THEN ROUND(v_cost_total / v_item.quantity, 2) ELSE 0 END
    WHERE id = v_item.id;
  END LOOP;

  WITH shortages AS (
    SELECT
      (need.ingredient_id)::BIGINT AS ingredient_id,
      ing.name AS ingredient_name,
      COALESCE(ing.purchase_unit, ing.unit) AS unit,
      ROUND((need.need_qty)::NUMERIC, 3) AS needed,
      ROUND(COALESCE(sl.current_quantity, 0)::NUMERIC, 3) AS on_hand,
      ROUND(((need.need_qty)::NUMERIC - COALESCE(sl.current_quantity, 0))::NUMERIC, 3) AS missing
    FROM jsonb_each_text(v_need_map) AS need(ingredient_id, need_qty)
    JOIN public.ingredients ing ON ing.id = (need.ingredient_id)::BIGINT
    LEFT JOIN public.stock_levels sl
      ON sl.tenant_id     = v_tenant
     AND sl.branch_id     = v_order.branch_id
     AND sl.location_id   = v_location_id
     AND sl.ingredient_id = (need.ingredient_id)::BIGINT
    WHERE COALESCE(sl.current_quantity, 0) < (need.need_qty)::NUMERIC
    ORDER BY ((need.need_qty)::NUMERIC - COALESCE(sl.current_quantity, 0)) DESC
    LIMIT 20
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(s)), '[]'::JSONB) INTO v_shortages FROM shortages s;

  IF jsonb_array_length(v_shortages) > 0 THEN
    RAISE EXCEPTION 'insufficient_stock_for_production'
      USING ERRCODE = 'P0001',
            DETAIL  = v_shortages::TEXT;
  END IF;

  FOR v_key, v_need_qty IN SELECT key, value::NUMERIC(15,3) FROM jsonb_each_text(v_need_map) LOOP
    SELECT sl.current_quantity, sl.avg_unit_cost INTO v_old_q, v_old_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id     = v_tenant
      AND sl.branch_id     = v_order.branch_id
      AND sl.location_id   = v_location_id
      AND sl.ingredient_id = v_key::BIGINT;
    IF NOT FOUND THEN v_old_q := 0; v_old_wac := 0; END IF;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, production_order_id, unit_cost, location_id
    )
    VALUES (
      v_tenant, v_order.branch_id, v_key::BIGINT, 'production_consumption', -v_need_qty,
      'Production ' || v_order.production_number, v_uid, p_order_id,
      COALESCE(v_old_wac, 0), v_location_id
    );
  END LOOP;

  FOR v_item IN
    SELECT poi.*, fg.item_kind FROM public.production_order_items poi
    JOIN public.ingredients fg ON fg.id = poi.finished_good_id
    WHERE poi.production_order_id = p_order_id AND poi.tenant_id = v_tenant
  LOOP
    v_cost_total := COALESCE(v_item.unit_cost_at_production, 0);
    SELECT sl.current_quantity, sl.avg_unit_cost INTO v_old_q, v_old_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id     = v_tenant
      AND sl.branch_id     = v_order.branch_id
      AND sl.location_id   = v_location_id
      AND sl.ingredient_id = v_item.finished_good_id;
    IF NOT FOUND THEN v_old_q := 0; v_old_wac := 0; END IF;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, production_order_id, unit_cost, location_id
    )
    VALUES (
      v_tenant, v_order.branch_id, v_item.finished_good_id, 'production_output', v_item.quantity,
      'Production ' || v_order.production_number, v_uid, p_order_id, v_cost_total, v_location_id
    );

    v_new_q := COALESCE(v_old_q, 0) + v_item.quantity;
    IF v_new_q > 0 THEN
      v_new_wac := (COALESCE(v_old_q, 0) * COALESCE(v_old_wac, 0) + v_item.quantity * v_cost_total) / v_new_q;
    ELSE
      v_new_wac := v_cost_total;
    END IF;

    UPDATE public.stock_levels sl SET avg_unit_cost = v_new_wac, updated_at = now()
    WHERE sl.tenant_id     = v_tenant
      AND sl.branch_id     = v_order.branch_id
      AND sl.location_id   = v_location_id
      AND sl.ingredient_id = v_item.finished_good_id;

    UPDATE public.ingredients SET unit_cost = v_cost_total, updated_at = now()
    WHERE id = v_item.finished_good_id AND tenant_id = v_tenant;

  END LOOP;

  UPDATE public.production_orders SET status = 'completed', completed_at = now(), updated_at = now()
  WHERE id = p_order_id AND tenant_id = v_tenant;

  RETURN jsonb_build_object('production_order_id', p_order_id, 'status', 'completed');
END;
$$;


--
-- Name: confirm_stock_issue(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_stock_issue(p_issue_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid         UUID   := auth.uid();
  v_tenant      BIGINT := public.auth_tenant_id();
  v_issue       RECORD;
  v_item        RECORD;
  v_branch_kind TEXT;
  v_subtype     TEXT;
  v_sl_q        NUMERIC(15,3);
  v_wac         NUMERIC(15,2);
  v_source_loc  RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_issue
  FROM public.stock_issues
  WHERE id = p_issue_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_issue.branch_id, 'inventory:write') THEN
    RAISE EXCEPTION 'forbidden_inventory_write' USING ERRCODE = '42501';
  END IF;

  IF v_issue.status <> 'draft' THEN
    RAISE EXCEPTION 'issue_not_draft' USING ERRCODE = '22023';
  END IF;

  IF v_issue.issue_type = 'writeoff' AND v_issue.approval_status = 'pending' THEN
    RAISE EXCEPTION 'writeoff_pending_approval' USING ERRCODE = '42501';
  END IF;

  IF v_issue.source_location_id IS NULL THEN
    RAISE EXCEPTION 'issue_source_location_missing' USING ERRCODE = '23502';
  END IF;

  SELECT id, branch_id
  INTO v_source_loc
  FROM public.inventory_locations
  WHERE id = v_issue.source_location_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  IF NOT FOUND OR v_source_loc.branch_id <> v_issue.branch_id THEN
    RAISE EXCEPTION 'issue_source_location_invalid' USING ERRCODE = '23514';
  END IF;

  SELECT b.branch_kind INTO v_branch_kind
  FROM public.branches b
  WHERE b.id = v_issue.branch_id
    AND b.tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'issue_branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_subtype := CASE
    WHEN v_issue.issue_type = 'consumption'
      THEN 'sale_consumption'
    WHEN v_issue.issue_type = 'writeoff'
      THEN 'writeoff'
    WHEN v_issue.issue_type = 'other'
      THEN 'other'
    ELSE NULL
  END;

  FOR v_item IN
    SELECT * FROM public.stock_issue_items
    WHERE issue_id = p_issue_id
      AND tenant_id = v_tenant
  LOOP
    SELECT sl.current_quantity, sl.avg_unit_cost
    INTO v_sl_q, v_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_issue.branch_id
      AND sl.location_id = v_issue.source_location_id
      AND sl.ingredient_id = v_item.ingredient_id
    FOR UPDATE;

    IF NOT FOUND OR v_wac IS NULL THEN
      RAISE EXCEPTION 'wac_not_ready_for_%', v_item.ingredient_id
        USING ERRCODE = '22023';
    END IF;

    IF v_sl_q < v_item.quantity THEN
      RAISE EXCEPTION 'insufficient_stock_for_%', v_item.ingredient_id
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.stock_issue_items
    SET unit_cost = v_wac
    WHERE id = v_item.id
      AND tenant_id = v_tenant;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, movement_subtype,
      quantity_change, unit_cost, reason, created_by, issue_id, location_id
    ) VALUES (
      v_tenant,
      v_issue.branch_id,
      v_item.ingredient_id,
      'consumption',
      v_subtype,
      -v_item.quantity,
      v_wac,
      COALESCE(v_item.reason, v_issue.notes),
      v_uid,
      p_issue_id,
      v_issue.source_location_id
    );
  END LOOP;

  UPDATE public.stock_issues
  SET status = 'confirmed'
  WHERE id = p_issue_id
    AND tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'ok', true,
    'issue_id', p_issue_id,
    'movement_subtype', v_subtype
  );
END;
$$;


--
-- Name: FUNCTION confirm_stock_issue(p_issue_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_stock_issue(p_issue_id bigint) IS 'Atomically confirms a stock issue with strict WAC lookup and movement subtype derivation.';


--
-- Name: confirm_supplier_return(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_supplier_return(p_return_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     UUID   := auth.uid();
  v_tenant  BIGINT := public.auth_tenant_id();
  v_ret     RECORD;
  v_item    RECORD;
  v_old_q   NUMERIC(15,3);
  v_mv_id   BIGINT;
  v_lines_processed INT := 0;
  v_loc_id  BIGINT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_ret
  FROM public.supplier_returns
  WHERE id = p_return_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'return_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_ret.branch_id, 'supplier_return:confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_ret.status <> 'draft' THEN
    RAISE EXCEPTION 'return_not_draft' USING ERRCODE = '22023';
  END IF;

  IF v_ret.source = 'post_receipt' THEN
    -- Look up default-receive location for the source branch (per-location migration 20260425).
    SELECT id INTO v_loc_id
    FROM public.inventory_locations
    WHERE branch_id = v_ret.branch_id
      AND tenant_id = v_tenant
      AND is_default_receive = TRUE
      AND is_active = TRUE
    LIMIT 1;

    IF v_loc_id IS NULL THEN
      RAISE EXCEPTION 'no_default_location_for_branch' USING ERRCODE = 'P0002',
        DETAIL = format('branch_id=%s', v_ret.branch_id);
    END IF;

    FOR v_item IN
      SELECT * FROM public.supplier_return_items
      WHERE return_id = p_return_id AND tenant_id = v_tenant
      ORDER BY ingredient_id
    LOOP
      SELECT current_quantity INTO v_old_q
      FROM public.stock_levels
      WHERE tenant_id = v_tenant
        AND branch_id = v_ret.branch_id
        AND ingredient_id = v_item.ingredient_id
        AND location_id = v_loc_id
      FOR UPDATE;

      IF NOT FOUND OR COALESCE(v_old_q, 0) < v_item.quantity THEN
        RAISE EXCEPTION 'insufficient_stock_for_return' USING ERRCODE = '23514',
          DETAIL = format('ingredient_id=%s, requested=%s, available=%s',
                          v_item.ingredient_id, v_item.quantity, COALESCE(v_old_q, 0));
      END IF;

      INSERT INTO public.stock_movements (
        tenant_id, branch_id, ingredient_id, location_id, type, quantity_change,
        reason, created_by, unit_cost
      ) VALUES (
        v_tenant, v_ret.branch_id, v_item.ingredient_id, v_loc_id, 'supplier_return',
        -v_item.quantity,
        'Tra NCC ' || v_ret.return_number, v_uid, v_item.unit_cost
      ) RETURNING id INTO v_mv_id;

      UPDATE public.supplier_return_items
      SET stock_movement_id = v_mv_id
      WHERE id = v_item.id;

      v_lines_processed := v_lines_processed + 1;
    END LOOP;
  END IF;

  UPDATE public.supplier_returns
  SET status = 'sent',
      confirmed_by = v_uid,
      confirmed_at = now(),
      updated_at = now()
  WHERE id = p_return_id;

  RETURN jsonb_build_object(
    'return_id', p_return_id,
    'status', 'sent',
    'lines_processed', v_lines_processed
  );
END;
$$;


--
-- Name: FUNCTION confirm_supplier_return(p_return_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_supplier_return(p_return_id bigint) IS 'Moves supplier_return draft → sent. For source=post_receipt, decrements stock_levels atomically (FOR UPDATE) and inserts negative stock_movement type=supplier_return.';


--
-- Name: confirm_vietqr_payment(bigint, bigint, bigint, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_vietqr_payment(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_amount numeric, p_created_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order          RECORD;
  v_payment_id     BIGINT;
  v_existing_id    BIGINT;
  v_existing_status TEXT;
  v_idempotent     BOOLEAN := FALSE;
  v_receipt_res    JSONB;
  v_print_job_id   BIGINT;
  v_print_failed   BOOLEAN := FALSE;
  v_print_error    TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('pos:confirm_payment') THEN
    RAISE EXCEPTION 'permission denied: pos:confirm_payment' USING ERRCODE = '42501';
  END IF;

  SELECT id, total_amount, tax_amount, payment_status, branch_id, tenant_id
  INTO v_order
  FROM public.orders
  WHERE id          = p_order_id
    AND tenant_id   = p_tenant_id
    AND branch_id   = p_branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.payment_status = 'paid' THEN
    SELECT id INTO v_payment_id
    FROM public.payments
    WHERE order_id  = p_order_id
      AND tenant_id = p_tenant_id
      AND status    = 'completed'
    ORDER BY id DESC LIMIT 1;

    RETURN jsonb_build_object(
      'payment_id', v_payment_id,
      'idempotent', TRUE,
      'print',      jsonb_build_object('failed', FALSE)
    );
  END IF;

  IF p_amount <> v_order.total_amount THEN
    RAISE EXCEPTION 'amount_mismatch: expected % got %',
      v_order.total_amount, p_amount
      USING ERRCODE = '22023';
  END IF;

  SELECT id, status
  INTO v_existing_id, v_existing_status
  FROM public.payments
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND order_id  = p_order_id
    AND status   <> 'failed'
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_status = 'completed' THEN
    v_payment_id := v_existing_id;
    v_idempotent := TRUE;

  ELSIF v_existing_status = 'pending' THEN
    UPDATE public.payments
    SET method     = 'vietqr',
        amount     = p_amount,
        status     = 'completed',
        paid_at    = now(),
        updated_at = now()
    WHERE id = v_existing_id
    RETURNING id INTO v_payment_id;

  ELSE
    INSERT INTO public.payments (
      tenant_id, branch_id, order_id,
      method, amount, status, paid_at, created_by
    ) VALUES (
      p_tenant_id, p_branch_id, p_order_id,
      'vietqr', p_amount, 'completed', now(), p_created_by
    )
    RETURNING id INTO v_payment_id;
  END IF;

  IF NOT v_idempotent THEN
    UPDATE public.orders
    SET payment_status = 'paid',
        payment_method = 'vietqr',
        updated_at     = now()
    WHERE id = p_order_id;

    PERFORM public.finalize_paid_order(p_order_id, p_created_by);
  END IF;

  BEGIN
    v_receipt_res  := public.enqueue_receipt_print(p_order_id, NULL, NULL);
    v_print_job_id := (v_receipt_res ->> 'job_id')::BIGINT;
  EXCEPTION WHEN OTHERS THEN
    v_print_failed := TRUE;
    v_print_error  := SQLERRM;
    RAISE NOTICE '[confirm_vietqr_payment] receipt print failed for order %: %',
      p_order_id, SQLERRM;
  END;

  RETURN jsonb_build_object(
    'payment_id', v_payment_id,
    'idempotent', v_idempotent,
    'print', jsonb_build_object(
      'job_id', v_print_job_id,
      'failed', v_print_failed,
      'error',  v_print_error
    )
  );
END;
$$;


--
-- Name: FUNCTION confirm_vietqr_payment(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_amount numeric, p_created_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_vietqr_payment(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_amount numeric, p_created_by uuid) IS 'Atomic cashier-confirm for VietQR bank transfer. No payment row is created until the cashier taps Da thanh toan — QR is generated client-side. Upserts payment as completed, posts GL (SALE_BANK), finalizes order, and enqueues receipt failsoft. Gated by pos:confirm_payment.';


--
-- Name: consume_stock_for_order(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_stock_for_order(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid         UUID := auth.uid();
  v_tenant      BIGINT := public.auth_tenant_id();
  v_order       RECORD;
  v_need        RECORD;
  v_sl          NUMERIC(15,3);
  v_total       NUMERIC(15,3);
  v_location_id BIGINT;
  v_location_is_default BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT o.id, o.tenant_id, o.branch_id, o.status
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
    AND o.tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.stock_movements sm
    WHERE sm.order_id = p_order_id
      AND sm.type = 'consumption'
      AND sm.tenant_id = v_tenant
  ) THEN
    RETURN jsonb_build_object('order_id', p_order_id, 'skipped', true, 'reason', 'already_consumed');
  END IF;

  SELECT il.id, il.is_default_consumption
  INTO v_location_id, v_location_is_default
  FROM public.inventory_locations il
  WHERE il.branch_id = v_order.branch_id
    AND il.tenant_id = v_tenant
    AND il.location_kind = 'kitchen'
    AND il.is_active = TRUE
  ORDER BY il.is_default_consumption DESC, il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'consumption_location_missing:%', v_order.branch_id USING ERRCODE = 'P0002';
  END IF;

  IF v_location_is_default IS DISTINCT FROM TRUE THEN
    RAISE WARNING 'default_consumption_location_missing:branch %; using kitchen location %',
      v_order.branch_id,
      v_location_id;
  END IF;

  FOR v_need IN
    SELECT
      r.ingredient_id,
      SUM(oi.quantity::NUMERIC * r.quantity / r.yield_factor) AS need_qty
    FROM public.order_items oi
    JOIN public.recipes r
      ON r.menu_item_id = oi.menu_item_id
     AND r.tenant_id = oi.tenant_id
    WHERE oi.order_id = p_order_id
      AND oi.tenant_id = v_tenant
      AND oi.status <> 'cancelled'
    GROUP BY r.ingredient_id
  LOOP
    SELECT sl.current_quantity INTO v_sl
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id;

    v_total := COALESCE(v_sl, 0);
    IF v_total < v_need.need_qty THEN
      RAISE EXCEPTION 'insufficient_stock_ingredient:%', v_need.ingredient_id USING ERRCODE = 'P0001';
    END IF;
  END LOOP;

  FOR v_need IN
    SELECT
      r.ingredient_id,
      SUM(oi.quantity::NUMERIC * r.quantity / r.yield_factor) AS need_qty
    FROM public.order_items oi
    JOIN public.recipes r
      ON r.menu_item_id = oi.menu_item_id
     AND r.tenant_id = oi.tenant_id
    WHERE oi.order_id = p_order_id
      AND oi.tenant_id = v_tenant
      AND oi.status <> 'cancelled'
    GROUP BY r.ingredient_id
  LOOP
    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, order_id, unit_cost, location_id
    )
    SELECT
      v_tenant,
      v_order.branch_id,
      v_need.ingredient_id,
      'consumption',
      -v_need.need_qty,
      'Order ' || p_order_id::TEXT,
      v_uid,
      p_order_id,
      COALESCE(sl.avg_unit_cost, 0),
      v_location_id
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id;
  END LOOP;

  RETURN jsonb_build_object('order_id', p_order_id, 'consumed', true);
END;
$$;


--
-- Name: consume_stock_for_order_service(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_stock_for_order_service(p_order_id bigint, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor      UUID := COALESCE(p_actor_id, '00000000-0000-0000-0000-000000000000'::UUID);
  v_order      RECORD;
  v_need       RECORD;
  v_sl         NUMERIC(15,3);
  v_total      NUMERIC(15,3);
  v_location_id BIGINT;
  v_location_is_default BOOLEAN;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT o.id, o.tenant_id, o.branch_id, o.status
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.stock_movements sm
    WHERE sm.order_id = p_order_id
      AND sm.type = 'consumption'
      AND sm.tenant_id = v_order.tenant_id
  ) THEN
    RETURN jsonb_build_object(
      'order_id', p_order_id, 'skipped', true, 'reason', 'already_consumed'
    );
  END IF;

  SELECT il.id, il.is_default_consumption
  INTO v_location_id, v_location_is_default
  FROM public.inventory_locations il
  WHERE il.branch_id = v_order.branch_id
    AND il.tenant_id = v_order.tenant_id
    AND il.location_kind = 'kitchen'
    AND il.is_active = TRUE
  ORDER BY il.is_default_consumption DESC, il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'consumption_location_missing:%', v_order.branch_id USING ERRCODE = 'P0002';
  END IF;

  IF v_location_is_default IS DISTINCT FROM TRUE THEN
    RAISE WARNING 'default_consumption_location_missing:branch %; using kitchen location %',
      v_order.branch_id,
      v_location_id;
  END IF;

  FOR v_need IN
    SELECT
      r.ingredient_id,
      SUM(oi.quantity::NUMERIC * r.quantity / r.yield_factor) AS need_qty
    FROM public.order_items oi
    JOIN public.recipes r
      ON r.menu_item_id = oi.menu_item_id
     AND r.tenant_id = oi.tenant_id
    WHERE oi.order_id = p_order_id
      AND oi.tenant_id = v_order.tenant_id
      AND oi.status <> 'cancelled'
    GROUP BY r.ingredient_id
  LOOP
    SELECT sl.current_quantity INTO v_sl
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_order.tenant_id
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id;

    v_total := COALESCE(v_sl, 0);
    IF v_total < v_need.need_qty THEN
      RAISE EXCEPTION 'insufficient_stock_ingredient:%', v_need.ingredient_id
        USING ERRCODE = 'P0001';
    END IF;
  END LOOP;

  FOR v_need IN
    SELECT
      r.ingredient_id,
      SUM(oi.quantity::NUMERIC * r.quantity / r.yield_factor) AS need_qty
    FROM public.order_items oi
    JOIN public.recipes r
      ON r.menu_item_id = oi.menu_item_id
     AND r.tenant_id = oi.tenant_id
    WHERE oi.order_id = p_order_id
      AND oi.tenant_id = v_order.tenant_id
      AND oi.status <> 'cancelled'
    GROUP BY r.ingredient_id
  LOOP
    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, order_id, unit_cost, location_id
    )
    SELECT
      v_order.tenant_id,
      v_order.branch_id,
      v_need.ingredient_id,
      'consumption',
      -v_need.need_qty,
      'Order ' || p_order_id::TEXT,
      v_actor,
      p_order_id,
      COALESCE(sl.avg_unit_cost, 0),
      v_location_id
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_order.tenant_id
      AND sl.branch_id = v_order.branch_id
      AND sl.location_id = v_location_id
      AND sl.ingredient_id = v_need.ingredient_id;
  END LOOP;

  RETURN jsonb_build_object('order_id', p_order_id, 'consumed', true);
END;
$$;


--
-- Name: correct_payment_method(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_payment_method(p_payment_id bigint, p_new_method text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor   uuid   := auth.uid();
  v_tenant  bigint := public.auth_tenant_id();
  v_payment RECORD;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  IF p_new_method IS NULL OR p_new_method NOT IN ('cash', 'vietqr', 'momo') THEN
    RAISE EXCEPTION 'invalid method: %', p_new_method USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;
  IF length(p_reason) > 500 THEN
    RAISE EXCEPTION 'reason exceeds 500 chars' USING ERRCODE = '22023';
  END IF;

  SELECT id, tenant_id, branch_id, status, method
  INTO v_payment
  FROM public.payments
  WHERE id = p_payment_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment % not found', p_payment_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_payment.branch_id, 'orders:refund_approve') THEN
    RAISE EXCEPTION 'permission denied: orders:refund_approve required'
      USING ERRCODE = '42501';
  END IF;

  IF v_payment.status <> 'completed' THEN
    RAISE EXCEPTION 'payment_not_completed: status=%', v_payment.status
      USING ERRCODE = 'P0001';
  END IF;

  IF v_payment.method = p_new_method THEN
    RAISE EXCEPTION 'method_unchanged: already %', p_new_method
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.payments
  SET method = p_new_method,
      updated_at = now()
  WHERE id = v_payment.id;

  PERFORM public.log_audit(
    'payment.method_correct',
    'payment',
    v_payment.id,
    jsonb_build_object('method', v_payment.method),
    jsonb_build_object('method', p_new_method, 'reason', p_reason)
  );

  RETURN jsonb_build_object(
    'status',     'corrected',
    'payment_id', v_payment.id,
    'old_method', v_payment.method,
    'new_method', p_new_method
  );
END;
$$;


--
-- Name: FUNCTION correct_payment_method(p_payment_id bigint, p_new_method text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.correct_payment_method(p_payment_id bigint, p_new_method text, p_reason text) IS 'Owner-level fix for a wrongly-recorded payment method (branch-scoped orders:refund_approve, completed-payment precondition, new<>old, audited). Pure record correction — post-D020 there is no GL and the HĐĐT payment field is hardcoded TM/CK, so an issued invoice is unaffected.';


--
-- Name: count_unread_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_unread_notifications() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH ctx AS MATERIALIZED (
    SELECT
      auth.uid() AS user_id,
      public.auth_tenant_id() AS tenant_id,
      public.auth_branch_id() AS branch_id,
      public.auth_role() AS user_role
  )
  SELECT count(*)::bigint
  FROM ctx
  JOIN public.notifications n
    ON n.tenant_id = ctx.tenant_id
  WHERE ctx.user_id IS NOT NULL
    AND ctx.tenant_id IS NOT NULL
    AND ctx.user_role IS NOT NULL
    AND n.target_roles @> ARRAY[ctx.user_role]::text[]
    AND (
      n.target_branch_id IS NULL
      OR n.target_branch_id = ctx.branch_id
      OR ctx.user_role IN ('owner')
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.notification_reads r
      WHERE r.notification_id = n.id
        AND r.user_id = ctx.user_id
    )
    AND (n.expires_at IS NULL OR n.expires_at > now());
$$;


--
-- Name: create_expiry_writeoff(bigint, bigint, bigint, numeric, text, bigint, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expiry_writeoff(p_branch_id bigint, p_location_id bigint, p_ingredient_id bigint, p_quantity numeric, p_unit text, p_grn_item_id bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_photo_urls text[] DEFAULT ARRAY[]::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_loc RECORD; v_grn RECORD;
  v_shift_key text; v_issue_id bigint; v_issue_no text; v_approval text;
  v_seed_cost numeric(15, 2);
  v_source_ref jsonb := jsonb_build_object('kind', 'expiry');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:writeoff') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 THEN RAISE EXCEPTION 'quantity must be positive' USING ERRCODE = '22023'; END IF;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501'; END IF;

  SELECT id, tenant_id, branch_id, is_active INTO v_loc
    FROM public.inventory_locations WHERE id = p_location_id;
  IF NOT FOUND OR NOT v_loc.is_active OR v_loc.tenant_id <> v_tenant OR v_loc.branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'location_scope_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_grn_item_id IS NOT NULL THEN
    SELECT gi.id, gi.batch_number, gi.expiry_date, gi.grn_id INTO v_grn
      FROM public.grn_items gi
      JOIN public.goods_received_notes g ON g.id = gi.grn_id AND g.tenant_id = gi.tenant_id
     WHERE gi.id = p_grn_item_id AND gi.tenant_id = v_tenant
       AND g.branch_id = p_branch_id AND gi.ingredient_id = p_ingredient_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'grn_item_not_found' USING ERRCODE = '22023';
    END IF;
    v_source_ref := v_source_ref || jsonb_build_object(
      'grn_item_id', v_grn.id, 'grn_id', v_grn.grn_id,
      'batch_number', v_grn.batch_number, 'expiry_date', v_grn.expiry_date);
  END IF;

  v_shift_key := public.inventory_shift_key(p_branch_id, now());
  v_issue_no := 'WO-' || to_char(now(), 'YYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::text, 1, 4);

  INSERT INTO public.stock_issues (tenant_id, branch_id, issue_number, issue_type, status, notes,
    issued_at, created_by, source_location_id, approval_status, shift_key, source_type, source_ref)
  VALUES (v_tenant, p_branch_id, v_issue_no, 'writeoff', 'draft', p_note,
    now(), v_uid, p_location_id, 'not_required', v_shift_key, 'manual', v_source_ref)
  RETURNING id INTO v_issue_id;

  SELECT avg_unit_cost INTO v_seed_cost
    FROM public.stock_levels
   WHERE tenant_id = v_tenant AND branch_id = p_branch_id
     AND location_id = p_location_id AND ingredient_id = p_ingredient_id;

  INSERT INTO public.stock_issue_items (tenant_id, issue_id, ingredient_id, quantity, unit, unit_cost,
    reason_code, photo_urls, reason)
  VALUES (v_tenant, v_issue_id, p_ingredient_id, p_quantity, COALESCE(p_unit, 'kg'),
    COALESCE(v_seed_cost, 0),
    'expired', COALESCE(p_photo_urls, ARRAY[]::text[]), p_note);

  SELECT approval_status INTO v_approval FROM public.stock_issues WHERE id = v_issue_id;
  IF v_approval = 'pending' THEN
    RETURN jsonb_build_object('issue_id', v_issue_id, 'issue_number', v_issue_no,
      'requires_approval', true, 'stock_decremented', false);
  END IF;

  PERFORM public._post_writeoff_movements(v_issue_id);
  RETURN jsonb_build_object('issue_id', v_issue_id, 'issue_number', v_issue_no,
    'requires_approval', false, 'stock_decremented', true);
END;
$$;


--
-- Name: create_grn_from_po(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_grn_from_po(p_po_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id    UUID   := auth.uid();
  v_tenant_id  BIGINT := public.auth_tenant_id();
  v_po         RECORD;
  v_branch     RECORD;
  v_supplier   RECORD;
  v_grn_id     BIGINT;
  v_grn_number TEXT;
  v_count      INTEGER := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'create_grn_from_po: anonymous caller'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'create_grn_from_po: missing tenant_id claim'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_po_id IS NULL OR p_po_id <= 0 THEN
    RAISE EXCEPTION 'create_grn_from_po: invalid PO id'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT id, supplier_id, status, branch_id
    INTO v_po
    FROM public.purchase_orders
   WHERE id = p_po_id
     AND tenant_id = v_tenant_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'create_grn_from_po: PO not found in tenant scope'
      USING ERRCODE = 'no_data_found';
  END IF;
  IF v_po.status NOT IN ('sent', 'partially_received') THEN
    RAISE EXCEPTION 'create_grn_from_po: PO status not eligible'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_po.branch_id IS NULL THEN
    RAISE EXCEPTION 'create_grn_from_po: PO has no destination branch'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT id, branch_kind, is_active
    INTO v_branch
    FROM public.branches
   WHERE id = v_po.branch_id
     AND tenant_id = v_tenant_id;

  IF NOT FOUND OR NOT v_branch.is_active THEN
    RAISE EXCEPTION 'create_grn_from_po: branch inactive or out of scope'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_branch.branch_kind NOT IN ('branch', 'central_supply', 'central_kitchen') THEN
    RAISE EXCEPTION 'create_grn_from_po: branch is not a procurement site'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT id, is_active
    INTO v_supplier
    FROM public.suppliers
   WHERE id = v_po.supplier_id
     AND tenant_id = v_tenant_id;

  IF NOT FOUND OR NOT v_supplier.is_active THEN
    RAISE EXCEPTION 'create_grn_from_po: supplier inactive or out of scope'
      USING ERRCODE = 'check_violation';
  END IF;

  CREATE TEMP TABLE _grn_remaining ON COMMIT DROP AS
    WITH received AS (
      SELECT gi.ingredient_id,
             SUM(COALESCE(gi.received_quantity, 0))::NUMERIC(15,3) AS qty_done
        FROM public.grn_items gi
        JOIN public.goods_received_notes g
          ON g.id = gi.grn_id
         AND g.tenant_id = gi.tenant_id
       WHERE g.po_id = v_po.id
         AND g.tenant_id = v_tenant_id
         AND g.status = 'confirmed'
       GROUP BY gi.ingredient_id
    )
    SELECT poi.ingredient_id,
           poi.unit,
           poi.quantity::NUMERIC(15,3)                  AS po_quantity,
           COALESCE(poi.unit_price_est, 0)::NUMERIC(15,2) AS po_unit_price,
           ROUND(
             poi.quantity - COALESCE(received.qty_done, 0),
             3
           )::NUMERIC(15,3) AS remaining
      FROM public.purchase_order_items poi
      LEFT JOIN received USING (ingredient_id)
     WHERE poi.po_id = v_po.id
       AND poi.tenant_id = v_tenant_id;

  IF NOT EXISTS (SELECT 1 FROM _grn_remaining WHERE remaining > 0) THEN
    RAISE EXCEPTION 'create_grn_from_po: PO already fully received'
      USING ERRCODE = 'no_data_found';
  END IF;

  v_grn_number := 'GRN-' || substring(replace(gen_random_uuid()::TEXT, '-', '') from 1 for 8);

  INSERT INTO public.goods_received_notes (
    tenant_id, branch_id, supplier_id, po_id,
    grn_number, status, created_by
  ) VALUES (
    v_tenant_id, v_branch.id, v_supplier.id, v_po.id,
    v_grn_number, 'draft', v_user_id
  ) RETURNING id INTO v_grn_id;

  IF v_grn_id IS NULL THEN
    RAISE EXCEPTION 'create_grn_from_po: header insert blocked (RLS)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  INSERT INTO public.grn_items (
    tenant_id, grn_id, ingredient_id,
    po_quantity, po_unit_price,
    received_quantity, unit, unit_cost, total_cost,
    quality_status
  )
  SELECT v_tenant_id,
         v_grn_id,
         r.ingredient_id,
         r.po_quantity,
         r.po_unit_price,
         r.remaining,
         r.unit,
         r.po_unit_price,
         ROUND(r.remaining * r.po_unit_price, 2),
         'accepted'
    FROM _grn_remaining r
   WHERE r.remaining > 0;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'create_grn_from_po: items insert blocked (RLS)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM public.log_audit(
    'inventory.grn.created_from_po',
    'goods_received_note',
    v_grn_id,
    NULL,
    jsonb_build_object(
      'po_id',     v_po.id,
      'lines',     v_count,
      'branch_id', v_branch.id
    )
  );

  RETURN jsonb_build_object(
    'grn_id',     v_grn_id,
    'grn_number', v_grn_number,
    'lines',      v_count
  );
END;
$$;


--
-- Name: create_order(bigint, bigint, uuid, jsonb, text, bigint, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_order(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text DEFAULT 'dine_in'::text, p_table_id bigint DEFAULT NULL::bigint, p_pos_session_id bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_created_by       UUID;
  v_order_id         BIGINT;
  v_order_number     TEXT;
  v_date_part        TEXT;
  v_subtotal         NUMERIC(15,2) := 0;
  v_seq              INT;
  v_table_number     INT;
  v_item             JSONB;
  v_base_price       NUMERIC(15,2);
  v_variant_adj      NUMERIC(15,2);
  v_modifier_sum     NUMERIC(15,2);
  v_sides_sum        NUMERIC(15,2);
  v_enriched_sides   JSONB;
  v_unit_price       NUMERIC(15,2);
  v_item_subtotal    NUMERIC(15,2);
  v_menu_item_id     BIGINT;
  v_variant_id       BIGINT;
  v_quantity         INT;
  v_prof_tenant      BIGINT;
  v_prof_branch      BIGINT;
  v_prof_role        TEXT;
  v_branch_code      TEXT;
  v_item_discount    NUMERIC(15,2);
BEGIN
  v_created_by := auth.uid();
  IF v_created_by IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
    INTO v_prof_tenant, v_prof_branch, v_prof_role
    FROM public.profiles p
    LEFT JOIN public.positions po ON po.id = p.position_id
   WHERE p.id = v_created_by;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_tenant IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = p_branch_id AND b.tenant_id = p_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF p_branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = p_branch_id AND b.tenant_id = p_tenant_id;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'p_items must be a non-empty JSON array' USING ERRCODE = '22023';
  END IF;

  IF p_order_type NOT IN ('dine_in', 'takeaway') THEN
    RAISE EXCEPTION 'p_order_type must be dine_in or takeaway' USING ERRCODE = '22023';
  END IF;

  IF p_table_id IS NOT NULL THEN
    SELECT t.number INTO v_table_number
      FROM public.tables t
     WHERE t.id = p_table_id AND t.branch_id = p_branch_id AND t.tenant_id = p_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Table does not belong to this branch' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_pos_session_id IS NOT NULL THEN
    PERFORM 1 FROM public.pos_sessions
     WHERE id = p_pos_session_id
       AND branch_id = p_branch_id
       AND tenant_id = p_tenant_id
       AND status = 'open';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'POS session does not belong to this branch or is not open' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT o.id, o.order_number INTO v_order_id, v_order_number
      FROM public.orders o
     WHERE o.tenant_id = p_tenant_id
       AND o.idempotency_key = p_idempotency_key;
    IF FOUND THEN
      RETURN jsonb_build_object('order_id', v_order_id, 'order_number', v_order_number);
    END IF;
  END IF;

  INSERT INTO public.order_daily_counters (
    tenant_id, branch_id, counter_date, last_seq
  )
  VALUES (
    p_tenant_id,
    p_branch_id,
    (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    1
  )
  ON CONFLICT (tenant_id, branch_id, counter_date)
  DO UPDATE SET
    last_seq   = public.order_daily_counters.last_seq + 1,
    updated_at = now()
  RETURNING last_seq INTO v_seq;

  v_date_part := to_char(
    CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh',
    'YYMMDD'
  );

  IF p_order_type = 'dine_in' THEN
    v_order_number := 'TC-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  ELSE
    v_order_number := 'MV-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  END IF;

  IF v_branch_code IS NOT NULL THEN
    v_order_number := v_order_number || '-' || v_branch_code;
  END IF;

  BEGIN
    INSERT INTO public.orders (
      tenant_id, branch_id, table_id, order_number, order_type,
      subtotal, total_amount, note, created_by,
      pos_session_id, idempotency_key
    )
    VALUES (
      p_tenant_id, p_branch_id, p_table_id, v_order_number, p_order_type,
      0, 0, p_note, v_created_by,
      p_pos_session_id, p_idempotency_key
    )
    RETURNING id INTO v_order_id;
  EXCEPTION
    WHEN unique_violation THEN
      IF p_idempotency_key IS NOT NULL THEN
        SELECT o.id, o.order_number INTO v_order_id, v_order_number
          FROM public.orders o
         WHERE o.tenant_id = p_tenant_id
           AND o.idempotency_key = p_idempotency_key;
        IF FOUND THEN
          RETURN jsonb_build_object('order_id', v_order_id, 'order_number', v_order_number);
        END IF;
      END IF;
      RAISE;
  END;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) AS value
  LOOP
    v_menu_item_id := (v_item ->> 'menu_item_id')::BIGINT;
    v_variant_id   := NULLIF(v_item ->> 'variant_id', '')::BIGINT;
    v_quantity     := (v_item ->> 'quantity')::INT;

    IF v_quantity IS NULL OR v_quantity < 1 THEN
      RAISE EXCEPTION 'invalid quantity' USING ERRCODE = '22023';
    END IF;

    SELECT base_price INTO v_base_price
      FROM public.menu_items
     WHERE id = v_menu_item_id AND tenant_id = p_tenant_id AND is_active = TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Menu item % not found or inactive', v_menu_item_id USING ERRCODE = 'P0002';
    END IF;

    v_variant_adj := 0;
    IF v_variant_id IS NOT NULL THEN
      SELECT price_adjustment INTO v_variant_adj
        FROM public.menu_item_variants
       WHERE id = v_variant_id AND item_id = v_menu_item_id AND tenant_id = p_tenant_id AND is_active = TRUE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Variant % not found or inactive', v_variant_id USING ERRCODE = 'P0002';
      END IF;
    END IF;

    v_modifier_sum := public.pos_order_modifier_sum(
      p_tenant_id,
      v_menu_item_id,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB)
    );

    SELECT sides_sum, enriched_sides
      INTO v_sides_sum, v_enriched_sides
      FROM public.pos_enrich_order_sides(
        p_tenant_id,
        v_menu_item_id,
        COALESCE(v_item -> 'sides', '[]'::JSONB)
      );

    v_unit_price    := v_base_price + v_variant_adj + v_modifier_sum + COALESCE(v_sides_sum, 0);
    v_item_subtotal := v_unit_price * v_quantity;
    v_subtotal      := v_subtotal + v_item_subtotal;

    INSERT INTO public.order_items (
      tenant_id, order_id, menu_item_id, variant_id,
      item_name, variant_name, quantity, unit_price,
      modifiers, sides, subtotal, note,
      discount_type, discount_value, discount_note
    )
    VALUES (
      p_tenant_id, v_order_id, v_menu_item_id, v_variant_id,
      v_item ->> 'item_name', v_item ->> 'variant_name',
      v_quantity, v_unit_price,
      COALESCE(v_item -> 'modifiers', '[]'::JSONB),
      COALESCE(v_enriched_sides, '[]'::JSONB),
      v_item_subtotal, v_item ->> 'note',
      NULLIF(v_item ->> 'discount_type', ''),
      CASE WHEN NULLIF(v_item ->> 'discount_value', '') IS NOT NULL
           THEN (v_item ->> 'discount_value')::NUMERIC
           ELSE NULL END,
      NULLIF(trim(COALESCE(v_item ->> 'discount_note', '')), '')
    );
  END LOOP;

  UPDATE public.orders
     SET subtotal = v_subtotal, total_amount = v_subtotal
   WHERE id = v_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by
  )
  VALUES (p_tenant_id, v_order_id, NULL, 'new', v_created_by);

  IF p_order_type = 'dine_in' AND p_table_id IS NOT NULL THEN
    UPDATE public.tables
       SET status = 'occupied'
     WHERE id = p_table_id AND branch_id = p_branch_id AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Failed to update table status' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  PERFORM public.route_order_to_kds(v_order_id);

  SELECT COALESCE(o.item_discount_amount, 0) INTO v_item_discount
    FROM public.orders o WHERE o.id = v_order_id;

  RETURN jsonb_build_object(
    'order_id', v_order_id,
    'order_number', v_order_number,
    'item_discount_amount', v_item_discount
  );
END;
$$;


--
-- Name: create_order_with_daily_limit_hold(bigint, bigint, uuid, jsonb, text, bigint, bigint, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_order_with_daily_limit_hold(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text DEFAULT 'dine_in'::text, p_table_id bigint DEFAULT NULL::bigint, p_pos_session_id bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_daily_limit_hold_token uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_order_id bigint;
BEGIN
  IF p_daily_limit_hold_token IS NOT NULL THEN
    PERFORM set_config(
      'comtammatu.daily_limit_hold_token',
      p_daily_limit_hold_token::text,
      true
    );
  END IF;

  v_result := public.create_order(
    p_tenant_id,
    p_branch_id,
    p_created_by,
    p_items,
    p_order_type,
    p_table_id,
    p_pos_session_id,
    p_note,
    p_idempotency_key
  );

  v_order_id := NULLIF(v_result ->> 'order_id', '')::bigint;

  IF p_daily_limit_hold_token IS NOT NULL AND v_order_id IS NOT NULL THEN
    UPDATE public.branch_menu_item_daily_holds h
    SET committed_at = COALESCE(h.committed_at, now()),
        order_id = COALESCE(h.order_id, v_order_id),
        updated_at = now()
    WHERE h.tenant_id = p_tenant_id
      AND h.branch_id = p_branch_id
      AND h.hold_token = p_daily_limit_hold_token
      AND h.held_by = v_uid
      AND h.committed_at IS NULL
      AND h.released_at IS NULL
      AND h.expires_at > now();
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION create_order_with_daily_limit_hold(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text, p_table_id bigint, p_pos_session_id bigint, p_note text, p_idempotency_key uuid, p_daily_limit_hold_token uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_order_with_daily_limit_hold(p_tenant_id bigint, p_branch_id bigint, p_created_by uuid, p_items jsonb, p_order_type text, p_table_id bigint, p_pos_session_id bigint, p_note text, p_idempotency_key uuid, p_daily_limit_hold_token uuid) IS 'Wrapper around create_order that sets transaction-local daily-limit hold token so the quota trigger excludes the caller hold, then commits matching active holds to the new order.';


--
-- Name: create_payment(bigint, bigint, bigint, text, numeric, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payment(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_method text, p_amount numeric, p_created_by uuid, p_provider_ref text DEFAULT NULL::text, p_status text DEFAULT 'pending'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order                        RECORD;
  v_payment_id                   BIGINT;
  v_existing_payment_id          BIGINT;
  v_existing_status              TEXT;
  v_existing_method              TEXT;
  v_effective_method             TEXT;
  v_final_status                 TEXT;
  v_skip_completion_side_effects BOOLEAN := FALSE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_created_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'actor_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_method NOT IN ('cash', 'momo') THEN
    RAISE EXCEPTION 'invalid payment method: %. VietQR uses confirm_vietqr_payment.',
      p_method USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'permission denied: pos:use' USING ERRCODE = '42501';
  END IF;

  SELECT id, total_amount, tax_amount, payment_status, branch_id, tenant_id
  INTO v_order
  FROM public.orders
  WHERE id        = p_order_id
    AND tenant_id = p_tenant_id
    AND branch_id = p_branch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.payment_status = 'paid' THEN
    RAISE EXCEPTION 'order_already_paid' USING ERRCODE = 'P0001';
  END IF;

  IF p_amount <> v_order.total_amount THEN
    RAISE EXCEPTION 'amount_mismatch: expected % got %', v_order.total_amount, p_amount
      USING ERRCODE = '22023';
  END IF;

  v_final_status := CASE
    WHEN p_method = 'cash' THEN 'completed'
    ELSE COALESCE(p_status, 'pending')
  END;
  v_effective_method := p_method;

  SELECT id, status, method
  INTO v_existing_payment_id, v_existing_status, v_existing_method
  FROM public.payments
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND order_id  = p_order_id
    AND status   <> 'failed'
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_status = 'completed' THEN
    v_payment_id                   := v_existing_payment_id;
    v_final_status                 := 'completed';
    v_effective_method             := v_existing_method;
    v_skip_completion_side_effects := TRUE;
  ELSIF v_existing_status = 'pending' THEN
    UPDATE public.payments
    SET method = p_method, amount = p_amount, status = v_final_status,
        provider_ref = p_provider_ref, provider_data = NULL,
        paid_at = CASE WHEN v_final_status = 'completed' THEN now() ELSE NULL END,
        updated_at = now()
    WHERE id = v_existing_payment_id
    RETURNING id INTO v_payment_id;
  ELSIF v_existing_payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'payment_not_pending: status=%', v_existing_status USING ERRCODE = '22023';
  ELSE
    INSERT INTO public.payments (
      tenant_id, branch_id, order_id, method, amount, status, provider_ref, paid_at, created_by
    ) VALUES (
      p_tenant_id, p_branch_id, p_order_id, p_method, p_amount, v_final_status, p_provider_ref,
      CASE WHEN v_final_status = 'completed' THEN now() ELSE NULL END, p_created_by
    )
    RETURNING id INTO v_payment_id;
  END IF;

  UPDATE public.orders
  SET payment_method = v_effective_method,
      payment_status = CASE WHEN v_final_status = 'completed' THEN 'paid' ELSE payment_status END,
      updated_at = now()
  WHERE id = p_order_id;

  IF v_final_status = 'completed' AND NOT v_skip_completion_side_effects THEN
    PERFORM public.finalize_paid_order(p_order_id, p_created_by);
  END IF;

  RETURN jsonb_build_object('payment_id', v_payment_id, 'status', v_final_status, 'idempotent', v_skip_completion_side_effects);
END;
$$;


--
-- Name: FUNCTION create_payment(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_method text, p_amount numeric, p_created_by uuid, p_provider_ref text, p_status text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_payment(p_tenant_id bigint, p_branch_id bigint, p_order_id bigint, p_method text, p_amount numeric, p_created_by uuid, p_provider_ref text, p_status text) IS 'Atomic POS payment creation for cash and MoMo only. VietQR is handled by confirm_vietqr_payment. No longer sets orders.payment_status=pending — the order stays unpaid until payment is confirmed (completed). This unblocks split/merge/edit while a MoMo QR is pending.';


--
-- Name: create_production_order(bigint, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_production_order(p_branch_id bigint, p_production_number text, p_notes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    UUID   := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_branch RECORD;
  v_order_id BIGINT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:production_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_production_number IS NULL OR btrim(p_production_number) = '' THEN
    RAISE EXCEPTION 'production_number_required' USING ERRCODE = '22023';
  END IF;

  SELECT id, branch_kind INTO v_branch
  FROM public.branches
  WHERE id = p_branch_id AND tenant_id = v_tenant AND is_active = TRUE
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_branch.branch_kind NOT IN ('branch', 'central_kitchen') THEN
    RAISE EXCEPTION 'branch_must_be_operational' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.production_orders (
    tenant_id, branch_id, production_number, status, notes, created_by
  )
  VALUES (v_tenant, p_branch_id, p_production_number, 'draft', p_notes, v_uid)
  RETURNING id INTO v_order_id;

  IF p_items IS NOT NULL AND jsonb_typeof(p_items) = 'array' THEN
    INSERT INTO public.production_order_items (
      tenant_id, production_order_id, finished_good_id, quantity, unit
    )
    SELECT v_tenant, v_order_id,
      (line->>'finishedGoodId')::BIGINT,
      (line->>'quantity')::NUMERIC(15,3),
      NULLIF(btrim(line->>'unit'), '')
    FROM jsonb_array_elements(p_items) AS line
    WHERE line ? 'finishedGoodId' AND line ? 'quantity' AND line ? 'unit'
    ON CONFLICT (production_order_id, finished_good_id, tenant_id)
    DO UPDATE SET quantity = EXCLUDED.quantity, unit = EXCLUDED.unit;
  END IF;

  RETURN jsonb_build_object('id', v_order_id);
END;
$$;


--
-- Name: create_purchase_order_with_lines(bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_purchase_order_with_lines(p_supplier_id bigint, p_branch_id bigint, p_notes text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid       uuid    := auth.uid();
  v_tenant_id bigint  := public.auth_tenant_id();
  v_branch    RECORD;
  v_po_id     bigint;
  v_display   text;
  v_count     integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission_any('procurement:po_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array'
     OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'invalid_po_lines' USING ERRCODE = '22023';
  END IF;

  SELECT id, branch_kind, is_active INTO v_branch
    FROM public.branches
   WHERE id = p_branch_id AND tenant_id = v_tenant_id;
  IF NOT FOUND OR NOT v_branch.is_active
     OR v_branch.branch_kind NOT IN ('branch', 'central_supply', 'central_kitchen') THEN
    RAISE EXCEPTION 'invalid_branch' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.suppliers
     WHERE id = p_supplier_id AND tenant_id = v_tenant_id AND is_active
  ) THEN
    RAISE EXCEPTION 'invalid_supplier' USING ERRCODE = 'P0002';
  END IF;

  v_display := public.next_po_display_id(v_tenant_id);

  INSERT INTO public.purchase_orders (
    tenant_id, branch_id, supplier_id, po_number, display_id, status, notes, created_by
  ) VALUES (
    v_tenant_id, p_branch_id, p_supplier_id, v_display, v_display, 'draft',
    NULLIF(btrim(p_notes), ''), v_uid
  ) RETURNING id INTO v_po_id;

  INSERT INTO public.purchase_order_items (
    tenant_id, po_id, ingredient_id, quantity, unit, unit_price_est, line_total
  )
  SELECT
    v_tenant_id, v_po_id, x.ingredient_id, x.quantity, x.unit, x.unit_price_est,
    CASE WHEN x.unit_price_est IS NULL THEN NULL
         ELSE round(x.quantity * x.unit_price_est, 2) END
  FROM jsonb_to_recordset(p_lines) AS x(
    ingredient_id  bigint,
    quantity       numeric,
    unit           text,
    unit_price_est numeric
  )
  ON CONFLICT (po_id, ingredient_id, tenant_id) DO UPDATE SET
    quantity       = EXCLUDED.quantity,
    unit           = EXCLUDED.unit,
    unit_price_est = EXCLUDED.unit_price_est,
    line_total     = EXCLUDED.line_total;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN
    RAISE EXCEPTION 'invalid_po_lines' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object('id', v_po_id, 'display_id', v_display, 'lines', v_count);
END;
$$;


--
-- Name: create_refund(bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_refund(p_payment_id bigint, p_amount numeric, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor     UUID   := auth.uid();
  v_tenant    BIGINT := public.auth_tenant_id();
  v_payment   RECORD;
  v_refund_id BIGINT;
  v_already   NUMERIC(15,2) := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid amount' USING ERRCODE = 'P0001';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;
  IF length(p_reason) > 500 THEN
    RAISE EXCEPTION 'reason exceeds 500 chars' USING ERRCODE = '22023';
  END IF;

  SELECT id, tenant_id, branch_id, order_id, amount, status, method
  INTO v_payment
  FROM public.payments
  WHERE id = p_payment_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment % not found', p_payment_id
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_payment.branch_id, 'orders:refund') THEN
    RAISE EXCEPTION 'permission denied: orders:refund required'
      USING ERRCODE = '42501';
  END IF;

  IF v_payment.status <> 'completed' THEN
    RAISE EXCEPTION 'payment_not_completed: status=%', v_payment.status
      USING ERRCODE = 'P0001';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_already
  FROM public.refunds
  WHERE payment_id = v_payment.id
    AND status IN ('pending', 'approved');

  IF v_already + p_amount > v_payment.amount THEN
    RAISE EXCEPTION 'refund_exceeds_remaining: already=%, requested=%, payment=%',
      v_already, p_amount, v_payment.amount USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.refunds
    (tenant_id, branch_id, payment_id, order_id, amount, reason, status, created_by)
  VALUES
    (v_payment.tenant_id, v_payment.branch_id, v_payment.id, v_payment.order_id,
     p_amount, p_reason, 'pending', v_actor)
  RETURNING id INTO v_refund_id;

  PERFORM public.log_audit(
    'refund.create',
    'refund',
    v_refund_id,
    NULL,
    jsonb_build_object(
      'payment_id', v_payment.id,
      'order_id',   v_payment.order_id,
      'amount',     p_amount,
      'method',     v_payment.method
    )
  );

  RETURN jsonb_build_object(
    'status',    'created',
    'refund_id', v_refund_id
  );
END;
$$;


--
-- Name: FUNCTION create_refund(p_payment_id bigint, p_amount numeric, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_refund(p_payment_id bigint, p_amount numeric, p_reason text) IS 'Creates pending refunds with branch-scoped orders:refund permission, completed-payment precondition, cumulative refund cap, and audit logging.';


--
-- Name: create_stock_transfer_draft(bigint, bigint, text, text, text, jsonb, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_transfer_draft(p_from_branch_id bigint, p_to_branch_id bigint, p_transfer_number text, p_notes text DEFAULT NULL::text, p_vehicle_info text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb, p_from_location_id bigint DEFAULT NULL::bigint, p_to_location_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_role         TEXT := public.auth_role();
  v_transfer_id  BIGINT;
  v_is_intra     BOOLEAN := (p_from_branch_id = p_to_branch_id);
  v_from_kind    TEXT;
  v_to_kind      TEXT;
  v_from_loc     RECORD;
  v_to_loc       RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT branch_kind INTO v_from_kind
  FROM public.branches
  WHERE id = p_from_branch_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  SELECT branch_kind INTO v_to_kind
  FROM public.branches
  WHERE id = p_to_branch_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  IF v_from_kind IS NULL OR v_to_kind IS NULL THEN
    RAISE EXCEPTION 'transfer_branch_invalid' USING ERRCODE = '23514';
  END IF;

  IF p_from_location_id IS NULL THEN
    RAISE EXCEPTION 'transfer_from_location_missing' USING ERRCODE = '23502';
  END IF;

  IF p_to_location_id IS NULL THEN
    RAISE EXCEPTION 'transfer_to_location_missing' USING ERRCODE = '23502';
  END IF;

  SELECT id, branch_id, location_kind, is_default_consumption
  INTO v_from_loc
  FROM public.inventory_locations
  WHERE id = p_from_location_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  IF NOT FOUND OR v_from_loc.branch_id <> p_from_branch_id THEN
    RAISE EXCEPTION 'transfer_from_location_invalid' USING ERRCODE = '23514';
  END IF;

  SELECT id, branch_id, location_kind, is_default_consumption
  INTO v_to_loc
  FROM public.inventory_locations
  WHERE id = p_to_location_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  IF NOT FOUND OR v_to_loc.branch_id <> p_to_branch_id THEN
    RAISE EXCEPTION 'transfer_to_location_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_is_intra THEN
    IF v_from_kind <> 'branch' OR v_to_kind <> 'branch' THEN
      RAISE EXCEPTION 'intra_branch_requires_branch_site' USING ERRCODE = '23514';
    END IF;

    IF p_from_location_id = p_to_location_id THEN
      RAISE EXCEPTION 'intra_branch_same_location' USING ERRCODE = '22023';
    END IF;

    IF v_from_loc.location_kind <> 'warehouse' THEN
      RAISE EXCEPTION 'intra_branch_source_must_be_warehouse' USING ERRCODE = '23514';
    END IF;

    IF v_to_loc.location_kind <> 'kitchen' THEN
      RAISE EXCEPTION 'intra_branch_target_must_be_kitchen' USING ERRCODE = '23514';
    END IF;

    IF v_to_loc.is_default_consumption IS DISTINCT FROM TRUE THEN
      RAISE WARNING 'default_consumption_location_not_marked:branch %, location %',
        p_to_branch_id,
        p_to_location_id;
    END IF;
  ELSE
    IF v_role = 'branch_manager' THEN
      RAISE EXCEPTION 'branch_manager_inter_site_create_forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NOT public.has_permission(p_from_branch_id, 'inventory:transfer_create') THEN
    RAISE EXCEPTION 'forbidden_transfer_create' USING ERRCODE = '42501';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'transfer_lines_invalid' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_lines) AS line(value)
    LEFT JOIN public.ingredients i
      ON i.id = (line.value->>'ingredientId')::BIGINT
     AND i.tenant_id = v_tenant
    WHERE NOT (line.value ? 'ingredientId')
       OR NOT (line.value ? 'quantity')
       OR NOT (line.value ? 'unit')
       OR (line.value->>'quantity')::NUMERIC <= 0
       OR NULLIF(BTRIM(line.value->>'unit'), '') IS NULL
       OR i.id IS NULL
  ) THEN
    RAISE EXCEPTION 'transfer_lines_invalid' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.stock_transfers (
    tenant_id,
    from_branch_id,
    to_branch_id,
    from_location_id,
    to_location_id,
    transfer_number,
    status,
    notes,
    vehicle_info,
    created_by
  ) VALUES (
    v_tenant,
    p_from_branch_id,
    p_to_branch_id,
    p_from_location_id,
    p_to_location_id,
    p_transfer_number,
    'draft',
    p_notes,
    CASE WHEN v_is_intra THEN NULL ELSE p_vehicle_info END,
    v_uid
  )
  RETURNING id INTO v_transfer_id;

  INSERT INTO public.stock_transfer_items (
    tenant_id,
    transfer_id,
    ingredient_id,
    quantity,
    unit,
    unit_cost_at_ship
  )
  SELECT
    v_tenant,
    v_transfer_id,
    (line.value->>'ingredientId')::BIGINT,
    (line.value->>'quantity')::NUMERIC(15,3),
    NULLIF(BTRIM(line.value->>'unit'), ''),
    (
      SELECT sl.avg_unit_cost
      FROM public.stock_levels sl
      WHERE sl.tenant_id = v_tenant
        AND sl.branch_id = p_from_branch_id
        AND sl.location_id = p_from_location_id
        AND sl.ingredient_id = (line.value->>'ingredientId')::BIGINT
      LIMIT 1
    )
  FROM jsonb_array_elements(p_lines) AS line(value)
  ON CONFLICT (transfer_id, ingredient_id, tenant_id)
  DO UPDATE SET
    quantity = EXCLUDED.quantity,
    unit = EXCLUDED.unit,
    unit_cost_at_ship = EXCLUDED.unit_cost_at_ship;

  RETURN jsonb_build_object('id', v_transfer_id, 'status', 'draft');
END;
$$;


--
-- Name: create_stocktake_session(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stocktake_session(p_branch_id bigint, p_location_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_session_id BIGINT; v_loc_id BIGINT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = '22023'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:stocktake_create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_location_id IS NOT NULL THEN
    SELECT il.id INTO v_loc_id FROM public.inventory_locations il
    WHERE il.id = p_location_id AND il.branch_id = p_branch_id AND il.tenant_id = v_tenant AND il.is_active = TRUE;
    IF NOT FOUND THEN RAISE EXCEPTION 'location_not_found_or_inactive' USING ERRCODE = 'P0002'; END IF;
  ELSE
    SELECT il.id INTO v_loc_id FROM public.inventory_locations il
    WHERE il.branch_id = p_branch_id AND il.tenant_id = v_tenant
      AND il.is_default_receive = TRUE AND il.is_active = TRUE LIMIT 1;
  END IF;

  INSERT INTO public.stocktake_sessions (tenant_id, branch_id, location_id, created_by)
  VALUES (v_tenant, p_branch_id, v_loc_id, v_uid) RETURNING id INTO v_session_id;

  INSERT INTO public.stocktake_lines (tenant_id, session_id, ingredient_id, system_quantity)
  SELECT v_tenant, v_session_id, sl.ingredient_id, sl.current_quantity
  FROM public.stock_levels sl WHERE sl.tenant_id = v_tenant AND sl.branch_id = p_branch_id;

  RETURN jsonb_build_object('id', v_session_id);
END;
$$;


--
-- Name: create_supplier_payment(bigint, bigint, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_payment(p_tenant_id bigint, p_supplier_invoice_id bigint, p_amount numeric, p_payment_method text, p_reference_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid(); v_invoice RECORD; v_branch_id BIGINT;
  v_payment_id BIGINT; v_new_paid NUMERIC(15,2); v_new_status TEXT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission_any('finance:ap_pay') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501'; END IF;
  IF p_payment_method NOT IN ('cash','bank_transfer') THEN RAISE EXCEPTION 'invalid_payment_method' USING ERRCODE = '22023'; END IF;

  SELECT si.* INTO v_invoice FROM public.supplier_invoices si
   WHERE si.id = p_supplier_invoice_id AND si.tenant_id = p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_invoice.payment_status = 'paid' THEN RAISE EXCEPTION 'invoice_already_paid' USING ERRCODE = 'P0001'; END IF;

  v_new_paid := COALESCE(v_invoice.paid_amount, 0) + p_amount;
  IF v_new_paid > v_invoice.total_amount THEN RAISE EXCEPTION 'payment_exceeds_invoice_total' USING ERRCODE = '22023'; END IF;
  v_new_status := CASE WHEN v_new_paid >= v_invoice.total_amount THEN 'paid' ELSE 'partial' END;

  SELECT branch_id INTO v_branch_id FROM public.goods_received_notes WHERE id = v_invoice.grn_id;
  IF v_branch_id IS NULL THEN
    SELECT branch_id INTO v_branch_id FROM public.purchase_orders WHERE id = v_invoice.po_id;
  END IF;

  INSERT INTO public.supplier_payments (tenant_id, supplier_invoice_id, payment_method, amount, payment_date, reference_note, created_by)
  VALUES (p_tenant_id, p_supplier_invoice_id, p_payment_method, p_amount, now(), p_reference_note, v_uid)
  RETURNING id INTO v_payment_id;

  UPDATE public.supplier_invoices
     SET payment_status = v_new_status, paid_amount = v_new_paid,
         paid_at = CASE WHEN v_new_status = 'paid' THEN now() ELSE paid_at END, updated_at = now()
   WHERE id = p_supplier_invoice_id;

  RETURN jsonb_build_object('payment_id', v_payment_id, 'payment_status', v_new_status);
END;
$$;


--
-- Name: create_supplier_return_from_grn(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_return_from_grn(p_grn_id bigint, p_resolution text DEFAULT 'replacement'::text, p_reason text DEFAULT 'damaged'::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     UUID   := auth.uid();
  v_tenant  BIGINT := public.auth_tenant_id();
  v_grn     RECORD;
  v_return_id BIGINT;
  v_ret_num   TEXT;
  v_total     NUMERIC(15,2) := 0;
  v_lines_inserted INT := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_resolution NOT IN ('replacement','credit_note','cash_refund') THEN
    RAISE EXCEPTION 'invalid_resolution' USING ERRCODE = '22023';
  END IF;
  IF p_reason NOT IN ('damaged','wrong_item','expired','quality_fail','short_delivery_credit','other') THEN
    RAISE EXCEPTION 'invalid_reason' USING ERRCODE = '22023';
  END IF;

  SELECT g.* INTO v_grn
  FROM public.goods_received_notes g
  WHERE g.id = p_grn_id AND g.tenant_id = v_tenant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'grn_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_grn.branch_id, 'supplier_return:create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.grn_items gi
    WHERE gi.grn_id = p_grn_id
      AND gi.tenant_id = v_tenant
      AND (gi.quality_status = 'rejected' OR COALESCE(gi.rejected_quantity,0) > 0)
  ) THEN
    RAISE EXCEPTION 'no_rejected_lines' USING ERRCODE = '22023';
  END IF;

  v_ret_num := 'SR-' || to_char(now(),'YYMMDD') || '-' || lpad(nextval('public.supplier_returns_id_seq')::TEXT, 4, '0');

  INSERT INTO public.supplier_returns (
    tenant_id, branch_id, supplier_id, grn_id, return_number,
    source, reason, resolution, status, notes, total_value, created_by
  ) VALUES (
    v_tenant, v_grn.branch_id, v_grn.supplier_id, p_grn_id, v_ret_num,
    'grn_reject', p_reason, p_resolution, 'draft', p_notes, 0, v_uid
  ) RETURNING id INTO v_return_id;

  -- Copy rejected lines (rejected_quantity if set, else full received_quantity when status='rejected')
  WITH rej AS (
    INSERT INTO public.supplier_return_items (
      tenant_id, return_id, ingredient_id, quantity, unit, unit_cost, total_cost,
      grn_item_id, reason_detail, photo_url
    )
    SELECT
      v_tenant,
      v_return_id,
      gi.ingredient_id,
      CASE
        WHEN gi.quality_status = 'rejected' AND COALESCE(gi.rejected_quantity,0) = 0
          THEN gi.received_quantity
        ELSE gi.rejected_quantity
      END,
      gi.unit,
      gi.unit_cost,
      ROUND(
        CASE
          WHEN gi.quality_status = 'rejected' AND COALESCE(gi.rejected_quantity,0) = 0
            THEN gi.received_quantity
          ELSE gi.rejected_quantity
        END * gi.unit_cost, 2
      ),
      gi.id,
      gi.rejection_reason,
      gi.rejected_photo_url
    FROM public.grn_items gi
    WHERE gi.grn_id = p_grn_id
      AND gi.tenant_id = v_tenant
      AND (gi.quality_status = 'rejected' OR COALESCE(gi.rejected_quantity,0) > 0)
    RETURNING total_cost
  )
  SELECT COALESCE(SUM(total_cost), 0), COUNT(*) INTO v_total, v_lines_inserted FROM rej;

  UPDATE public.supplier_returns SET total_value = v_total WHERE id = v_return_id;

  RETURN jsonb_build_object(
    'return_id', v_return_id,
    'return_number', v_ret_num,
    'lines', v_lines_inserted,
    'total_value', v_total
  );
END;
$$;


--
-- Name: create_supplier_return_from_stock(bigint, bigint, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_supplier_return_from_stock(p_branch_id bigint, p_supplier_id bigint, p_resolution text, p_reason text, p_notes text, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid     UUID   := auth.uid();
  v_tenant  BIGINT := public.auth_tenant_id();
  v_branch  RECORD;
  v_return_id BIGINT;
  v_ret_num   TEXT;
  v_total     NUMERIC(15,2) := 0;
  v_line      JSONB;
  v_ing_id    BIGINT;
  v_qty       NUMERIC(15,3);
  v_unit_cost NUMERIC(15,2);
  v_unit      TEXT;
  v_lines_inserted INT := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'supplier_return:create') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_resolution NOT IN ('replacement','credit_note','cash_refund') THEN
    RAISE EXCEPTION 'invalid_resolution' USING ERRCODE = '22023';
  END IF;
  IF p_reason NOT IN ('damaged','wrong_item','expired','quality_fail','short_delivery_credit','other') THEN
    RAISE EXCEPTION 'invalid_reason' USING ERRCODE = '22023';
  END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'no_lines' USING ERRCODE = '22023';
  END IF;

  SELECT b.id, b.branch_kind INTO v_branch
  FROM public.branches b
  WHERE b.id = p_branch_id AND b.tenant_id = v_tenant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_ret_num := 'SR-' || to_char(now(),'YYMMDD') || '-' || lpad(nextval('public.supplier_returns_id_seq')::TEXT, 4, '0');

  INSERT INTO public.supplier_returns (
    tenant_id, branch_id, supplier_id, grn_id, return_number,
    source, reason, resolution, status, notes, total_value, created_by
  ) VALUES (
    v_tenant, p_branch_id, p_supplier_id, NULL, v_ret_num,
    'post_receipt', p_reason, p_resolution, 'draft', p_notes, 0, v_uid
  ) RETURNING id INTO v_return_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    v_ing_id    := (v_line->>'ingredient_id')::BIGINT;
    v_qty       := (v_line->>'quantity')::NUMERIC(15,3);
    v_unit_cost := (v_line->>'unit_cost')::NUMERIC(15,2);

    IF v_ing_id IS NULL OR v_qty IS NULL OR v_qty <= 0 OR v_unit_cost IS NULL THEN
      RAISE EXCEPTION 'invalid_line' USING ERRCODE = '22023';
    END IF;

    SELECT i.unit INTO v_unit
    FROM public.ingredients i
    WHERE i.id = v_ing_id AND i.tenant_id = v_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO public.supplier_return_items (
      tenant_id, return_id, ingredient_id, quantity, unit, unit_cost, total_cost,
      reason_detail, photo_url
    ) VALUES (
      v_tenant, v_return_id, v_ing_id, v_qty, v_unit, v_unit_cost,
      ROUND(v_qty * v_unit_cost, 2),
      v_line->>'reason_detail', v_line->>'photo_url'
    );
    v_total := v_total + ROUND(v_qty * v_unit_cost, 2);
    v_lines_inserted := v_lines_inserted + 1;
  END LOOP;

  UPDATE public.supplier_returns SET total_value = v_total WHERE id = v_return_id;

  RETURN jsonb_build_object(
    'return_id', v_return_id,
    'return_number', v_ret_num,
    'lines', v_lines_inserted,
    'total_value', v_total
  );
END;
$$;


--
-- Name: create_waste_entry(bigint, bigint, jsonb, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_waste_entry(p_branch_id bigint, p_location_id bigint, p_items jsonb, p_source_type text DEFAULT 'manual'::text, p_source_ref jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid(); v_tenant BIGINT; v_location RECORD; v_shift_key TEXT; v_issue_id BIGINT;
  v_issue_no TEXT; v_item JSONB; v_photos TEXT[]; v_created INT := 0; v_needs_appr BOOLEAN := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:writeoff') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  SELECT tenant_id INTO v_tenant FROM public.branches WHERE id = p_branch_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002'; END IF;
  SELECT tenant_id, branch_id INTO v_location FROM public.inventory_locations WHERE id = p_location_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'location_scope_mismatch' USING ERRCODE = '42501';
  END IF;
  IF v_location.tenant_id <> v_tenant OR v_location.branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'location_scope_mismatch' USING ERRCODE = '42501';
  END IF;
  v_shift_key := public.inventory_shift_key(p_branch_id, now());
  v_issue_no := 'WO-' || to_char(now(), 'YYMMDDHH24MISS') || '-' || substr(gen_random_uuid()::TEXT, 1, 4);
  INSERT INTO public.stock_issues (tenant_id, branch_id, issue_number, issue_type, status, notes,
    issued_at, created_by, source_location_id, approval_status, shift_key, source_type, source_ref)
  VALUES (v_tenant, p_branch_id, v_issue_no, 'writeoff', 'draft', p_notes,
    now(), v_uid, p_location_id, 'not_required', v_shift_key, COALESCE(p_source_type, 'manual'), p_source_ref)
  RETURNING id INTO v_issue_id;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_photos := CASE WHEN v_item ? 'photo_urls'
                     THEN ARRAY(SELECT jsonb_array_elements_text(v_item->'photo_urls'))
                     ELSE ARRAY[]::TEXT[] END;
    INSERT INTO public.stock_issue_items (tenant_id, issue_id, ingredient_id, quantity, unit, unit_cost,
      reason_code, photo_urls, reason)
    VALUES (v_tenant, v_issue_id, (v_item->>'ingredient_id')::BIGINT, (v_item->>'quantity')::NUMERIC,
      COALESCE(v_item->>'unit', 'kg'), NULLIF(v_item->>'unit_cost','')::NUMERIC,
      v_item->>'reason_code', v_photos, v_item->>'note');
    v_created := v_created + 1;
  END LOOP;
  SELECT bool_or(approval_required) INTO v_needs_appr FROM public.stock_issue_items WHERE issue_id = v_issue_id;
  -- Tier0 (no approval): post the decrementing movements + confirm. Tier2 stays
  -- draft/pending for approve_waste.
  IF NOT COALESCE(v_needs_appr, false) THEN
    PERFORM public._post_writeoff_movements(v_issue_id);
  END IF;
  RETURN jsonb_build_object('issue_id', v_issue_id, 'issue_number', v_issue_no,
    'shift_key', v_shift_key, 'items_created', v_created, 'requires_approval', COALESCE(v_needs_appr, false));
END; $$;


--
-- Name: create_waste_from_order(bigint, bigint, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_waste_from_order(p_order_id bigint, p_location_id bigint, p_source_type text, p_items jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_order RECORD; v_default_reason TEXT; v_items_norm JSONB;
BEGIN
  IF p_source_type NOT IN ('pos_return','kds_cancel_mid_cook','kds_cancel_after_cook') THEN
    RAISE EXCEPTION 'source_type must be pos_return / kds_cancel_mid_cook / kds_cancel_after_cook' USING ERRCODE = '22023';
  END IF;
  IF p_source_type = 'pos_return' THEN v_default_reason := 'customer_return';
  ELSE v_default_reason := p_source_type; END IF;
  SELECT id, branch_id INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002'; END IF;
  SELECT jsonb_agg(CASE WHEN item ? 'reason_code' THEN item ELSE item || jsonb_build_object('reason_code', v_default_reason) END)
    INTO v_items_norm FROM jsonb_array_elements(p_items) AS item;
  RETURN public.create_waste_entry(v_order.branch_id, p_location_id, v_items_norm,
    p_source_type, jsonb_build_object('order_id', p_order_id), COALESCE(p_note, 'Auto from order #' || p_order_id::TEXT));
END; $$;


--
-- Name: current_position(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_position() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT COALESCE(po.code, pr.role::text)
  FROM public.profiles pr
  LEFT JOIN public.positions po ON po.id = pr.position_id
  WHERE pr.id = auth.uid()
  LIMIT 1;
$$;


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  claims jsonb;
  user_profile record;
BEGIN
  claims := event -> 'claims';
  claims := jsonb_set(
    claims,
    '{app_metadata}',
    COALESCE(claims -> 'app_metadata', '{}'::jsonb)
    - ('ar' || 'ea_' || 'id')
    - 'tenant_id'
    - 'branch_id'
    - 'user_role'
    - 'role'
    - 'access_bucket'
    - 'position'
    - 'position_code'
  );

  SELECT
    p.tenant_id,
    p.branch_id,
    private.staff_role_from_position_code(po.code) AS access_bucket,
    po.code AS position_code
  INTO user_profile
  FROM public.profiles p
  JOIN public.positions po
    ON po.id = p.position_id
   AND po.tenant_id = p.tenant_id
  WHERE p.id = (event ->> 'user_id')::uuid
    AND COALESCE(p.is_active, true) = true
  LIMIT 1;

  IF user_profile.tenant_id IS NOT NULL THEN
    IF user_profile.access_bucket IS NULL THEN
      RAISE EXCEPTION
        'custom_access_token_hook: position_role_not_resolved for position=% tenant=%',
        user_profile.position_code, user_profile.tenant_id
        USING ERRCODE = 'P0001';
    END IF;

    claims := jsonb_set(
      claims,
      '{app_metadata}',
      COALESCE(claims -> 'app_metadata', '{}'::jsonb) ||
      jsonb_build_object(
        'tenant_id', user_profile.tenant_id,
        'branch_id', user_profile.branch_id,
        'user_role', user_profile.access_bucket,
        'role', user_profile.access_bucket,
        'access_bucket', user_profile.access_bucket,
        'position', user_profile.position_code,
        'position_code', user_profile.position_code
      )
    );
  END IF;

  event := jsonb_set(event, '{claims}', claims);
  RETURN event;
END;
$$;


--
-- Name: FUNCTION custom_access_token_hook(event jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.custom_access_token_hook(event jsonb) IS 'Auth hook emits tenant/branch plus position and compatibility access bucket claims.';


--
-- Name: decrement_branch_menu_daily_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_branch_menu_daily_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_branch_id  BIGINT;
  v_order_date DATE;
  v_target     RECORD;
BEGIN
  IF OLD.status = 'cancelled' OR NEW.status <> 'cancelled' THEN
    RETURN NEW;
  END IF;

  SELECT o.branch_id,
         (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  INTO v_branch_id, v_order_date
  FROM public.orders o
  WHERE o.id = NEW.order_id;

  IF v_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_target IN
    WITH agg AS (
      SELECT OLD.menu_item_id::BIGINT AS item_id,
             OLD.quantity::INT        AS need_qty
      UNION ALL
      SELECT (s.elem ->> 'side_item_id')::BIGINT,
             (OLD.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::INT, 1))::INT
      FROM jsonb_array_elements(COALESCE(OLD.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT item_id, SUM(need_qty)::INT AS need_qty
    FROM agg
    WHERE item_id IS NOT NULL
    GROUP BY item_id
    ORDER BY item_id ASC
  LOOP
    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = GREATEST(0, sold_today - v_target.need_qty)
    WHERE branch_id    = v_branch_id
      AND menu_item_id = v_target.item_id
      AND limit_date   = v_order_date;
  END LOOP;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION decrement_branch_menu_daily_limit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.decrement_branch_menu_daily_limit() IS 'AFTER UPDATE OF status on order_items (→ cancelled): symmetric decrement using OLD.menu_item_id + OLD.sides aggregated by menu_item_id ASC. Bounded at 0 via GREATEST.';


--
-- Name: edit_pending_order_item(bigint, bigint, text, numeric, jsonb, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_pending_order_item(p_order_item_id bigint, p_variant_id bigint, p_variant_name text, p_unit_price numeric, p_modifiers jsonb, p_sides jsonb, p_note text, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid            UUID;
  v_prof_tenant    BIGINT;
  v_prof_branch    BIGINT;
  v_prof_role      TEXT;
  v_item           public.order_items%ROWTYPE;
  v_order          public.orders%ROWTYPE;
  v_menu_active    BOOLEAN;
  v_base_price     NUMERIC(15,2);
  v_variant_adj    NUMERIC(15,2) := 0;
  v_modifier_sum   NUMERIC(15,2) := 0;
  v_sides_sum      NUMERIC(15,2) := 0;
  v_enriched_sides JSONB := '[]'::JSONB;
  v_new_unit       NUMERIC(15,2);
  v_old_qty        INT;
  v_old_unit       NUMERIC(15,2);
  v_new_subtotal   NUMERIC(15,2);
  v_subtotal_sum   NUMERIC(15,2);
  v_disc_amount    NUMERIC(15,2);
  v_total_amount   NUMERIC(15,2);
  v_flag_enabled   TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_quantity IS NULL OR p_quantity < 1 THEN
    RAISE EXCEPTION 'quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  IF p_unit_price IS NULL OR p_unit_price < 0 THEN
    RAISE EXCEPTION 'unit_price must be >= 0' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_edit_pending_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'feature disabled' USING ERRCODE = '22023';
  END IF;

  IF v_item.status <> 'pending' THEN
    RAISE EXCEPTION 'item not editable' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  SELECT base_price, is_active
  INTO v_base_price, v_menu_active
  FROM public.menu_items
  WHERE id = v_item.menu_item_id AND tenant_id = v_order.tenant_id;

  IF NOT FOUND OR COALESCE(v_menu_active, FALSE) = FALSE THEN
    RAISE EXCEPTION 'menu item inactive' USING ERRCODE = '22023';
  END IF;

  IF p_variant_id IS NOT NULL THEN
    SELECT price_adjustment INTO v_variant_adj
    FROM public.menu_item_variants
    WHERE id = p_variant_id
      AND item_id = v_item.menu_item_id
      AND tenant_id = v_order.tenant_id
      AND is_active = TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'variant inactive' USING ERRCODE = '22023';
    END IF;
  ELSE
    v_variant_adj := 0;
  END IF;

  v_modifier_sum := public.pos_order_modifier_sum(
    v_order.tenant_id,
    v_item.menu_item_id,
    COALESCE(p_modifiers, '[]'::JSONB)
  );

  SELECT sides_sum, enriched_sides
  INTO v_sides_sum, v_enriched_sides
  FROM public.pos_enrich_order_sides(
    v_order.tenant_id,
    v_item.menu_item_id,
    COALESCE(p_sides, '[]'::JSONB)
  );

  v_new_unit := v_base_price + v_variant_adj + v_modifier_sum + COALESCE(v_sides_sum, 0);

  v_old_qty := v_item.quantity;
  v_old_unit := v_item.unit_price;
  v_new_subtotal := v_new_unit * p_quantity;

  UPDATE public.order_items
  SET variant_id   = p_variant_id,
      variant_name = NULLIF(p_variant_name, ''),
      unit_price   = v_new_unit,
      modifiers    = COALESCE(p_modifiers, '[]'::JSONB),
      sides        = COALESCE(v_enriched_sides, '[]'::JSONB),
      note         = NULLIF(trim(COALESCE(p_note, '')), ''),
      quantity     = p_quantity,
      subtotal     = v_new_subtotal,
      updated_at   = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET updated_at = now()
  WHERE order_item_id = p_order_item_id
    AND tenant_id = v_item.tenant_id
    AND status NOT IN ('served', 'cancelled');

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal_sum
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  v_disc_amount := public.compute_discount_amount(
    v_order.discount_type, v_order.discount_value, v_subtotal_sum
  );
  v_total_amount := v_subtotal_sum
    + COALESCE(v_order.service_charge, 0)
    - v_disc_amount;

  UPDATE public.orders
  SET subtotal        = v_subtotal_sum,
      discount_amount = v_disc_amount,
      total_amount    = v_total_amount,
      updated_at      = now()
  WHERE id = v_item.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
    'edit_item ' || p_order_item_id::TEXT
      || ': qty ' || v_old_qty::TEXT || '->' || p_quantity::TEXT
      || ', unit ' || v_old_unit::TEXT || '->' || v_new_unit::TEXT
  );

  RETURN jsonb_build_object(
    'order_id',           v_item.order_id,
    'order_item_id',      p_order_item_id,
    'old_quantity',       v_old_qty,
    'new_quantity',       p_quantity,
    'subtotal',           v_subtotal_sum,
    'discount_amount',    v_disc_amount,
    'total_amount',       v_total_amount,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


--
-- Name: FUNCTION edit_pending_order_item(p_order_item_id bigint, p_variant_id bigint, p_variant_name text, p_unit_price numeric, p_modifiers jsonb, p_sides jsonb, p_note text, p_quantity integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.edit_pending_order_item(p_order_item_id bigint, p_variant_id bigint, p_variant_name text, p_unit_price numeric, p_modifiers jsonb, p_sides jsonb, p_note text, p_quantity integer) IS 'Sửa món đã gửi khi status=pending (chef chưa bắt đầu nấu). Server recompute unit_price/subtotal từ menu (base + variant_adj + modifier_sum + sides_sum) — BỎ QUA p_unit_price từ client (giữ trong signature cho compat). Mirror create_order/append_order_items convention. Sides JSONB được enrich qua pos_enrich_order_sides. Lock order + item, gate qua pos:void_order. Recompute discount qua compute_discount_amount, bump kds_tickets.updated_at. Block khi status<>pending, order completed/cancelled, payment_status=paid, menu_item inactive, variant inactive, feature flag pos_edit_pending_enabled=false.';


--
-- Name: employee_clock_in_with_checklist(bigint, bigint, bigint, bigint, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_clock_in_with_checklist(p_tenant_id bigint, p_employee_id bigint, p_branch_id bigint, p_shift_id bigint, p_business_date date, p_photo_path text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_attendance_id bigint;
  v_shift_id bigint;
  v_shift_start time;
  v_is_open boolean;
  v_is_close boolean;
  v_template_id bigint;
BEGIN
  IF p_photo_path IS NULL OR btrim(p_photo_path) = '' THEN
    RAISE EXCEPTION 'photo_required' USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(e.default_checklist_template_id, po.default_checklist_template_id)
  INTO v_template_id
  FROM public.employees e
  JOIN public.profiles p
    ON p.id = e.profile_id
   AND p.tenant_id = e.tenant_id
  LEFT JOIN public.positions po
    ON po.id = p.position_id
   AND po.tenant_id = p.tenant_id
  WHERE e.id = p_employee_id
    AND e.tenant_id = p_tenant_id
    AND e.is_active = true
    AND p.branch_id = p_branch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = p_tenant_id
      AND COALESCE(b.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_shift_id IS NULL OR p_shift_id = 0 THEN
    RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT s.id, s.start_time
  INTO v_shift_id, v_shift_start
  FROM public.shifts s
  WHERE s.id = p_shift_id
    AND s.tenant_id = p_tenant_id
    AND (s.branch_id IS NULL OR s.branch_id = p_branch_id)
    AND COALESCE(s.is_active, true) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT v_shift_start = min(s.start_time), v_shift_start = max(s.start_time)
  INTO v_is_open, v_is_close
  FROM public.shifts s
  WHERE s.tenant_id = p_tenant_id
    AND (s.branch_id IS NULL OR s.branch_id = p_branch_id)
    AND COALESCE(s.is_active, true) = true;

  IF v_template_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.shift_checklist_templates t
      WHERE t.id = v_template_id
        AND t.tenant_id = p_tenant_id
        AND t.is_active = true
        AND (t.branch_id IS NULL OR t.branch_id = p_branch_id)
    ) THEN
    v_template_id := NULL;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.attendance_records ar
    WHERE ar.tenant_id = p_tenant_id
      AND ar.employee_id = p_employee_id
      AND ar.date = p_business_date
      AND ar.shift_id = v_shift_id
  ) THEN
    RAISE EXCEPTION 'duplicate_clock_in' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.attendance_records (
    tenant_id,
    branch_id,
    employee_id,
    shift_id,
    date,
    check_in,
    status,
    method,
    code_verified,
    check_in_photo_path,
    checklist_template_id
  )
  VALUES (
    p_tenant_id,
    p_branch_id,
    p_employee_id,
    v_shift_id,
    p_business_date,
    now(),
    'present',
    'pwa',
    false,
    p_photo_path,
    v_template_id
  )
  RETURNING id INTO v_attendance_id;

  INSERT INTO public.attendance_checklist_items (
    tenant_id,
    attendance_record_id,
    template_item_id,
    title,
    phase,
    done_definition,
    is_required,
    scope,
    task_kind,
    sort_order
  )
  SELECT
    p_tenant_id,
    v_attendance_id,
    i.id,
    i.title,
    i.phase,
    i.done_definition,
    i.is_required,
    i.scope,
    i.task_kind,
    row_number() OVER (ORDER BY i.sort_order, i.id)::integer
  FROM public.shift_checklist_template_items i
  WHERE i.tenant_id = p_tenant_id
    AND i.template_id = v_template_id
    AND i.is_active = true
    AND (
      i.scope = 'every_shift'
      OR (i.scope = 'opening' AND v_is_open)
      OR (i.scope = 'closing' AND v_is_close)
    )
  ORDER BY i.sort_order, i.id;

  RETURN v_attendance_id;
END;
$$;


--
-- Name: FUNCTION employee_clock_in_with_checklist(p_tenant_id bigint, p_employee_id bigint, p_branch_id bigint, p_shift_id bigint, p_business_date date, p_photo_path text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employee_clock_in_with_checklist(p_tenant_id bigint, p_employee_id bigint, p_branch_id bigint, p_shift_id bigint, p_business_date date, p_photo_path text) IS 'Per-shift employee clock-in: validates a global-or-branch shift, dedupes per (employee, date, shift), snapshots the employee default checklist filtered by item scope for this shift (opening shift gets every_shift+opening, closing gets every_shift+closing; weekly excluded).';


--
-- Name: employee_clock_out_with_code(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_clock_out_with_code(p_tenant_id bigint, p_employee_id bigint, p_attendance_id bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN public.employee_request_clock_out(
    p_tenant_id,
    p_employee_id,
    p_attendance_id
  );
END;
$$;


--
-- Name: employee_request_clock_out(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_request_clock_out(p_tenant_id bigint, p_employee_id bigint, p_attendance_id bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_record public.attendance_records%ROWTYPE;
  v_remaining integer;
  v_requested_at timestamptz;
  v_employee_name text;
  v_requester_role text;
  v_target_roles text[];
BEGIN
  SELECT *
  INTO v_record
  FROM public.attendance_records ar
  WHERE ar.id = p_attendance_id
    AND ar.tenant_id = p_tenant_id
    AND ar.employee_id = p_employee_id
    AND ar.check_out IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'open_attendance_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::integer
  INTO v_remaining
  FROM public.attendance_checklist_items i
  WHERE i.tenant_id = p_tenant_id
    AND i.attendance_record_id = p_attendance_id
    AND i.is_required = true
    AND i.is_done = false;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'checklist_incomplete' USING ERRCODE = '23514';
  END IF;

  IF v_record.checkout_requested_at IS NOT NULL THEN
    RETURN v_record.checkout_requested_at;
  END IF;

  v_requested_at := now();

  SELECT
    p.full_name,
    COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_employee_name, v_requester_role
  FROM public.employees e
  LEFT JOIN public.profiles p
    ON p.id = e.profile_id
   AND p.tenant_id = e.tenant_id
  LEFT JOIN public.positions po
    ON po.id = p.position_id
   AND po.tenant_id = p.tenant_id
  WHERE e.id = p_employee_id
    AND e.tenant_id = p_tenant_id;

  v_requester_role := COALESCE(v_requester_role, 'office');
  v_target_roles := CASE
    WHEN v_requester_role = 'branch_manager' THEN ARRAY['owner']::text[]
    WHEN v_requester_role IN ('cashier', 'waiter', 'chef') THEN ARRAY['branch_manager']::text[]
    ELSE ARRAY['owner']::text[]
  END;

  UPDATE public.attendance_records
  SET
    checkout_requested_at = v_requested_at,
    checkout_requested_by_role = v_requester_role,
    checkout_approval_target_roles = v_target_roles,
    check_out_code_verified = false,
    updated_at = now()
  WHERE id = p_attendance_id
    AND tenant_id = p_tenant_id
    AND employee_id = p_employee_id
    AND check_out IS NULL;

  INSERT INTO public.notifications (
    tenant_id,
    target_branch_id,
    target_roles,
    kind,
    severity,
    title,
    body,
    entity_type,
    entity_id,
    action_url,
    meta,
    dedup_key
  )
  VALUES (
    p_tenant_id,
    v_record.branch_id,
    v_target_roles,
    'attendance.checkout_requested',
    'info',
    'Yêu cầu duyệt kết ca',
    format(
      '%s đã gửi yêu cầu kết ca lúc %s.',
      COALESCE(v_employee_name, 'Nhân viên'),
      to_char(v_requested_at AT TIME ZONE 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM')
    ),
    'attendance_record',
    p_attendance_id,
    '/employee/checkout-approvals',
    jsonb_build_object(
      'attendance_id', p_attendance_id,
      'employee_id', p_employee_id,
      'requester_role', v_requester_role,
      'approval_target_roles', to_jsonb(v_target_roles),
      'branch_id', v_record.branch_id,
      'business_date', v_record.date,
      'requested_at', v_requested_at
    ),
    format('attendance.checkout_request:%s', p_attendance_id)
  )
  ON CONFLICT (tenant_id, dedup_key)
    WHERE dedup_key IS NOT NULL
  DO UPDATE SET
    created_at = EXCLUDED.created_at,
    expires_at = NULL,
    meta = EXCLUDED.meta;

  RETURN v_requested_at;
END;
$$;


--
-- Name: employee_submit_consumption_report(bigint, bigint, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_submit_consumption_report(p_tenant_id bigint, p_attendance_id bigint, p_lines jsonb, p_note text DEFAULT NULL::text, p_no_consumption boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant bigint := public.auth_tenant_id();
  v_attendance record;
  v_report_id bigint;
  v_checklist_item_id bigint;
  v_line_count integer;
  v_distinct_line_count integer;
  v_no_consumption boolean := COALESCE(p_no_consumption, false);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_tenant IS NULL OR v_tenant <> p_tenant_id THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'invalid_consumption_lines' USING ERRCODE = '22023';
  END IF;

  IF v_no_consumption AND jsonb_array_length(p_lines) <> 0 THEN
    RAISE EXCEPTION 'no_consumption_with_lines' USING ERRCODE = '22023';
  END IF;

  IF NOT v_no_consumption AND jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'consumption_lines_required' USING ERRCODE = '22023';
  END IF;

  SELECT ar.id, ar.tenant_id, ar.branch_id, ar.employee_id, ar.check_in, ar.check_out,
         ar.checkout_requested_at
  INTO v_attendance
  FROM public.attendance_records ar
  JOIN public.employees e
    ON e.id = ar.employee_id
   AND e.tenant_id = ar.tenant_id
  WHERE ar.id = p_attendance_id
    AND ar.tenant_id = p_tenant_id
    AND e.profile_id = v_uid
  FOR UPDATE OF ar;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'attendance_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_attendance.check_in IS NULL OR v_attendance.check_out IS NOT NULL THEN
    RAISE EXCEPTION 'attendance_not_open' USING ERRCODE = '22023';
  END IF;

  IF v_attendance.checkout_requested_at IS NOT NULL THEN
    RAISE EXCEPTION 'checkout_already_requested' USING ERRCODE = '22023';
  END IF;

  SELECT ci.id
  INTO v_checklist_item_id
  FROM public.attendance_checklist_items ci
  WHERE ci.tenant_id = p_tenant_id
    AND ci.attendance_record_id = v_attendance.id
    AND ci.task_kind = 'consumption_report'
  LIMIT 1;

  IF v_checklist_item_id IS NULL THEN
    RAISE EXCEPTION 'consumption_checklist_not_assigned' USING ERRCODE = '22023';
  END IF;

  SELECT count(*)
  INTO v_line_count
  FROM jsonb_to_recordset(p_lines) AS src(
    default_item_id bigint,
    ingredient_id bigint,
    quantity numeric,
    note text
  )
  JOIN public.ingredients i
    ON i.id = src.ingredient_id
   AND i.tenant_id = p_tenant_id
   AND i.is_active = true
  LEFT JOIN public.shift_checklist_consumption_default_items d
    ON d.id = src.default_item_id
   AND d.tenant_id = p_tenant_id
   AND d.ingredient_id = src.ingredient_id
   AND d.is_active = true
  LEFT JOIN public.attendance_checklist_items ci
    ON ci.tenant_id = p_tenant_id
   AND ci.attendance_record_id = v_attendance.id
   AND ci.task_kind = 'consumption_report'
   AND ci.template_item_id = d.template_item_id
  WHERE src.quantity > 0
    AND (src.default_item_id IS NULL OR ci.id IS NOT NULL);

  SELECT count(DISTINCT src.ingredient_id)
  INTO v_distinct_line_count
  FROM jsonb_to_recordset(p_lines) AS src(
    default_item_id bigint,
    ingredient_id bigint,
    quantity numeric,
    note text
  );

  IF v_line_count <> jsonb_array_length(p_lines)
     OR v_distinct_line_count <> jsonb_array_length(p_lines) THEN
    RAISE EXCEPTION 'invalid_consumption_line' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.attendance_consumption_reports (
    tenant_id,
    attendance_record_id,
    branch_id,
    employee_id,
    status,
    note,
    submitted_by,
    submitted_at,
    reviewed_by,
    reviewed_at,
    review_note,
    stock_issue_id,
    no_consumption
  )
  VALUES (
    p_tenant_id,
    v_attendance.id,
    v_attendance.branch_id,
    v_attendance.employee_id,
    'submitted',
    NULLIF(btrim(COALESCE(p_note, '')), ''),
    v_uid,
    now(),
    NULL,
    NULL,
    NULL,
    NULL,
    v_no_consumption
  )
  ON CONFLICT (tenant_id, attendance_record_id)
  DO UPDATE SET
    status = 'submitted',
    note = EXCLUDED.note,
    submitted_by = EXCLUDED.submitted_by,
    submitted_at = EXCLUDED.submitted_at,
    reviewed_by = NULL,
    reviewed_at = NULL,
    review_note = NULL,
    stock_issue_id = NULL,
    no_consumption = EXCLUDED.no_consumption
  WHERE attendance_consumption_reports.status IN ('draft', 'submitted', 'needs_changes')
  RETURNING id INTO v_report_id;

  IF v_report_id IS NULL THEN
    RAISE EXCEPTION 'consumption_report_locked' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.attendance_consumption_report_lines
  WHERE tenant_id = p_tenant_id
    AND report_id = v_report_id;

  INSERT INTO public.attendance_consumption_report_lines (
    tenant_id,
    report_id,
    ingredient_id,
    default_item_id,
    quantity,
    unit,
    note,
    sort_order
  )
  SELECT
    p_tenant_id,
    v_report_id,
    src.ingredient_id,
    src.default_item_id,
    src.quantity,
    i.purchase_unit,
    NULLIF(btrim(COALESCE(src.note, '')), ''),
    src.sort_order
  FROM (
    SELECT
      row_number() OVER ()::integer AS sort_order,
      default_item_id,
      ingredient_id,
      quantity,
      note
    FROM jsonb_to_recordset(p_lines) AS parsed(
      default_item_id bigint,
      ingredient_id bigint,
      quantity numeric,
      note text
    )
  ) src
  JOIN public.ingredients i
    ON i.id = src.ingredient_id
   AND i.tenant_id = p_tenant_id
   AND i.is_active = true;

  UPDATE public.attendance_checklist_items
  SET is_done = true,
      completed_at = now()
  WHERE tenant_id = p_tenant_id
    AND attendance_record_id = v_attendance.id
    AND task_kind = 'consumption_report';

  RETURN v_report_id;
END;
$$;


--
-- Name: FUNCTION employee_submit_consumption_report(p_tenant_id bigint, p_attendance_id bigint, p_lines jsonb, p_note text, p_no_consumption boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employee_submit_consumption_report(p_tenant_id bigint, p_attendance_id bigint, p_lines jsonb, p_note text, p_no_consumption boolean) IS 'Employee submits daily kitchen consumption lines or an explicit no-consumption confirmation for an open attendance record. Does not affect Inventory.';


--
-- Name: enable_offline_for_session(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enable_offline_for_session(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(NULL, 'settings:tenant') THEN
    RAISE EXCEPTION 'forbidden: settings:tenant required for offline pilot' USING ERRCODE = '42501';
  END IF;
  IF v_ss.status <> 'in_progress' THEN RAISE EXCEPTION 'session not in_progress (status=%)', v_ss.status USING ERRCODE = '22023'; END IF;
  IF v_ss.offline_enabled THEN RAISE EXCEPTION 'offline already enabled for session %', p_session_id USING ERRCODE = '22023'; END IF;
  UPDATE public.stocktake_sessions SET offline_enabled = true, offline_enabled_by = v_uid, offline_enabled_at = now()
   WHERE id = p_session_id;
  RETURN jsonb_build_object('session_id', p_session_id, 'offline_enabled', true, 'enabled_by', v_uid, 'enabled_at', now());
END; $$;


--
-- Name: enforce_branch_menu_daily_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_branch_menu_daily_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_branch_id       bigint;
  v_order_date      date;
  v_tenant_id       bigint;
  v_target          record;
  v_limit           record;
  v_hold_token_text text;
  v_hold_token      uuid;
  v_active_hold_qty integer;
BEGIN
  IF COALESCE(current_setting('comtammatu.skip_quota_enforcement', true), 'false') = 'true' THEN
    RETURN NEW;
  END IF;

  v_hold_token_text := NULLIF(
    current_setting('comtammatu.daily_limit_hold_token', true),
    ''
  );
  IF v_hold_token_text IS NOT NULL THEN
    v_hold_token := v_hold_token_text::uuid;
  END IF;

  SELECT o.tenant_id,
         o.branch_id,
         (o.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
  INTO v_tenant_id, v_branch_id, v_order_date
  FROM public.orders o
  WHERE o.id = NEW.order_id;

  IF v_branch_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_target IN
    WITH agg AS (
      SELECT NEW.menu_item_id::bigint AS item_id,
             NEW.quantity::integer    AS need_qty
      UNION ALL
      SELECT (s.elem ->> 'side_item_id')::bigint,
             (NEW.quantity * COALESCE(NULLIF(s.elem ->> 'quantity', '')::integer, 1))::integer
      FROM jsonb_array_elements(COALESCE(NEW.sides, '[]'::jsonb)) AS s(elem)
      WHERE s.elem ? 'side_item_id'
        AND (s.elem ->> 'side_item_id') ~ '^[0-9]+$'
    )
    SELECT item_id, SUM(need_qty)::integer AS need_qty
    FROM agg
    WHERE item_id IS NOT NULL
    GROUP BY item_id
    ORDER BY item_id ASC
  LOOP
    SELECT * INTO v_limit
    FROM public.branch_menu_item_daily_limits
    WHERE branch_id = v_branch_id
      AND menu_item_id = v_target.item_id
      AND limit_date = v_order_date
    FOR UPDATE;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    IF v_limit.is_disabled THEN
      RAISE EXCEPTION 'daily_limit_item_disabled'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_item_disabled',
                'menu_item_id', v_target.item_id
              )::text;
    END IF;

    SELECT COALESCE(SUM(h.quantity), 0)::integer
    INTO v_active_hold_qty
    FROM public.branch_menu_item_daily_holds h
    WHERE h.tenant_id = v_tenant_id
      AND h.branch_id = v_branch_id
      AND h.menu_item_id = v_target.item_id
      AND h.limit_date = v_order_date
      AND (v_hold_token IS NULL OR h.hold_token <> v_hold_token)
      AND h.committed_at IS NULL
      AND h.released_at IS NULL
      AND h.expires_at > now();

    IF v_limit.limit_quantity IS NOT NULL
       AND v_limit.sold_today + v_active_hold_qty + v_target.need_qty > v_limit.limit_quantity THEN
      RAISE EXCEPTION 'daily_limit_exceeded'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_exceeded',
                'menu_item_id', v_target.item_id,
                'limit_quantity', v_limit.limit_quantity,
                'sold_today', v_limit.sold_today,
                'held_quantity', v_active_hold_qty,
                'requested_quantity', v_target.need_qty
              )::text;
    END IF;

    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = sold_today + v_target.need_qty
    WHERE id = v_limit.id;
  END LOOP;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION enforce_branch_menu_daily_limit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_branch_menu_daily_limit() IS 'AFTER INSERT on order_items: aggregate main + sides by menu_item_id ASC, lock each limit row, count active daily-limit holds except comtammatu.daily_limit_hold_token, raise P0001 daily_limit_item_disabled / daily_limit_exceeded, increment sold_today. Skip-hatch: comtammatu.skip_quota_enforcement=true.';


--
-- Name: enforce_period_close(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_period_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_status TEXT; v_effective TIMESTAMPTZ; v_tenant BIGINT;
BEGIN
  v_effective := (row_to_json(NEW.*)->>'effective_date')::TIMESTAMPTZ;
  v_tenant    := (row_to_json(NEW.*)->>'tenant_id')::BIGINT;
  IF v_effective IS NULL OR v_tenant IS NULL THEN RETURN NEW; END IF;
  v_status := public.period_status_at(v_tenant, v_effective);
  IF v_status = 'hard_closed' THEN
    IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN
      RAISE EXCEPTION 'target period is hard-closed' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: enforce_period_close_stock_issues(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_period_close_stock_issues() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_status TEXT;
BEGIN
  IF NEW.issued_at IS NULL OR NEW.tenant_id IS NULL THEN RETURN NEW; END IF;
  v_status := public.period_status_at(NEW.tenant_id, NEW.issued_at);
  IF v_status = 'hard_closed' AND NOT public.has_permission(NULL, 'accounting:period_reopen') THEN
    RAISE EXCEPTION 'target accounting period is hard-closed; accounting:period_reopen required' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: enforce_po_grn_branch_is_procurement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_po_grn_branch_is_procurement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = NEW.branch_id
      AND b.tenant_id = NEW.tenant_id
      AND b.branch_kind IN ('branch', 'central_supply', 'central_kitchen')
      AND b.is_active = true
  ) THEN
    RAISE EXCEPTION 'branch must be active procurement site' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_stock_transfer_direction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_stock_transfer_direction() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from_kind text;
  v_to_kind text;
BEGIN
  IF NEW.from_branch_id = NEW.to_branch_id THEN
    RAISE EXCEPTION 'intra_branch_transfer_not_supported' USING ERRCODE = '23514';
  END IF;

  SELECT b.branch_kind
  INTO v_from_kind
  FROM public.branches b
  WHERE b.id = NEW.from_branch_id
    AND b.tenant_id = NEW.tenant_id;

  SELECT b.branch_kind
  INTO v_to_kind
  FROM public.branches b
  WHERE b.id = NEW.to_branch_id
    AND b.tenant_id = NEW.tenant_id;

  IF v_from_kind IS NULL OR v_to_kind IS NULL THEN
    RAISE EXCEPTION 'stock_transfers: invalid branch reference' USING ERRCODE = '23514';
  END IF;

  IF v_from_kind = 'branch' AND v_to_kind = 'branch' THEN
    RETURN NEW;
  END IF;

  IF v_from_kind = 'branch' AND v_to_kind IN ('central_supply', 'central_kitchen') THEN
    RETURN NEW;
  END IF;

  IF v_from_kind IN ('central_supply', 'central_kitchen') AND v_to_kind = 'branch' THEN
    RETURN NEW;
  END IF;

  IF v_from_kind = 'central_supply' AND v_to_kind = 'central_kitchen' THEN
    RETURN NEW;
  END IF;

  IF v_from_kind = 'central_kitchen' AND v_to_kind = 'central_supply' THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'stock_transfers: invalid direction % -> %', v_from_kind, v_to_kind
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: FUNCTION enforce_stock_transfer_direction(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_stock_transfer_direction() IS 'Allowed transfers: branch-to-branch, branch-to-central, central-to-branch, central_supply-to-central_kitchen, and central_kitchen-to-central_supply. Reject same-site.';


--
-- Name: enqueue_cancel_ticket_print(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_cancel_ticket_print(p_order_item_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid           UUID;
  v_item          public.order_items%ROWTYPE;
  v_order         public.orders%ROWTYPE;
  v_table_no      INT;
  v_slot          SMALLINT;
  v_printer_id    BIGINT;
  v_category_id   BIGINT;
  v_voided_by     TEXT;
  v_flag_enabled  TEXT;
  v_items_payload JSONB;
  v_payload       JSONB;
  v_idempotency   TEXT;
  v_job_id        BIGINT;
  v_now           TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_cancel_ticket_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  SELECT p.id, CASE WHEN p.role = 'kitchen_2' THEN 2 ELSE 1 END
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = 'cancel_ticket'
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_voided_by
  FROM public.profiles WHERE id = v_uid;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',    v_item.item_name,
    'variant_name', v_item.variant_name,
    'quantity',     v_item.quantity,
    'modifiers',    v_item.modifiers,
    'sides',        v_item.sides,
    'note',         v_item.note
  ));

  v_payload := jsonb_build_object(
    'kind',          'cancel_ticket',
    'order_number',  v_order.order_number,
    'order_type',    v_order.order_type,
    'table_number',  v_table_no,
    'slot',          v_slot,
    'items',         v_items_payload,
    'reason',        COALESCE(NULLIF(trim(p_reason), ''), v_item.cancel_reason, ''),
    'voided_by',     COALESCE(v_voided_by, ''),
    'printed_at',    to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                             'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':cancel:' || p_order_item_id::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'cancel_ticket',
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot
  );
END;
$$;


--
-- Name: FUNCTION enqueue_cancel_ticket_print(p_order_item_id bigint, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_cancel_ticket_print(p_order_item_id bigint, p_reason text) IS 'Enqueue a PHIẾU HUỶ MÓN print job targeting the original kitchen slot. Skips silently (returns skipped:true) when feature flag off, item never sent to kitchen, category has no slot, or no active printer for the slot. Called by the voidOrderItem Server Action after void_order_item commits.';


--
-- Name: enqueue_edit_pending_order_item_quantity_print(bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_edit_pending_order_item_quantity_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_item            public.order_items%ROWTYPE;
  v_order           public.orders%ROWTYPE;
  v_table_no        INT;
  v_slot            SMALLINT;
  v_printer_id      BIGINT;
  v_category_id     BIGINT;
  v_staff_name      TEXT;
  v_flag_enabled    TEXT;
  v_delta           INT;
  v_print_type      TEXT;
  v_items_payload   JSONB;
  v_payload         JSONB;
  v_idempotency     TEXT;
  v_job_id          BIGINT;
  v_now             TIMESTAMPTZ := now();
  v_change_note     TEXT;
  v_item_note       TEXT;
  v_event_token     TEXT;
  v_batch_ticket_number TEXT;
  v_batch_send_seq      INT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_old_quantity IS NULL OR p_new_quantity IS NULL
     OR p_old_quantity < 1 OR p_new_quantity < 1
  THEN
    RAISE EXCEPTION 'quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  IF p_old_quantity = p_new_quantity THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_quantity_change');
  END IF;

  IF p_new_quantity < p_old_quantity THEN
    SELECT value INTO v_flag_enabled
    FROM public.system_settings
    WHERE tenant_id = v_order.tenant_id AND key = 'pos_reduce_qty_enabled';
    IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
      RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
    END IF;
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id
    AND mi.tenant_id = v_order.tenant_id;

  IF v_category_id IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  v_delta := abs(p_new_quantity - p_old_quantity);
  v_print_type := CASE
    WHEN p_new_quantity > p_old_quantity THEN 'kitchen_ticket'
    ELSE 'cancel_ticket'
  END;

  SELECT p.id, CASE WHEN p.role = 'kitchen_2' THEN 2 ELSE 1 END
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = v_print_type
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_staff_name
  FROM public.profiles WHERE id = v_uid;

  SELECT ksb.kitchen_ticket_number, ksb.send_seq
  INTO v_batch_ticket_number, v_batch_send_seq
  FROM public.kds_tickets kt
  JOIN public.kitchen_send_batches ksb
    ON ksb.id = kt.kitchen_send_batch_id
  WHERE kt.tenant_id = v_order.tenant_id
    AND kt.order_item_id = v_item.id
  ORDER BY ksb.created_at DESC
  LIMIT 1;

  v_change_note := CASE
    WHEN p_new_quantity > p_old_quantity THEN
      'TANG SL ' || p_old_quantity::TEXT || ' -> ' || p_new_quantity::TEXT
    ELSE
      'GIAM SL ' || p_old_quantity::TEXT || ' -> ' || p_new_quantity::TEXT
  END;

  v_item_note := v_change_note
    || CASE
      WHEN NULLIF(trim(COALESCE(v_item.note, '')), '') IS NULL THEN ''
      ELSE ': ' || trim(v_item.note)
    END;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',    v_item.item_name,
    'variant_name', v_item.variant_name,
    'quantity',     v_delta,
    'modifiers',    v_item.modifiers,
    'sides',        v_item.sides,
    'note',         v_item_note
  ));

  v_event_token := replace(
    COALESCE(extract(epoch from v_item.updated_at)::NUMERIC(20,6)::TEXT, ''),
    '.',
    ''
  );

  IF p_new_quantity > p_old_quantity THEN
    v_payload := jsonb_build_object(
      'kind',                  'kitchen_ticket',
      'kitchen_ticket_number', COALESCE(v_batch_ticket_number, v_order.order_number),
      'source_order_number',   v_order.order_number,
      'order_number',          v_order.order_number,
      'order_type',            v_order.order_type,
      'table_number',          v_table_no,
      'cashier_name',          COALESCE(v_staff_name, ''),
      'send_seq',              COALESCE(v_batch_send_seq, v_order.kitchen_send_count, 1),
      'send_kind',             'append',
      'slot',                  v_slot,
      'note',                  v_change_note,
      'items',                 v_items_payload,
      'printed_at',            to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                       'YYYY-MM-DD"T"HH24:MI:SS')
    );
  ELSE
    v_payload := jsonb_build_object(
      'kind',         'cancel_ticket',
      'order_number', v_order.order_number,
      'order_type',   v_order.order_type,
      'table_number', v_table_no,
      'slot',         v_slot,
      'items',        v_items_payload,
      'reason',       v_change_note || ': '
                      || COALESCE(NULLIF(trim(p_reason), ''), 'Sua so luong mon'),
      'voided_by',    COALESCE(v_staff_name, ''),
      'printed_at',   to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                              'YYYY-MM-DD"T"HH24:MI:SS')
    );
  END IF;

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':edit-qty:' || p_order_item_id::TEXT
    || ':' || p_old_quantity::TEXT || '->' || p_new_quantity::TEXT
    || ':printer:' || v_printer_id::TEXT
    || ':at:' || v_event_token;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, v_print_type,
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  IF v_job_id IS NULL THEN
    SELECT id INTO v_job_id
    FROM public.print_jobs
    WHERE idempotency_key = v_idempotency;
  END IF;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot,
    'job_type',   v_print_type,
    'delta',      v_delta
  );
END;
$$;


--
-- Name: FUNCTION enqueue_edit_pending_order_item_quantity_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_edit_pending_order_item_quantity_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text) IS 'Enqueue a kitchen-visible print delta after edit_pending_order_item changes quantity for an already-sent pending item. Increase uses kitchen_ticket (GỌI THÊM); decrease uses cancel_ticket. Returns skipped reasons for not_sent, no_quantity_change, no_slot, no_printer, and feature_disabled.';


--
-- Name: enqueue_kitchen_print(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_kitchen_print(p_order_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_order public.orders%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'send_seq', v_order.kitchen_send_count,
    'jobs', '[]'::jsonb,
    'deferred_to', 'kds_completion'
  );
END;
$$;


--
-- Name: FUNCTION enqueue_kitchen_print(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_kitchen_print(p_order_id bigint) IS 'Compatibility wrapper. POS send routes work to KDS; kitchen paper is queued by complete_kds_tickets when KDS marks items ready.';


--
-- Name: enqueue_partial_cancel_ticket_print(bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_partial_cancel_ticket_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_item            public.order_items%ROWTYPE;
  v_order           public.orders%ROWTYPE;
  v_table_no        INT;
  v_slot            SMALLINT;
  v_printer_id      BIGINT;
  v_category_id     BIGINT;
  v_voided_by       TEXT;
  v_flag_enabled    TEXT;
  v_items_payload   JSONB;
  v_payload         JSONB;
  v_idempotency     TEXT;
  v_job_id          BIGINT;
  v_now             TIMESTAMPTZ := now();
  v_reason_prefixed TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:send_kitchen') THEN
    RAISE EXCEPTION 'permission denied: pos:send_kitchen' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_reduce_qty_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'feature_disabled');
  END IF;

  IF v_item.sent_to_kitchen_at IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_sent');
  END IF;

  IF p_new_quantity >= p_old_quantity THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_reduction');
  END IF;

  SELECT mi.category_id INTO v_category_id
  FROM public.menu_items mi
  WHERE mi.id = v_item.menu_item_id;

  IF NOT EXISTS (
    SELECT 1
    FROM public.printer_menu_categories pmc
    WHERE pmc.tenant_id = v_order.tenant_id
      AND pmc.branch_id = v_order.branch_id
      AND pmc.category_id = v_category_id
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_slot');
  END IF;

  SELECT p.id, CASE WHEN p.role = 'kitchen_2' THEN 2 ELSE 1 END
  INTO v_printer_id, v_slot
  FROM public.printer_menu_categories pmc
  JOIN public.printers p
    ON p.id = pmc.printer_id
   AND p.tenant_id = pmc.tenant_id
   AND p.branch_id = pmc.branch_id
   AND p.is_active = TRUE
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = 'cancel_ticket'
  WHERE pmc.tenant_id = v_order.tenant_id
    AND pmc.branch_id = v_order.branch_id
    AND pmc.category_id = v_category_id
  ORDER BY p.id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_voided_by
  FROM public.profiles WHERE id = v_uid;

  v_items_payload := jsonb_build_array(jsonb_build_object(
    'item_name',     v_item.item_name,
    'variant_name',  v_item.variant_name,
    'quantity',      p_old_quantity - p_new_quantity,
    'modifiers',     v_item.modifiers,
    'sides',         v_item.sides,
    'note',          v_item.note
  ));

  v_reason_prefixed := 'GIAM SL ' || p_old_quantity::TEXT
    || ' -> ' || p_new_quantity::TEXT
    || ': ' || COALESCE(NULLIF(trim(p_reason), ''), '');

  v_payload := jsonb_build_object(
    'kind',          'cancel_ticket',
    'order_number',  v_order.order_number,
    'order_type',    v_order.order_type,
    'table_number',  v_table_no,
    'slot',          v_slot,
    'items',         v_items_payload,
    'reason',        v_reason_prefixed,
    'voided_by',     COALESCE(v_voided_by, ''),
    'printed_at',    to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                             'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || v_order.id::TEXT
    || ':reduce:' || p_order_item_id::TEXT
    || ':' || p_old_quantity::TEXT || '->' || p_new_quantity::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'cancel_ticket',
    v_order.id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'slot',       v_slot
  );
END;
$$;


--
-- Name: FUNCTION enqueue_partial_cancel_ticket_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_partial_cancel_ticket_print(p_order_item_id bigint, p_old_quantity integer, p_new_quantity integer, p_reason text) IS 'Enqueue PHIẾU GIẢM SL — payload.kind=cancel_ticket (reuse template HUỶ MÓN ở print-agent), items[].quantity=delta (số phần bị giảm), reason prefix "GIẢM SL N → M:" để chef phân biệt với phiếu huỷ-toàn-phần. Skip silently khi feature flag off, item chưa gửi bếp, không có slot/printer. Idempotency key bao gồm old_qty+new_qty cho phép giảm nhiều lần (5→3 rồi 3→1) mà vẫn dedup double-submit cùng delta.';


--
-- Name: enqueue_provisional_bill(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_provisional_bill(p_order_id bigint, p_qr_content text DEFAULT NULL::text, p_qr_header_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID;
  v_order        public.orders%ROWTYPE;
  v_branch       public.branches%ROWTYPE;
  v_table_no     INT;
  v_printer_id   BIGINT;
  v_cashier_name TEXT;
  v_branch_tax   TEXT;
  v_qr_type      TEXT;
  v_flag_enabled TEXT;
  v_vietqr_bank  TEXT;
  v_vietqr_acc   TEXT;
  v_vietqr_name  TEXT;
  v_payment_qr   JSONB;
  v_items        JSONB;
  v_payload      JSONB;
  v_idempotency  TEXT;
  v_job_id       BIGINT;
  v_now          TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('pos:print') THEN
    RAISE EXCEPTION 'permission denied: pos:print' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_flag_enabled
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'pos_provisional_bill_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'provisional bill printing is disabled' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.payment_status = 'paid' THEN
    RAISE EXCEPTION 'order already paid; cannot print provisional bill' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.status = 'cancelled' THEN
    RAISE EXCEPTION 'order is cancelled; cannot print provisional bill' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_order.branch_id;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_order.created_by;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_order.tenant_id,
    v_order.branch_id,
    'provisional_bill'
  );

  IF v_printer_id IS NULL THEN
    RAISE EXCEPTION 'no active receipt printer for branch %', v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  IF p_qr_content IS NOT NULL AND length(trim(p_qr_content)) > 0 THEN
    SELECT value INTO v_qr_type
    FROM public.system_settings
    WHERE tenant_id = v_order.tenant_id AND key = 'payment_qr_type';
    v_qr_type := COALESCE(v_qr_type, 'vietqr');

    IF v_qr_type = 'vietqr' THEN
      SELECT value INTO v_vietqr_bank FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_bank_code';
      SELECT value INTO v_vietqr_acc FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_no';
      SELECT value INTO v_vietqr_name FROM public.system_settings
       WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_name';
    END IF;

    v_payment_qr := jsonb_build_object(
      'type',          v_qr_type,
      'content',       p_qr_content,
      'header_label',  COALESCE(p_qr_header_label, UPPER(v_qr_type)),
      'account_no',    v_vietqr_acc,
      'account_name',  v_vietqr_name,
      'amount',        v_order.total_amount,
      'description',   'DH ' || v_order.order_number
    );
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'item_name',    oi.item_name,
      'variant_name', oi.variant_name,
      'category_type', mc.type,
      'quantity',     oi.quantity,
      'unit_price',   oi.unit_price,
      'modifiers',    oi.modifiers,
      'sides',        oi.sides,
      'subtotal',     oi.subtotal,
      'note',         oi.note
    )
    ORDER BY oi.id
  )
  INTO v_items
  FROM public.order_items oi
  LEFT JOIN public.menu_items mi
    ON mi.id = oi.menu_item_id
   AND mi.tenant_id = oi.tenant_id
  LEFT JOIN public.menu_categories mc
    ON mc.id = mi.category_id
   AND mc.tenant_id = oi.tenant_id
  WHERE oi.order_id = p_order_id
    AND oi.status <> 'cancelled';

  v_payload := jsonb_build_object(
    'kind',             'provisional_bill',
    'branch_name',      COALESCE(v_branch.name, ''),
    'branch_address',   COALESCE(v_branch.address, ''),
    'branch_phone',     COALESCE(v_branch.phone, ''),
    'branch_tax_code',  COALESCE(v_branch_tax, ''),
    'order_number',     v_order.order_number,
    'order_type',       v_order.order_type,
    'table_number',     v_table_no,
    'cashier_name',     COALESCE(v_cashier_name, ''),
    'note',             v_order.note,
    'items',            COALESCE(v_items, '[]'::jsonb),
    'subtotal',         v_order.subtotal,
    'tax_amount',       v_order.tax_amount,
    'service_charge',   v_order.service_charge,
    'discount_amount',  v_order.discount_amount,
    'total_amount',     v_order.total_amount,
    'payment_qr',       v_payment_qr,
    'created_at',       to_char(v_order.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS'),
    'printed_at',       to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || p_order_id::TEXT
    || ':provisional:' || extract(epoch from v_now)::BIGINT::TEXT;

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  )
  VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'provisional_bill',
    p_order_id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET payload = EXCLUDED.payload
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'order_id',   p_order_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id,
    'qr_type',    v_qr_type
  );
END;
$$;


--
-- Name: enqueue_receipt_print(bigint, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_receipt_print(p_order_id bigint, p_cash_received numeric DEFAULT NULL::numeric, p_cash_change numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID;
  v_order        public.orders%ROWTYPE;
  v_branch       public.branches%ROWTYPE;
  v_table_no     INT;
  v_printer_id   BIGINT;
  v_cashier_name TEXT;
  v_branch_tax   TEXT;
  v_qr_type      TEXT;
  v_vietqr_bank  TEXT;
  v_vietqr_acc   TEXT;
  v_vietqr_name  TEXT;
  v_qr_content   TEXT;
  v_payment_qr   JSONB;
  v_items        JSONB;
  v_payload      JSONB;
  v_idempotency  TEXT;
  v_job_id       BIGINT;
  v_now          TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_permission_any('pos:print')
    OR public.has_permission_any('pos:reprint_receipt')
  ) THEN
    RAISE EXCEPTION 'permission denied: pos:print' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_order.branch_id;

  IF v_order.table_id IS NOT NULL THEN
    SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
  END IF;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_order.created_by;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_order.tenant_id,
    v_order.branch_id,
    'receipt'
  );

  IF v_printer_id IS NULL THEN
    RAISE EXCEPTION 'no active receipt printer for branch %', v_order.branch_id
      USING ERRCODE = 'P0002';
  END IF;

  IF p_cash_received IS NOT NULL OR p_cash_change IS NOT NULL THEN
    UPDATE public.orders
       SET cash_received = p_cash_received,
           cash_change   = p_cash_change
     WHERE id = p_order_id;
  END IF;

  SELECT value INTO v_qr_type
  FROM public.system_settings
  WHERE tenant_id = v_order.tenant_id AND key = 'payment_qr_type';
  v_qr_type := COALESCE(v_qr_type, 'vietqr');

  IF v_qr_type = 'vietqr' THEN
    SELECT value INTO v_vietqr_bank FROM public.system_settings
     WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_bank_code';
    SELECT value INTO v_vietqr_acc FROM public.system_settings
     WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_no';
    SELECT value INTO v_vietqr_name FROM public.system_settings
     WHERE tenant_id = v_order.tenant_id AND key = 'payment_vietqr_account_name';

    BEGIN
      v_qr_content := public.print_vietqr_emvco(
        v_vietqr_bank,
        v_vietqr_acc,
        v_vietqr_name,
        v_order.total_amount,
        'DH ' || v_order.order_number
      );
    EXCEPTION WHEN OTHERS THEN
      v_qr_content := NULL;
      RAISE WARNING '[enqueue_receipt_print] vietqr emv build failed for order %: %',
        p_order_id, SQLERRM;
    END;

    IF v_qr_content IS NOT NULL THEN
      v_payment_qr := jsonb_build_object(
        'type',         'vietqr',
        'content',      v_qr_content,
        'header_label', upper(COALESCE(v_vietqr_bank, ''))
                          || ' (BIN ' || public.print_vietqr_bank_bin(v_vietqr_bank) || ')',
        'account_no',   v_vietqr_acc,
        'account_name', v_vietqr_name,
        'amount',       v_order.total_amount,
        'description',  'DH ' || v_order.order_number
      );
    END IF;
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'item_name',    oi.item_name,
      'variant_name', oi.variant_name,
      'category_type', mc.type,
      'quantity',     oi.quantity,
      'unit_price',   oi.unit_price,
      'modifiers',    oi.modifiers,
      'sides',        oi.sides,
      'subtotal',     oi.subtotal,
      'note',         oi.note
    )
    ORDER BY oi.id
  )
  INTO v_items
  FROM public.order_items oi
  LEFT JOIN public.menu_items mi
    ON mi.id = oi.menu_item_id
   AND mi.tenant_id = oi.tenant_id
  LEFT JOIN public.menu_categories mc
    ON mc.id = mi.category_id
   AND mc.tenant_id = oi.tenant_id
  WHERE oi.order_id = p_order_id
    AND oi.status <> 'cancelled';

  v_payload := jsonb_build_object(
    'kind',             'receipt',
    'branch_name',      COALESCE(v_branch.name, ''),
    'branch_address',   COALESCE(v_branch.address, ''),
    'branch_phone',     COALESCE(v_branch.phone, ''),
    'branch_tax_code',  COALESCE(v_branch_tax, ''),
    'order_number',     v_order.order_number,
    'order_type',       v_order.order_type,
    'table_number',     v_table_no,
    'cashier_name',     COALESCE(v_cashier_name, ''),
    'note',             v_order.note,
    'items',            COALESCE(v_items, '[]'::jsonb),
    'subtotal',         v_order.subtotal,
    'tax_amount',       v_order.tax_amount,
    'service_charge',   v_order.service_charge,
    'discount_amount',  v_order.discount_amount,
    'total_amount',     v_order.total_amount,
    'payment_method',   v_order.payment_method,
    'payment_qr',       v_payment_qr,
    'cash_received',    p_cash_received,
    'cash_change',      p_cash_change,
    'created_at',       to_char(v_order.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS'),
    'printed_at',       to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'order:' || p_order_id::TEXT || ':receipt';

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  )
  VALUES (
    v_order.tenant_id, v_order.branch_id, v_printer_id, 'receipt',
    p_order_id, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET
    payload    = EXCLUDED.payload,
    printer_id = EXCLUDED.printer_id,
    status = CASE
               WHEN public.print_jobs.status IN ('failed','expired','printed')
               THEN 'pending'
               ELSE public.print_jobs.status
             END,
    last_error       = NULL,
    claimed_by_agent = NULL,
    claimed_at       = NULL
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'order_id',   p_order_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id
  );
END;
$$;


--
-- Name: enqueue_shift_close_print(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_shift_close_print(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid                 UUID;
  v_session             RECORD;
  v_branch              RECORD;
  v_cashier_name        TEXT;
  v_approver_name       TEXT;
  v_branch_tax          TEXT;
  v_printer_id          BIGINT;
  v_breakdown           JSONB;
  v_total_revenue       NUMERIC(15,2);
  v_discount_total      NUMERIC(15,2);
  v_item_breakdown      JSONB;
  v_total_item_quantity INT;
  v_payload             JSONB;
  v_idempotency         TEXT;
  v_job_id              BIGINT;
  v_now                 TIMESTAMPTZ := now();
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, status, opening_cash, closing_cash,
         expected_cash, cash_difference, opened_at, closed_at, closed_by,
         note, variance_approval_note, variance_approver_user_id
  INTO v_session
  FROM public.pos_sessions
  WHERE id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_session.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_session.status <> 'closed' THEN
    RAISE EXCEPTION 'session not closed yet' USING ERRCODE = '22023';
  END IF;

  IF NOT public.has_permission_any('pos:close_shift') THEN
    RAISE EXCEPTION 'permission denied: pos:close_shift' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_branch FROM public.branches WHERE id = v_session.branch_id;

  SELECT full_name INTO v_cashier_name
  FROM public.profiles WHERE id = v_session.closed_by;

  IF v_session.variance_approver_user_id IS NOT NULL THEN
    SELECT full_name INTO v_approver_name
    FROM public.profiles WHERE id = v_session.variance_approver_user_id;
  END IF;

  SELECT value INTO v_branch_tax
  FROM public.system_settings
  WHERE tenant_id = v_session.tenant_id AND key = 'branch_tax_code';

  v_printer_id := public.resolve_branch_printer_for_type(
    v_session.tenant_id,
    v_session.branch_id,
    'shift_close_report'
  );

  IF v_printer_id IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'no_printer');
  END IF;

  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'method',  payment_method,
      'count',   cnt,
      'amount',  amount
    ) ORDER BY payment_method), '[]'::jsonb),
    COALESCE(SUM(amount), 0)
  INTO v_breakdown, v_total_revenue
  FROM (
    SELECT
      COALESCE(payment_method, 'unknown') AS payment_method,
      COUNT(*) AS cnt,
      SUM(total_amount) AS amount
    FROM public.orders
    WHERE pos_session_id = p_session_id
      AND tenant_id = v_session.tenant_id
      AND payment_status = 'paid'
      AND status <> 'cancelled'
    GROUP BY payment_method
  ) AS grp;

  SELECT COALESCE(SUM(discount_amount), 0)
  INTO v_discount_total
  FROM public.orders
  WHERE pos_session_id = p_session_id
    AND tenant_id = v_session.tenant_id
    AND payment_status = 'paid'
    AND status <> 'cancelled';

  WITH paid_items AS (
    SELECT
      oi.item_name,
      oi.quantity,
      oi.unit_price,
      CASE
        WHEN jsonb_typeof(oi.modifiers) = 'array' THEN oi.modifiers
        ELSE '[]'::jsonb
      END AS modifiers,
      CASE
        WHEN jsonb_typeof(oi.sides) = 'array' THEN oi.sides
        ELSE '[]'::jsonb
      END AS sides
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
    WHERE o.pos_session_id = p_session_id
      AND o.tenant_id = v_session.tenant_id
      AND o.payment_status = 'paid'
      AND o.status <> 'cancelled'
      AND oi.status <> 'cancelled'
  ),
  item_unit_prices AS (
    SELECT
      pi.item_name,
      pi.quantity,
      pi.unit_price,
      pi.modifiers,
      pi.sides,
      COALESCE((
        SELECT SUM(COALESCE(NULLIF(m->>'price', '')::numeric, 0))
        FROM jsonb_array_elements(pi.modifiers) AS m
      ), 0) AS modifier_unit_sum,
      COALESCE((
        SELECT SUM(
          COALESCE(NULLIF(s->>'price', '')::numeric, 0)
          * COALESCE(NULLIF(s->>'quantity', '')::numeric, 1)
        )
        FROM jsonb_array_elements(pi.sides) AS s
      ), 0) AS side_unit_sum
    FROM paid_items pi
  ),
  main_agg AS (
    SELECT
      item_name AS name,
      'main'::TEXT AS source,
      COALESCE(SUM(COALESCE(quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(GREATEST(0, COALESCE(unit_price, 0) - modifier_unit_sum - side_unit_sum) * COALESCE(quantity, 0)), 0) AS revenue,
      1 AS source_order
    FROM item_unit_prices
    GROUP BY item_name
  ),
  side_agg AS (
    SELECT
      COALESCE(NULLIF(s->>'name', ''), NULLIF(s->>'side_item_name', ''), 'Side')::TEXT AS name,
      'side'::TEXT AS source,
      COALESCE(SUM(COALESCE(NULLIF(s->>'quantity', '')::numeric, 1) * COALESCE(pi.quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(
        COALESCE(NULLIF(s->>'price', '')::numeric, 0)
        * COALESCE(NULLIF(s->>'quantity', '')::numeric, 1)
        * COALESCE(pi.quantity, 0)
      ), 0) AS revenue,
      2 AS source_order
    FROM item_unit_prices pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.sides) AS s
    GROUP BY COALESCE(NULLIF(s->>'name', ''), NULLIF(s->>'side_item_name', ''), 'Side')
  ),
  mod_agg AS (
    SELECT
      COALESCE(NULLIF(m->>'name', ''), 'Modifier')::TEXT AS name,
      'modifier'::TEXT AS source,
      COALESCE(SUM(COALESCE(pi.quantity, 0)), 0)::INT AS qty,
      COALESCE(SUM(COALESCE(NULLIF(m->>'price', '')::numeric, 0) * COALESCE(pi.quantity, 0)), 0) AS revenue,
      3 AS source_order
    FROM item_unit_prices pi
    CROSS JOIN LATERAL jsonb_array_elements(pi.modifiers) AS m
    GROUP BY COALESCE(NULLIF(m->>'name', ''), 'Modifier')
  ),
  all_items AS (
    SELECT name, source, qty, revenue, source_order FROM main_agg
    UNION ALL
    SELECT name, source, qty, revenue, source_order FROM side_agg
    UNION ALL
    SELECT name, source, qty, revenue, source_order FROM mod_agg
  )
  SELECT
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'name', name,
        'source', source,
        'qty', qty,
        'revenue', revenue
      )
      ORDER BY revenue DESC, qty DESC, source_order, name
    ), '[]'::jsonb),
    COALESCE(SUM(qty), 0)::INT
  INTO v_item_breakdown, v_total_item_quantity
  FROM all_items;

  v_payload := jsonb_build_object(
    'kind',                  'shift_close_report',
    'branch_name',           COALESCE(v_branch.name, ''),
    'branch_address',        COALESCE(v_branch.address, ''),
    'branch_phone',          COALESCE(v_branch.phone, ''),
    'branch_tax_code',       COALESCE(v_branch_tax, ''),
    'session_id',            p_session_id,
    'cashier_name',          COALESCE(v_cashier_name, ''),
    'opened_at',             to_char(v_session.opened_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS'),
    'closed_at',             to_char(v_session.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS'),
    'opening_cash',          v_session.opening_cash,
    'closing_cash',          v_session.closing_cash,
    'expected_cash',         v_session.expected_cash,
    'cash_difference',       v_session.cash_difference,
    'note',                  v_session.note,
    'variance_note',         v_session.variance_approval_note,
    'variance_approver',     v_approver_name,
    'paid_order_count',      (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND payment_status = 'paid'
         AND status <> 'cancelled'
    ),
    'unpaid_order_count',    (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND payment_status <> 'paid'
         AND status <> 'cancelled'
    ),
    'cancelled_order_count', (
      SELECT COUNT(*) FROM public.orders
       WHERE pos_session_id = p_session_id
         AND tenant_id = v_session.tenant_id
         AND status = 'cancelled'
    ),
    'payment_breakdown',     v_breakdown,
    'total_revenue',         v_total_revenue,
    'discount_total',        COALESCE(v_discount_total, 0),
    'total_item_quantity',   COALESCE(v_total_item_quantity, 0),
    'item_breakdown',        COALESCE(v_item_breakdown, '[]'::jsonb),
    'printed_at',            to_char(v_now AT TIME ZONE 'Asia/Ho_Chi_Minh',
                                     'YYYY-MM-DD"T"HH24:MI:SS')
  );

  v_idempotency := 'session:' || p_session_id::TEXT || ':shift_close';

  INSERT INTO public.print_jobs (
    tenant_id, branch_id, printer_id, job_type,
    order_id, payload, idempotency_key, created_by
  ) VALUES (
    v_session.tenant_id, v_session.branch_id, v_printer_id, 'shift_close_report',
    NULL, v_payload, v_idempotency, v_uid
  )
  ON CONFLICT (idempotency_key) DO UPDATE SET
    payload = EXCLUDED.payload,
    status  = CASE WHEN public.print_jobs.status IN ('failed', 'expired')
                   THEN 'pending' ELSE public.print_jobs.status END,
    last_error = NULL,
    claimed_by_agent = NULL,
    claimed_at = NULL
  RETURNING id INTO v_job_id;

  RETURN jsonb_build_object(
    'session_id', p_session_id,
    'job_id',     v_job_id,
    'printer_id', v_printer_id
  );
END;
$$;


--
-- Name: FUNCTION enqueue_shift_close_print(p_session_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_shift_close_print(p_session_id bigint) IS 'Enqueue data-driven shift-close print payload. Includes paid-order discount_total and sold-item breakdown ordered by revenue desc.';


--
-- Name: ensure_branch_inventory_location_defaults(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_branch_inventory_location_defaults(p_tenant_id bigint, p_branch_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_branch_kind TEXT;
  v_warehouse_id BIGINT;
  v_kitchen_id BIGINT;
  v_needs_default_receive BOOLEAN;
  v_needs_default_issue BOOLEAN;
BEGIN
  SELECT branch_kind
  INTO v_branch_kind
  FROM public.branches
  WHERE id = p_branch_id
    AND tenant_id = p_tenant_id;

  IF NOT FOUND OR v_branch_kind IS DISTINCT FROM 'branch' THEN
    RETURN;
  END IF;

  SELECT il.id
  INTO v_warehouse_id
  FROM public.inventory_locations il
  WHERE il.tenant_id = p_tenant_id
    AND il.branch_id = p_branch_id
    AND il.location_kind = 'warehouse'
    AND il.is_active = TRUE
  ORDER BY il.is_default_receive DESC, il.sort_order NULLS LAST, il.id
  LIMIT 1;

  v_needs_default_receive := NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations il
    WHERE il.tenant_id = p_tenant_id
      AND il.branch_id = p_branch_id
      AND il.is_default_receive = TRUE
      AND il.is_active = TRUE
  );

  v_needs_default_issue := NOT EXISTS (
    SELECT 1
    FROM public.inventory_locations il
    WHERE il.tenant_id = p_tenant_id
      AND il.branch_id = p_branch_id
      AND il.is_default_issue = TRUE
      AND il.is_active = TRUE
  );

  IF v_warehouse_id IS NULL THEN
    INSERT INTO public.inventory_locations (
      tenant_id,
      branch_id,
      code,
      name,
      location_kind,
      is_active,
      is_default_receive,
      is_default_issue,
      is_default_consumption,
      sort_order
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      'main_warehouse',
      U&'Kho chi nh\00E1nh',
      'warehouse',
      TRUE,
      v_needs_default_receive,
      v_needs_default_issue,
      FALSE,
      0
    )
    ON CONFLICT (code, branch_id, tenant_id) DO UPDATE
    SET name = EXCLUDED.name,
        location_kind = 'warehouse',
        is_active = TRUE,
        is_default_receive = EXCLUDED.is_default_receive,
        is_default_issue = EXCLUDED.is_default_issue,
        is_default_consumption = FALSE,
        sort_order = EXCLUDED.sort_order,
        updated_at = now()
    RETURNING id INTO v_warehouse_id;
  ELSE
    IF v_needs_default_receive THEN
      UPDATE public.inventory_locations
      SET is_default_receive = TRUE,
          updated_at = now()
      WHERE id = v_warehouse_id;
    END IF;

    IF v_needs_default_issue THEN
      UPDATE public.inventory_locations
      SET is_default_issue = TRUE,
          updated_at = now()
      WHERE id = v_warehouse_id;
    END IF;
  END IF;

  SELECT il.id
  INTO v_kitchen_id
  FROM public.inventory_locations il
  WHERE il.tenant_id = p_tenant_id
    AND il.branch_id = p_branch_id
    AND il.location_kind = 'kitchen'
    AND il.is_active = TRUE
    AND il.is_default_consumption = TRUE
  ORDER BY il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_kitchen_id IS NOT NULL THEN
    RETURN;
  END IF;

  UPDATE public.inventory_locations
  SET is_default_consumption = FALSE,
      updated_at = now()
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND is_active = TRUE
    AND is_default_consumption = TRUE;

  SELECT il.id
  INTO v_kitchen_id
  FROM public.inventory_locations il
  WHERE il.tenant_id = p_tenant_id
    AND il.branch_id = p_branch_id
    AND il.location_kind = 'kitchen'
    AND il.is_active = TRUE
  ORDER BY il.sort_order NULLS LAST, il.id
  LIMIT 1;

  IF v_kitchen_id IS NOT NULL THEN
    UPDATE public.inventory_locations
    SET is_default_consumption = TRUE,
        updated_at = now()
    WHERE id = v_kitchen_id;
    RETURN;
  END IF;

  INSERT INTO public.inventory_locations (
    tenant_id,
    branch_id,
    code,
    name,
    location_kind,
    is_active,
    is_default_receive,
    is_default_issue,
    is_default_consumption,
    sort_order
  )
  VALUES (
    p_tenant_id,
    p_branch_id,
    'kitchen',
    U&'B\1EBFp',
    'kitchen',
    TRUE,
    FALSE,
    FALSE,
    TRUE,
    10
  )
  ON CONFLICT (code, branch_id, tenant_id) DO UPDATE
  SET name = EXCLUDED.name,
      location_kind = 'kitchen',
      is_active = TRUE,
      is_default_receive = FALSE,
      is_default_issue = FALSE,
      is_default_consumption = TRUE,
      sort_order = EXCLUDED.sort_order,
      updated_at = now();
END;
$$;


--
-- Name: escalate_round_4(bigint, bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_round_4(p_session_id bigint, p_ingredient_id bigint, p_final_qty numeric, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_recount') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF length(COALESCE(p_note, '')) < 20 THEN RAISE EXCEPTION 'escalation note must be at least 20 characters' USING ERRCODE = '22023'; END IF;
  INSERT INTO public.stocktake_lines (tenant_id, session_id, ingredient_id, system_quantity,
    counted_quantity, counted_by, counted_at, round_no, variance_reason, is_final, needs_recount, abc_class)
  SELECT v_ss.tenant_id, p_session_id, p_ingredient_id,
    (SELECT system_quantity FROM public.stocktake_lines WHERE session_id=p_session_id AND ingredient_id=p_ingredient_id AND round_no=1),
    p_final_qty, v_uid, now(), 4, '[ROUND4] ' || p_note, true, false,
    (SELECT abc_class FROM public.stocktake_lines WHERE session_id=p_session_id AND ingredient_id=p_ingredient_id AND round_no=1)
  ON CONFLICT (session_id, ingredient_id, round_no) DO UPDATE SET
    counted_quantity = EXCLUDED.counted_quantity, counted_by = EXCLUDED.counted_by,
    counted_at = EXCLUDED.counted_at, variance_reason = EXCLUDED.variance_reason, is_final = true;
  UPDATE public.stocktake_lines SET counted_quantity = p_final_qty, is_final = true, needs_recount = false,
    variance_reason = COALESCE(variance_reason, '') || E'\n[ROUND4 escalated by ' || v_uid::TEXT || ']'
  WHERE session_id = p_session_id AND ingredient_id = p_ingredient_id AND round_no = 1;
END; $$;


--
-- Name: expire_stuck_print_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_stuck_print_jobs(p_stale_after_seconds integer DEFAULT 300) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_revived INT;
BEGIN
  UPDATE public.print_jobs
     SET status           = 'pending',
         claimed_by_agent = NULL,
         claimed_at       = NULL,
         last_error       = COALESCE(last_error, '') ||
                            CASE WHEN COALESCE(last_error, '') = '' THEN '' ELSE E'\n' END ||
                            'reaped: stuck in processing >' ||
                            p_stale_after_seconds || 's at ' || now()::text
   WHERE status     = 'processing'
     AND claimed_at < (now() - make_interval(secs => p_stale_after_seconds));

  GET DIAGNOSTICS v_revived = ROW_COUNT;
  RETURN v_revived;
END;
$$;


--
-- Name: extend_express_window(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extend_express_window(p_branch_id bigint, p_minutes integer, p_note text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_tz TEXT; v_recent INT; v_until TIMESTAMPTZ; v_win RECORD;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:grn_express_extend') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_minutes IS NULL OR p_minutes <= 0 OR p_minutes > 60 THEN RAISE EXCEPTION 'minutes must be in (0, 60]' USING ERRCODE = '22023'; END IF;
  IF length(COALESCE(p_note, '')) < 10 THEN RAISE EXCEPTION 'note must be at least 10 characters' USING ERRCODE = '22023'; END IF;
  SELECT COUNT(*) INTO v_recent FROM public.grn_express_extend_audit WHERE user_id = v_uid AND created_at > now() - INTERVAL '7 days';
  IF v_recent >= 3 THEN RAISE EXCEPTION 'express-extend rate-limit (3/week) exceeded' USING ERRCODE = '54000'; END IF;
  SELECT timezone INTO v_tz FROM public.branches WHERE id = p_branch_id;
  IF v_tz IS NULL THEN v_tz := 'Asia/Ho_Chi_Minh'; END IF;
  SELECT enabled, start_time, end_time INTO v_win FROM public.branch_express_window WHERE branch_id = p_branch_id;
  IF NOT FOUND OR NOT v_win.enabled THEN RAISE EXCEPTION 'express window not enabled for branch %', p_branch_id USING ERRCODE = '22023'; END IF;
  v_until := (((now() AT TIME ZONE v_tz)::DATE + v_win.end_time) AT TIME ZONE v_tz) + make_interval(mins => p_minutes);
  INSERT INTO public.grn_express_extend_audit (tenant_id, branch_id, user_id, extended_until, extend_minutes, note)
  SELECT b.tenant_id, p_branch_id, v_uid, v_until, p_minutes, p_note FROM public.branches b WHERE b.id = p_branch_id;
  RETURN v_until;
END; $$;


--
-- Name: finalize_paid_order(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_paid_order(p_order_id bigint, p_actor_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order  RECORD;
  v_actor  UUID := COALESCE(p_actor_id, auth.uid());
BEGIN
  SELECT o.id, o.tenant_id, o.status
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RETURN;
  END IF;

  UPDATE public.orders
  SET status     = 'completed',
      updated_at = now()
  WHERE id = p_order_id;

  IF v_actor IS NOT NULL THEN
    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_order.tenant_id,
      p_order_id,
      v_order.status,
      'completed',
      v_actor,
      'auto_complete_on_payment'
    );
  END IF;
END;
$$;


--
-- Name: FUNCTION finalize_paid_order(p_order_id bigint, p_actor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalize_paid_order(p_order_id bigint, p_actor_id uuid) IS 'Helper: marks order as completed after payment confirmed. Idempotent. Does NOT force order_items/kds_tickets — chef continues via KDS flow even after order completed (pay-first-cook-after is a valid F&B case). Table release fires via trg_release_table_on_order_status trigger.';


--
-- Name: finalize_stocktake(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_stocktake(p_session_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD; v_pending INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_complete') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF v_ss.status <> 'in_progress' THEN RAISE EXCEPTION 'session not in_progress' USING ERRCODE = '22023'; END IF;
  SELECT COUNT(*) INTO v_pending FROM public.stocktake_lines WHERE session_id = p_session_id AND round_no = 1 AND is_final = false;
  IF v_pending > 0 THEN RAISE EXCEPTION 'cannot finalize: % round-1 line(s) still not final', v_pending USING ERRCODE = '22023'; END IF;
  UPDATE public.stocktake_sessions SET status = 'completed', completed_at = now() WHERE id = p_session_id;
  RETURN jsonb_build_object('session_id', p_session_id, 'status', 'completed', 'completed_at', now());
END; $$;


--
-- Name: finance_views_last_refresh(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_views_last_refresh() RETURNS TABLE(last_run timestamp with time zone, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_permission_any('finance:view') THEN
    RAISE EXCEPTION 'permission denied: finance:view required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT d.end_time, d.status
  FROM cron.job_run_details d
  JOIN cron.job j ON j.jobid = d.jobid
  WHERE j.jobname = 'refresh-finance-views-daily'
  ORDER BY d.start_time DESC
  LIMIT 1;
END;
$$;


--
-- Name: find_payment_order_desync(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_payment_order_desync(p_since timestamp with time zone DEFAULT (now() - '30 days'::interval)) RETURNS TABLE(payment_id bigint, order_id bigint, tenant_id bigint, branch_id bigint, amount numeric, payment_method text, payment_status text, payment_paid_at timestamp with time zone, order_status text, order_payment_status text, order_created_at timestamp with time zone, age_minutes integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    p.id                                     AS payment_id,
    p.order_id                               AS order_id,
    p.tenant_id                              AS tenant_id,
    p.branch_id                              AS branch_id,
    p.amount                                 AS amount,
    p.method                                 AS payment_method,
    p.status                                 AS payment_status,
    p.paid_at                                AS payment_paid_at,
    o.status                                 AS order_status,
    o.payment_status                         AS order_payment_status,
    o.created_at                             AS order_created_at,
    GREATEST(
      EXTRACT(EPOCH FROM (now() - p.paid_at))::INTEGER / 60,
      0
    )                                        AS age_minutes
  FROM public.payments p
  JOIN public.orders   o ON o.id = p.order_id AND o.tenant_id = p.tenant_id
  WHERE p.tenant_id = public.auth_tenant_id()
    AND p.status = 'completed'
    AND COALESCE(o.payment_status, 'unpaid') <> 'paid'
    AND p.paid_at >= p_since
    AND public.has_permission_any('finance:view')
  ORDER BY p.paid_at DESC;
$$;


--
-- Name: FUNCTION find_payment_order_desync(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.find_payment_order_desync(p_since timestamp with time zone) IS 'Ops reconciliation: rows are payments marked completed whose order did not flip to paid. Returns empty for callers without finance:view. Lookback window defaults to 30 days.';


--
-- Name: get_branch_menu_daily_limits_for_pos(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_branch_menu_daily_limits_for_pos(p_branch_id bigint) RETURNS TABLE(menu_item_id bigint, limit_quantity integer, is_disabled boolean, sold_today integer)
    LANGUAGE sql STABLE SECURITY DEFINER
