    WHEN 'ABB' THEN '970423'
    WHEN 'LIENVIETPOSTBANK' THEN '970449'
    WHEN 'LPB' THEN '970449'
    WHEN 'KIENLONGBANK' THEN '970452'
    WHEN 'KLB' THEN '970452'
