--
-- Name: print_vietqr_crc16(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_vietqr_crc16(p_input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_crc INT := 65535;
  v_i INT;
  v_j INT;
BEGIN
  FOR v_i IN 1..length(COALESCE(p_input, '')) LOOP
    v_crc := (v_crc # ((ascii(substring(p_input FROM v_i FOR 1)) << 8) & 65535)) & 65535;
    FOR v_j IN 1..8 LOOP
      IF (v_crc & 32768) <> 0 THEN
        v_crc := ((v_crc << 1) # 4129) & 65535;
      ELSE
        v_crc := (v_crc << 1) & 65535;
      END IF;
    END LOOP;
  END LOOP;
  RETURN lpad(upper(to_hex(v_crc)), 4, '0');
END;
$$;


--
-- Name: print_vietqr_emvco(text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_vietqr_emvco(p_bank_code text, p_account_no text, p_account_name text, p_amount numeric, p_description text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bin TEXT;
  v_amount TEXT;
  v_description TEXT;
  v_merchant_name TEXT;
  v_beneficiary TEXT;
  v_merchant_account_info TEXT;
  v_additional TEXT := '';
  v_payload TEXT;
BEGIN
  IF COALESCE(p_bank_code, '') = ''
     OR COALESCE(p_account_no, '') = ''
     OR COALESCE(p_amount, 0) <= 0 THEN
    RETURN NULL;
  END IF;

  v_bin := public.print_vietqr_bank_bin(p_bank_code);
  v_amount := trim(to_char(round(p_amount), 'FM9999999999999999'));
  v_description := public.print_vietqr_ascii(p_description, 25);
  v_merchant_name := COALESCE(
    NULLIF(public.print_vietqr_ascii(p_account_name, 25), ''),
    'MERCHANT'
  );

  v_beneficiary :=
    '00' || lpad(length(v_bin)::text, 2, '0') || v_bin
    || '01' || lpad(length(p_account_no)::text, 2, '0') || p_account_no;
  v_merchant_account_info :=
    '0010A000000727'
    || '01' || lpad(length(v_beneficiary)::text, 2, '0') || v_beneficiary
    || '0208QRIBFTTA';

  IF v_description <> '' THEN
    v_additional := '08' || lpad(length(v_description)::text, 2, '0') || v_description;
  END IF;

  v_payload :=
    '000201'
    || '010212'
    || '38' || lpad(length(v_merchant_account_info)::text, 2, '0') || v_merchant_account_info
    || '5303704'
    || '54' || lpad(length(v_amount)::text, 2, '0') || v_amount
    || '5802VN'
    || '59' || lpad(length(v_merchant_name)::text, 2, '0') || v_merchant_name
    || '6007VIETNAM'
    || CASE WHEN v_additional <> ''
         THEN '62' || lpad(length(v_additional)::text, 2, '0') || v_additional
         ELSE ''
       END;

  v_payload := v_payload || '6304';
  RETURN v_payload || public.print_vietqr_crc16(v_payload);
END;
$$;


--
-- Name: FUNCTION print_vietqr_emvco(p_bank_code text, p_account_no text, p_account_name text, p_amount numeric, p_description text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.print_vietqr_emvco(p_bank_code text, p_account_no text, p_account_name text, p_amount numeric, p_description text) IS 'VietQR EMVCo payload for thermal printing. Mirrors buildVietQrEmvco in packages/shared/src/providers/impl/vietqr.ts; keep outputs identical.';


--
-- Name: recall_kds_ticket(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_kds_ticket(p_ticket_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket     RECORD;
  v_new_status TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('kds:recall') THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT id, tenant_id, branch_id, status
  INTO v_ticket
  FROM public.kds_tickets
  WHERE id = p_ticket_id
    AND tenant_id = public.auth_tenant_id()
    AND public.can_access_branch(branch_id)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_ticket.status = 'ready' THEN
    v_new_status := 'preparing';
  ELSIF v_ticket.status = 'preparing' THEN
    v_new_status := 'pending';
  ELSE
    RAISE EXCEPTION 'Ticket cannot be recalled from status %', v_ticket.status
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.kds_tickets
  SET status    = v_new_status,
      bumped_at = NULL,
      bumped_by = NULL
  WHERE id = p_ticket_id;

  RETURN v_new_status;
END;
$$;


--
-- Name: recompute_supplier_invoice_matching(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_supplier_invoice_matching(p_invoice_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant   BIGINT := public.auth_tenant_id();
  v_inv      RECORD;
  v_grn_tot  NUMERIC(15,2);
  v_po_tot   NUMERIC(15,2);
  v_status   TEXT := 'matched';
BEGIN
  SELECT * INTO v_inv FROM public.supplier_invoices
  WHERE id = p_invoice_id AND tenant_id = v_tenant;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_inv.grn_id IS NOT NULL THEN
    SELECT COALESCE(SUM(gi.total_cost), 0) INTO v_grn_tot
    FROM public.grn_items gi WHERE gi.grn_id = v_inv.grn_id;
    IF v_inv.total_amount > v_grn_tot * 1.02 THEN
      v_status := 'discrepancy';
    END IF;
  END IF;

  IF v_inv.po_id IS NOT NULL THEN
    SELECT COALESCE(SUM(poi.line_total), 0) INTO v_po_tot
    FROM public.purchase_order_items poi WHERE poi.po_id = v_inv.po_id;
    IF v_po_tot > 0 AND abs(v_inv.subtotal - v_po_tot) / v_po_tot > 0.02 THEN
      v_status := 'discrepancy';
    END IF;
  END IF;

  UPDATE public.supplier_invoices
  SET matching_status = v_status, updated_at = now()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object('invoice_id', p_invoice_id, 'matching_status', v_status);
END;
$$;


--
-- Name: reduce_order_item_quantity(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reduce_order_item_quantity(p_order_item_id bigint, p_new_quantity integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid           UUID;
  v_prof_tenant   BIGINT;
  v_prof_branch   BIGINT;
  v_prof_role     TEXT;
  v_item          public.order_items%ROWTYPE;
  v_order         public.orders%ROWTYPE;
  v_old_qty       INT;
  v_qty_diff      INT;
  v_new_subtotal  NUMERIC(15,2);
  v_subtotal_sum  NUMERIC(15,2);
  v_disc_amount   NUMERIC(15,2);
  v_total_amount  NUMERIC(15,2);
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'reason too short' USING ERRCODE = '22023';
  END IF;

  IF p_new_quantity IS NULL OR p_new_quantity < 1 THEN
    RAISE EXCEPTION 'new quantity must be >= 1' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_item.status IN ('served', 'cancelled') THEN
    RAISE EXCEPTION 'item not reducible' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  v_old_qty := v_item.quantity;

  IF p_new_quantity >= v_old_qty THEN
    RAISE EXCEPTION 'no reduction needed' USING ERRCODE = '22023';
  END IF;

  v_qty_diff := v_old_qty - p_new_quantity;
  v_new_subtotal := v_item.unit_price * p_new_quantity;

  UPDATE public.order_items
  SET quantity   = p_new_quantity,
      subtotal   = v_new_subtotal,
      updated_at = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET updated_at = now()
  WHERE order_item_id = p_order_item_id
    AND tenant_id = v_item.tenant_id
    AND status NOT IN ('served', 'cancelled');

  IF v_item.menu_item_id IS NOT NULL THEN
    UPDATE public.branch_menu_item_daily_limits
    SET sold_today = GREATEST(sold_today - v_qty_diff, 0),
        updated_at = now()
    WHERE branch_id = v_order.branch_id
      AND menu_item_id = v_item.menu_item_id
      AND limit_date = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  END IF;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal_sum
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  v_disc_amount := public.compute_discount_amount(
    v_order.discount_type, v_order.discount_value, v_subtotal_sum
  );
  v_total_amount := v_subtotal_sum
    + COALESCE(v_order.service_charge, 0)
    - v_disc_amount;

  UPDATE public.orders
  SET subtotal        = v_subtotal_sum,
      discount_amount = v_disc_amount,
      total_amount    = v_total_amount,
      updated_at      = now()
  WHERE id = v_item.order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
    'reduce_item ' || p_order_item_id::text
      || ': ' || v_old_qty::text || '->' || p_new_quantity::text
      || ': ' || p_reason
  );

  RETURN jsonb_build_object(
    'order_id',           v_item.order_id,
    'order_item_id',      p_order_item_id,
    'old_quantity',       v_old_qty,
    'new_quantity',       p_new_quantity,
    'qty_reduced',        v_qty_diff,
    'subtotal',           v_subtotal_sum,
    'discount_amount',    v_disc_amount,
    'total_amount',       v_total_amount,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


--
-- Name: FUNCTION reduce_order_item_quantity(p_order_item_id bigint, p_new_quantity integer, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reduce_order_item_quantity(p_order_item_id bigint, p_new_quantity integer, p_reason text) IS 'Giảm SL món đã gửi (qty: từ N xuống M, M<N, M>=1). Lock order + item, permission pos:void_order, recompute subtotal/discount/total qua compute_discount_amount, bump kds_tickets.updated_at, decrement branch_menu_item_daily_limits.sold_today cho menu_item của row (DAILY-LIMIT-REDUCE-QTY-LEAK fix). Reason >=5 ký tự, ghi order_status_history. Block khi item served/cancelled, order completed/cancelled, hoặc payment_status=paid.';


--
-- Name: refresh_abc_classification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_abc_classification() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count INT;
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_inventory_value_ranking;
  DELETE FROM public.ingredient_abc_class;
  INSERT INTO public.ingredient_abc_class (tenant_id, branch_id, ingredient_id, class, stock_value, cumulative_share)
  WITH ranked AS (
    SELECT r.tenant_id, r.branch_id, r.ingredient_id, r.total_value,
      SUM(r.total_value) OVER (PARTITION BY r.tenant_id, r.branch_id ORDER BY r.total_value DESC
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum,
      SUM(r.total_value) OVER (PARTITION BY r.tenant_id, r.branch_id) AS branch_total
    FROM public.mv_inventory_value_ranking r WHERE r.total_value > 0
  )
  SELECT tenant_id, branch_id, ingredient_id,
    CASE WHEN running_sum / NULLIF(branch_total, 0) <= 0.80 THEN 'A'
         WHEN running_sum / NULLIF(branch_total, 0) <= 0.95 THEN 'B'
         ELSE 'C' END,
    total_value, COALESCE(running_sum / NULLIF(branch_total, 0), 0)::NUMERIC(5,4)
  FROM ranked;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END; $$;


--
-- Name: refresh_finance_views(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_finance_views() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Authenticated callers must hold settings:tenant (matches the server action);
  -- pg_cron runs with no JWT (auth.uid() IS NULL) and bypasses the check.
  IF auth.uid() IS NOT NULL AND NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'permission denied: settings:tenant required' USING ERRCODE = '42501';
  END IF;

  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_daily_revenue;
  INSERT INTO public.mv_refresh_log(view_name, refreshed_at)
    VALUES ('mv_daily_revenue', now())
    ON CONFLICT (view_name) DO UPDATE SET refreshed_at = EXCLUDED.refreshed_at;

  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_top_items;
  INSERT INTO public.mv_refresh_log(view_name, refreshed_at)
    VALUES ('mv_top_items', now())
    ON CONFLICT (view_name) DO UPDATE SET refreshed_at = EXCLUDED.refreshed_at;

  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_food_cost;
  INSERT INTO public.mv_refresh_log(view_name, refreshed_at)
    VALUES ('mv_food_cost', now())
    ON CONFLICT (view_name) DO UPDATE SET refreshed_at = EXCLUDED.refreshed_at;
END;
$$;


--
-- Name: refresh_inventory_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_inventory_dashboard() RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT (public.has_permission(NULL, 'reports:view_branch') OR public.has_permission(NULL, 'reports:view_tenant')
       OR public.has_permission(NULL, 'settings:branch') OR public.has_permission(NULL, 'settings:tenant')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_inventory_stock_current;
  RETURN now();
END; $$;


--
-- Name: register_branch_presence(bigint, bigint, text, text, inet); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_branch_presence(p_tenant_id bigint, p_branch_id bigint, p_agent_id text, p_token_sha256 text, p_ip_address inet) RETURNS TABLE(ok boolean, status text, ip text, skipped boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now TIMESTAMPTZ := now();
  v_token_id BIGINT;
  v_token_revoked_at TIMESTAMPTZ;
  v_agent_branch_id BIGINT;
  v_existing RECORD;
  v_updated_id BIGINT;
BEGIN
  SELECT id, revoked_at
    INTO v_token_id, v_token_revoked_at
  FROM public.printer_agent_presence_tokens
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND agent_id = p_agent_id
    AND token_sha256 = lower(p_token_sha256)
  FOR UPDATE;

  IF v_token_id IS NULL OR v_token_revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'invalid_token', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  UPDATE public.printer_agent_presence_tokens
  SET last_attempt_at = v_now
  WHERE id = v_token_id
    AND (
      last_attempt_at IS NULL
      OR last_attempt_at <= v_now - INTERVAL '30 seconds'
    )
  RETURNING id INTO v_updated_id;

  IF v_updated_id IS NULL THEN
    RETURN QUERY SELECT false, 'rate_limited', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  SELECT branch_id
    INTO v_agent_branch_id
  FROM public.printer_agents
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND agent_id = p_agent_id;

  IF v_agent_branch_id IS NULL THEN
    RETURN QUERY SELECT false, 'agent_not_registered', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  SELECT id, last_seen_at, revoked_at
    INTO v_existing
  FROM public.branch_trusted_egress_ips
  WHERE tenant_id = p_tenant_id
    AND branch_id = p_branch_id
    AND ip_address = p_ip_address
  FOR UPDATE;

  IF v_existing.id IS NOT NULL AND v_existing.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, 'ip_revoked', p_ip_address::TEXT, false;
    RETURN;
  END IF;

  IF v_existing.id IS NOT NULL
     AND v_existing.last_seen_at > v_now - INTERVAL '60 seconds' THEN
    UPDATE public.printer_agent_presence_tokens
    SET last_used_at = v_now
    WHERE id = v_token_id;

    RETURN QUERY SELECT true, 'skipped', p_ip_address::TEXT, true;
    RETURN;
  END IF;

  IF v_existing.id IS NOT NULL THEN
    v_updated_id := NULL;

    UPDATE public.branch_trusted_egress_ips
    SET
      registered_via = 'agent',
      registered_by_agent_id = p_agent_id,
      last_seen_at = v_now
    WHERE id = v_existing.id
      AND revoked_at IS NULL
    RETURNING id INTO v_updated_id;

    IF v_updated_id IS NULL THEN
      RETURN QUERY SELECT false, 'ip_revoked', p_ip_address::TEXT, false;
      RETURN;
    END IF;
  ELSE
    INSERT INTO public.branch_trusted_egress_ips (
      tenant_id,
      branch_id,
      ip_address,
      registered_via,
      registered_by_agent_id,
      last_seen_at
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      p_ip_address,
      'agent',
      p_agent_id,
      v_now
    );
  END IF;

  UPDATE public.printer_agent_presence_tokens
  SET last_used_at = v_now
  WHERE id = v_token_id;

  RETURN QUERY SELECT true, 'ok', p_ip_address::TEXT, false;
END;
$$;


--
-- Name: FUNCTION register_branch_presence(p_tenant_id bigint, p_branch_id bigint, p_agent_id text, p_token_sha256 text, p_ip_address inet); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.register_branch_presence(p_tenant_id bigint, p_branch_id bigint, p_agent_id text, p_token_sha256 text, p_ip_address inet) IS 'Service-role-only atomic branch presence registration. Validates per-agent token hash, rate-limits 1/30s, and never clears revoked trusted IP rows.';


--
-- Name: reject_leave_request(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_leave_request(p_request_id bigint, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_user_id   UUID   := auth.uid();
  v_request   public.leave_requests%ROWTYPE;
  v_reason    TEXT := NULLIF(trim(COALESCE(p_reason, '')), '');
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'reject_leave_request: missing auth context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_reason IS NOT NULL AND char_length(v_reason) > 500 THEN
    RAISE EXCEPTION 'reject_leave_request: reason too long'
      USING ERRCODE = 'string_data_right_truncation';
  END IF;

  SELECT * INTO v_request
  FROM public.leave_requests
  WHERE id = p_request_id
    AND tenant_id = v_tenant_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'reject_leave_request: request not found'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF NOT public.has_permission(v_request.branch_id, 'hr:approve_leave_request') THEN
    RAISE EXCEPTION 'reject_leave_request: missing permission for this branch'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'reject_leave_request: request is %, not pending', v_request.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = v_request.employee_id
      AND e.profile_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'reject_leave_request: cannot review own request'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  UPDATE public.leave_requests
  SET status = 'rejected',
      reviewed_by = v_user_id,
      reviewed_at = now(),
      rejected_reason = v_reason
  WHERE id = p_request_id;

  PERFORM public.log_audit(
    'reject'::TEXT,
    'leave_request'::TEXT,
    p_request_id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'rejected', 'reason', v_reason)
  );
END;
$$;


--
-- Name: FUNCTION reject_leave_request(p_request_id bigint, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reject_leave_request(p_request_id bigint, p_reason text) IS 'Manager rejects a pending leave_request within branch scope and records an optional reason.';


--
-- Name: release_branch_menu_daily_holds(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_branch_id bigint := public.auth_branch_id();
  v_role text := public.auth_role();
  v_released integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_hold_token IS NULL THEN
    RAISE EXCEPTION 'hold_token required' USING ERRCODE = '22023';
  END IF;

  IF v_role NOT IN ('owner', 'branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'permission denied: pos daily-limit hold' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('owner')
     AND (v_branch_id IS NULL OR v_branch_id <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  UPDATE public.branch_menu_item_daily_holds h
  SET released_at = now(),
      updated_at = now()
  WHERE h.tenant_id = v_tenant_id
    AND h.branch_id = p_branch_id
    AND h.hold_token = p_hold_token
    AND h.held_by = v_uid
    AND h.committed_at IS NULL
    AND h.released_at IS NULL;

  GET DIAGNOSTICS v_released = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'hold_token', p_hold_token,
    'released_count', v_released
  );
END;
$$;


--
-- Name: FUNCTION release_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.release_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid) IS 'Release active POS daily-limit holds owned by the caller token for a branch.';


--
-- Name: release_table(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_table(p_table_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.tables
  SET status = 'available'
  WHERE id = p_table_id
    AND branch_id = public.auth_branch_id()
    AND tenant_id = public.auth_tenant_id();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Table not found or not in your branch' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: release_zone_lock(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_zone_lock(p_session_id bigint, p_zone_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_count INT;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  DELETE FROM public.stocktake_zone_locks WHERE session_id = p_session_id AND zone_id = p_zone_id AND locked_by = v_uid;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count > 0;
END; $$;


--
-- Name: reopen_period(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_period(p_tenant_id bigint, p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_tenant_id <> public.auth_tenant_id() THEN RAISE EXCEPTION 'cross-tenant reopen forbidden' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission(NULL, 'accounting:period_reopen') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  UPDATE public.accounting_periods SET soft_closed_at = NULL, hard_closed_at = NULL, closed_by = v_uid
   WHERE tenant_id = p_tenant_id AND year = p_year AND month = p_month;
END; $$;


--
-- Name: replace_tax_invoice(bigint, text, text, timestamp with time zone, text, text, text, numeric, numeric, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_tax_invoice(p_old_id bigint, p_reason text, p_agreement_ref text, p_agreement_date timestamp with time zone, p_buyer_name text, p_buyer_tax_code text, p_buyer_address text, p_subtotal numeric, p_vat_rate numeric, p_vat_amount numeric, p_total_amount numeric, p_provider text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old        RECORD;
  v_actor      UUID;
  v_new_id     BIGINT;
  v_chain_depth INTEGER;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'forbidden_no_auth' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 20 THEN
    RAISE EXCEPTION 'reason_too_short' USING ERRCODE = '23514';
  END IF;
  IF length(p_reason) > 255 THEN
    RAISE EXCEPTION 'reason_too_long' USING ERRCODE = '23514';
  END IF;

  IF p_agreement_ref IS NULL OR length(trim(p_agreement_ref)) = 0 THEN
    RAISE EXCEPTION 'agreement_ref_required' USING ERRCODE = '23514';
  END IF;
  IF length(p_agreement_ref) > 225 THEN
    RAISE EXCEPTION 'agreement_ref_too_long' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_old
  FROM public.tax_invoices
  WHERE id = p_old_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_old.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'permission_denied_settings_tenant' USING ERRCODE = '42501';
  END IF;

  IF v_old.status IS DISTINCT FROM 'issued' THEN
    RAISE EXCEPTION 'only_issued_can_be_replaced' USING ERRCODE = '22023';
  END IF;

  IF v_old.replaced_by IS NOT NULL THEN
    RAISE EXCEPTION 'already_replaced' USING ERRCODE = '22023';
  END IF;

  IF v_old.invoice_kind IS DISTINCT FROM 'per_order' THEN
    RAISE EXCEPTION 'b2c_summary_replace_not_supported' USING ERRCODE = '0A000';
  END IF;

  IF p_agreement_date > now() THEN
    RAISE EXCEPTION 'agreement_date_in_future' USING ERRCODE = '22008';
  END IF;
  IF v_old.issued_at IS NOT NULL AND p_agreement_date < v_old.issued_at THEN
    RAISE EXCEPTION 'agreement_date_before_issued_at' USING ERRCODE = '22008';
  END IF;

  WITH RECURSIVE chain AS (
    SELECT id, replaced_for, 1 AS depth
    FROM public.tax_invoices
    WHERE id = p_old_id
    UNION ALL
    SELECT t.id, t.replaced_for, c.depth + 1
    FROM public.tax_invoices t
    JOIN chain c ON t.id = c.replaced_for
    WHERE c.depth < 10
  )
  SELECT MAX(depth) INTO v_chain_depth FROM chain;

  IF v_chain_depth >= 3 THEN
    RAISE EXCEPTION 'replacement_chain_too_deep_max_3' USING ERRCODE = '22023';
  END IF;

  UPDATE public.tax_invoices
  SET status = 'replaced',
      cancelled_at = now(),
      updated_at = now()
  WHERE id = p_old_id;

  INSERT INTO public.tax_invoices (
    tenant_id, branch_id, order_id,
    status, invoice_kind,
    buyer_name, buyer_tax_code, buyer_address,
    subtotal, vat_rate, vat_amount, total_amount,
    provider, provider_data,
    replaced_for,
    created_by
  )
  VALUES (
    v_old.tenant_id, v_old.branch_id, v_old.order_id,
    'draft', 'per_order',
    p_buyer_name, p_buyer_tax_code, p_buyer_address,
    p_subtotal, p_vat_rate, p_vat_amount, p_total_amount,
    p_provider,
    jsonb_build_object(
      'replace', jsonb_build_object(
        'reason', p_reason,
        'agreement_ref', p_agreement_ref,
        'agreement_date', p_agreement_date,
        'original_invoice_id', v_old.id,
        'original_invoice_number', v_old.invoice_number,
        'original_issued_at', v_old.issued_at,
        'original_provider_ref', v_old.provider_ref
      )
    ),
    p_old_id,
    v_actor
  )
  RETURNING id INTO v_new_id;

  UPDATE public.tax_invoices
  SET replaced_by = v_new_id
  WHERE id = p_old_id;

  INSERT INTO public.tax_invoice_events
    (tax_invoice_id, from_status, to_status, payload, note, actor_id, tenant_id)
  VALUES
    (p_old_id, 'issued', 'replaced',
     jsonb_build_object(
       'reason', p_reason,
       'replaced_by', v_new_id,
       'agreement_ref', p_agreement_ref,
       'agreement_date', p_agreement_date
     ),
     'TT78 §7 replace: ' || p_reason,
     v_actor,
     v_old.tenant_id),
    (v_new_id, NULL, 'draft',
     jsonb_build_object(
       'replaces', p_old_id,
       'original_invoice_number', v_old.invoice_number
     ),
     'Replacement draft for invoice ' || COALESCE(v_old.invoice_number, '#' || p_old_id::TEXT),
     v_actor,
     v_old.tenant_id);

  RETURN v_new_id;
END;
$$;


--
-- Name: FUNCTION replace_tax_invoice(p_old_id bigint, p_reason text, p_agreement_ref text, p_agreement_date timestamp with time zone, p_buyer_name text, p_buyer_tax_code text, p_buyer_address text, p_subtotal numeric, p_vat_rate numeric, p_vat_amount numeric, p_total_amount numeric, p_provider text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replace_tax_invoice(p_old_id bigint, p_reason text, p_agreement_ref text, p_agreement_date timestamp with time zone, p_buyer_name text, p_buyer_tax_code text, p_buyer_address text, p_subtotal numeric, p_vat_rate numeric, p_vat_amount numeric, p_total_amount numeric, p_provider text) IS 'TT78 §7 atomic replacement RPC. Locks OLD invoice, flips to replaced, INSERTs NEW draft, links both via replaced_by/replaced_for, audits via tax_invoice_events — all in single tx. Caller then transitions NEW: draft → signing → call provider with adjustmentType=3 → issued|submitted|draft. Requires settings:tenant + same tenant. Chain depth capped at 3.';


--
-- Name: reserve_branch_menu_daily_holds(bigint, uuid, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid, p_items jsonb, p_source text DEFAULT 'pos_cart'::text, p_ttl_seconds integer DEFAULT 180) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tenant_id bigint := public.auth_tenant_id();
  v_branch_id bigint := public.auth_branch_id();
  v_role text := public.auth_role();
  v_limit_date date := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_ttl_seconds integer := LEAST(GREATEST(COALESCE(p_ttl_seconds, 180), 30), 600);
  v_expires_at timestamptz := now() + make_interval(secs => LEAST(GREATEST(COALESCE(p_ttl_seconds, 180), 30), 600));
  v_target record;
  v_limit record;
  v_other_hold_qty integer;
  v_items jsonb := '[]'::jsonb;
  v_released integer := 0;
BEGIN
  IF v_uid IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_hold_token IS NULL THEN
    RAISE EXCEPTION 'hold_token required' USING ERRCODE = '22023';
  END IF;

  IF p_source NOT IN ('pos_cart', 'pos_append') THEN
    RAISE EXCEPTION 'invalid hold source' USING ERRCODE = '22023';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'p_items must be a JSON array' USING ERRCODE = '22023';
  END IF;

  IF v_role NOT IN ('owner', 'branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'permission denied: pos daily-limit hold' USING ERRCODE = '42501';
  END IF;

  IF v_role NOT IN ('owner')
     AND (v_branch_id IS NULL OR v_branch_id <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.branches b
  WHERE b.id = p_branch_id
    AND b.tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.branch_menu_item_daily_holds h
  SET released_at = h.expires_at,
      updated_at = now()
  WHERE h.tenant_id = v_tenant_id
    AND h.branch_id = p_branch_id
    AND h.limit_date = v_limit_date
    AND h.committed_at IS NULL
    AND h.released_at IS NULL
    AND h.expires_at <= now();

  IF jsonb_array_length(p_items) = 0 THEN
    UPDATE public.branch_menu_item_daily_holds h
    SET released_at = now(),
        updated_at = now()
    WHERE h.tenant_id = v_tenant_id
      AND h.branch_id = p_branch_id
      AND h.hold_token = p_hold_token
      AND h.held_by = v_uid
      AND h.committed_at IS NULL
      AND h.released_at IS NULL;

    GET DIAGNOSTICS v_released = ROW_COUNT;

    RETURN jsonb_build_object(
      'success', true,
      'hold_token', p_hold_token,
      'items', '[]'::jsonb,
      'released_count', v_released
    );
  END IF;

  FOR v_target IN
    SELECT *
    FROM public.pos_daily_limit_item_quantities(p_items)
  LOOP
    SELECT * INTO v_limit
    FROM public.branch_menu_item_daily_limits bl
    WHERE bl.tenant_id = v_tenant_id
      AND bl.branch_id = p_branch_id
      AND bl.menu_item_id = v_target.menu_item_id
      AND bl.limit_date = v_limit_date
    FOR UPDATE;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    IF v_limit.is_disabled THEN
      RAISE EXCEPTION 'daily_limit_item_disabled'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_item_disabled',
                'menu_item_id', v_target.menu_item_id
              )::text;
    END IF;

    IF v_limit.limit_quantity IS NULL THEN
      CONTINUE;
    END IF;

    SELECT COALESCE(SUM(h.quantity), 0)::integer
    INTO v_other_hold_qty
    FROM public.branch_menu_item_daily_holds h
    WHERE h.tenant_id = v_tenant_id
      AND h.branch_id = p_branch_id
      AND h.menu_item_id = v_target.menu_item_id
      AND h.limit_date = v_limit_date
      AND h.hold_token <> p_hold_token
      AND h.committed_at IS NULL
      AND h.released_at IS NULL
      AND h.expires_at > now();

    IF v_limit.sold_today + v_other_hold_qty + v_target.quantity > v_limit.limit_quantity THEN
      RAISE EXCEPTION 'daily_limit_exceeded'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'reason', 'daily_limit_exceeded',
                'menu_item_id', v_target.menu_item_id,
                'limit_quantity', v_limit.limit_quantity,
                'sold_today', v_limit.sold_today,
                'held_quantity', v_other_hold_qty,
                'requested_quantity', v_target.quantity
              )::text;
    END IF;
  END LOOP;

  UPDATE public.branch_menu_item_daily_holds h
  SET released_at = now(),
      updated_at = now()
  WHERE h.tenant_id = v_tenant_id
    AND h.branch_id = p_branch_id
    AND h.hold_token = p_hold_token
    AND h.held_by = v_uid
    AND h.committed_at IS NULL
    AND h.released_at IS NULL;

  WITH requested AS (
    SELECT *
    FROM public.pos_daily_limit_item_quantities(p_items)
  ),
  inserted AS (
    INSERT INTO public.branch_menu_item_daily_holds (
      tenant_id,
      branch_id,
      menu_item_id,
      limit_date,
      hold_token,
      held_by,
      source,
      quantity,
      expires_at
    )
    SELECT
      v_tenant_id,
      p_branch_id,
      r.menu_item_id,
      v_limit_date,
      p_hold_token,
      v_uid,
      p_source,
      r.quantity,
      v_expires_at
    FROM requested r
    JOIN public.branch_menu_item_daily_limits bl
      ON bl.tenant_id = v_tenant_id
     AND bl.branch_id = p_branch_id
     AND bl.menu_item_id = r.menu_item_id
     AND bl.limit_date = v_limit_date
    WHERE bl.limit_quantity IS NOT NULL
      AND bl.is_disabled = false
    RETURNING menu_item_id, quantity, expires_at
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'menu_item_id', inserted.menu_item_id,
        'quantity', inserted.quantity,
        'expires_at', inserted.expires_at
      )
      ORDER BY inserted.menu_item_id
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM inserted;

  RETURN jsonb_build_object(
    'success', true,
    'hold_token', p_hold_token,
    'expires_at', v_expires_at,
    'ttl_seconds', v_ttl_seconds,
    'items', v_items
  );
END;
$$;


--
-- Name: FUNCTION reserve_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid, p_items jsonb, p_source text, p_ttl_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reserve_branch_menu_daily_holds(p_branch_id bigint, p_hold_token uuid, p_items jsonb, p_source text, p_ttl_seconds integer) IS 'Replace a POS cart daily-limit hold snapshot. Locks limit rows by menu_item_id ASC, excludes the caller token, raises daily_limit_item_disabled / daily_limit_exceeded, and stores short-lived active holds.';


--
-- Name: resolve_branch_printer_for_type(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_branch_printer_for_type(p_tenant_id bigint, p_branch_id bigint, p_print_type text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id
  FROM public.printers p
  JOIN public.printer_print_types ppt
    ON ppt.printer_id = p.id
   AND ppt.tenant_id = p.tenant_id
   AND ppt.branch_id = p.branch_id
   AND ppt.print_type = p_print_type
  WHERE p.tenant_id = p_tenant_id
    AND p.branch_id = p_branch_id
    AND p_tenant_id = public.auth_tenant_id()
    AND (
      public.auth_branch_id() IS NULL
      OR p_branch_id = public.auth_branch_id()
    )
    AND p.is_active = TRUE
  ORDER BY
    CASE
      WHEN p.role = 'receipt' THEN 0
      WHEN p.role = 'kitchen_1' THEN 1
      WHEN p.role = 'kitchen_2' THEN 2
      ELSE 3
    END,
    p.id
  LIMIT 1;
$$;


--
-- Name: resolve_gtgt_rate(bigint, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_gtgt_rate(p_tenant_id bigint, p_at_date date DEFAULT ((now() AT TIME ZONE 'Asia/Ho_Chi_Minh'::text))::date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_year_start  date;
  v_days_elapsed int;
  v_ytd_gross   numeric;
  v_annual      numeric;
  v_in_window   boolean;
  v_base        numeric;
BEGIN
  v_year_start := date_trunc('year', p_at_date)::date;
  v_days_elapsed := (p_at_date - v_year_start) + 1;

  -- YTD gross paid revenue (rate-independent → use orders.total_amount), keyed
  -- on the completed payment whose paid_at VN-date falls in the current year.
  SELECT COALESCE(SUM(o.total_amount), 0)
    INTO v_ytd_gross
  FROM public.payments p
  JOIN public.orders o
    ON o.id = p.order_id
   AND o.tenant_id = p.tenant_id
   AND o.branch_id = p.branch_id
  WHERE p.tenant_id = p_tenant_id
    AND p.status = 'completed'
    AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date >= v_year_start
    AND (p.paid_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date <= p_at_date
    AND o.status <> 'cancelled'
    AND o.payment_status = 'paid';

  -- Annualize YTD: gross / days_elapsed * 365.
  v_annual := v_ytd_gross / NULLIF(v_days_elapsed, 0) * 365;

  -- Exempt tier: < 1 tỷ/năm.
  IF v_annual < 1000000000 THEN
    RETURN 0::numeric(5,2);
  END IF;

  -- Temporary GTGT reduction window (NQ 204/2025 + NĐ 174/2025): ăn uống
  -- trực tiếp 3% → 2,4% for dates in [2025-07-01, 2026-12-31].
  v_in_window := p_at_date >= DATE '2025-07-01' AND p_at_date <= DATE '2026-12-31';

  -- Chargeable tiers (group2 <3 tỷ, group3/4 ≥3 tỷ) share the same base rate.
  v_base := CASE WHEN v_in_window THEN 2.40 ELSE 3.00 END;

  RETURN v_base::numeric(5,2);
END;
$$;


--
-- Name: resolve_po_price(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_po_price(p_supplier_id bigint, p_ingredient_id bigint, p_uom text) RETURNS TABLE(unit_price numeric, source text, effective_from date, min_order_qty numeric, lead_time_days smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(NULL, 'procurement:price_list_read') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY
  SELECT spl.unit_price, spl.source, spl.effective_from, spl.min_order_qty, spl.lead_time_days
  FROM public.supplier_price_list spl
  WHERE spl.tenant_id = v_tenant AND spl.supplier_id = p_supplier_id AND spl.ingredient_id = p_ingredient_id AND spl.uom = p_uom
    AND spl.effective_from <= CURRENT_DATE AND (spl.effective_to IS NULL OR spl.effective_to >= CURRENT_DATE)
  ORDER BY spl.priority ASC, spl.effective_from DESC LIMIT 1;
END; $$;


--
-- Name: resolve_po_prices_batch(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_po_prices_batch(p_supplier_id bigint, p_items jsonb) RETURNS TABLE(ingredient_id bigint, uom text, unit_price numeric, source text, effective_from date, min_order_qty numeric, lead_time_days smallint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant BIGINT := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(NULL, 'procurement:price_list_read') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  RETURN QUERY
  WITH inputs AS (
    SELECT (v->>'ingredient_id')::BIGINT AS ing_id, (v->>'uom')::TEXT AS u
    FROM jsonb_array_elements(p_items) AS v
  ),
  ranked AS (
    SELECT i.ing_id, i.u, spl.unit_price, spl.source, spl.effective_from, spl.min_order_qty, spl.lead_time_days,
           ROW_NUMBER() OVER (PARTITION BY i.ing_id, i.u ORDER BY spl.priority ASC, spl.effective_from DESC) AS rn
    FROM inputs i
    LEFT JOIN public.supplier_price_list spl
      ON spl.tenant_id = v_tenant AND spl.supplier_id = p_supplier_id
     AND spl.ingredient_id = i.ing_id AND spl.uom = i.u
     AND spl.effective_from <= CURRENT_DATE AND (spl.effective_to IS NULL OR spl.effective_to >= CURRENT_DATE)
  )
  SELECT r.ing_id, r.u, r.unit_price, r.source, r.effective_from, r.min_order_qty, r.lead_time_days
  FROM ranked r WHERE r.rn = 1;
END; $$;


--
-- Name: resolve_print_template_version(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_print_template_version(p_tenant_id bigint, p_branch_id bigint, p_kind text) RETURNS TABLE(template_id bigint, template_version integer, paper_width_mm integer, font_profile text, content jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT pt.id, pt.version, pt.paper_width_mm, pt.font_profile, pt.content
  FROM public.print_template_versions pt
  WHERE pt.is_active = true AND pt.kind = p_kind
    AND (
      (pt.tenant_id = p_tenant_id AND pt.branch_id = p_branch_id)
      OR (pt.tenant_id = p_tenant_id AND pt.branch_id IS NULL)
      OR (pt.tenant_id IS NULL AND pt.branch_id IS NULL)
    )
  ORDER BY
    CASE
      WHEN pt.tenant_id = p_tenant_id AND pt.branch_id = p_branch_id THEN 1
      WHEN pt.tenant_id = p_tenant_id AND pt.branch_id IS NULL THEN 2
      WHEN pt.tenant_id IS NULL AND pt.branch_id IS NULL THEN 3
      ELSE 4
    END,
    pt.version DESC, pt.id DESC
  LIMIT 1;
$$;


--
-- Name: resolve_stocktake_conflict(bigint, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_stocktake_conflict(p_conflict_id bigint, p_resolution text, p_manual_qty numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_conf RECORD; v_session RECORD; v_final_qty NUMERIC;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF p_resolution NOT IN ('keep_server','apply_client','manual_value','reject') THEN RAISE EXCEPTION 'invalid resolution' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_conf FROM public.stocktake_conflicts WHERE id = p_conflict_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'conflict not found' USING ERRCODE = 'P0002'; END IF;
  IF v_conf.resolved_at IS NOT NULL THEN RAISE EXCEPTION 'conflict already resolved' USING ERRCODE = '22023'; END IF;
  SELECT ss.* INTO v_session FROM public.stocktake_sessions ss WHERE ss.id = v_conf.session_id;
  IF NOT public.has_permission(v_session.branch_id, 'inventory:stocktake_recount') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  v_final_qty := CASE p_resolution
    WHEN 'keep_server' THEN (v_conf.server_payload->>'existing_counted_quantity')::NUMERIC
    WHEN 'apply_client' THEN (v_conf.client_payload->>'counted_quantity')::NUMERIC
    WHEN 'manual_value' THEN p_manual_qty
    WHEN 'reject' THEN NULL END;
  IF p_resolution = 'manual_value' AND p_manual_qty IS NULL THEN RAISE EXCEPTION 'manual_qty required' USING ERRCODE = '22023'; END IF;
  IF p_resolution <> 'reject' AND v_final_qty IS NOT NULL THEN
    UPDATE public.stocktake_lines SET counted_quantity = v_final_qty, counted_by = v_uid, counted_at = now(),
      variance_reason = COALESCE(variance_reason,'') || E'\n[conflict#' || p_conflict_id::TEXT || ' resolved=' || p_resolution || COALESCE(': ' || p_note, '') || ']'
    WHERE session_id = v_conf.session_id AND ingredient_id = v_conf.ingredient_id AND round_no = v_conf.round_no;
  END IF;
  UPDATE public.stocktake_conflicts SET resolved_at = now(), resolved_by = v_uid, resolution = p_resolution,
    resolution_qty = v_final_qty, resolution_note = p_note WHERE id = p_conflict_id;
  RETURN jsonb_build_object('conflict_id', p_conflict_id, 'resolution', p_resolution, 'final_qty', v_final_qty, 'resolved_at', now());
END; $$;


--
-- Name: restore_stock_for_order(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_stock_for_order(p_order_id bigint, p_actor_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_order   RECORD;
  v_count   INT := 0;
BEGIN
  SELECT id, tenant_id, branch_id INTO v_order
  FROM public.orders
  WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'restore_stock_for_order: order % not found', p_order_id
      USING ERRCODE = 'P0002';
  END IF;

  WITH per_ingredient AS (
    SELECT
      ri.ingredient_id,
      SUM(oi.quantity * ri.quantity_required) AS qty
    FROM public.order_items oi
    JOIN public.menu_items mi
      ON mi.id = oi.menu_item_id
    JOIN public.recipes r
      ON r.menu_item_id = mi.id
    JOIN public.recipe_ingredients ri
      ON ri.recipe_id = r.id
    WHERE oi.order_id = p_order_id
      AND COALESCE(oi.status, '') <> 'cancelled'
    GROUP BY ri.ingredient_id
  ),
  inserted AS (
    INSERT INTO public.stock_movements
      (tenant_id, branch_id, ingredient_id, type, quantity_change, reason, created_by)
    SELECT
      v_order.tenant_id,
      v_order.branch_id,
      pi.ingredient_id,
      'refund_restore',
      pi.qty,
      'Hoàn tiền — restore tồn kho cho đơn ' || p_order_id::TEXT,
      COALESCE(p_actor_id, auth.uid())
    FROM per_ingredient pi
    WHERE pi.qty > 0
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM inserted;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION restore_stock_for_order(p_order_id bigint, p_actor_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.restore_stock_for_order(p_order_id bigint, p_actor_id uuid) IS 'M4 (2026-04-29): inserts positive stock_movements of type=refund_restore for every recipe ingredient × ordered quantity. Internal helper for reverse_payment_and_post. Not callable by authenticated users.';


--
-- Name: retry_print_job(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_print_job(p_job_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      UUID := auth.uid();
  v_tenant   BIGINT := public.auth_tenant_id();
  v_updated  INT;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant context missing' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_permission_any('printer:manage')
    OR public.has_permission_any('pos:print')
  ) THEN
    RAISE EXCEPTION 'permission denied: printer:manage' USING ERRCODE = '42501';
  END IF;

  UPDATE public.print_jobs
     SET status           = 'pending',
         last_error       = NULL,
         claimed_by_agent = NULL,
         claimed_at       = NULL,
         retry_count      = retry_count + 1,
         last_retried_at  = now(),
         last_retried_by  = v_uid
   WHERE id = p_job_id
     AND tenant_id = v_tenant
     AND status IN ('failed', 'expired');

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated = 1;
END;
$$;


--
-- Name: reverse_payment_and_post(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_payment_and_post(p_refund_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_refund          RECORD;
  v_payment         RECORD;
  v_order           RECORD;
  v_actor           UUID := auth.uid();
  v_tenant          BIGINT := public.auth_tenant_id();
  v_stock_count     INT := 0;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'tenant claim missing' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, payment_id, order_id, amount, status
  INTO v_refund
  FROM public.refunds
  WHERE id = p_refund_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'refund % not found', p_refund_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_permission(v_refund.branch_id, 'orders:refund_approve') THEN
    RAISE EXCEPTION 'permission denied: orders:refund_approve required'
      USING ERRCODE = '42501';
  END IF;

  IF v_refund.status = 'approved' THEN
    RETURN jsonb_build_object(
      'status', 'already_approved',
      'refund_id', v_refund.id
    );
  END IF;
  IF v_refund.status <> 'pending' THEN
    RAISE EXCEPTION 'refund cannot transition from % to approved', v_refund.status
      USING ERRCODE = 'P0001';
  END IF;

  SELECT id, tenant_id, branch_id, amount, status, stock_consumed_status
  INTO v_payment
  FROM public.payments
  WHERE id = v_refund.payment_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment % not found', v_refund.payment_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_payment.status <> 'completed' THEN
    RAISE EXCEPTION 'payment status=% - refund requires completed',
      v_payment.status USING ERRCODE = 'P0001';
  END IF;
  IF v_refund.amount > v_payment.amount THEN
    RAISE EXCEPTION 'refund amount % exceeds payment amount %',
      v_refund.amount, v_payment.amount USING ERRCODE = 'P0001';
  END IF;

  -- Lock kept for serialization against concurrent payment/cancel flows even
  -- though the order row is no longer mutated.
  SELECT id, tenant_id, branch_id, payment_status
  INTO v_order
  FROM public.orders
  WHERE id = v_refund.order_id
    AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order % not found', v_refund.order_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Restore stock only when this payment actually consumed stock ('ok').
  -- NULL means stock was never consumed, so nothing is restored.
  IF v_payment.stock_consumed_status = 'ok' THEN
    BEGIN
      v_stock_count := public.restore_stock_for_order(v_refund.order_id, v_actor);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'restore_stock_for_order failed: %', SQLERRM;
    END;
  END IF;

  UPDATE public.payments
     SET status = 'refunded', updated_at = now()
   WHERE id = v_payment.id;

  UPDATE public.refunds
     SET status      = 'approved',
         approved_by = v_actor,
         approved_at = now(),
         updated_at  = now()
   WHERE id = v_refund.id;

  PERFORM public.log_audit(
    'refund.approve',
    'refund',
    v_refund.id,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object(
      'status', 'approved',
      'stock_movements_created', v_stock_count
    )
  );

  RETURN jsonb_build_object(
    'status', 'approved',
    'refund_id', v_refund.id,
    'stock_movements_created', v_stock_count,
    'payment_new_status', 'refunded'
  );
END;
$$;


--
-- Name: FUNCTION reverse_payment_and_post(p_refund_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reverse_payment_and_post(p_refund_id bigint) IS 'Atomic refund reversal with branch-scoped orders:refund_approve permission. Locks refund/payment/order, restores stock ONLY when stock_consumed_status=''ok'' strictly (NULL = never consumed), flips payment and refund, and audits. orders.payment_status intentionally stays ''paid'' (CHECK allows unpaid/pending/paid only; partial refunds make an order-level refunded label wrong) — refund truth = payments.status + refunds.';


--
-- Name: revoke_permission(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_permission(p_target_user uuid, p_branch_id bigint, p_permission_key text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT;
  v_target_tenant BIGINT;
  v_deleted INTEGER;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'staff:assign_permission') THEN
    RAISE EXCEPTION 'forbidden: missing staff:assign_permission' USING ERRCODE = '42501';
  END IF;

  SELECT tenant_id INTO v_tenant_id FROM public.profiles WHERE id = auth.uid();
  SELECT tenant_id INTO v_target_tenant FROM public.profiles WHERE id = p_target_user;
  IF v_target_tenant IS NULL OR v_target_tenant <> v_tenant_id THEN
    RAISE EXCEPTION 'target_not_in_tenant' USING ERRCODE = '42501';
  END IF;

  IF public.auth_is_owner(p_target_user) THEN
    RAISE EXCEPTION 'cannot_manage_owner_permissions' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.staff_permissions
  WHERE user_id = p_target_user
    AND permission_key = p_permission_key
    AND (
      (p_branch_id IS NULL AND branch_id IS NULL)
      OR branch_id = p_branch_id
    );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted > 0 THEN
    INSERT INTO public.permission_audit_log (
      tenant_id, actor_user_id, target_user_id, branch_id,
      permission_key, action
    ) VALUES (
      v_tenant_id, auth.uid(), p_target_user, p_branch_id,
      p_permission_key, 'revoke'
    );
  END IF;

  RETURN v_deleted;
END;
$$;


--
-- Name: rotate_branch_override_code(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_branch_override_code(p_branch_id bigint, p_new_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'procurement:override_code_rotate') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF length(p_new_code) < 6 THEN
    RAISE EXCEPTION 'override code must be at least 6 characters' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.branch_override_codes (branch_id, code_hash, rotated_at, rotated_by)
  VALUES (p_branch_id, extensions.crypt(p_new_code, extensions.gen_salt('bf', 10)), now(), v_uid)
  ON CONFLICT (branch_id) DO UPDATE
    SET code_hash = EXCLUDED.code_hash, rotated_at = EXCLUDED.rotated_at, rotated_by = EXCLUDED.rotated_by;
END;
$$;


--
-- Name: route_order_to_kds(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_order_to_kds(p_order_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_order RECORD;
  v_item RECORD;
  v_station_id BIGINT;
  v_fallback_station_id BIGINT;
  v_has_printer_route BOOLEAN := FALSE;
  v_batch_id BIGINT;
  v_send_seq INT;
  v_ticket_seq INT;
  v_order_number_clean TEXT;
  v_order_number_match TEXT[];
  v_ticket_base TEXT;
  v_ticket_number TEXT;
  v_ticket_id BIGINT;
  v_table_no INT;
  v_cashier_name TEXT;
  v_route RECORD;
  v_payload JSONB;
  v_idempotency TEXT;
  v_job_id BIGINT;
  v_unrouted INT;
BEGIN
  SELECT tenant_id, branch_id, order_number, order_type, note, created_by,
         table_id, kitchen_send_count
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = public.auth_tenant_id()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT s.id INTO v_fallback_station_id
  FROM public.kds_stations s
  LEFT JOIN public.kds_station_categories sc ON sc.station_id = s.id
  WHERE s.branch_id = v_order.branch_id
    AND s.tenant_id = v_order.tenant_id
    AND s.is_active = TRUE
    AND sc.id IS NULL
  ORDER BY s.position
  LIMIT 1;

  FOR v_item IN
    SELECT oi.id AS order_item_id, mi.category_id
    FROM public.order_items oi
    JOIN public.menu_items mi ON mi.id = oi.menu_item_id
    WHERE oi.order_id = p_order_id
      AND oi.sent_to_kitchen_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.kds_tickets kt
        WHERE kt.tenant_id = v_order.tenant_id
          AND kt.order_item_id = oi.id
      )
    ORDER BY oi.id
  LOOP
    v_station_id := NULL;
    v_has_printer_route := FALSE;

    SELECT sc.station_id INTO v_station_id
    FROM public.kds_station_categories sc
    JOIN public.kds_stations s ON s.id = sc.station_id
    WHERE sc.category_id = v_item.category_id
      AND s.branch_id = v_order.branch_id
      AND s.tenant_id = v_order.tenant_id
      AND s.is_active = TRUE
    LIMIT 1;

    SELECT EXISTS (
      SELECT 1
      FROM public.printer_menu_categories pmc
      JOIN public.printers p
        ON p.id = pmc.printer_id
       AND p.tenant_id = pmc.tenant_id
       AND p.branch_id = pmc.branch_id
       AND p.is_active = TRUE
      JOIN public.printer_print_types ppt
        ON ppt.printer_id = p.id
       AND ppt.tenant_id = p.tenant_id
       AND ppt.branch_id = p.branch_id
       AND ppt.print_type = 'kitchen_ticket'
      WHERE pmc.category_id = v_item.category_id
        AND pmc.tenant_id = v_order.tenant_id
        AND pmc.branch_id = v_order.branch_id
    ) INTO v_has_printer_route;

    IF v_station_id IS NULL AND v_has_printer_route THEN
      CONTINUE;
    END IF;

    IF v_station_id IS NULL THEN
      v_station_id := v_fallback_station_id;
    END IF;

    IF v_station_id IS NOT NULL THEN
      IF v_batch_id IS NULL THEN
        UPDATE public.orders
           SET kitchen_send_count = kitchen_send_count + 1
         WHERE id = p_order_id
         RETURNING kitchen_send_count INTO v_send_seq;

        INSERT INTO public.kitchen_daily_counters (
          tenant_id, branch_id, counter_date, last_seq
        )
        VALUES (
          v_order.tenant_id,
          v_order.branch_id,
          (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
          1
        )
        ON CONFLICT (tenant_id, branch_id, counter_date)
        DO UPDATE SET
          last_seq = public.kitchen_daily_counters.last_seq + 1,
          updated_at = now()
        RETURNING last_seq INTO v_ticket_seq;

        v_order_number_clean := regexp_replace(
          btrim(COALESCE(v_order.order_number, '')),
          '^#+',
          ''
        );
        v_order_number_match := regexp_match(
          v_order_number_clean,
          '^(?:TC|MV)-(?:(?:[0-9]{6}|[0-9]{8})-)?([0-9]{1,5})(?:-.+)?$',
          'i'
        );
        v_ticket_base := COALESCE(
          v_order_number_match[1],
          NULLIF(v_order_number_clean, ''),
          p_order_id::TEXT
        );
        v_ticket_number := '#' || v_ticket_base
          || CASE WHEN v_send_seq > 1 THEN '-' || v_send_seq::TEXT ELSE '' END;

        INSERT INTO public.kitchen_send_batches (
          tenant_id, branch_id, order_id, counter_date, ticket_seq,
          kitchen_ticket_number, send_seq, kind, created_by
        )
        VALUES (
          v_order.tenant_id,
          v_order.branch_id,
          p_order_id,
          (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
          v_ticket_seq,
          v_ticket_number,
          v_send_seq,
          CASE WHEN v_send_seq = 1 THEN 'initial' ELSE 'append' END,
          auth.uid()
        )
        RETURNING id INTO v_batch_id;
      END IF;

      INSERT INTO public.kds_tickets (
        tenant_id, branch_id, station_id, order_id, order_item_id,
        kitchen_send_batch_id
      )
      VALUES (
        v_order.tenant_id, v_order.branch_id, v_station_id,
        p_order_id, v_item.order_item_id, v_batch_id
      )
      ON CONFLICT (order_item_id, station_id, tenant_id) DO NOTHING
      RETURNING id INTO v_ticket_id;
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.order_items oi
    JOIN public.menu_items mi ON mi.id = oi.menu_item_id
    JOIN public.printer_menu_categories pmc
      ON pmc.category_id = mi.category_id
     AND pmc.tenant_id = v_order.tenant_id
     AND pmc.branch_id = v_order.branch_id
    JOIN public.printers p
      ON p.id = pmc.printer_id
     AND p.tenant_id = pmc.tenant_id
     AND p.branch_id = pmc.branch_id
     AND p.is_active = TRUE
    JOIN public.printer_print_types ppt
      ON ppt.printer_id = p.id
     AND ppt.tenant_id = p.tenant_id
     AND ppt.branch_id = p.branch_id
     AND ppt.print_type = 'kitchen_ticket'
    WHERE oi.order_id = p_order_id
      AND oi.sent_to_kitchen_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.kds_tickets kt
        WHERE kt.tenant_id = v_order.tenant_id
          AND kt.order_item_id = oi.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.kds_station_categories sc
        JOIN public.kds_stations s ON s.id = sc.station_id
        WHERE sc.category_id = mi.category_id
          AND s.branch_id = v_order.branch_id
          AND s.tenant_id = v_order.tenant_id
          AND s.is_active = TRUE
      )
    LIMIT 1
  ) THEN
    IF v_batch_id IS NULL THEN
      UPDATE public.orders
         SET kitchen_send_count = kitchen_send_count + 1
       WHERE id = p_order_id
       RETURNING kitchen_send_count INTO v_send_seq;

      INSERT INTO public.kitchen_daily_counters (
        tenant_id, branch_id, counter_date, last_seq
      )
      VALUES (
        v_order.tenant_id,
        v_order.branch_id,
        (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
        1
      )
      ON CONFLICT (tenant_id, branch_id, counter_date)
      DO UPDATE SET
        last_seq = public.kitchen_daily_counters.last_seq + 1,
        updated_at = now()
      RETURNING last_seq INTO v_ticket_seq;

      v_order_number_clean := regexp_replace(
        btrim(COALESCE(v_order.order_number, '')),
        '^#+',
        ''
      );
      v_order_number_match := regexp_match(
        v_order_number_clean,
        '^(?:TC|MV)-(?:(?:[0-9]{6}|[0-9]{8})-)?([0-9]{1,5})(?:-.+)?$',
        'i'
      );
      v_ticket_base := COALESCE(
        v_order_number_match[1],
        NULLIF(v_order_number_clean, ''),
        p_order_id::TEXT
      );
      v_ticket_number := '#' || v_ticket_base
        || CASE WHEN v_send_seq > 1 THEN '-' || v_send_seq::TEXT ELSE '' END;

      INSERT INTO public.kitchen_send_batches (
        tenant_id, branch_id, order_id, counter_date, ticket_seq,
        kitchen_ticket_number, send_seq, kind, created_by
      )
      VALUES (
        v_order.tenant_id,
        v_order.branch_id,
        p_order_id,
        (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
        v_ticket_seq,
        v_ticket_number,
        v_send_seq,
        CASE WHEN v_send_seq = 1 THEN 'initial' ELSE 'append' END,
        auth.uid()
      )
      RETURNING id INTO v_batch_id;
    ELSE
      SELECT kitchen_ticket_number, send_seq
        INTO v_ticket_number, v_send_seq
      FROM public.kitchen_send_batches
      WHERE id = v_batch_id;
    END IF;

    IF v_order.table_id IS NOT NULL THEN
      SELECT number INTO v_table_no FROM public.tables WHERE id = v_order.table_id;
    END IF;

    SELECT full_name INTO v_cashier_name
    FROM public.profiles WHERE id = v_order.created_by;

    FOR v_route IN
      WITH routed_items AS (
        SELECT
          p.id AS printer_id,
          p.role AS printer_role,
          CASE WHEN p.role = 'kitchen_2' THEN 2 ELSE 1 END AS slot,
          oi.id AS order_item_id,
          jsonb_build_object(
            'item_name', oi.item_name,
            'variant_name', oi.variant_name,
            'quantity', oi.quantity,
            'modifiers', oi.modifiers,
            'sides', oi.sides,
            'note', oi.note
          ) AS item_payload
        FROM public.order_items oi
        JOIN public.menu_items mi ON mi.id = oi.menu_item_id
        JOIN public.printer_menu_categories pmc
          ON pmc.category_id = mi.category_id
         AND pmc.tenant_id = v_order.tenant_id
         AND pmc.branch_id = v_order.branch_id
        JOIN public.printers p
          ON p.id = pmc.printer_id
         AND p.tenant_id = pmc.tenant_id
         AND p.branch_id = pmc.branch_id
         AND p.is_active = TRUE
        JOIN public.printer_print_types ppt
          ON ppt.printer_id = p.id
         AND ppt.tenant_id = p.tenant_id
         AND ppt.branch_id = p.branch_id
         AND ppt.print_type = 'kitchen_ticket'
        WHERE oi.order_id = p_order_id
          AND oi.sent_to_kitchen_at IS NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.kds_tickets kt
            WHERE kt.tenant_id = v_order.tenant_id
              AND kt.order_item_id = oi.id
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.kds_station_categories sc
            JOIN public.kds_stations s ON s.id = sc.station_id
            WHERE sc.category_id = mi.category_id
              AND s.branch_id = v_order.branch_id
              AND s.tenant_id = v_order.tenant_id
              AND s.is_active = TRUE
          )
      ),
      grouped_routes AS (
        SELECT
          printer_id,
          printer_role,
          slot,
          array_agg(order_item_id ORDER BY order_item_id) AS item_ids,
          jsonb_agg(item_payload ORDER BY order_item_id) AS items
        FROM routed_items
        GROUP BY printer_id, printer_role, slot
      )
      SELECT *
      FROM grouped_routes
      ORDER BY printer_role, printer_id
    LOOP
      v_job_id := NULL;

      v_payload := jsonb_build_object(
        'kind', 'kitchen_ticket',
        'kitchen_ticket_number', v_ticket_number,
        'source_order_number', v_order.order_number,
        'order_number', v_order.order_number,
        'order_type', v_order.order_type,
        'table_number', v_table_no,
        'cashier_name', COALESCE(v_cashier_name, ''),
        'send_seq', v_send_seq,
        'send_kind', CASE WHEN v_send_seq = 1 THEN 'initial' ELSE 'append' END,
        'slot', v_route.slot,
        'note', v_order.note,
        'items', v_route.items,
        'printed_at', to_char(now() AT TIME ZONE 'Asia/Ho_Chi_Minh',
                              'YYYY-MM-DD"T"HH24:MI:SS')
      );

      v_idempotency := 'order:' || p_order_id::TEXT
        || ':non-kds-dispatch:printer:' || v_route.printer_id::TEXT
        || ':batch:' || v_batch_id::TEXT
        || ':items:' || md5(array_to_string(v_route.item_ids, ','));

      INSERT INTO public.print_jobs (
        tenant_id, branch_id, printer_id, job_type,
        order_id, payload, idempotency_key, created_by
      )
      VALUES (
        v_order.tenant_id, v_order.branch_id, v_route.printer_id,
        'kitchen_ticket', p_order_id, v_payload, v_idempotency, auth.uid()
      )
      ON CONFLICT (idempotency_key) DO NOTHING
      RETURNING id INTO v_job_id;

      IF v_job_id IS NULL THEN
        SELECT id INTO v_job_id
        FROM public.print_jobs
        WHERE idempotency_key = v_idempotency;
      END IF;

      UPDATE public.order_items
         SET sent_to_kitchen_at = COALESCE(sent_to_kitchen_at, now())
       WHERE id = ANY(v_route.item_ids)
         AND sent_to_kitchen_at IS NULL;
    END LOOP;
  END IF;

  -- Fail-loud guard. After both the KDS-ticket loop and the printer-dispatch
  -- block, any non-cancelled item that is still unsent (sent_to_kitchen_at IS
  -- NULL) AND has no kds_tickets row was routed nowhere — its category has no
  -- active station, no fallback station, and no kitchen-ticket printer. Raising
  -- here rolls the whole send back so the order is never half-sent silently.
  SELECT count(*)::int INTO v_unrouted
  FROM public.order_items oi
  WHERE oi.order_id = p_order_id
    AND oi.status <> 'cancelled'
    AND oi.sent_to_kitchen_at IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.kds_tickets kt
      WHERE kt.tenant_id = v_order.tenant_id
        AND kt.order_item_id = oi.id
    );

  IF v_unrouted > 0 THEN
    RAISE EXCEPTION 'kds_no_route: order % has % unroutable item(s)',
      p_order_id, v_unrouted
      USING ERRCODE = '22023';
  END IF;
END;
$_$;


--
-- Name: FUNCTION route_order_to_kds(p_order_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.route_order_to_kds(p_order_id bigint) IS 'Routes KDS-visible categories to KDS tickets and immediately queues printer-only category slips, such as drinks, at POS dispatch time.';


--
-- Name: save_item_modifiers(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_item_modifiers(p_item_id bigint, p_modifiers jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT;
  m JSONB;
  i INT := 0;
BEGIN
  IF p_modifiers IS NULL OR jsonb_typeof(p_modifiers) <> 'array' THEN
    RAISE EXCEPTION 'p_modifiers must be a JSON array' USING ERRCODE = '22023';
  END IF;

  v_tenant_id := public.auth_tenant_id();

  PERFORM 1 FROM public.menu_items
    WHERE id = p_item_id AND tenant_id = v_tenant_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.menu_item_modifiers
    WHERE item_id = p_item_id AND tenant_id = v_tenant_id;

  FOR m IN SELECT * FROM jsonb_array_elements(p_modifiers)
  LOOP
    INSERT INTO public.menu_item_modifiers (tenant_id, item_id, name, price, sort_order)
    VALUES (
      v_tenant_id,
      p_item_id,
      m ->> 'name',
      (m ->> 'price')::NUMERIC(15,2),
      COALESCE((m ->> 'sort_order')::INT, i)
    );
    i := i + 1;
  END LOOP;
END;
$$;


--
-- Name: save_item_sides(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_item_sides(p_main_item_id bigint, p_sides jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT;
  s JSONB;
BEGIN
  IF p_sides IS NULL OR jsonb_typeof(p_sides) <> 'array' THEN
    RAISE EXCEPTION 'p_sides must be a JSON array' USING ERRCODE = '22023';
  END IF;

  v_tenant_id := public.auth_tenant_id();

  PERFORM 1 FROM public.menu_items
    WHERE id = p_main_item_id AND tenant_id = v_tenant_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.menu_item_available_sides
    WHERE main_item_id = p_main_item_id AND tenant_id = v_tenant_id;

  FOR s IN SELECT * FROM jsonb_array_elements(p_sides)
  LOOP
    INSERT INTO public.menu_item_available_sides (tenant_id, main_item_id, side_item_id, is_default)
    VALUES (
      v_tenant_id,
      p_main_item_id,
      (s ->> 'side_item_id')::BIGINT,
      COALESCE((s ->> 'is_default')::BOOLEAN, false)
    );
  END LOOP;
END;
$$;


--
-- Name: save_item_variants(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_item_variants(p_item_id bigint, p_variants jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT;
  v JSONB;
  i INT := 0;
BEGIN
  IF p_variants IS NULL OR jsonb_typeof(p_variants) <> 'array' THEN
    RAISE EXCEPTION 'p_variants must be a JSON array' USING ERRCODE = '22023';
  END IF;

  v_tenant_id := public.auth_tenant_id();

  -- Lock parent row to serialize concurrent replace operations
  PERFORM 1 FROM public.menu_items
    WHERE id = p_item_id AND tenant_id = v_tenant_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.menu_item_variants
    WHERE item_id = p_item_id AND tenant_id = v_tenant_id;

  FOR v IN SELECT * FROM jsonb_array_elements(p_variants)
  LOOP
    INSERT INTO public.menu_item_variants (tenant_id, item_id, name, price_adjustment, sort_order)
    VALUES (
      v_tenant_id,
      p_item_id,
      v ->> 'name',
      (v ->> 'price_adjustment')::NUMERIC(15,2),
      COALESCE((v ->> 'sort_order')::INT, i)
    );
    i := i + 1;
  END LOOP;
END;
$$;


--
-- Name: save_print_template_version(text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_print_template_version(p_kind text, p_name text, p_paper_width_mm integer, p_content jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant  BIGINT := public.auth_tenant_id();
  v_uid     UUID := auth.uid();
  v_name    TEXT := NULLIF(btrim(COALESCE(p_name, '')), '');
  v_version INT;
  v_id      BIGINT;
BEGIN
  IF v_uid IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF p_kind NOT IN (
    'receipt', 'provisional_bill', 'kitchen_ticket',
    'cancel_ticket', 'shift_close_report'
  ) THEN
    RAISE EXCEPTION 'invalid kind' USING ERRCODE = '22023';
  END IF;

  IF p_paper_width_mm NOT IN (58, 80) THEN
    RAISE EXCEPTION 'invalid paper width' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_content) <> 'object'
     OR jsonb_typeof(p_content->'blocks') <> 'array' THEN
    RAISE EXCEPTION 'invalid content' USING ERRCODE = '22023';
  END IF;

  IF jsonb_array_length(p_content->'blocks') > 160 THEN
    RAISE EXCEPTION 'too many blocks' USING ERRCODE = '22023';
  END IF;

  UPDATE public.print_template_versions
     SET is_active = false,
         updated_by = v_uid,
         updated_at = now()
   WHERE tenant_id = v_tenant
     AND branch_id IS NULL
     AND kind = p_kind
     AND is_active;

  SELECT COALESCE(MAX(version), 0) + 1
    INTO v_version
    FROM public.print_template_versions
   WHERE tenant_id = v_tenant
     AND branch_id IS NULL
     AND kind = p_kind;

  INSERT INTO public.print_template_versions (
    tenant_id, branch_id, kind, version, name,
    paper_width_mm, content, is_active, created_by, updated_by
  )
  VALUES (
    v_tenant, NULL, p_kind, v_version,
    COALESCE(v_name, 'Bản tùy chỉnh v' || v_version::TEXT),
    p_paper_width_mm, p_content, true, v_uid, v_uid
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'version', v_version);
END;
$$;


--
-- Name: FUNCTION save_print_template_version(p_kind text, p_name text, p_paper_width_mm integer, p_content jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_print_template_version(p_kind text, p_name text, p_paper_width_mm integer, p_content jsonb) IS 'Template editor save: deactivates the active tenant-scope template for the kind and inserts the next version atomically. SECURITY INVOKER — RLS policies on print_template_versions decide authorization.';


--
-- Name: save_station_categories(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_station_categories(p_station_id bigint, p_category_ids bigint[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_station RECORD;
  v_distinct_category_count INT;
  v_valid_category_count INT;
BEGIN
  SELECT id, tenant_id, branch_id
    INTO v_station
  FROM public.kds_stations
  WHERE id = p_station_id
    AND tenant_id = public.auth_tenant_id();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Station not found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    SELECT COUNT(DISTINCT x.category_id)
      INTO v_distinct_category_count
    FROM unnest(p_category_ids) AS x(category_id)
    WHERE x.category_id IS NOT NULL;

    SELECT COUNT(DISTINCT c.id)
      INTO v_valid_category_count
    FROM public.menu_categories c
    WHERE c.tenant_id = v_station.tenant_id
      AND c.id = ANY(p_category_ids);

    IF v_valid_category_count <> v_distinct_category_count THEN
      RAISE EXCEPTION 'Invalid station category' USING ERRCODE = '22023';
    END IF;
  END IF;

  DELETE FROM public.kds_station_categories
  WHERE station_id = p_station_id
    AND tenant_id = v_station.tenant_id;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    INSERT INTO public.kds_station_categories (tenant_id, station_id, category_id)
    SELECT DISTINCT v_station.tenant_id, p_station_id, x.category_id
    FROM unnest(p_category_ids) AS x(category_id)
    WHERE x.category_id IS NOT NULL
    ON CONFLICT (station_id, category_id, tenant_id) DO NOTHING;
  END IF;
END;
$$;


--
-- Name: scan_inventory_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scan_inventory_alerts() RETURNS TABLE(low_stock_count bigint, expiry_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_low BIGINT := 0;
  v_exp BIGINT := 0;
  v_today TEXT := to_char(now() AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYY-MM-DD');
BEGIN
  -- Low-stock alerts
  WITH inserted AS (
    INSERT INTO public.notifications (
      tenant_id, target_branch_id, target_roles,
      kind, severity, title, body,
      entity_type, entity_id, action_url, dedup_key, meta,
      expires_at
    )
    SELECT
      sl.tenant_id,
      sl.branch_id,
      ARRAY['branch_manager', 'owner']::TEXT[],
      'inventory.stock_low',
      'warning',
      format('Tồn kho thấp: %s', ing.name),
      format('Còn %s %s (ngưỡng đặt lại %s)',
        trim(trailing '.0' from sl.current_quantity::text),
        ing.unit,
        trim(trailing '.0' from ing.reorder_point::text)),
      'ingredient',
      ing.id,
      format('/inventory/stock?ingredient=%s&branch=%s', ing.id, sl.branch_id),
      format('stock_low:ingredient:%s:branch:%s:%s', ing.id, sl.branch_id, v_today),
      jsonb_build_object(
        'current_quantity', sl.current_quantity,
        'reorder_point', ing.reorder_point,
        'branch_id', sl.branch_id
      ),
      (now() + interval '7 days')
    FROM public.stock_levels sl
    JOIN public.ingredients ing
      ON ing.id = sl.ingredient_id AND ing.tenant_id = sl.tenant_id
    WHERE ing.reorder_point IS NOT NULL
      AND ing.reorder_point > 0
      AND sl.current_quantity <= ing.reorder_point
      AND ing.is_active = true
    ON CONFLICT (tenant_id, dedup_key)
      WHERE dedup_key IS NOT NULL
      DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_low FROM inserted;

  -- Expiry soon
  WITH inserted AS (
    INSERT INTO public.notifications (
      tenant_id, target_branch_id, target_roles,
      kind, severity, title, body,
      entity_type, entity_id, action_url, dedup_key, meta,
      expires_at
    )
    SELECT
      gi.tenant_id,
      g.branch_id,
      ARRAY['branch_manager', 'owner']::TEXT[],
      'inventory.expiry_soon',
      CASE
        WHEN gi.expiry_date <= (now()::date + interval '2 days') THEN 'critical'
        ELSE 'warning'
      END,
      format('Sắp hết hạn: %s', ing.name),
      format('Hạn %s — lô %s (còn %s %s)',
        to_char(gi.expiry_date, 'DD/MM/YYYY'),
        COALESCE(gi.batch_number, '—'),
        trim(trailing '.0' from (gi.received_quantity - gi.rejected_quantity)::text),
        ing.unit),
      'grn_item',
      gi.id,
      format('/inventory/expiry?grn_item=%s', gi.id),
      format('expiry_soon:grn_item:%s:%s', gi.id, v_today),
      jsonb_build_object(
        'expiry_date', gi.expiry_date,
        'batch_number', gi.batch_number,
        'remaining_quantity', gi.received_quantity - gi.rejected_quantity,
        'grn_id', gi.grn_id,
        'branch_id', g.branch_id
      ),
      (gi.expiry_date::timestamptz + interval '1 day')
    FROM public.grn_items gi
    JOIN public.goods_received_notes g
      ON g.id = gi.grn_id AND g.tenant_id = gi.tenant_id
    JOIN public.ingredients ing
      ON ing.id = gi.ingredient_id AND ing.tenant_id = gi.tenant_id
    WHERE gi.expiry_date IS NOT NULL
      AND gi.expiry_date BETWEEN now()::date AND (now()::date + interval '7 days')
      AND (gi.received_quantity - gi.rejected_quantity) > 0
      AND g.status = 'confirmed'
    ON CONFLICT (tenant_id, dedup_key)
      WHERE dedup_key IS NOT NULL
      DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_exp FROM inserted;

  DELETE FROM public.notifications
  WHERE expires_at IS NOT NULL AND expires_at < now();

  RETURN QUERY SELECT v_low, v_exp;
END;
$$;


--
-- Name: FUNCTION scan_inventory_alerts(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.scan_inventory_alerts() IS 'Emit inventory.stock_low and inventory.expiry_soon notifications (idempotent per day via dedup_key). Wire to pg_cron.';


--
-- Name: set_branch_kind(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_branch_kind(p_branch_id bigint, p_kind text DEFAULT 'branch'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_tenant bigint;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id
  INTO v_tenant
  FROM public.profiles p
  WHERE p.id = v_actor_id
    AND COALESCE(p.is_active, true) = true;

  IF NOT FOUND OR v_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_kind NOT IN ('branch', 'central_supply', 'central_kitchen') THEN
    RAISE EXCEPTION 'invalid branch_kind' USING ERRCODE = '22023';
  END IF;

  UPDATE public.branches
  SET branch_kind = p_kind,
      updated_at = now()
  WHERE id = p_branch_id
    AND tenant_id = v_tenant
    AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: FUNCTION set_branch_kind(p_branch_id bigint, p_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_branch_kind(p_branch_id bigint, p_kind text) IS 'Sets the operating site kind for a branch-backed inventory site.';


--
-- Name: set_branch_menu_daily_limit(bigint, bigint, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_branch_menu_daily_limit(p_branch_id bigint, p_menu_item_id bigint, p_limit_quantity integer, p_is_disabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_role      TEXT   := public.auth_role();
  v_branch    BIGINT := public.auth_branch_id();
  v_today     DATE   := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_row       public.branch_menu_item_daily_limits;
BEGIN
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF v_role NOT IN ('owner',
                    'branch_manager', 'cashier', 'chef') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('branch_manager', 'cashier', 'chef')
     AND (v_branch IS NULL OR v_branch <> p_branch_id) THEN
    RAISE EXCEPTION 'branch scope mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_limit_quantity IS NOT NULL AND p_limit_quantity <= 0 THEN
    RAISE EXCEPTION 'limit_quantity must be positive or null' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.menu_items mi
    WHERE mi.id = p_menu_item_id
      AND mi.tenant_id = v_tenant_id
      AND mi.is_active = TRUE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'menu item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM 1 FROM public.branches b
    WHERE b.id = p_branch_id AND b.tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.branch_menu_item_daily_limits
    (tenant_id, branch_id, menu_item_id, limit_date, limit_quantity, is_disabled, sold_today)
  VALUES
    (v_tenant_id, p_branch_id, p_menu_item_id, v_today, p_limit_quantity, p_is_disabled, 0)
  ON CONFLICT (branch_id, menu_item_id, limit_date)
  DO UPDATE SET
    limit_quantity = EXCLUDED.limit_quantity,
    is_disabled    = EXCLUDED.is_disabled,
    updated_at     = now()
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'branch_id', v_row.branch_id,
    'menu_item_id', v_row.menu_item_id,
    'limit_date', v_row.limit_date,
    'limit_quantity', v_row.limit_quantity,
    'is_disabled', v_row.is_disabled,
    'sold_today', v_row.sold_today
  );
END;
$$;


--
-- Name: set_order_service_charge(bigint, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_order_service_charge(p_order_id bigint, p_amount numeric, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid          UUID;
  v_prof_tenant  BIGINT;
  v_prof_branch  BIGINT;
  v_prof_role    TEXT;
  v_order        RECORD;
  v_note_trim    TEXT;
  v_amount       NUMERIC(15,2);
  v_total_amount NUMERIC(15,2);
  v_has_pending  BOOLEAN;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'branch_manager', 'cashier', 'waiter')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_amount IS NULL OR p_amount < 0 THEN
    RAISE EXCEPTION 'service_charge_invalid_amount' USING ERRCODE = '22023';
  END IF;

  IF p_amount > 50000000 THEN
    RAISE EXCEPTION 'service_charge_amount_too_large' USING ERRCODE = '22023';
  END IF;

  v_note_trim := COALESCE(trim(p_note), '');
  IF length(v_note_trim) < 3 THEN
    RAISE EXCEPTION 'service_charge_note_required' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.status, o.payment_status,
         o.subtotal, o.tax_amount, o.service_charge, o.discount_amount
  INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1 FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.payments p
    WHERE p.order_id = p_order_id
      AND p.tenant_id = v_order.tenant_id
      AND p.branch_id = v_order.branch_id
      AND p.status = 'pending'
  )
  INTO v_has_pending;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'pending' OR v_has_pending THEN
    RAISE EXCEPTION 'service_charge_payment_pending' USING ERRCODE = '22023';
  END IF;

  v_amount := ROUND(p_amount::NUMERIC, 2);
  v_total_amount := COALESCE(v_order.subtotal, 0)
                  + COALESCE(v_order.tax_amount, 0)
                  + v_amount
                  - COALESCE(v_order.discount_amount, 0);

  UPDATE public.orders
     SET service_charge = v_amount,
         total_amount   = v_total_amount,
         updated_at     = now()
   WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_order.tenant_id,
    p_order_id,
    v_order.status,
    v_order.status,
    v_uid,
    CASE
      WHEN v_amount = 0 THEN 'service_charge_cleared'
      ELSE 'service_charge_set: ' || v_amount::TEXT || 'đ'
    END || ' :: ' || v_note_trim
  );

  RETURN jsonb_build_object(
    'order_id',       p_order_id,
    'service_charge', v_amount,
    'total_amount',   v_total_amount
  );
END;
$$;


--
-- Name: FUNCTION set_order_service_charge(p_order_id bigint, p_amount numeric, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_order_service_charge(p_order_id bigint, p_amount numeric, p_note text) IS 'Set or clear orders.service_charge before payment. Requires note >=3 chars, blocks paid/terminal/pending-payment orders, recomputes total_amount, and records an order_status_history audit note.';


--
-- Name: set_pos_order_item_priority(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pos_order_item_priority(p_order_item_id bigint, p_is_priority boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_item public.order_items%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_note TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_item
  FROM public.order_items
  WHERE id = p_order_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = v_item.order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1
    FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  IF v_item.status NOT IN ('pending', 'preparing') THEN
    RAISE EXCEPTION 'item not prioritizable' USING ERRCODE = '22023';
  END IF;

  v_note := NULLIF(trim(COALESCE(p_note, '')), '');

  UPDATE public.order_items
  SET is_priority = COALESCE(p_is_priority, FALSE),
      priority_note = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_note ELSE NULL END,
      priority_marked_at = CASE WHEN COALESCE(p_is_priority, FALSE) THEN now() ELSE NULL END,
      priority_marked_by = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_uid ELSE NULL END,
      updated_at = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET updated_at = now()
  WHERE order_item_id = p_order_item_id
    AND tenant_id = v_item.tenant_id
    AND status IN ('pending', 'preparing');

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id,
    v_order.id,
    v_order.status,
    v_order.status,
    v_uid,
    CASE WHEN COALESCE(p_is_priority, FALSE)
      THEN 'priority_item:on '
      ELSE 'priority_item:off '
    END || p_order_item_id::TEXT || COALESCE(' - ' || v_note, '')
  );

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'order_item_id', p_order_item_id,
    'is_priority', COALESCE(p_is_priority, FALSE)
  );
END;
$$;


--
-- Name: set_pos_order_priority(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_pos_order_priority(p_order_id bigint, p_is_priority boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order public.orders%ROWTYPE;
  v_active_count INT;
  v_note TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    PERFORM 1
    FROM public.branches b
    WHERE b.id = v_order.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NOT NULL THEN
    IF v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_order.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'order already paid' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*)::INT INTO v_active_count
  FROM public.order_items
  WHERE order_id = p_order_id
    AND tenant_id = v_order.tenant_id
    AND status IN ('pending', 'preparing');

  IF v_active_count = 0 THEN
    RAISE EXCEPTION 'no active kitchen work' USING ERRCODE = '22023';
  END IF;

  v_note := NULLIF(trim(COALESCE(p_note, '')), '');

  UPDATE public.orders
  SET is_priority = COALESCE(p_is_priority, FALSE),
      priority_note = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_note ELSE NULL END,
      priority_marked_at = CASE WHEN COALESCE(p_is_priority, FALSE) THEN now() ELSE NULL END,
      priority_marked_by = CASE WHEN COALESCE(p_is_priority, FALSE) THEN v_uid ELSE NULL END,
      updated_at = now()
  WHERE id = p_order_id;

  UPDATE public.kds_tickets kt
  SET updated_at = now()
  WHERE kt.order_id = p_order_id
    AND kt.tenant_id = v_order.tenant_id
    AND kt.status IN ('pending', 'preparing');

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id,
    p_order_id,
    v_order.status,
    v_order.status,
    v_uid,
    CASE WHEN COALESCE(p_is_priority, FALSE)
      THEN 'priority_order:on'
      ELSE 'priority_order:off'
    END || COALESCE(' - ' || v_note, '')
  );

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'is_priority', COALESCE(p_is_priority, FALSE)
  );
END;
$$;


--
-- Name: set_print_template_versions_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_print_template_versions_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := COALESCE(NEW.created_by, auth.uid());
  END IF;
  NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: split_order(bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_order(p_source_order_id bigint, p_item_partials jsonb, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid                  UUID;
  v_prof_tenant          BIGINT;
  v_prof_branch          BIGINT;
  v_prof_role            TEXT;
  v_source               RECORD;
  v_active_total_rows    INT;
  v_full_move_count      INT := 0;
  v_total_units_moved    INT := 0;
  v_remaining_rows       INT;
  v_new_order_id         BIGINT;
  v_new_order_number     TEXT;
  v_seq                  INT;
  v_date_part            TEXT;
  v_flag_enabled         TEXT;
  v_existing_id          BIGINT;
  v_existing_number      TEXT;
  v_source_subtotal      NUMERIC(15,2);
  v_source_discount      NUMERIC(15,2);
  v_source_total         NUMERIC(15,2);
  v_new_subtotal         NUMERIC(15,2);
  v_new_total            NUMERIC(15,2);
  v_partial              JSONB;
  v_partial_item_id      BIGINT;
  v_partial_qty          INT;
  v_src_row              public.order_items%ROWTYPE;
  v_new_item_id          BIGINT;
  v_branch_code          TEXT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
    INTO v_prof_tenant, v_prof_branch, v_prof_role
    FROM public.profiles p
    LEFT JOIN public.positions po ON po.id = p.position_id
   WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN
     ('owner', 'super_manager', 'area_manager', 'branch_manager', 'cashier', 'waiter')
  THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_item_partials IS NULL
     OR jsonb_typeof(p_item_partials) <> 'array'
     OR jsonb_array_length(p_item_partials) = 0
  THEN
    RAISE EXCEPTION 'split_no_items' USING ERRCODE = '22023';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT o.id, o.order_number INTO v_existing_id, v_existing_number
      FROM public.orders o
     WHERE o.split_from_order_id = p_source_order_id
       AND o.idempotency_key = p_idempotency_key;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'source_order_id',  p_source_order_id,
        'new_order_id',     v_existing_id,
        'new_order_number', v_existing_number,
        'idempotent',       true
      );
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(p_source_order_id);

  SELECT o.id, o.tenant_id, o.branch_id, o.table_id, o.order_type, o.status,
         o.payment_status, o.pos_session_id, o.service_charge,
         o.discount_type, o.discount_value
    INTO v_source
    FROM public.orders o
   WHERE o.id = p_source_order_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_source.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner', 'super_manager', 'area_manager') THEN
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = v_source.branch_id AND b.tenant_id = v_prof_tenant;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid branch' USING ERRCODE = 'P0002';
    END IF;
  ELSIF v_prof_branch IS NULL OR v_source.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  ELSE
    SELECT b.code INTO v_branch_code
      FROM public.branches b
     WHERE b.id = v_source.branch_id AND b.tenant_id = v_prof_tenant;
  END IF;

  SELECT value INTO v_flag_enabled
    FROM public.system_settings
   WHERE tenant_id = v_source.tenant_id AND key = 'pos_split_merge_enabled';
  IF COALESCE(v_flag_enabled, 'true') = 'false' THEN
    RAISE EXCEPTION 'split_merge_disabled' USING ERRCODE = 'P0001';
  END IF;

  IF v_source.status NOT IN ('new', 'confirmed', 'preparing', 'ready', 'served') THEN
    RAISE EXCEPTION 'split_source_not_eligible' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_source.payment_status, 'unpaid') = 'paid' THEN
    RAISE EXCEPTION 'split_source_paid' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.payments
   WHERE order_id = p_source_order_id AND status NOT IN ('failed', 'completed');
  IF FOUND THEN
    RAISE EXCEPTION 'split_payment_pending' USING ERRCODE = '22023';
  END IF;

  FOR v_partial IN SELECT value FROM jsonb_array_elements(p_item_partials)
  LOOP
    v_partial_item_id := NULLIF(v_partial ->> 'item_id', '')::BIGINT;
    v_partial_qty := NULLIF(v_partial ->> 'quantity', '')::INT;

    IF v_partial_item_id IS NULL OR v_partial_qty IS NULL OR v_partial_qty < 1 THEN
      RAISE EXCEPTION 'split_items_invalid' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_src_row
      FROM public.order_items
     WHERE id = v_partial_item_id
       AND order_id = p_source_order_id
       AND status <> 'cancelled'
       FOR UPDATE;

    IF NOT FOUND OR v_partial_qty > v_src_row.quantity THEN
      RAISE EXCEPTION 'split_items_invalid' USING ERRCODE = '22023';
    END IF;

    IF v_partial_qty = v_src_row.quantity THEN
      v_full_move_count := v_full_move_count + 1;
    END IF;

    v_total_units_moved := v_total_units_moved + v_partial_qty;
  END LOOP;

  SELECT COUNT(*) INTO v_active_total_rows
    FROM public.order_items
   WHERE order_id = p_source_order_id AND status <> 'cancelled';

  v_remaining_rows := v_active_total_rows - v_full_move_count;
  IF v_remaining_rows < 1 THEN
    RAISE EXCEPTION 'split_would_empty_source' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.order_daily_counters (
    tenant_id, branch_id, counter_date, last_seq
  )
  VALUES (
    v_source.tenant_id,
    v_source.branch_id,
    (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,
    1
  )
  ON CONFLICT (tenant_id, branch_id, counter_date)
  DO UPDATE SET
    last_seq   = public.order_daily_counters.last_seq + 1,
    updated_at = now()
  RETURNING last_seq INTO v_seq;

  v_date_part := to_char(
    CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYMMDD'
  );

  IF v_source.order_type = 'dine_in' THEN
    v_new_order_number := 'TC-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  ELSE
    v_new_order_number := 'MV-' || v_date_part || '-' || lpad(v_seq::TEXT, 3, '0');
  END IF;

  IF v_branch_code IS NOT NULL THEN
    v_new_order_number := v_new_order_number || '-' || v_branch_code;
  END IF;

  INSERT INTO public.orders (
    tenant_id, branch_id, table_id, order_number, order_type,
    status, subtotal, total_amount, note, created_by,
    pos_session_id, idempotency_key, split_from_order_id
  )
  VALUES (
    v_source.tenant_id, v_source.branch_id, v_source.table_id,
    v_new_order_number, v_source.order_type,
    v_source.status,
    0, 0, NULL, v_uid,
    v_source.pos_session_id, p_idempotency_key, p_source_order_id
  )
  RETURNING id INTO v_new_order_id;

  FOR v_partial IN SELECT value FROM jsonb_array_elements(p_item_partials)
  LOOP
    v_partial_item_id := (v_partial ->> 'item_id')::BIGINT;
    v_partial_qty := (v_partial ->> 'quantity')::INT;

    SELECT * INTO v_src_row
      FROM public.order_items
     WHERE id = v_partial_item_id;

    IF v_partial_qty = v_src_row.quantity THEN
      UPDATE public.order_items
         SET order_id   = v_new_order_id,
             updated_at = now()
       WHERE id = v_partial_item_id
         AND order_id = p_source_order_id;

      UPDATE public.kds_tickets
         SET order_id   = v_new_order_id,
             updated_at = now()
       WHERE order_item_id = v_partial_item_id
         AND order_id = p_source_order_id;
    ELSE
      PERFORM set_config('comtammatu.skip_quota_enforcement', 'true', true);
      INSERT INTO public.order_items (
        tenant_id, order_id, menu_item_id, variant_id,
        item_name, variant_name, quantity, unit_price,
        modifiers, sides, subtotal, note, status,
        sent_to_kitchen_at
      )
      VALUES (
        v_src_row.tenant_id, v_new_order_id,
        v_src_row.menu_item_id, v_src_row.variant_id,
        v_src_row.item_name, v_src_row.variant_name,
        v_partial_qty, v_src_row.unit_price,
        v_src_row.modifiers, v_src_row.sides,
        v_src_row.unit_price * v_partial_qty,
        v_src_row.note, v_src_row.status,
        v_src_row.sent_to_kitchen_at
      )
      RETURNING id INTO v_new_item_id;
      PERFORM set_config('comtammatu.skip_quota_enforcement', 'false', true);

      UPDATE public.order_items
         SET quantity   = v_src_row.quantity - v_partial_qty,
             subtotal   = v_src_row.unit_price * (v_src_row.quantity - v_partial_qty),
             updated_at = now()
       WHERE id = v_partial_item_id;

      INSERT INTO public.kds_tickets (
        tenant_id, branch_id, station_id, order_id, order_item_id,
        status, bumped_at, bumped_by, created_at
      )
      SELECT
        kt.tenant_id, kt.branch_id, kt.station_id,
        v_new_order_id, v_new_item_id,
        kt.status, kt.bumped_at, kt.bumped_by, kt.created_at
      FROM public.kds_tickets kt
      WHERE kt.order_item_id = v_partial_item_id
        AND kt.order_id = p_source_order_id;
    END IF;
  END LOOP;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_source_subtotal
    FROM public.order_items
   WHERE order_id = p_source_order_id AND status <> 'cancelled';

  v_source_discount := public.compute_discount_amount(
    v_source.discount_type, v_source.discount_value, v_source_subtotal
  );

  v_source_total := v_source_subtotal
                  + COALESCE(v_source.service_charge, 0)
                  - v_source_discount;

  UPDATE public.orders
     SET subtotal        = v_source_subtotal,
         discount_amount = v_source_discount,
         total_amount    = v_source_total,
         updated_at      = now()
   WHERE id = p_source_order_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_new_subtotal
    FROM public.order_items
   WHERE order_id = v_new_order_id AND status <> 'cancelled';

  v_new_total := v_new_subtotal;

  UPDATE public.orders
     SET subtotal     = v_new_subtotal,
         total_amount = v_new_total,
         updated_at   = now()
   WHERE id = v_new_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES
    (v_source.tenant_id, p_source_order_id, v_source.status, v_source.status, v_uid,
     'split_to: ' || v_new_order_number
       || ' (moved ' || v_total_units_moved::TEXT || ' units across '
       || jsonb_array_length(p_item_partials)::TEXT || ' lines)'),
    (v_source.tenant_id, v_new_order_id, NULL, v_source.status, v_uid,
     'split_from: order#' || p_source_order_id::TEXT);

  RETURN jsonb_build_object(
    'source_order_id',  p_source_order_id,
    'new_order_id',     v_new_order_id,
    'new_order_number', v_new_order_number,
    'moved_count',      v_total_units_moved,
    'source_subtotal',  v_source_subtotal,
    'source_total',     v_source_total,
    'new_subtotal',     v_new_subtotal,
    'new_total',        v_new_total
  );
END;
$$;


--
-- Name: FUNCTION split_order(p_source_order_id bigint, p_item_partials jsonb, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.split_order(p_source_order_id bigint, p_item_partials jsonb, p_idempotency_key uuid) IS 'Tách hoá đơn — partials [{item_id, quantity}]. quantity == row.quantity → in-place UPDATE order_id; quantity < row.quantity → INSERT clone trên đơn mới + giảm qty source + mirror kds_tickets per station. Source phải giữ ≥1 active ROW sau move (block split_would_empty_source). Đơn mới: discount=0, service_charge=0, status inherit từ source. Idempotent qua p_idempotency_key. Clone INSERT bypass enforce_branch_menu_daily_limit qua GUC comtammatu.skip_quota_enforcement (net qty unchanged). Counter mint dùng schema (tenant,branch,date) — chia chung pool với create_order.';


--
-- Name: start_stocktake(bigint, bigint, text, boolean, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_stocktake(p_branch_id bigint, p_location_id bigint DEFAULT NULL::bigint, p_mode text DEFAULT 'daily'::text, p_blind_mode boolean DEFAULT NULL::boolean, p_auditor_id uuid DEFAULT NULL::uuid, p_threshold_pct numeric DEFAULT NULL::numeric, p_threshold_vnd numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_tenant BIGINT; v_blind BOOLEAN;
  v_session BIGINT; v_is_unaud BOOLEAN := false; v_rows INT := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission(p_branch_id, 'inventory:stocktake_create') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_mode NOT IN ('daily','weekly','monthly','quarterly','spot') THEN RAISE EXCEPTION 'invalid mode' USING ERRCODE = '22023'; END IF;
  SELECT tenant_id INTO v_tenant FROM public.branches WHERE id = p_branch_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002'; END IF;
  v_blind := COALESCE(p_blind_mode, CASE p_mode
    WHEN 'daily' THEN false WHEN 'weekly' THEN false
    WHEN 'monthly' THEN true WHEN 'quarterly' THEN true WHEN 'spot' THEN true END);
  IF p_mode IN ('monthly','quarterly') AND p_auditor_id IS NULL THEN v_is_unaud := true; END IF;
  INSERT INTO public.stocktake_sessions (tenant_id, branch_id, location_id, status, started_at, created_by,
    mode, blind_mode, auditor_id, is_unaudited, variance_threshold_pct, variance_threshold_vnd,
    abc_snapshot_at, current_round)
  VALUES (v_tenant, p_branch_id, p_location_id, 'in_progress', now(), v_uid, p_mode, v_blind,
    p_auditor_id, v_is_unaud, COALESCE(p_threshold_pct, 5.00), COALESCE(p_threshold_vnd, 200000), now(), 1)
  RETURNING id INTO v_session;
  INSERT INTO public.stocktake_lines (tenant_id, session_id, ingredient_id, system_quantity, round_no, abc_class)
  SELECT v_tenant, v_session, sl.ingredient_id, COALESCE(sl.current_quantity, 0), 1,
    public.get_ingredient_abc_class(p_branch_id, sl.ingredient_id)
  FROM public.stock_levels sl JOIN public.ingredients ing ON ing.id = sl.ingredient_id
  WHERE sl.branch_id = p_branch_id AND (p_location_id IS NULL OR sl.location_id = p_location_id) AND ing.is_active = true;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN jsonb_build_object('session_id', v_session, 'mode', p_mode, 'blind_mode', v_blind,
    'is_unaudited', v_is_unaud, 'seeded_lines', v_rows, 'abc_snapshot_at', now());
END; $$;


--
-- Name: stock_issue_items_bubble_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_issue_items_bubble_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.approval_required THEN
    UPDATE public.stock_issues SET approval_status = 'pending'
     WHERE id = NEW.issue_id AND approval_status = 'not_required';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: stock_issue_items_compute_waste_tier(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_issue_items_compute_waste_tier() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_parent RECORD; v_item_value NUMERIC(15,2); v_stock RECORD; v_qty_ratio NUMERIC(5,4);
  v_rolling_sum NUMERIC(15,2); v_shift_sum NUMERIC(15,2); v_branch_cap RECORD;
  v_branch_today NUMERIC(15,2); v_manual_review BOOLEAN; v_photo BOOLEAN := false;
  v_approve BOOLEAN := false; v_tier SMALLINT := 0;
  v_risky_reasons CONSTANT TEXT[] := ARRAY['dropped','quality_fail','contaminated','found_missing','theft_suspected'];
  v_always_tier2 CONSTANT TEXT[] := ARRAY['found_missing','theft_suspected'];
  v_v1_thr CONSTANT NUMERIC := 150000; v_v2_thr CONSTANT NUMERIC := 500000;
  v_shift_cap CONSTANT NUMERIC := 1500000;
BEGIN
  SELECT tenant_id, branch_id, source_location_id, created_by, issue_type, shift_key, issued_at
    INTO v_parent FROM public.stock_issues WHERE id = NEW.issue_id;
  IF NOT FOUND OR v_parent.issue_type <> 'writeoff' THEN RETURN NEW; END IF;

  IF NEW.unit_cost IS NOT NULL AND NEW.unit_cost > 0 THEN
    v_item_value := NEW.quantity * NEW.unit_cost;
  ELSE
    SELECT current_quantity, avg_unit_cost INTO v_stock FROM public.stock_levels
    WHERE branch_id = v_parent.branch_id AND ingredient_id = NEW.ingredient_id
      AND (v_parent.source_location_id IS NULL OR location_id = v_parent.source_location_id)
    ORDER BY location_id NULLS LAST LIMIT 1;
    v_item_value := COALESCE(NEW.quantity * v_stock.avg_unit_cost, 0);
  END IF;

  SELECT current_quantity INTO v_stock FROM public.stock_levels
  WHERE branch_id = v_parent.branch_id AND ingredient_id = NEW.ingredient_id
    AND (v_parent.source_location_id IS NULL OR location_id = v_parent.source_location_id)
  ORDER BY location_id NULLS LAST LIMIT 1;
  IF v_stock.current_quantity IS NOT NULL AND v_stock.current_quantity > 0 THEN
    v_qty_ratio := LEAST(NEW.quantity / v_stock.current_quantity, 9.9999)::NUMERIC(5,4);
  ELSE v_qty_ratio := NULL; END IF;

  SELECT COALESCE(SUM(sii.total_cost), 0) INTO v_rolling_sum
  FROM public.stock_issue_items sii JOIN public.stock_issues si ON si.id = sii.issue_id
  WHERE si.issue_type = 'writeoff' AND si.created_by = v_parent.created_by
    AND si.branch_id = v_parent.branch_id AND sii.ingredient_id = NEW.ingredient_id
    AND si.created_at > now() - INTERVAL '15 minutes' AND sii.id <> COALESCE(NEW.id, -1);

  IF v_parent.shift_key IS NOT NULL THEN
    SELECT COALESCE(SUM(sii.total_cost), 0) INTO v_shift_sum
    FROM public.stock_issue_items sii JOIN public.stock_issues si ON si.id = sii.issue_id
    WHERE si.issue_type = 'writeoff' AND si.created_by = v_parent.created_by
      AND si.branch_id = v_parent.branch_id AND si.shift_key = v_parent.shift_key
      AND sii.id <> COALESCE(NEW.id, -1);
  ELSE v_shift_sum := 0; END IF;

  SELECT cap_vnd, avg_revenue_7d INTO v_branch_cap FROM public.branch_daily_waste_cap WHERE branch_id = v_parent.branch_id;
  SELECT COALESCE(SUM(sii.total_cost), 0) INTO v_branch_today
  FROM public.stock_issue_items sii JOIN public.stock_issues si ON si.id = sii.issue_id
  WHERE si.issue_type = 'writeoff' AND si.branch_id = v_parent.branch_id
    AND si.issued_at >= date_trunc('day', now() AT TIME ZONE COALESCE(
        (SELECT timezone FROM public.branches WHERE id = v_parent.branch_id), 'Asia/Ho_Chi_Minh'))
    AND sii.id <> COALESCE(NEW.id, -1);

  v_manual_review := public.inventory_requires_manual_review(NEW.ingredient_id);

  v_photo := v_item_value >= v_v1_thr
          OR (v_qty_ratio IS NOT NULL AND v_qty_ratio >= 0.5)
          OR (NEW.reason_code IS NOT NULL AND NEW.reason_code = ANY(v_risky_reasons))
          OR (v_rolling_sum + v_item_value) >= v_v1_thr;

  v_approve := v_item_value >= v_v2_thr
            OR (v_shift_sum + v_item_value) >= v_shift_cap
            OR (NEW.reason_code IS NOT NULL AND NEW.reason_code = ANY(v_always_tier2))
            OR (v_branch_cap.cap_vnd IS NOT NULL AND (v_branch_today + v_item_value) > v_branch_cap.cap_vnd)
            OR v_manual_review;

  IF v_approve THEN v_tier := 2;
  ELSIF v_photo THEN v_tier := 1;
  ELSE v_tier := 0; END IF;

  NEW.waste_tier := v_tier; NEW.photo_required := v_photo; NEW.approval_required := v_approve;
  NEW.qty_ratio := v_qty_ratio; NEW.rolling_15min_sum := v_rolling_sum;

  IF v_photo AND COALESCE(array_length(NEW.photo_urls, 1), 0) = 0
     AND NOT public.has_permission(v_parent.branch_id, 'inventory:waste_bypass_photo') THEN
    RAISE EXCEPTION 'waste photo required for tier >= 1 (reason=%, value=%, qty_ratio=%)',
      NEW.reason_code, v_item_value, v_qty_ratio USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: stock_issue_items_reason_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_issue_items_reason_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.reason_code IS NOT NULL AND NEW.reason_code IS DISTINCT FROM OLD.reason_code THEN
    RAISE EXCEPTION 'reason_code is immutable once set (got % -> %)', OLD.reason_code, NEW.reason_code USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: stock_transfer_confirm_receive(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_confirm_receive(p_transfer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_role         TEXT := public.auth_role();
  v_branch_claim BIGINT := public.auth_branch_id();
  v_tr           RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tr
  FROM public.stock_transfers
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_tr.from_branch_id = v_tr.to_branch_id THEN
    RAISE EXCEPTION 'intra_branch_transfer_has_no_receive_step' USING ERRCODE = '22023';
  END IF;

  IF v_role IN ('branch_manager', 'warehouse_manager', 'production_manager')
     AND (v_branch_claim IS NULL OR v_branch_claim <> v_tr.to_branch_id) THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_tr.to_branch_id, 'inventory:transfer_receive') THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF v_tr.status <> 'in_transit' THEN
    RAISE EXCEPTION 'transfer_not_in_transit' USING ERRCODE = '22023';
  END IF;

  UPDATE public.stock_transfers
  SET status = 'confirmed_receive',
      receive_started_at = COALESCE(receive_started_at, now()),
      updated_at = now()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object('transfer_id', p_transfer_id, 'status', 'confirmed_receive');
END;
$$;


--
-- Name: stock_transfer_confirm_ship(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_confirm_ship(p_transfer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid         UUID := auth.uid();
  v_tenant      BIGINT := public.auth_tenant_id();
  v_role        TEXT := public.auth_role();
  v_tr          RECORD;
  v_line        RECORD;
  v_src_q       NUMERIC(15,3);
  v_src_wac     NUMERIC(15,2);
  v_is_intra    BOOLEAN;
  v_required    TEXT;
  v_from_loc    RECORD;
  v_to_loc      RECORD;
  v_dst_old_q   NUMERIC(15,3);
  v_dst_old_wac NUMERIC(15,2);
  v_dst_new_q   NUMERIC(15,3);
  v_dst_new_wac NUMERIC(15,2);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tr
  FROM public.stock_transfers
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_tr.status <> 'draft' THEN
    RAISE EXCEPTION 'transfer_not_draft' USING ERRCODE = '22023';
  END IF;

  v_is_intra := (v_tr.from_branch_id = v_tr.to_branch_id);
  v_required := CASE
    WHEN v_is_intra THEN 'inventory:transfer_create'
    ELSE 'inventory:transfer_ship'
  END;

  IF NOT public.has_permission(v_tr.from_branch_id, v_required) THEN
    RAISE EXCEPTION 'forbidden_transfer_ship' USING ERRCODE = '42501';
  END IF;

  IF v_role = 'branch_manager' AND NOT v_is_intra THEN
    RAISE EXCEPTION 'branch_manager_inter_site_ship_forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_tr.from_location_id IS NULL THEN
    RAISE EXCEPTION 'transfer_from_location_missing' USING ERRCODE = '23502';
  END IF;

  SELECT id, branch_id, location_kind, is_default_consumption
  INTO v_from_loc
  FROM public.inventory_locations
  WHERE id = v_tr.from_location_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  IF NOT FOUND OR v_from_loc.branch_id <> v_tr.from_branch_id THEN
    RAISE EXCEPTION 'transfer_from_location_invalid' USING ERRCODE = '23514';
  END IF;

  IF v_is_intra THEN
    IF v_tr.to_location_id IS NULL THEN
      RAISE EXCEPTION 'intra_branch_transfer_requires_to_location' USING ERRCODE = '23502';
    END IF;

    SELECT id, branch_id, location_kind, is_default_consumption
    INTO v_to_loc
    FROM public.inventory_locations
    WHERE id = v_tr.to_location_id
      AND tenant_id = v_tenant
      AND is_active = TRUE;

    IF NOT FOUND
       OR v_to_loc.branch_id <> v_tr.to_branch_id
       OR v_from_loc.location_kind <> 'warehouse'
       OR v_to_loc.location_kind <> 'kitchen' THEN
      RAISE EXCEPTION 'intra_branch_location_invalid' USING ERRCODE = '23514';
    END IF;

    IF v_to_loc.is_default_consumption IS DISTINCT FROM TRUE THEN
      RAISE WARNING 'default_consumption_location_not_marked:branch %, location %',
        v_tr.to_branch_id,
        v_tr.to_location_id;
    END IF;
  END IF;

  FOR v_line IN
    SELECT * FROM public.stock_transfer_items
    WHERE transfer_id = p_transfer_id
      AND tenant_id = v_tenant
  LOOP
    SELECT sl.current_quantity, sl.avg_unit_cost
    INTO v_src_q, v_src_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_tr.from_branch_id
      AND sl.location_id = v_tr.from_location_id
      AND sl.ingredient_id = v_line.ingredient_id
    FOR UPDATE;

    IF NOT FOUND OR COALESCE(v_src_q, 0) < v_line.quantity THEN
      RAISE EXCEPTION 'insufficient_stock:%', v_line.ingredient_id USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, transfer_id, unit_cost, location_id
    ) VALUES (
      v_tenant, v_tr.from_branch_id, v_line.ingredient_id, 'transfer_out', -v_line.quantity,
      'Transfer ' || v_tr.transfer_number, v_uid, p_transfer_id, v_src_wac,
      v_tr.from_location_id
    );

    UPDATE public.stock_transfer_items
    SET unit_cost_at_ship = v_src_wac
    WHERE id = v_line.id;

    IF v_is_intra THEN
      SELECT sl.current_quantity, sl.avg_unit_cost
      INTO v_dst_old_q, v_dst_old_wac
      FROM public.stock_levels sl
      WHERE sl.tenant_id = v_tenant
        AND sl.branch_id = v_tr.to_branch_id
        AND sl.location_id = v_tr.to_location_id
        AND sl.ingredient_id = v_line.ingredient_id
      FOR UPDATE;

      IF NOT FOUND THEN
        v_dst_old_q := 0;
        v_dst_old_wac := NULL;
      END IF;

      INSERT INTO public.stock_movements (
        tenant_id, branch_id, ingredient_id, type, quantity_change,
        reason, created_by, transfer_id, unit_cost, location_id
      ) VALUES (
        v_tenant, v_tr.to_branch_id, v_line.ingredient_id, 'transfer_in', v_line.quantity,
        'Transfer ' || v_tr.transfer_number, v_uid, p_transfer_id, v_src_wac,
        v_tr.to_location_id
      );

      v_dst_new_q := COALESCE(v_dst_old_q, 0) + v_line.quantity;
      v_dst_new_wac := (
        COALESCE(v_dst_old_q, 0) * COALESCE(v_dst_old_wac, 0)
          + v_line.quantity * COALESCE(v_src_wac, 0)
      ) / v_dst_new_q;

      UPDATE public.stock_levels sl
      SET avg_unit_cost = v_dst_new_wac,
          updated_at = now()
      WHERE sl.tenant_id = v_tenant
        AND sl.branch_id = v_tr.to_branch_id
        AND sl.location_id = v_tr.to_location_id
        AND sl.ingredient_id = v_line.ingredient_id;

      UPDATE public.stock_transfer_items
      SET quantity_received = v_line.quantity
      WHERE id = v_line.id;
    END IF;
  END LOOP;

  IF v_is_intra THEN
    UPDATE public.stock_transfers
    SET status = 'received',
        shipped_at = now(),
        received_at = now(),
        receive_started_at = COALESCE(receive_started_at, now()),
        updated_at = now()
    WHERE id = p_transfer_id;

    RETURN jsonb_build_object('transfer_id', p_transfer_id, 'status', 'received');
  END IF;

  UPDATE public.stock_transfers
  SET status = 'confirmed_ship',
      shipped_at = now(),
      updated_at = now()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object('transfer_id', p_transfer_id, 'status', 'confirmed_ship');
END;
$$;


--
-- Name: stock_transfer_list_branches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_list_branches() RETURNS TABLE(id bigint, name text, branch_kind text, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT b.id, b.name, b.branch_kind, b.is_active
  FROM public.branches b
  WHERE b.tenant_id = public.auth_tenant_id()
    AND b.is_active = true
    AND public.auth_role() IN (
      'owner',
      'branch_manager',
      'warehouse_manager',
      'production_manager'
    )
  ORDER BY b.name;
$$;


--
-- Name: stock_transfer_mark_in_transit(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_mark_in_transit(p_transfer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_role         TEXT := public.auth_role();
  v_branch_claim BIGINT := public.auth_branch_id();
  v_tr           RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tr
  FROM public.stock_transfers
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_tr.from_branch_id = v_tr.to_branch_id THEN
    RAISE EXCEPTION 'intra_branch_transfer_has_no_transit' USING ERRCODE = '22023';
  END IF;

  IF v_role = 'branch_manager' THEN
    RAISE EXCEPTION 'branch_manager_inter_site_ship_forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_role IN ('warehouse_manager', 'production_manager')
     AND (v_branch_claim IS NULL OR v_branch_claim <> v_tr.from_branch_id) THEN
    RAISE EXCEPTION 'forbidden_transfer_ship' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_tr.from_branch_id, 'inventory:transfer_ship') THEN
    RAISE EXCEPTION 'forbidden_transfer_ship' USING ERRCODE = '42501';
  END IF;

  IF v_tr.status <> 'confirmed_ship' THEN
    RAISE EXCEPTION 'transfer_wrong_state' USING ERRCODE = '22023';
  END IF;

  UPDATE public.stock_transfers
  SET status = 'in_transit',
      updated_at = now()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object('transfer_id', p_transfer_id, 'status', 'in_transit');
END;
$$;


--
-- Name: stock_transfer_receive(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_transfer_receive(p_transfer_id bigint, p_items jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid          UUID := auth.uid();
  v_tenant       BIGINT := public.auth_tenant_id();
  v_role         TEXT := public.auth_role();
  v_branch_claim BIGINT := public.auth_branch_id();
  v_tr           RECORD;
  v_line         RECORD;
  v_recv         NUMERIC(15,3);
  v_note         TEXT;
  v_cost         NUMERIC(15,2);
  v_old_q        NUMERIC(15,3);
  v_old_wac      NUMERIC(15,2);
  v_new_q        NUMERIC(15,3);
  v_new_wac      NUMERIC(15,2);
  v_key          TEXT;
  v_to_loc          RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tr
  FROM public.stock_transfers
  WHERE id = p_transfer_id
    AND tenant_id = v_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_tr.from_branch_id = v_tr.to_branch_id THEN
    RAISE EXCEPTION 'intra_branch_transfer_already_atomic' USING ERRCODE = '22023';
  END IF;

  IF v_role IN ('branch_manager', 'warehouse_manager', 'production_manager')
     AND (v_branch_claim IS NULL OR v_branch_claim <> v_tr.to_branch_id) THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_tr.to_branch_id, 'inventory:transfer_receive') THEN
    RAISE EXCEPTION 'forbidden_transfer_receive' USING ERRCODE = '42501';
  END IF;

  IF v_tr.status <> 'confirmed_receive' THEN
    RAISE EXCEPTION 'transfer_not_in_confirmed_receive' USING ERRCODE = '22023';
  END IF;

  IF v_tr.to_location_id IS NULL THEN
    RAISE EXCEPTION 'transfer_to_location_missing' USING ERRCODE = '23502';
  END IF;

  SELECT id, branch_id
  INTO v_to_loc
  FROM public.inventory_locations
  WHERE id = v_tr.to_location_id
    AND tenant_id = v_tenant
    AND is_active = TRUE;

  IF NOT FOUND OR v_to_loc.branch_id <> v_tr.to_branch_id THEN
    RAISE EXCEPTION 'transfer_to_location_invalid' USING ERRCODE = '23514';
  END IF;

  FOR v_line IN
    SELECT * FROM public.stock_transfer_items
    WHERE transfer_id = p_transfer_id
      AND tenant_id = v_tenant
  LOOP
    v_recv := v_line.quantity;
    v_note := NULL;

    IF p_items IS NOT NULL THEN
      v_key := v_line.ingredient_id::TEXT;
      IF (p_items ? v_key) THEN
        IF jsonb_typeof(p_items -> v_key) = 'object' THEN
          v_recv := ((p_items -> v_key) ->> 'qty')::NUMERIC;
          v_note := (p_items -> v_key) ->> 'note';
        ELSE
          v_recv := (p_items ->> v_key)::NUMERIC;
        END IF;
      END IF;
    END IF;

    IF v_recv < 0 OR v_recv > v_line.quantity THEN
      RAISE EXCEPTION 'invalid_receive_qty:%', v_line.ingredient_id USING ERRCODE = '22023';
    END IF;

    IF v_recv <= 0 THEN
      UPDATE public.stock_transfer_items
      SET quantity_received = 0,
          receive_note = v_note
      WHERE id = v_line.id;
      CONTINUE;
    END IF;

    v_cost := COALESCE(v_line.unit_cost_at_ship, 0);

    SELECT sl.current_quantity, sl.avg_unit_cost
    INTO v_old_q, v_old_wac
    FROM public.stock_levels sl
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_tr.to_branch_id
      AND sl.location_id = v_tr.to_location_id
      AND sl.ingredient_id = v_line.ingredient_id
    FOR UPDATE;

    IF NOT FOUND THEN
      v_old_q := 0;
      v_old_wac := NULL;
    END IF;

    INSERT INTO public.stock_movements (
      tenant_id, branch_id, ingredient_id, type, quantity_change,
      reason, created_by, transfer_id, unit_cost, location_id
    ) VALUES (
      v_tenant, v_tr.to_branch_id, v_line.ingredient_id, 'transfer_in', v_recv,
      'Transfer ' || v_tr.transfer_number, v_uid, p_transfer_id, v_cost,
      v_tr.to_location_id
    );

    v_new_q := COALESCE(v_old_q, 0) + v_recv;
    IF v_new_q > 0 THEN
      v_new_wac := (
        COALESCE(v_old_q, 0) * COALESCE(v_old_wac, 0) + v_recv * v_cost
      ) / v_new_q;
    ELSE
      v_new_wac := v_cost;
    END IF;

    UPDATE public.stock_levels sl
    SET avg_unit_cost = v_new_wac,
        updated_at = now()
    WHERE sl.tenant_id = v_tenant
      AND sl.branch_id = v_tr.to_branch_id
      AND sl.location_id = v_tr.to_location_id
      AND sl.ingredient_id = v_line.ingredient_id;

    UPDATE public.stock_transfer_items
    SET quantity_received = v_recv,
        receive_note = v_note
    WHERE id = v_line.id;
  END LOOP;

  UPDATE public.stock_transfers
  SET status = 'received',
      received_at = now(),
      updated_at = now()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object(
    'transfer_id', p_transfer_id,
    'status', 'received'
  );
END;
$$;


--
-- Name: submit_count_round(bigint, smallint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_count_round(p_session_id bigint, p_round_no smallint, p_counts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_ss RECORD; v_count JSONB; v_applied INT := 0; v_conflict_count INT := 0;
  v_existing RECORD; v_offline_at TIMESTAMPTZ; v_ingredient BIGINT; v_counted NUMERIC; v_op_id UUID;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT * INTO v_ss FROM public.stocktake_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session not found' USING ERRCODE = 'P0002'; END IF;
  IF v_ss.status <> 'in_progress' THEN RAISE EXCEPTION 'session not in_progress (status=%)', v_ss.status USING ERRCODE = '22023'; END IF;
  IF NOT public.has_permission(v_ss.branch_id, 'inventory:stocktake_create') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF p_round_no <> v_ss.current_round THEN RAISE EXCEPTION 'round % does not match current_round %', p_round_no, v_ss.current_round USING ERRCODE = '22023'; END IF;
  FOR v_count IN SELECT value FROM jsonb_array_elements(p_counts) LOOP
    v_ingredient := (v_count->>'ingredient_id')::BIGINT;
    v_counted    := (v_count->>'counted_quantity')::NUMERIC;
    v_op_id      := NULLIF(v_count->>'client_op_id','')::UUID;
    v_offline_at := NULLIF(v_count->>'offline_created_at','')::TIMESTAMPTZ;
    IF v_ss.offline_enabled AND v_offline_at IS NOT NULL THEN
      IF v_offline_at > now() + INTERVAL '5 minutes' OR v_offline_at < v_ss.started_at THEN
        INSERT INTO public.stocktake_conflicts (tenant_id, session_id, ingredient_id, round_no, conflict_type, client_payload, submitted_by)
        VALUES (v_ss.tenant_id, p_session_id, v_ingredient, p_round_no, 'clock_tamper',
          jsonb_build_object('client_op_id', v_op_id, 'offline_created_at', v_offline_at, 'counted_quantity', v_counted), v_uid);
        v_conflict_count := v_conflict_count + 1;
        CONTINUE;
      END IF;
    END IF;
    SELECT id, counted_quantity, is_final INTO v_existing FROM public.stocktake_lines
      WHERE session_id = p_session_id AND ingredient_id = v_ingredient AND round_no = p_round_no;
    IF FOUND AND v_existing.is_final AND v_existing.counted_quantity IS DISTINCT FROM v_counted THEN
      INSERT INTO public.stocktake_conflicts (tenant_id, session_id, ingredient_id, round_no, conflict_type, client_payload, server_payload, submitted_by)
      VALUES (v_ss.tenant_id, p_session_id, v_ingredient, p_round_no, 'is_final_overwrite',
        jsonb_build_object('client_op_id', v_op_id, 'counted_quantity', v_counted, 'offline_created_at', v_offline_at),
        jsonb_build_object('existing_counted_quantity', v_existing.counted_quantity, 'is_final', true), v_uid);
      v_conflict_count := v_conflict_count + 1;
      CONTINUE;
    END IF;
    INSERT INTO public.stocktake_lines (tenant_id, session_id, ingredient_id, system_quantity,
      counted_quantity, counted_by, counted_at, round_no, abc_class, client_op_id, offline_created_at)
    SELECT v_ss.tenant_id, p_session_id, v_ingredient,
      (SELECT system_quantity FROM public.stocktake_lines WHERE session_id = p_session_id AND ingredient_id = v_ingredient AND round_no = 1),
      v_counted, v_uid, now(), p_round_no,
      (SELECT abc_class FROM public.stocktake_lines WHERE session_id = p_session_id AND ingredient_id = v_ingredient AND round_no = 1),
      v_op_id, v_offline_at
    ON CONFLICT (session_id, ingredient_id, round_no) DO UPDATE SET
      counted_quantity = EXCLUDED.counted_quantity, counted_by = EXCLUDED.counted_by, counted_at = EXCLUDED.counted_at,
      client_op_id = COALESCE(EXCLUDED.client_op_id, public.stocktake_lines.client_op_id),
      offline_created_at = COALESCE(EXCLUDED.offline_created_at, public.stocktake_lines.offline_created_at);
    v_applied := v_applied + 1;
  END LOOP;
  RETURN jsonb_build_object('applied_count', v_applied, 'conflict_count', v_conflict_count, 'round_no', p_round_no);
END; $$;


--
-- Name: submit_leave_request(bigint, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_leave_request(p_branch_id bigint, p_start_date date, p_end_date date, p_leave_type text DEFAULT 'annual'::text, p_reason text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id     BIGINT := public.auth_tenant_id();
  v_user_id       UUID   := auth.uid();
  v_employee_id   BIGINT;
  v_request_id    BIGINT;
  v_today         DATE := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_leave_type    TEXT := COALESCE(NULLIF(trim(p_leave_type), ''), 'annual');
  v_reason        TEXT := NULLIF(trim(COALESCE(p_reason, '')), '');
  v_employee_name TEXT;
  v_requester_bucket TEXT := public.auth_role();
  v_target_roles  TEXT[];
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'submit_leave_request: missing auth context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'hr:request_leave') THEN
    RAISE EXCEPTION 'submit_leave_request: missing permission hr:request_leave'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'submit_leave_request: invalid date range'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_start_date < v_today THEN
    RAISE EXCEPTION 'submit_leave_request: cannot request past date'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_leave_type NOT IN ('annual', 'sick', 'unpaid', 'personal', 'other') THEN
    RAISE EXCEPTION 'submit_leave_request: invalid leave type'
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_reason IS NOT NULL AND char_length(v_reason) > 500 THEN
    RAISE EXCEPTION 'submit_leave_request: reason too long'
      USING ERRCODE = 'string_data_right_truncation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = v_tenant_id
      AND b.is_active = true
  ) THEN
    RAISE EXCEPTION 'submit_leave_request: branch not found or inactive'
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  SELECT e.id, p.full_name INTO v_employee_id, v_employee_name
  FROM public.employees e
  JOIN public.profiles p ON p.id = e.profile_id
  WHERE e.profile_id = v_user_id
    AND e.tenant_id = v_tenant_id
    AND e.is_active = true
    AND p.tenant_id = v_tenant_id
    AND p.branch_id = p_branch_id
  LIMIT 1;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION 'submit_leave_request: no active employee in this branch'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  PERFORM pg_advisory_xact_lock(v_employee_id);

  IF EXISTS (
    SELECT 1
    FROM public.leave_requests lr
    WHERE lr.tenant_id = v_tenant_id
      AND lr.employee_id = v_employee_id
      AND lr.status IN ('pending', 'approved')
      AND daterange(lr.start_date, lr.end_date, '[]')
          && daterange(p_start_date, p_end_date, '[]')
  ) THEN
    RAISE EXCEPTION 'submit_leave_request: date range overlaps existing request'
      USING ERRCODE = 'unique_violation';
  END IF;

  INSERT INTO public.leave_requests
    (tenant_id, branch_id, employee_id, start_date, end_date, leave_type, status, reason)
  VALUES
    (v_tenant_id, p_branch_id, v_employee_id, p_start_date, p_end_date, v_leave_type, 'pending', v_reason)
  RETURNING id INTO v_request_id;

  -- Người gửi là branch_manager thì chỉ cấp trên duyệt (RPC duyệt đã chặn
  -- tự duyệt; target_roles mang access bucket, không phải position code).
  IF v_requester_bucket = 'branch_manager' THEN
    v_target_roles := ARRAY[ 'owner'];
  ELSE
    v_target_roles := ARRAY['branch_manager', 'owner'];
  END IF;

  INSERT INTO public.notifications (
    tenant_id,
    target_branch_id,
    target_roles,
    kind,
    severity,
    title,
    body,
    entity_type,
    entity_id,
    action_url,
    meta,
    dedup_key
  )
  VALUES (
    v_tenant_id,
    p_branch_id,
    v_target_roles,
    'hr.leave_requested',
    'info',
    'Yêu cầu nghỉ phép mới',
    format(
      '%s xin nghỉ %s.',
      COALESCE(v_employee_name, 'Nhân viên'),
      CASE
        WHEN p_start_date = p_end_date
          THEN format('ngày %s', to_char(p_start_date, 'DD/MM'))
        ELSE format(
          'từ %s đến %s',
          to_char(p_start_date, 'DD/MM'),
          to_char(p_end_date, 'DD/MM')
        )
      END
    ),
    'leave_request',
    v_request_id,
    '/hr',
    jsonb_build_object(
      'leave_request_id', v_request_id,
      'employee_id', v_employee_id,
      'branch_id', p_branch_id,
      'start_date', p_start_date,
      'end_date', p_end_date,
      'leave_type', v_leave_type,
      'requester_bucket', v_requester_bucket
    ),
    format('hr.leave_request:%s', v_request_id)
  )
  ON CONFLICT (tenant_id, dedup_key)
    WHERE dedup_key IS NOT NULL
  DO UPDATE SET
    created_at = EXCLUDED.created_at,
    expires_at = NULL,
    meta = EXCLUDED.meta;

  PERFORM public.log_audit(
    'submit'::TEXT,
    'leave_request'::TEXT,
    v_request_id,
    NULL,
    jsonb_build_object(
      'branch_id', p_branch_id,
      'employee_id', v_employee_id,
      'start_date', p_start_date,
      'end_date', p_end_date,
      'leave_type', v_leave_type
    )
  );

  RETURN v_request_id;
END;
$$;


--
-- Name: FUNCTION submit_leave_request(p_branch_id bigint, p_start_date date, p_end_date date, p_leave_type text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_leave_request(p_branch_id bigint, p_start_date date, p_end_date date, p_leave_type text, p_reason text) IS 'Employee submits a branch-scoped leave request. Resolves employee_id from auth.uid(), enforces hr:request_leave, blocks past/overlapping pending+approved ranges, notifies approver buckets. Does not mutate attendance or payroll.';


--
-- Name: sync_insurance_base(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_insurance_base(p_employee_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_insurance_base NUMERIC(15,2);
  v_gross NUMERIC(15,2);
BEGIN
  SELECT ec.insurance_base_salary, ec.gross_salary
  INTO v_insurance_base, v_gross
  FROM public.employment_contracts ec
  WHERE ec.employee_id = p_employee_id
    AND ec.status = 'active'
  ORDER BY ec.start_date DESC
  LIMIT 1;

  IF v_insurance_base IS NOT NULL THEN
    UPDATE public.employees
    SET
      insurance_base_salary = v_insurance_base,
      base_salary = v_gross,
      updated_at = now()
    WHERE id = p_employee_id;
  END IF;
END;
$$;


--
-- Name: sync_missing_permissions_from_template(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_missing_permissions_from_template() RETURNS TABLE(rows_added integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_profile record;
  v_template record;
  v_perm_key text;
  v_branch bigint;
  v_added integer := 0;
  v_rows integer;
BEGIN
  FOR v_profile IN
    SELECT
      p.id AS user_id,
      p.tenant_id,
      p.branch_id,
      pos.code AS position_code,
      private.staff_role_from_position_code(pos.code) AS access_bucket
    FROM public.profiles p
    JOIN public.positions pos
      ON pos.id = p.position_id
     AND pos.tenant_id = p.tenant_id
    WHERE p.is_active = true
      AND p.position_id IS NOT NULL
  LOOP
    IF v_profile.access_bucket IS NULL THEN
      CONTINUE;
    END IF;

    SELECT rt.id, rt.permission_keys
    INTO v_template
    FROM public.role_templates rt
    WHERE rt.tenant_id = v_profile.tenant_id
      AND rt.position_code = v_profile.position_code
    LIMIT 1;

    IF v_template.permission_keys IS NULL THEN
      CONTINUE;
    END IF;

    IF v_profile.access_bucket IN ('owner') THEN
      v_branch := NULL;
    ELSE
      v_branch := v_profile.branch_id;
      IF v_branch IS NULL THEN
        CONTINUE;
      END IF;
    END IF;

    FOREACH v_perm_key IN ARRAY v_template.permission_keys LOOP
      INSERT INTO public.staff_permissions (
        user_id,
        tenant_id,
        branch_id,
        permission_key,
        source_template
      )
      VALUES (
        v_profile.user_id,
        v_profile.tenant_id,
        v_branch,
        v_perm_key,
        v_template.id
      )
      ON CONFLICT DO NOTHING;

      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_added := v_added + v_rows;
    END LOOP;
  END LOOP;

  RETURN QUERY SELECT v_added;
END;
$$;


--
-- Name: FUNCTION sync_missing_permissions_from_template(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_missing_permissions_from_template() IS 'Additive backfill: inserts template rows missing from staff_permissions. Never removes. Safe to run anytime after a template edit.';


--
-- Name: sync_order_item_status_from_kds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_order_item_status_from_kds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    UPDATE public.order_items oi
    SET
      status = CASE
        WHEN NEW.status = 'cancelled' THEN 'cancelled'::text
        ELSE NEW.status::text
      END,
      updated_at = now()
    WHERE oi.id = NEW.order_item_id
      AND oi.tenant_id = NEW.tenant_id
      AND oi.status <> 'cancelled';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tio_assert_one_active_summary_per_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tio_assert_one_active_summary_per_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.tax_invoice_orders tio
    JOIN public.tax_invoices ti ON ti.id = tio.tax_invoice_id
    WHERE tio.order_id = NEW.order_id
      AND tio.tax_invoice_id <> NEW.tax_invoice_id
      AND ti.status NOT IN ('cancelled', 'replaced')
  ) THEN
    RAISE EXCEPTION 'order % already in active summary HĐ', NEW.order_id
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: toggle_category_active(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_category_active(p_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_state BOOLEAN;
BEGIN
  UPDATE public.menu_categories
    SET is_active = NOT is_active
    WHERE id = p_id AND tenant_id = public.auth_tenant_id()
    RETURNING is_active INTO new_state;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  RETURN new_state;
END;
$$;


--
-- Name: toggle_ingredient_active(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_ingredient_active(p_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  new_state BOOLEAN;
BEGIN
  UPDATE public.ingredients
    SET is_active = NOT is_active,
        updated_at = now()
    WHERE id = p_id
      AND tenant_id = public.auth_tenant_id()
    RETURNING is_active INTO new_state;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  RETURN new_state;
END;
$$;


--
-- Name: toggle_item_active(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_item_active(p_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_state BOOLEAN;
BEGIN
  UPDATE public.menu_items
    SET is_active = NOT is_active
    WHERE id = p_id AND tenant_id = public.auth_tenant_id()
    RETURNING is_active INTO new_state;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  RETURN new_state;
END;
$$;


--
-- Name: toggle_profile_active(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_profile_active(p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT; v_actor_tenant BIGINT; v_actor_branch BIGINT;
  v_target_role TEXT; v_target_branch BIGINT; v_target_active BOOLEAN; v_new_state BOOLEAN;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  SELECT COALESCE(private.staff_role_from_position_code(po.code), 'unassigned'), p.tenant_id, p.branch_id
  INTO v_actor_role, v_actor_tenant, v_actor_branch
  FROM public.profiles p LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_actor_id AND COALESCE(p.is_active, true) = true;
  IF NOT FOUND OR v_actor_tenant IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.has_permission_any('staff:manage') THEN
    RAISE EXCEPTION 'forbidden: missing staff:manage' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(private.staff_role_from_position_code(po.code), 'unassigned'), p.branch_id, p.is_active
  INTO v_target_role, v_target_branch, v_target_active
  FROM public.profiles p LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = p_target_id AND p.tenant_id = v_actor_tenant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found';
  END IF;
  IF p_target_id = v_actor_id THEN
    RAISE EXCEPTION 'cannot_toggle_self';
  END IF;
  IF v_actor_role = 'owner' THEN
    NULL;
  ELSIF v_actor_role = 'branch_manager' THEN
    IF v_target_branch IS DISTINCT FROM v_actor_branch THEN
      RAISE EXCEPTION 'branch_manager: target not in your branch';
    END IF;
    IF v_target_role IN ('owner','branch_manager') THEN
      RAISE EXCEPTION 'permission_denied';
    END IF;
  ELSE
    RAISE EXCEPTION 'permission_denied';
  END IF;
  UPDATE public.profiles SET is_active = NOT is_active WHERE id = p_target_id AND tenant_id = v_actor_tenant RETURNING is_active INTO v_new_state;
  RETURN v_new_state;
END;
$$;


--
-- Name: FUNCTION toggle_profile_active(p_target_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.toggle_profile_active(p_target_id uuid) IS 'Staff active-state toggle RPC. SECURITY DEFINER with staff:manage gate before role hierarchy checks.';


--
-- Name: transfer_order_table(bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_order_table(p_order_id bigint, p_new_table_id bigint, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order RECORD;
  v_new_table RECORD;
  v_old_table_id BIGINT;
  v_active_on_old INT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT id, tenant_id, branch_id, table_id, order_type, status,
         last_transfer_idempotency_key
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role <> 'owner' THEN
    IF v_prof_branch IS NULL THEN
      RAISE EXCEPTION 'branch scope required' USING ERRCODE = '42501';
    END IF;
    IF v_order.branch_id <> v_prof_branch THEN
      RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:use') THEN
    RAISE EXCEPTION 'forbidden: missing pos:use' USING ERRCODE = '42501';
  END IF;

  IF p_idempotency_key IS NOT NULL
     AND v_order.last_transfer_idempotency_key = p_idempotency_key THEN
    RETURN jsonb_build_object(
      'order_id', p_order_id,
      'table_id', v_order.table_id,
      'idempotent', true
    );
  END IF;

  IF v_order.order_type <> 'dine_in' THEN
    RAISE EXCEPTION 'takeaway cannot transfer' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  SELECT id, status INTO v_new_table
  FROM public.tables
  WHERE id = p_new_table_id AND branch_id = v_order.branch_id AND tenant_id = v_order.tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'table not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_new_table_id = v_order.table_id THEN
    UPDATE public.orders
    SET last_transfer_idempotency_key = COALESCE(p_idempotency_key, last_transfer_idempotency_key),
        updated_at = now()
    WHERE id = p_order_id;
    RETURN jsonb_build_object('order_id', p_order_id, 'table_id', p_new_table_id);
  END IF;

  IF v_new_table.status NOT IN ('available', 'occupied') THEN
    RAISE EXCEPTION 'table not available' USING ERRCODE = '22023';
  END IF;

  v_old_table_id := v_order.table_id;

  UPDATE public.orders
  SET table_id = p_new_table_id,
      last_transfer_idempotency_key = p_idempotency_key,
      updated_at = now()
  WHERE id = p_order_id;

  UPDATE public.tables
  SET status = 'occupied', updated_at = now()
  WHERE id = p_new_table_id AND tenant_id = v_order.tenant_id;

  IF v_old_table_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_active_on_old
    FROM public.orders
    WHERE table_id = v_old_table_id
      AND tenant_id = v_order.tenant_id
      AND id <> p_order_id
      AND status NOT IN ('completed', 'cancelled', 'served');

    IF v_active_on_old = 0 THEN
      UPDATE public.tables
      SET status = 'available', updated_at = now()
      WHERE id = v_old_table_id AND tenant_id = v_order.tenant_id;
    END IF;
  END IF;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id, p_order_id, v_order.status, v_order.status, v_uid,
    'transfer_table -> ' || p_new_table_id::text
  );

  RETURN jsonb_build_object('order_id', p_order_id, 'table_id', p_new_table_id);
END;
$$;


--
-- Name: transition_order_item_status(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_order_item_status(p_item_id bigint, p_new_status text, p_expected_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id UUID;
  v_actor_tenant BIGINT;
  v_actor_branch BIGINT;
  v_item RECORD;
  v_order RECORD;
  v_derived_status TEXT;
  v_old_order_status TEXT;
  v_pending_count INT;
  v_preparing_count INT;
  v_ready_count INT;
  v_served_count INT;
  v_cancelled_count INT;
  v_total_count INT;
BEGIN
  -- Auth context
  v_actor_id := auth.uid();
  v_actor_tenant := public.auth_tenant_id();
  v_actor_branch := public.auth_branch_id();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  -- Validate new_status
  IF p_new_status NOT IN ('pending', 'preparing', 'ready', 'served', 'cancelled') THEN
    RAISE EXCEPTION 'invalid item status: %', p_new_status USING ERRCODE = '22023';
  END IF;

  -- Fetch and lock item + parent order
  SELECT oi.id, oi.order_id, oi.tenant_id, oi.status AS item_status
  INTO v_item
  FROM public.order_items oi
  WHERE oi.id = p_item_id
    AND oi.tenant_id = v_actor_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'item_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Fetch parent order for branch check
  SELECT o.id, o.branch_id, o.status, o.table_id, o.order_type, o.tenant_id
  INTO v_order
  FROM public.orders o
  WHERE o.id = v_item.order_id
  FOR UPDATE;

  -- Branch authorization (ops roles must be in same branch, managers bypass)
  IF v_actor_branch IS NOT NULL AND v_order.branch_id <> v_actor_branch THEN
    RAISE EXCEPTION 'not_in_branch' USING ERRCODE = 'P0003';
  END IF;

  -- Optimistic locking: verify expected status
  IF v_item.item_status <> p_expected_status THEN
    RAISE EXCEPTION 'status_changed:% expected % got %', v_item.item_status, p_expected_status, v_item.item_status
      USING ERRCODE = 'P0001';
  END IF;

  -- Validate transition
  IF NOT (
    (p_expected_status = 'pending' AND p_new_status IN ('preparing', 'cancelled'))
    OR (p_expected_status = 'preparing' AND p_new_status IN ('ready', 'cancelled'))
    OR (p_expected_status = 'ready' AND p_new_status = 'served')
    -- Allow served → cancelled for post-serve void (manager action)
  ) THEN
    RAISE EXCEPTION 'invalid_transition:% to %', p_expected_status, p_new_status
      USING ERRCODE = '22023';
  END IF;

  -- Apply item status change
  UPDATE public.order_items
  SET status = p_new_status, updated_at = now()
  WHERE id = p_item_id;

  -- ── Derive order status from sibling items ──
  v_old_order_status := v_order.status;

  SELECT
    COUNT(*) FILTER (WHERE status = 'pending') AS pending_count,
    COUNT(*) FILTER (WHERE status = 'preparing') AS preparing_count,
    COUNT(*) FILTER (WHERE status = 'ready') AS ready_count,
    COUNT(*) FILTER (WHERE status = 'served') AS served_count,
    COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled_count,
    COUNT(*) AS total_count
  INTO v_pending_count, v_preparing_count, v_ready_count, v_served_count, v_cancelled_count, v_total_count
  FROM public.order_items
  WHERE order_id = v_item.order_id;

  -- Derive new order status
  IF v_cancelled_count = v_total_count THEN
    v_derived_status := 'cancelled';
  ELSIF v_served_count + v_cancelled_count = v_total_count THEN
    v_derived_status := 'served';
  ELSIF v_ready_count + v_served_count + v_cancelled_count = v_total_count THEN
    v_derived_status := 'ready';
  ELSIF v_preparing_count > 0 OR v_ready_count > 0 THEN
    v_derived_status := 'preparing';
  ELSE
    v_derived_status := v_old_order_status; -- no change
  END IF;

  -- Update order status if changed
  IF v_derived_status <> v_old_order_status
     AND v_old_order_status NOT IN ('completed') -- never override completed
  THEN
    UPDATE public.orders
    SET status = v_derived_status, updated_at = now()
    WHERE id = v_item.order_id;

    -- Write audit trail for order transition
    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    ) VALUES (
      v_actor_tenant, v_item.order_id, v_old_order_status, v_derived_status,
      v_actor_id, 'derived from item ' || p_item_id || ' → ' || p_new_status
    );

    -- Table release handled by existing trigger trg_order_release_table
  END IF;

  RETURN jsonb_build_object(
    'item_id', p_item_id,
    'item_status', p_new_status,
    'order_id', v_item.order_id,
    'order_status', v_derived_status,
    'order_status_changed', v_derived_status <> v_old_order_status
  );
END;
$$;


--
-- Name: transition_order_status(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_order_status(p_order_id bigint, p_new_status text, p_expected_status text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id UUID;
  v_actor_tenant BIGINT;
  v_actor_branch BIGINT;
  v_order RECORD;
BEGIN
  v_actor_id := auth.uid();
  v_actor_tenant := public.auth_tenant_id();
  v_actor_branch := public.auth_branch_id();

  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT id, tenant_id, branch_id, status, table_id, order_type
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND tenant_id = v_actor_tenant
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_branch IS NOT NULL AND v_order.branch_id <> v_actor_branch THEN
    RAISE EXCEPTION 'not_in_branch' USING ERRCODE = 'P0003';
  END IF;

  IF v_order.status <> p_expected_status THEN
    RAISE EXCEPTION 'status_changed:% expected % got %', v_order.status, p_expected_status, v_order.status
      USING ERRCODE = 'P0001';
  END IF;

  IF NOT (
    (p_expected_status = 'new' AND p_new_status = 'confirmed')
    OR (p_expected_status = 'served' AND p_new_status = 'completed')
    OR (p_expected_status NOT IN ('completed') AND p_new_status = 'cancelled')
  ) THEN
    RAISE EXCEPTION 'invalid_transition:% to %', p_expected_status, p_new_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.orders
  SET status = p_new_status, updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  ) VALUES (
    v_actor_tenant, p_order_id, v_order.status, p_new_status, v_actor_id, p_note
  );

  IF p_new_status = 'cancelled' THEN
    UPDATE public.order_items
    SET status = 'cancelled', updated_at = now()
    WHERE order_id = p_order_id
      AND status NOT IN ('served', 'cancelled');
  END IF;

  IF p_new_status = 'completed' AND p_expected_status = 'served' THEN
    PERFORM public.consume_stock_for_order(p_order_id);
  END IF;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'old_status', v_order.status,
    'new_status', p_new_status
  );
END;
$$;


--
-- Name: transition_supplier_return(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_supplier_return(p_return_id bigint, p_target_status text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid       UUID   := auth.uid();
  v_tenant    BIGINT := public.auth_tenant_id();
  v_ret       RECORD;
  v_credit_id BIGINT;
  v_credit_no TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_target_status NOT IN ('credited', 'refunded', 'cancelled') THEN
    RAISE EXCEPTION 'invalid_target_status' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ret
  FROM public.supplier_returns
  WHERE id = p_return_id AND tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'return_not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Permission: confirm-grade for credit/refund (impacts AP); confirm-grade for cancel too
  IF NOT public.has_permission(v_ret.branch_id, 'supplier_return:confirm') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- State transition rules
  IF p_target_status = 'cancelled' AND v_ret.status NOT IN ('draft', 'sent') THEN
    RAISE EXCEPTION 'cannot_cancel_after_credit' USING ERRCODE = '22023';
  END IF;
  IF p_target_status IN ('credited', 'refunded') AND v_ret.status <> 'sent' THEN
    RAISE EXCEPTION 'must_be_sent_before_credit' USING ERRCODE = '22023';
  END IF;
  IF p_target_status = 'credited' AND v_ret.resolution <> 'credit_note' THEN
    RAISE EXCEPTION 'resolution_mismatch_credit' USING ERRCODE = '22023';
  END IF;
  IF p_target_status = 'refunded' AND v_ret.resolution <> 'cash_refund' THEN
    RAISE EXCEPTION 'resolution_mismatch_refund' USING ERRCODE = '22023';
  END IF;

  -- Move state
  UPDATE public.supplier_returns
  SET status = p_target_status,
      notes = COALESCE(p_notes, notes),
      updated_at = now()
  WHERE id = p_return_id;

  -- Auto-create supplier_credit_note for credited/refunded
  IF p_target_status IN ('credited', 'refunded') THEN
    v_credit_no := 'CN-' || to_char(now(),'YYMMDD') || '-' ||
                   lpad(nextval('public.supplier_credit_notes_id_seq')::TEXT, 4, '0');

    INSERT INTO public.supplier_credit_notes (
      tenant_id, supplier_id, return_id, credit_number,
      kind, amount, status, notes, created_by, applied_at
    ) VALUES (
      v_tenant, v_ret.supplier_id, p_return_id, v_credit_no,
      CASE WHEN p_target_status = 'credited' THEN 'credit_note' ELSE 'cash_refund' END,
      v_ret.total_value,
      CASE WHEN p_target_status = 'refunded' THEN 'applied' ELSE 'open' END,
      p_notes,
      v_uid,
      CASE WHEN p_target_status = 'refunded' THEN now() ELSE NULL END
    )
    ON CONFLICT (return_id, tenant_id) DO NOTHING
    RETURNING id INTO v_credit_id;
  END IF;

  RETURN jsonb_build_object(
    'return_id', p_return_id,
    'status', p_target_status,
    'credit_note_id', v_credit_id,
    'credit_number', v_credit_no
  );
END;
$$;


--
-- Name: FUNCTION transition_supplier_return(p_return_id bigint, p_target_status text, p_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transition_supplier_return(p_return_id bigint, p_target_status text, p_notes text) IS 'Transitions supplier_returns.status from sent → credited|refunded|cancelled. For credited/refunded, auto-inserts a supplier_credit_notes row (idempotent on return_id).';


--
-- Name: transition_tax_invoice_state(bigint, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_tax_invoice_state(p_tax_invoice_id bigint, p_to_status text, p_payload jsonb DEFAULT NULL::jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice  RECORD;
  v_uid      UUID := auth.uid();
  v_allowed  BOOLEAN := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices
  WHERE id = p_tax_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_invoice.tenant_id <> public.auth_tenant_id() THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_to_status IN ('cancelled', 'replaced') THEN
    IF NOT public.has_permission_any('settings:tenant') THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT public.has_permission_any('orders:write') THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_allowed := (
    (v_invoice.status = 'draft'     AND p_to_status IN ('signing', 'cancelled'))
    OR (v_invoice.status = 'signing'   AND p_to_status IN ('submitted', 'issued', 'draft', 'cancelled'))
    OR (v_invoice.status = 'submitted' AND p_to_status IN ('issued', 'cancelled'))
    OR (v_invoice.status = 'issued'    AND p_to_status IN ('cancelled', 'replaced'))
  );

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'illegal_transition: % -> %', v_invoice.status, p_to_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.tax_invoices
  SET
    status = p_to_status,
    issued_at = CASE WHEN p_to_status = 'issued' THEN now() ELSE issued_at END,
    cancelled_at = CASE WHEN p_to_status = 'cancelled' THEN now() ELSE cancelled_at END,
    signing_started_at = CASE WHEN p_to_status = 'signing' THEN now() ELSE signing_started_at END,
    provider_data = CASE
      WHEN p_payload IS NULL THEN provider_data
      ELSE COALESCE(provider_data, '{}'::JSONB) || jsonb_build_object(p_to_status, p_payload)
    END,
    updated_at = now()
  WHERE id = p_tax_invoice_id;

  INSERT INTO public.tax_invoice_events
    (tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note)
  VALUES
    (p_tax_invoice_id, v_invoice.tenant_id, v_invoice.status, p_to_status, v_uid, p_payload, p_note);

  RETURN jsonb_build_object(
    'tax_invoice_id', p_tax_invoice_id,
    'from_status', v_invoice.status,
    'to_status', p_to_status
  );
END;
$$;


--
-- Name: transition_tax_invoice_state_as_system(bigint, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_tax_invoice_state_as_system(p_tax_invoice_id bigint, p_to_status text, p_actor uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT NULL::jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_allowed BOOLEAN := false;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden_service_role_only' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_invoice
  FROM public.tax_invoices
  WHERE id = p_tax_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tax_invoice_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_allowed := (
    (v_invoice.status = 'draft'     AND p_to_status IN ('signing', 'cancelled'))
    OR (v_invoice.status = 'signing'   AND p_to_status IN ('submitted', 'issued', 'draft', 'cancelled'))
    OR (v_invoice.status = 'submitted' AND p_to_status IN ('issued', 'cancelled'))
    OR (v_invoice.status = 'issued'    AND p_to_status IN ('cancelled', 'replaced'))
  );

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'illegal_transition: % -> %', v_invoice.status, p_to_status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.tax_invoices
  SET
    status = p_to_status,
    issued_at = CASE WHEN p_to_status = 'issued'    THEN now() ELSE issued_at END,
    cancelled_at = CASE WHEN p_to_status = 'cancelled' THEN now() ELSE cancelled_at END,
    signing_started_at = CASE WHEN p_to_status = 'signing'   THEN now() ELSE signing_started_at END,
    provider_data = CASE
      WHEN p_payload IS NULL THEN provider_data
      WHEN provider_data IS NULL THEN p_payload
      ELSE provider_data || p_payload
    END,
    updated_at = now()
  WHERE id = p_tax_invoice_id;

  INSERT INTO public.tax_invoice_events
    (tax_invoice_id, tenant_id, from_status, to_status, actor_id, payload, note)
  VALUES
    (p_tax_invoice_id, v_invoice.tenant_id, v_invoice.status, p_to_status, p_actor, p_payload, p_note);

  RETURN jsonb_build_object(
    'tax_invoice_id', p_tax_invoice_id,
    'from_status', v_invoice.status,
    'to_status', p_to_status,
    'actor', p_actor
  );
END;
$$;


--
-- Name: FUNCTION transition_tax_invoice_state_as_system(p_tax_invoice_id bigint, p_to_status text, p_actor uuid, p_payload jsonb, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transition_tax_invoice_state_as_system(p_tax_invoice_id bigint, p_to_status text, p_actor uuid, p_payload jsonb, p_note text) IS 'Service-role-only overload of transition_tax_invoice_state. Use from cron routes that need to drive HĐĐT state machine without auth.uid(). Per D1 owner decision 2026-05-08.';


--
-- Name: trg_ensure_branch_inventory_location_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_ensure_branch_inventory_location_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.branch_kind = 'branch' THEN
    PERFORM public.ensure_branch_inventory_location_defaults(NEW.tenant_id, NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_grn_requires_review_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_grn_requires_review_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_grn        RECORD;
  v_ingredient RECORD;
BEGIN
  IF NEW.requires_review IS NOT TRUE THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.requires_review IS TRUE THEN
    RETURN NEW;
  END IF;

  SELECT g.id, g.grn_number, g.supplier_id, g.branch_id, s.name AS supplier_name, b.name AS branch_name
  INTO v_grn
  FROM public.goods_received_notes g
  LEFT JOIN public.suppliers s ON s.id = g.supplier_id
  LEFT JOIN public.branches b ON b.id = g.branch_id
  WHERE g.id = NEW.grn_id AND g.tenant_id = NEW.tenant_id;

  SELECT id, name, unit INTO v_ingredient
  FROM public.ingredients
  WHERE id = NEW.ingredient_id AND tenant_id = NEW.tenant_id;

  INSERT INTO public.notification_outbox (tenant_id, channel, topic, payload)
  VALUES (
    NEW.tenant_id,
    'inventory',
    'grn.requires_review',
    jsonb_build_object(
      'grn_id', v_grn.id,
      'grn_number', v_grn.grn_number,
      'branch_id', v_grn.branch_id,
      'branch_name', v_grn.branch_name,
      'supplier_id', v_grn.supplier_id,
      'supplier_name', v_grn.supplier_name,
      'ingredient_id', v_ingredient.id,
      'ingredient_name', v_ingredient.name,
      'unit', v_ingredient.unit,
      'po_unit_price', NEW.po_unit_price,
      'unit_cost', NEW.unit_cost,
      'price_variance_pct', NEW.price_variance_pct,
      'override_note', NEW.price_override_note
    )
  );
  RETURN NEW;
END;
$$;


