--
-- Name: trg_update_stock_on_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_update_stock_on_movement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.location_id IS NULL THEN
    RAISE EXCEPTION 'stock_movements.location_id required (after per-location migration)'
      USING ERRCODE = '23502';
  END IF;

  UPDATE public.stock_levels
  SET
    current_quantity = current_quantity + NEW.quantity_change,
    updated_at = now()
  WHERE ingredient_id = NEW.ingredient_id
    AND branch_id IS NOT DISTINCT FROM NEW.branch_id
    AND location_id = NEW.location_id
    AND tenant_id = NEW.tenant_id;

  IF NOT FOUND THEN
    INSERT INTO public.stock_levels (
      tenant_id,
      branch_id,
      ingredient_id,
      location_id,
      current_quantity
    )
    VALUES (
      NEW.tenant_id,
      NEW.branch_id,
      NEW.ingredient_id,
      NEW.location_id,
      NEW.quantity_change
    );
  END IF;

  IF NEW.type = 'count_adjustment' THEN
    UPDATE public.stock_levels
    SET last_counted_at = now()
    WHERE ingredient_id = NEW.ingredient_id
      AND branch_id IS NOT DISTINCT FROM NEW.branch_id
      AND location_id = NEW.location_id
      AND tenant_id = NEW.tenant_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_upsert_grn_last_on_confirm(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_upsert_grn_last_on_confirm() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status <> 'confirmed' THEN RETURN NEW; END IF;
  IF OLD.status = 'confirmed' THEN RETURN NEW; END IF;
  IF COALESCE(NEW.express_approved, false) THEN RETURN NEW; END IF;
  INSERT INTO public.supplier_price_list (tenant_id, supplier_id, ingredient_id, uom, unit_price, source, effective_from, source_ref, created_by)
  SELECT NEW.tenant_id, NEW.supplier_id, gi.ingredient_id, gi.unit, gi.unit_cost, 'grn_last', CURRENT_DATE,
         jsonb_build_object('grn_id', NEW.id, 'grn_item_id', gi.id), NEW.created_by
  FROM public.grn_items gi
  WHERE gi.grn_id = NEW.id AND gi.received_quantity > 0 AND gi.unit_cost IS NOT NULL AND gi.unit_cost > 0
  ON CONFLICT (tenant_id, supplier_id, ingredient_id, uom) WHERE source = 'grn_last' AND effective_to IS NULL
  DO UPDATE SET unit_price = EXCLUDED.unit_price, effective_from = EXCLUDED.effective_from,
                source_ref = EXCLUDED.source_ref, created_at = now(), created_by = EXCLUDED.created_by;
  RETURN NEW;
END; $$;


--
-- Name: try_auto_approve_grn(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.try_auto_approve_grn(p_grn_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_eval JSONB; v_grn RECORD; v_confirm_result JSONB;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT id, branch_id, status INTO v_grn FROM public.goods_received_notes WHERE id = p_grn_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'grn not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_permission(v_grn.branch_id, 'procurement:grn_confirm') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF v_grn.status <> 'draft' THEN
    RETURN jsonb_build_object('approved', false, 'reason', 'grn not in draft', 'status', v_grn.status);
  END IF;
  v_eval := public.grn_is_auto_approvable(p_grn_id);
  IF NOT (v_eval->>'approved')::BOOLEAN THEN
    RETURN jsonb_build_object('approved', false, 'evaluation', v_eval, 'status', v_grn.status);
  END IF;
  UPDATE public.goods_received_notes SET express_approved = true WHERE id = p_grn_id;
  v_confirm_result := public.confirm_goods_receipt_note(p_grn_id);
  RETURN jsonb_build_object('approved', true, 'evaluation', v_eval, 'confirm', v_confirm_result);
END; $$;


--
-- Name: update_ingredient_thresholds_bulk(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_ingredient_thresholds_bulk(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id      BIGINT := public.auth_tenant_id();
  v_user_id        UUID   := auth.uid();
  v_count          INTEGER := 0;
  v_request_count  INTEGER := 0;
  v_delta          JSONB := '[]'::jsonb;
  v_row            RECORD;
  v_payload_item   JSONB;
  v_id             BIGINT;
  v_min            NUMERIC(15,3);
  v_max            NUMERIC(15,3);
  v_reorder        NUMERIC(15,3);
  v_before         JSONB;
  v_after          JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'thresholds.bulk: anonymous caller'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'thresholds.bulk: missing tenant_id claim'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF jsonb_typeof(p_payload) <> 'array' THEN
    RAISE EXCEPTION 'thresholds.bulk: payload must be array'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  v_request_count := jsonb_array_length(p_payload);
  IF v_request_count = 0 THEN
    RETURN jsonb_build_object('updated', 0);
  END IF;
  IF v_request_count > 500 THEN
    RAISE EXCEPTION 'thresholds.bulk: max 500 items per call (got %)',
      v_request_count
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  FOR v_payload_item IN
    SELECT * FROM jsonb_array_elements(p_payload)
  LOOP
    v_id := (v_payload_item->>'id')::BIGINT;
    IF v_id IS NULL OR v_id <= 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: invalid id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;

    v_min := NULLIF(v_payload_item->>'min_stock_level', '')::NUMERIC(15,3);
    v_max := NULLIF(v_payload_item->>'max_stock_level', '')::NUMERIC(15,3);
    v_reorder := NULLIF(v_payload_item->>'reorder_point', '')::NUMERIC(15,3);

    IF v_min IS NOT NULL AND v_min < 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: min < 0 for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_max IS NOT NULL AND v_max < 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: max < 0 for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_reorder IS NOT NULL AND v_reorder < 0 THEN
      RAISE EXCEPTION 'thresholds.bulk: reorder < 0 for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_min IS NOT NULL AND v_reorder IS NOT NULL AND v_min > v_reorder THEN
      RAISE EXCEPTION 'thresholds.bulk: min > reorder for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_reorder IS NOT NULL AND v_max IS NOT NULL AND v_reorder > v_max THEN
      RAISE EXCEPTION 'thresholds.bulk: reorder > max for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v_min IS NOT NULL AND v_max IS NOT NULL AND v_min > v_max THEN
      RAISE EXCEPTION 'thresholds.bulk: min > max for id %', v_id
        USING ERRCODE = 'invalid_parameter_value';
    END IF;

    SELECT id, min_stock_level, max_stock_level, reorder_point
      INTO v_row
      FROM public.ingredients
     WHERE id = v_id
       AND tenant_id = v_tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'thresholds.bulk: ingredient % not in tenant scope', v_id
        USING ERRCODE = 'no_data_found';
    END IF;

    v_before := jsonb_build_object(
      'min_stock_level', v_row.min_stock_level,
      'max_stock_level', v_row.max_stock_level,
      'reorder_point',   v_row.reorder_point
    );
    v_after := jsonb_build_object(
      'min_stock_level', COALESCE(v_min, v_row.min_stock_level),
      'max_stock_level', CASE
        WHEN v_payload_item ? 'max_stock_level' THEN v_max
        ELSE v_row.max_stock_level
      END,
      'reorder_point', CASE
        WHEN v_payload_item ? 'reorder_point' THEN v_reorder
        ELSE v_row.reorder_point
      END
    );

    IF v_before = v_after THEN
      CONTINUE;
    END IF;

    UPDATE public.ingredients
       SET min_stock_level = (v_after->>'min_stock_level')::NUMERIC(15,3),
           max_stock_level = NULLIF(v_after->>'max_stock_level', '')::NUMERIC(15,3),
           reorder_point   = NULLIF(v_after->>'reorder_point', '')::NUMERIC(15,3),
           updated_at      = now()
     WHERE id = v_id
       AND tenant_id = v_tenant_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'thresholds.bulk: write blocked for id % (RLS or revoked)', v_id
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    v_count := v_count + 1;
    v_delta := v_delta || jsonb_build_object(
      'id',     v_id,
      'before', v_before,
      'after',  v_after
    );
  END LOOP;

  IF v_count > 0 THEN
    PERFORM public.log_audit(
      'inventory.thresholds.bulk_update',
      'ingredient',
      NULL,
      NULL,
      jsonb_build_object('updated', v_count, 'items', v_delta)
    );
  END IF;

  RETURN jsonb_build_object(
    'updated', v_count,
    'requested', v_request_count
  );
END;
$$;


--
-- Name: FUNCTION update_ingredient_thresholds_bulk(p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_ingredient_thresholds_bulk(p_payload jsonb) IS 'Bulk-update min/max/reorder on ingredients within the callers tenant. Validates min <= reorder <= max per row, skips no-ops, raises on RLS denial, and writes one audit_logs row capturing the full delta. Sprint 2 PP3-A.';


--
-- Name: update_my_dependents_count(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_dependents_count(p_count integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tenant_id BIGINT := public.auth_tenant_id();
  v_user_id   UUID   := auth.uid();
  v_emp_id    BIGINT;
  v_old       INTEGER;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'update_my_dependents_count: missing auth context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_count IS NULL OR p_count < 0 OR p_count > 20 THEN
    RAISE EXCEPTION 'update_my_dependents_count: invalid count'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT id, dependents_count INTO v_emp_id, v_old
  FROM public.employees
  WHERE profile_id = v_user_id
    AND tenant_id = v_tenant_id
    AND is_active = true
  LIMIT 1;

  IF v_emp_id IS NULL THEN
    RAISE EXCEPTION 'update_my_dependents_count: no active employee record'
      USING ERRCODE = 'no_data_found';
  END IF;

  UPDATE public.employees
  SET dependents_count = p_count,
      updated_at = now()
  WHERE id = v_emp_id;

  PERFORM public.log_audit(
    'update'::TEXT,
    'employee'::TEXT,
    v_emp_id,
    jsonb_build_object('dependents_count', v_old),
    jsonb_build_object('dependents_count', p_count, 'self_service', true)
  );
END;
$$;


--
-- Name: FUNCTION update_my_dependents_count(p_count integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_my_dependents_count(p_count integer) IS 'Self-service: employee updates own dependents_count. Affects PIT. SECURITY DEFINER bypasses employees_write RLS; guarded by profile_id = auth.uid() and count in [0, 20].';


--
-- Name: update_my_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_profile(p_full_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.profiles SET
    full_name  = COALESCE(p_full_name, full_name),
    phone      = COALESCE(p_phone, phone),
    avatar_url = COALESCE(p_avatar_url, avatar_url),
    updated_at = now()
  WHERE id = auth.uid();
END;
$$;


--
-- Name: update_pos_order_status(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_pos_order_status(p_order_id bigint, p_new_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_prof_tenant BIGINT;
  v_prof_branch BIGINT;
  v_prof_role TEXT;
  v_order RECORD;
  v_from_status TEXT;
  v_bad_items INT;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF p_new_status NOT IN ('served', 'completed') THEN
    RAISE EXCEPTION 'invalid status' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(p_order_id);

  SELECT id, tenant_id, branch_id, status
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_role IN ('owner') THEN
    NULL;
  ELSIF v_prof_branch IS NOT NULL AND v_order.branch_id <> v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  v_from_status := v_order.status;

  IF p_new_status = 'served' THEN
    IF v_order.status NOT IN ('new', 'confirmed', 'preparing', 'ready') THEN
      RAISE EXCEPTION 'invalid transition to served' USING ERRCODE = '22023';
    END IF;

    -- Same invariant as 'completed': every active item must already be
    -- terminal from the kitchen's perspective. Cashier cannot retire a
    -- ticket the chef is still working on.
    SELECT COUNT(*) INTO v_bad_items
    FROM public.order_items
    WHERE order_id = p_order_id
      AND status NOT IN ('ready', 'served', 'cancelled');

    IF v_bad_items > 0 THEN
      RAISE EXCEPTION 'items not terminal' USING ERRCODE = '22023';
    END IF;

    -- Only flip the rows that still need transitioning. 'served' stays
    -- 'served', 'cancelled' stays 'cancelled' (guard above already proved
    -- nothing is pending/preparing).
    UPDATE public.order_items
    SET status = 'served',
        updated_at = now()
    WHERE order_id = p_order_id
      AND tenant_id = v_order.tenant_id
      AND status = 'ready';

    UPDATE public.kds_tickets
    SET status = 'served',
        bumped_at = COALESCE(bumped_at, now()),
        bumped_by = COALESCE(bumped_by, v_uid),
        updated_at = now()
    WHERE order_id = p_order_id
      AND tenant_id = v_order.tenant_id
      AND status = 'ready';

    UPDATE public.orders
    SET status = 'served', updated_at = now()
    WHERE id = p_order_id;
  ELSIF p_new_status = 'completed' THEN
    IF v_order.status <> 'served' THEN
      RAISE EXCEPTION 'complete requires served' USING ERRCODE = '22023';
    END IF;

    SELECT COUNT(*) INTO v_bad_items
    FROM public.order_items
    WHERE order_id = p_order_id
      AND status NOT IN ('ready', 'served', 'cancelled');

    IF v_bad_items > 0 THEN
      RAISE EXCEPTION 'items not terminal' USING ERRCODE = '22023';
    END IF;

    UPDATE public.orders
    SET status = 'completed', updated_at = now()
    WHERE id = p_order_id;
  END IF;

  INSERT INTO public.order_status_history (
    tenant_id, order_id, from_status, to_status, changed_by, note
  )
  VALUES (
    v_order.tenant_id, p_order_id, v_from_status, p_new_status, v_uid, 'pos update'
  );

  RETURN jsonb_build_object('order_id', p_order_id, 'status', p_new_status);
END;
$$;


--
-- Name: FUNCTION update_pos_order_status(p_order_id bigint, p_new_status text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_pos_order_status(p_order_id bigint, p_new_status text) IS 'POS order status update. Both ''served'' and ''completed'' require every active order_item to already be ready/served/cancelled — cashier cannot retire kitchen tickets that are still pending/preparing. Per-item served stays available via mark_order_item_served.';


--
-- Name: update_tenant_identity(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_tenant_identity(p_legal_name text, p_tax_code text, p_legal_address text, p_representative text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant BIGINT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.has_permission_any('settings:tenant') THEN
    RAISE EXCEPTION 'permission denied: settings:tenant' USING ERRCODE = '42501';
  END IF;

  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  UPDATE public.tenants
  SET legal_name = NULLIF(btrim(p_legal_name), ''),
      tax_code = NULLIF(btrim(p_tax_code), ''),
      legal_address = NULLIF(btrim(p_legal_address), ''),
      representative = NULLIF(btrim(p_representative), ''),
      updated_at = now()
  WHERE id = v_tenant;
END;
$$;


--
-- Name: update_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: upsert_payroll_calculation(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_payroll_calculation(p_period_id bigint, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_period RECORD;
  v_count INTEGER;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501'; END IF;
  IF NOT public.has_permission_any('finance:payroll_calculate') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array' OR jsonb_array_length(p_entries) = 0 THEN
    RAISE EXCEPTION 'invalid_payroll_entries' USING ERRCODE = '22023';
  END IF;

  SELECT pp.id, pp.status INTO v_period
  FROM public.payroll_periods pp
  WHERE pp.id = p_period_id AND pp.tenant_id = v_tenant
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'payroll_period_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_period.status NOT IN ('draft', 'calculated') THEN
    RAISE EXCEPTION 'payroll_locked' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.payroll_entries pe
  WHERE pe.payroll_period_id = p_period_id
    AND pe.tenant_id = v_tenant
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_entries) x
      WHERE (x->>'employee_id')::bigint = pe.employee_id
    );

  INSERT INTO public.payroll_entries (
    tenant_id, payroll_period_id, employee_id,
    working_days, standard_days, overtime_hours, base_salary, allowances,
    tax_exempt_allowances, overtime_pay, bonus, gross_total,
    bhxh_employee, bhyt_employee, bhtn_employee, total_insurance_employee,
    bhxh_employer, bhyt_employer, bhtn_employer, total_insurance_employer,
    personal_deduction, dependent_count, dependent_deduction, charity_deduction,
    taxable_income, pit_tax, advance_deduction, other_deductions, net_salary, insurance_base
  )
  SELECT
    v_tenant, p_period_id, x.employee_id,
    x.working_days, x.standard_days, x.overtime_hours, x.base_salary, x.allowances,
    x.tax_exempt_allowances, x.overtime_pay, x.bonus, x.gross_total,
    x.bhxh_employee, x.bhyt_employee, x.bhtn_employee, x.total_insurance_employee,
    x.bhxh_employer, x.bhyt_employer, x.bhtn_employer, x.total_insurance_employer,
    x.personal_deduction, x.dependent_count, x.dependent_deduction, x.charity_deduction,
    x.taxable_income, x.pit_tax, x.advance_deduction, x.other_deductions, x.net_salary, x.insurance_base
  FROM jsonb_to_recordset(p_entries) AS x(
    employee_id bigint,
    working_days numeric, standard_days numeric, overtime_hours numeric,
    base_salary numeric, allowances numeric, tax_exempt_allowances numeric,
    overtime_pay numeric, bonus numeric, gross_total numeric,
    bhxh_employee numeric, bhyt_employee numeric, bhtn_employee numeric, total_insurance_employee numeric,
    bhxh_employer numeric, bhyt_employer numeric, bhtn_employer numeric, total_insurance_employer numeric,
    personal_deduction numeric, dependent_count integer, dependent_deduction numeric, charity_deduction numeric,
    taxable_income numeric, pit_tax numeric, advance_deduction numeric, other_deductions numeric,
    net_salary numeric, insurance_base numeric
  )
  ON CONFLICT (payroll_period_id, employee_id, tenant_id) DO UPDATE SET
    working_days = EXCLUDED.working_days,
    standard_days = EXCLUDED.standard_days,
    overtime_hours = EXCLUDED.overtime_hours,
    base_salary = EXCLUDED.base_salary,
    allowances = EXCLUDED.allowances,
    tax_exempt_allowances = EXCLUDED.tax_exempt_allowances,
    overtime_pay = EXCLUDED.overtime_pay,
    bonus = EXCLUDED.bonus,
    gross_total = EXCLUDED.gross_total,
    bhxh_employee = EXCLUDED.bhxh_employee,
    bhyt_employee = EXCLUDED.bhyt_employee,
    bhtn_employee = EXCLUDED.bhtn_employee,
    total_insurance_employee = EXCLUDED.total_insurance_employee,
    bhxh_employer = EXCLUDED.bhxh_employer,
    bhyt_employer = EXCLUDED.bhyt_employer,
    bhtn_employer = EXCLUDED.bhtn_employer,
    total_insurance_employer = EXCLUDED.total_insurance_employer,
    personal_deduction = EXCLUDED.personal_deduction,
    dependent_count = EXCLUDED.dependent_count,
    dependent_deduction = EXCLUDED.dependent_deduction,
    charity_deduction = EXCLUDED.charity_deduction,
    taxable_income = EXCLUDED.taxable_income,
    pit_tax = EXCLUDED.pit_tax,
    advance_deduction = EXCLUDED.advance_deduction,
    other_deductions = EXCLUDED.other_deductions,
    net_salary = EXCLUDED.net_salary,
    insurance_base = EXCLUDED.insurance_base,
    updated_at = now();

  GET DIAGNOSTICS v_count = ROW_COUNT;

  UPDATE public.payroll_periods
  SET status = 'calculated'
  WHERE id = p_period_id AND tenant_id = v_tenant;

  RETURN jsonb_build_object('employee_count', v_count, 'status', 'calculated');
END;
$$;


--
-- Name: upsert_printer_with_routes(bigint, bigint, text, text, text, integer, smallint, text, boolean, text[], bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_printer_with_routes(p_printer_id bigint DEFAULT NULL::bigint, p_branch_id bigint DEFAULT NULL::bigint, p_role text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_lan_host text DEFAULT NULL::text, p_lan_port integer DEFAULT NULL::integer, p_paper_width_mm smallint DEFAULT 80, p_code_page text DEFAULT 'CP1258'::text, p_is_active boolean DEFAULT true, p_print_types text[] DEFAULT ARRAY[]::text[], p_category_ids bigint[] DEFAULT ARRAY[]::bigint[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid UUID;
  v_tenant_id BIGINT;
  v_claim_branch_id BIGINT;
  v_existing RECORD;
  v_printer_id BIGINT;
  v_print_type TEXT;
  v_category_id BIGINT;
  v_allowed_print_types TEXT[] := ARRAY[
    'receipt',
    'provisional_bill',
    'shift_close_report',
    'kitchen_ticket',
    'cancel_ticket'
  ];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  v_tenant_id := public.auth_tenant_id();
  v_claim_branch_id := public.auth_branch_id();

  IF p_branch_id IS NULL OR p_role IS NULL OR p_name IS NULL THEN
    RAISE EXCEPTION 'invalid_printer_payload' USING ERRCODE = '22023';
  END IF;

  IF v_claim_branch_id IS NOT NULL AND v_claim_branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(p_branch_id, 'printer:manage') THEN
    RAISE EXCEPTION 'permission denied: printer:manage' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.branches
  WHERE id = p_branch_id
    AND tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_role NOT IN ('receipt', 'kitchen_1', 'kitchen_2') THEN
    RAISE EXCEPTION 'invalid printer role' USING ERRCODE = '22023';
  END IF;

  IF NULLIF(trim(COALESCE(p_lan_host, '')), '') IS NULL THEN
    RAISE EXCEPTION 'lan host required' USING ERRCODE = '22023';
  END IF;

  IF p_paper_width_mm NOT IN (58, 80) THEN
    RAISE EXCEPTION 'invalid paper width' USING ERRCODE = '22023';
  END IF;

  FOREACH v_print_type IN ARRAY COALESCE(p_print_types, ARRAY[]::TEXT[])
  LOOP
    IF NOT v_print_type = ANY(v_allowed_print_types) THEN
      RAISE EXCEPTION 'invalid print type: %', v_print_type USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOREACH v_category_id IN ARRAY COALESCE(p_category_ids, ARRAY[]::BIGINT[])
  LOOP
    PERFORM 1
    FROM public.menu_categories
    WHERE id = v_category_id
      AND tenant_id = v_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'category not found: %', v_category_id USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  IF p_printer_id IS NOT NULL THEN
    SELECT id, branch_id, role
    INTO v_existing
    FROM public.printers
    WHERE id = p_printer_id
      AND tenant_id = v_tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'printer not found' USING ERRCODE = 'P0002';
    END IF;

    IF v_existing.branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'cannot move printer across branches' USING ERRCODE = '22023';
    END IF;

    UPDATE public.printers
       SET role = p_role,
           name = trim(p_name),
           connection_type = 'lan',
           lan_host = trim(p_lan_host),
           lan_port = COALESCE(p_lan_port, 9100),
           paper_width_mm = p_paper_width_mm,
           code_page = COALESCE(NULLIF(trim(p_code_page), ''), 'CP1258'),
           is_active = COALESCE(p_is_active, TRUE)
     WHERE id = p_printer_id
       AND tenant_id = v_tenant_id
     RETURNING id INTO v_printer_id;
  ELSE
    INSERT INTO public.printers (
      tenant_id,
      branch_id,
      role,
      name,
      connection_type,
      lan_host,
      lan_port,
      paper_width_mm,
      code_page,
      is_active
    ) VALUES (
      v_tenant_id,
      p_branch_id,
      p_role,
      trim(p_name),
      'lan',
      trim(p_lan_host),
      COALESCE(p_lan_port, 9100),
      p_paper_width_mm,
      COALESCE(NULLIF(trim(p_code_page), ''), 'CP1258'),
      COALESCE(p_is_active, TRUE)
    )
    RETURNING id INTO v_printer_id;
  END IF;

  DELETE FROM public.printer_print_types ppt
  WHERE ppt.tenant_id = v_tenant_id
    AND ppt.branch_id = p_branch_id
    AND ppt.printer_id <> v_printer_id
    AND ppt.print_type = ANY(COALESCE(p_print_types, ARRAY[]::TEXT[]))
    AND ppt.print_type IN ('receipt', 'provisional_bill', 'shift_close_report');

  DELETE FROM public.printer_print_types
  WHERE tenant_id = v_tenant_id
    AND branch_id = p_branch_id
    AND printer_id = v_printer_id;

  INSERT INTO public.printer_print_types (tenant_id, branch_id, printer_id, print_type)
  SELECT v_tenant_id, p_branch_id, v_printer_id, unnest(COALESCE(p_print_types, ARRAY[]::TEXT[]))
  ON CONFLICT (tenant_id, branch_id, printer_id, print_type) DO NOTHING;

  DELETE FROM public.printer_menu_categories
  WHERE tenant_id = v_tenant_id
    AND branch_id = p_branch_id
    AND printer_id = v_printer_id;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    DELETE FROM public.printer_menu_categories
    WHERE tenant_id = v_tenant_id
      AND branch_id = p_branch_id
      AND category_id = ANY(p_category_ids);

    INSERT INTO public.printer_menu_categories (
      tenant_id,
      branch_id,
      printer_id,
      category_id
    )
    SELECT DISTINCT v_tenant_id, p_branch_id, v_printer_id, x.category_id
    FROM unnest(p_category_ids) AS x(category_id)
    ON CONFLICT (tenant_id, branch_id, category_id) DO UPDATE
      SET printer_id = EXCLUDED.printer_id;
  END IF;

  RETURN v_printer_id;
END;
$$;


--
-- Name: FUNCTION upsert_printer_with_routes(p_printer_id bigint, p_branch_id bigint, p_role text, p_name text, p_lan_host text, p_lan_port integer, p_paper_width_mm smallint, p_code_page text, p_is_active boolean, p_print_types text[], p_category_ids bigint[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_printer_with_routes(p_printer_id bigint, p_branch_id bigint, p_role text, p_name text, p_lan_host text, p_lan_port integer, p_paper_width_mm smallint, p_code_page text, p_is_active boolean, p_print_types text[], p_category_ids bigint[]) IS 'Upsert a branch printer (LAN-only) and its print-type/category routes. Printer role is a slot label only; routing choices are not role-restricted.';


--
-- Name: upsert_production_recipe_lines(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_production_recipe_lines(p_finished_good_id bigint, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid           UUID   := auth.uid();
  v_tenant        BIGINT := public.auth_tenant_id();
  v_kept          BIGINT[] := ARRAY[]::BIGINT[];
  v_line          JSONB;
  v_ingredient_id BIGINT;
  v_quantity      NUMERIC;
  v_yield_factor  NUMERIC;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_inventory_production_operator() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission_any('menu:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.ingredients i
    WHERE i.id = p_finished_good_id AND i.tenant_id = v_tenant
      AND i.item_kind = 'finished_good' AND i.is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'finished_good_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'lines_must_be_array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'lines_must_not_be_empty' USING ERRCODE = '22023';
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    IF (v_line->>'ingredient_id') IS NULL OR (v_line->>'quantity') IS NULL
       OR (v_line->>'unit') IS NULL OR btrim(v_line->>'unit') = '' THEN
      RAISE EXCEPTION 'invalid_line_shape' USING ERRCODE = '22023';
    END IF;

    v_ingredient_id := (v_line->>'ingredient_id')::BIGINT;
    v_quantity := (v_line->>'quantity')::NUMERIC;
    v_yield_factor := COALESCE(NULLIF(v_line->>'yield_factor', '')::NUMERIC, 1.000);

    IF v_quantity <= 0 OR v_yield_factor <= 0 THEN
      RAISE EXCEPTION 'invalid_line_quantity' USING ERRCODE = '22023';
    END IF;

    IF v_ingredient_id = ANY(v_kept) THEN
      RAISE EXCEPTION 'duplicate_ingredient' USING ERRCODE = '23505';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.ingredients i
      WHERE i.id = v_ingredient_id AND i.tenant_id = v_tenant
        AND i.item_kind = 'raw_material' AND i.is_active = TRUE
    ) THEN
      RAISE EXCEPTION 'ingredient_not_found' USING ERRCODE = 'P0002';
    END IF;

    INSERT INTO public.production_recipes (
      tenant_id, finished_good_id, ingredient_id,
      quantity, unit, note, yield_factor
    )
    VALUES (
      v_tenant, p_finished_good_id, v_ingredient_id,
      v_quantity, btrim(v_line->>'unit'),
      NULLIF(v_line->>'note', ''), v_yield_factor
    )
    ON CONFLICT (finished_good_id, ingredient_id, tenant_id)
    DO UPDATE SET
      quantity = EXCLUDED.quantity, unit = EXCLUDED.unit,
      note = EXCLUDED.note, yield_factor = EXCLUDED.yield_factor;

    v_kept := v_kept || v_ingredient_id;
  END LOOP;

  DELETE FROM public.production_recipes pr
  WHERE pr.tenant_id = v_tenant
    AND pr.finished_good_id = p_finished_good_id
    AND NOT (pr.ingredient_id = ANY(v_kept));

  RETURN jsonb_build_object(
    'finished_good_id', p_finished_good_id,
    'kept_count', COALESCE(array_length(v_kept, 1), 0)
  );
END;
$$;


--
-- Name: FUNCTION upsert_production_recipe_lines(p_finished_good_id bigint, p_lines jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_production_recipe_lines(p_finished_good_id bigint, p_lines jsonb) IS 'Atomically replaces production BOM lines for one finished good.';


--
-- Name: upsert_recipe_lines(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_recipe_lines(p_menu_item_id bigint, p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid    UUID   := auth.uid();
  v_tenant BIGINT := public.auth_tenant_id();
  v_kept   BIGINT[] := ARRAY[]::BIGINT[];
  v_line   JSONB;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000'; END IF;
  IF NOT public.has_permission_any('menu:write') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.menu_items mi WHERE mi.id = p_menu_item_id AND mi.tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'menu_item_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF jsonb_typeof(p_lines) <> 'array' THEN RAISE EXCEPTION 'lines_must_be_array' USING ERRCODE = '22023'; END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    IF (v_line->>'ingredient_id') IS NULL OR (v_line->>'quantity') IS NULL OR (v_line->>'unit') IS NULL THEN
      RAISE EXCEPTION 'invalid_line_shape' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.recipes (tenant_id, menu_item_id, ingredient_id, quantity, unit, note, yield_factor)
    VALUES (v_tenant, p_menu_item_id, (v_line->>'ingredient_id')::BIGINT,
            (v_line->>'quantity')::NUMERIC, v_line->>'unit',
            NULLIF(v_line->>'note',''), COALESCE((v_line->>'yield_factor')::NUMERIC, 1.000))
    ON CONFLICT (menu_item_id, ingredient_id, tenant_id)
    DO UPDATE SET quantity = EXCLUDED.quantity, unit = EXCLUDED.unit,
                  note = EXCLUDED.note, yield_factor = EXCLUDED.yield_factor;
    v_kept := v_kept || (v_line->>'ingredient_id')::BIGINT;
  END LOOP;

  DELETE FROM public.recipes r
  WHERE r.tenant_id = v_tenant AND r.menu_item_id = p_menu_item_id
    AND NOT (r.ingredient_id = ANY(v_kept));

  RETURN jsonb_build_object('menu_item_id', p_menu_item_id, 'kept_count', COALESCE(array_length(v_kept, 1), 0));
END;
$$;


--
-- Name: FUNCTION upsert_recipe_lines(p_menu_item_id bigint, p_lines jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_recipe_lines(p_menu_item_id bigint, p_lines jsonb) IS 'Atomically replace the recipe lines of a menu item (finished product). Inserts/updates provided lines and deletes removed ones.';


--
-- Name: upsert_shift_checklist_template(bigint, bigint, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_shift_checklist_template(p_tenant_id bigint, p_branch_id bigint, p_template_id bigint, p_name text, p_items jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_template_id bigint;
  v_items jsonb := COALESCE(p_items, '[]'::jsonb);
  v_item jsonb;
  v_title text;
  v_phase text;
  v_done_definition text;
  v_is_required boolean;
  v_scope text;
  v_task_kind text;
  v_sort integer := 0;
  v_name text := btrim(COALESCE(p_name, ''));
BEGIN
  IF v_name = '' THEN
    RAISE EXCEPTION 'template_name_required' USING ERRCODE = '23514';
  END IF;

  IF char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'template_name_too_long' USING ERRCODE = '23514';
  END IF;

  IF p_branch_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.branches b
    WHERE b.id = p_branch_id
      AND b.tenant_id = p_tenant_id
      AND COALESCE(b.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF jsonb_typeof(v_items) <> 'array' THEN
    RAISE EXCEPTION 'checklist_items_invalid' USING ERRCODE = '23514';
  END IF;

  IF jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'checklist_empty' USING ERRCODE = '23514';
  END IF;

  IF jsonb_array_length(v_items) > 40 THEN
    RAISE EXCEPTION 'checklist_too_many_items' USING ERRCODE = '23514';
  END IF;

  IF p_template_id IS NULL THEN
    INSERT INTO public.shift_checklist_templates (
      tenant_id,
      branch_id,
      role_code,
      name,
      is_active
    )
    VALUES (
      p_tenant_id,
      p_branch_id,
      NULL,
      v_name,
      true
    )
    RETURNING id INTO v_template_id;
  ELSE
    SELECT id
    INTO v_template_id
    FROM public.shift_checklist_templates
    WHERE id = p_template_id
      AND tenant_id = p_tenant_id
      AND branch_id IS NOT DISTINCT FROM p_branch_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'template_not_found' USING ERRCODE = 'P0002';
    END IF;

    UPDATE public.shift_checklist_templates
    SET
      name = v_name,
      is_active = true
    WHERE id = v_template_id;
  END IF;

  DELETE FROM public.shift_checklist_template_items
  WHERE tenant_id = p_tenant_id
    AND template_id = v_template_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_title := btrim(COALESCE(v_item ->> 'title', ''));
    v_phase := COALESCE(NULLIF(v_item ->> 'phase', ''), 'during_shift');
    v_done_definition := btrim(
      COALESCE(
        v_item ->> 'doneDefinition',
        v_item ->> 'done_definition',
        ''
      )
    );
    v_is_required := COALESCE(
      NULLIF(v_item ->> 'isRequired', '')::boolean,
      NULLIF(v_item ->> 'is_required', '')::boolean,
      true
    );
    v_scope := COALESCE(NULLIF(v_item ->> 'scope', ''), 'every_shift');
    v_task_kind := COALESCE(NULLIF(v_item ->> 'taskKind', ''), 'standard');

    IF v_title = '' THEN
      CONTINUE;
    END IF;

    IF char_length(v_title) > 120 THEN
      RAISE EXCEPTION 'checklist_item_too_long' USING ERRCODE = '23514';
    END IF;

    IF v_phase <> ALL (ARRAY['start_of_shift', 'during_shift', 'end_of_shift']::text[]) THEN
      RAISE EXCEPTION 'checklist_phase_invalid' USING ERRCODE = '23514';
    END IF;

    IF v_scope <> ALL (ARRAY['every_shift', 'opening', 'closing', 'weekly']::text[]) THEN
      RAISE EXCEPTION 'checklist_scope_invalid' USING ERRCODE = '23514';
    END IF;

    IF v_task_kind <> ALL (ARRAY['standard', 'consumption_report']::text[]) THEN
      RAISE EXCEPTION 'checklist_task_kind_invalid' USING ERRCODE = '23514';
    END IF;

    IF char_length(v_done_definition) > 240 THEN
      RAISE EXCEPTION 'done_definition_too_long' USING ERRCODE = '23514';
    END IF;

    v_sort := v_sort + 1;

    INSERT INTO public.shift_checklist_template_items (
      tenant_id,
      template_id,
      title,
      phase,
      done_definition,
      is_required,
      scope,
      task_kind,
      sort_order,
      is_active
    )
    VALUES (
      p_tenant_id,
      v_template_id,
      v_title,
      v_phase,
      v_done_definition,
      v_is_required,
      v_scope,
      v_task_kind,
      v_sort,
      true
    );
  END LOOP;

  IF v_sort = 0 THEN
    RAISE EXCEPTION 'checklist_empty' USING ERRCODE = '23514';
  END IF;

  RETURN v_template_id;
END;
$$;


--
-- Name: FUNCTION upsert_shift_checklist_template(p_tenant_id bigint, p_branch_id bigint, p_template_id bigint, p_name text, p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_shift_checklist_template(p_tenant_id bigint, p_branch_id bigint, p_template_id bigint, p_name text, p_items jsonb) IS 'Service-role-only atomic checklist template save. Payload includes item title, phase, done definition, and required flag.';


--
-- Name: upsert_station_with_categories(bigint, bigint, text, integer, boolean, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_station_with_categories(p_station_id bigint DEFAULT NULL::bigint, p_branch_id bigint DEFAULT NULL::bigint, p_name text DEFAULT NULL::text, p_position integer DEFAULT 0, p_is_active boolean DEFAULT true, p_category_ids bigint[] DEFAULT ARRAY[]::bigint[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             uuid    := auth.uid();
  v_tenant_id       bigint  := public.auth_tenant_id();
  v_claim_branch_id bigint  := public.auth_branch_id();
  v_existing        RECORD;
  v_station_id      bigint;
  v_category_id     bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_branch_id IS NULL OR NULLIF(btrim(COALESCE(p_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_station_payload' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_position, 0) < 0 THEN
    RAISE EXCEPTION 'invalid_station_payload' USING ERRCODE = '22023';
  END IF;

  IF v_claim_branch_id IS NOT NULL AND v_claim_branch_id <> p_branch_id THEN
    RAISE EXCEPTION 'branch_mismatch' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_permission(p_branch_id, 'settings:branch') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM public.branches WHERE id = p_branch_id AND tenant_id = v_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'branch_not_found' USING ERRCODE = 'P0002';
  END IF;

  FOREACH v_category_id IN ARRAY COALESCE(p_category_ids, ARRAY[]::bigint[])
  LOOP
    PERFORM 1 FROM public.menu_categories
     WHERE id = v_category_id AND tenant_id = v_tenant_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'category_not_found' USING ERRCODE = 'P0002';
    END IF;
  END LOOP;

  IF p_station_id IS NOT NULL THEN
    SELECT id, branch_id INTO v_existing
      FROM public.kds_stations
     WHERE id = p_station_id AND tenant_id = v_tenant_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'station_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_existing.branch_id <> p_branch_id THEN
      RAISE EXCEPTION 'cannot_move_station_across_branches' USING ERRCODE = '22023';
    END IF;

    UPDATE public.kds_stations
       SET name = btrim(p_name),
           position = COALESCE(p_position, 0),
           is_active = COALESCE(p_is_active, TRUE),
           updated_at = now()
     WHERE id = p_station_id AND tenant_id = v_tenant_id
     RETURNING id INTO v_station_id;
  ELSE
    INSERT INTO public.kds_stations (tenant_id, branch_id, name, position, is_active)
    VALUES (v_tenant_id, p_branch_id, btrim(p_name), COALESCE(p_position, 0), COALESCE(p_is_active, TRUE))
    RETURNING id INTO v_station_id;
  END IF;

  DELETE FROM public.kds_station_categories
   WHERE station_id = v_station_id AND tenant_id = v_tenant_id;

  IF COALESCE(array_length(p_category_ids, 1), 0) > 0 THEN
    INSERT INTO public.kds_station_categories (tenant_id, station_id, category_id)
    SELECT DISTINCT v_tenant_id, v_station_id, x.category_id
      FROM unnest(p_category_ids) AS x(category_id)
     WHERE x.category_id IS NOT NULL
    ON CONFLICT (station_id, category_id, tenant_id) DO NOTHING;
  END IF;

  RETURN v_station_id;
END;
$$;


--
-- Name: verify_branch_override_code(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_branch_override_code(p_branch_id bigint, p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_hash TEXT; v_recent_fail INT; v_ok BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000'; END IF;
  SELECT COUNT(*) INTO v_recent_fail FROM public.branch_override_attempts
   WHERE branch_id = p_branch_id AND user_id = v_uid AND success = false
     AND attempted_at > now() - INTERVAL '1 minute';
  IF v_recent_fail >= 3 THEN RAISE EXCEPTION 'override verify rate-limited' USING ERRCODE = '54000'; END IF;
  SELECT code_hash INTO v_hash FROM public.branch_override_codes WHERE branch_id = p_branch_id;
  v_ok := v_hash IS NOT NULL AND extensions.crypt(p_code, v_hash) = v_hash;
  INSERT INTO public.branch_override_attempts (branch_id, user_id, success) VALUES (p_branch_id, v_uid, v_ok);
  RETURN v_ok;
END;
$$;


--
-- Name: void_order_item(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_order_item(p_order_item_id bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid             UUID;
  v_prof_tenant     BIGINT;
  v_prof_branch     BIGINT;
  v_prof_role       TEXT;
  v_item            RECORD;
  v_order           RECORD;
  v_subtotal        NUMERIC(15,2);
  v_discount_amount NUMERIC(15,2);
  v_all_cancelled   BOOLEAN;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  SELECT p.tenant_id, p.branch_id, COALESCE(private.staff_role_from_position_code(po.code), 'office')
  INTO v_prof_tenant, v_prof_branch, v_prof_role
  FROM public.profiles p
  LEFT JOIN public.positions po ON po.id = p.position_id
  WHERE p.id = v_uid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = '28000';
  END IF;

  IF v_prof_role IS NULL OR v_prof_role NOT IN ('branch_manager', 'cashier', 'waiter') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 1 THEN
    RAISE EXCEPTION 'reason required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'item not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(v_item.order_id);

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_order.tenant_id <> v_prof_tenant THEN
    RAISE EXCEPTION 'tenant mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_prof_branch IS NULL OR v_order.branch_id IS DISTINCT FROM v_prof_branch THEN
    RAISE EXCEPTION 'branch mismatch' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_permission(v_order.branch_id, 'pos:void_order') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_item.status IN ('served', 'cancelled') THEN
    RAISE EXCEPTION 'item not voidable' USING ERRCODE = '22023';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'order terminal' USING ERRCODE = '22023';
  END IF;

  UPDATE public.order_items
  SET status = 'cancelled',
      cancel_reason = p_reason,
      updated_at = now()
  WHERE id = p_order_item_id;

  UPDATE public.kds_tickets
  SET status = 'cancelled', updated_at = now()
  WHERE order_item_id = p_order_item_id AND tenant_id = v_item.tenant_id;

  SELECT COALESCE(SUM(subtotal), 0) INTO v_subtotal
  FROM public.order_items
  WHERE order_id = v_item.order_id AND status <> 'cancelled';

  SELECT NOT EXISTS (
    SELECT 1 FROM public.order_items WHERE order_id = v_item.order_id AND status <> 'cancelled'
  ) INTO v_all_cancelled;

  IF v_all_cancelled THEN
    UPDATE public.orders
    SET
      status          = 'cancelled',
      subtotal        = 0,
      discount_type   = NULL,
      discount_value  = NULL,
      discount_note   = NULL,
      discount_amount = 0,
      total_amount    = 0 + COALESCE(service_charge, 0),
      updated_at      = now()
    WHERE id = v_item.order_id;

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_item.tenant_id, v_item.order_id, v_order.status, 'cancelled', v_uid,
      'auto_cancel_all_items_voided: ' || p_reason
    );
  ELSE
    v_discount_amount := public.compute_discount_amount(
      v_order.discount_type, v_order.discount_value, v_subtotal
    );

    UPDATE public.orders o
    SET
      subtotal        = v_subtotal,
      discount_type   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_type END,
      discount_value  = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_value END,
      discount_note   = CASE WHEN v_discount_amount = 0 THEN NULL ELSE o.discount_note END,
      discount_amount = v_discount_amount,
      total_amount    = v_subtotal + COALESCE(o.service_charge, 0) - v_discount_amount,
      updated_at      = now()
    WHERE o.id = v_item.order_id;

    INSERT INTO public.order_status_history (
      tenant_id, order_id, from_status, to_status, changed_by, note
    )
    VALUES (
      v_item.tenant_id, v_item.order_id, v_order.status, v_order.status, v_uid,
      'void_item ' || p_order_item_id::text || ': ' || p_reason
    );
  END IF;

  RETURN jsonb_build_object(
    'order_id', v_item.order_id,
    'auto_cancelled_order', v_all_cancelled,
    'was_sent_to_kitchen', v_item.sent_to_kitchen_at IS NOT NULL
  );
END;
$$;


--
-- Name: weekly_grn_override_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_grn_override_report() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row RECORD; v_count INT := 0;
BEGIN
  FOR v_row IN
    SELECT ho.tenant_id, ho.branch_id, COUNT(*) AS override_count,
           COUNT(DISTINCT ho.overridden_by) AS distinct_users,
           SUM(ho.submitted_price - COALESCE(ho.baseline_avg_30d, 0)) AS total_markup_vnd
    FROM public.grn_hardblock_overrides ho
    WHERE ho.overridden_at > now() - INTERVAL '7 days'
    GROUP BY ho.tenant_id, ho.branch_id HAVING COUNT(*) >= 1
  LOOP
    INSERT INTO public.notifications (tenant_id, target_branch_id, target_roles, kind, severity, title, body, meta, dedup_key)
    VALUES (v_row.tenant_id, v_row.branch_id, ARRAY['owner','quan_ly_vung']::TEXT[],
            'inventory.grn.weekly_override_report',
            CASE WHEN v_row.override_count >= 5 THEN 'warning' ELSE 'info' END,
            'GRN hardblock override — weekly report',
            format('Branch has %s hardblock overrides by %s user(s) in past 7 days. Total markup: %s VND',
                   v_row.override_count, v_row.distinct_users, v_row.total_markup_vnd),
            jsonb_build_object('override_count', v_row.override_count, 'distinct_users', v_row.distinct_users, 'total_markup_vnd', v_row.total_markup_vnd),
            format('grn_override_report:%s:%s', v_row.branch_id, to_char(now(), 'IYYY-IW')));
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END; $$;


--
-- Name: weekly_waste_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_waste_report() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row RECORD; v_count INT := 0;
BEGIN
  FOR v_row IN
    SELECT si.tenant_id, si.branch_id, COUNT(*) AS waste_count,
      COUNT(*) FILTER (WHERE si.approval_status = 'pending')  AS pending_count,
      COUNT(*) FILTER (WHERE si.approval_status = 'approved') AS approved_count,
      COUNT(*) FILTER (WHERE si.approval_status = 'rejected') AS rejected_count,
      COALESCE(SUM(sii.total_cost), 0) AS total_value
    FROM public.stock_issues si JOIN public.stock_issue_items sii ON sii.issue_id = si.id
    WHERE si.issue_type = 'writeoff' AND si.issued_at > now() - INTERVAL '7 days'
    GROUP BY si.tenant_id, si.branch_id
  LOOP
    INSERT INTO public.notifications (tenant_id, target_branch_id, target_roles, kind, severity, title, body, meta, dedup_key)
    VALUES (v_row.tenant_id, v_row.branch_id, ARRAY['owner','quan_ly_vung','quan_ly_CN']::TEXT[],
      'inventory.waste.weekly_report',
      CASE WHEN v_row.pending_count >= 5 THEN 'warning' ELSE 'info' END,
      'Báo cáo waste — tuần vừa qua',
      format('Chi nhánh có %s phiếu waste tuần qua (pending: %s, approved: %s, rejected: %s). Tổng giá trị: %s VND',
             v_row.waste_count, v_row.pending_count, v_row.approved_count, v_row.rejected_count, v_row.total_value),
      jsonb_build_object('waste_count', v_row.waste_count, 'pending_count', v_row.pending_count,
        'approved_count', v_row.approved_count, 'rejected_count', v_row.rejected_count, 'total_value', v_row.total_value),
      format('waste_report:%s:%s', v_row.branch_id, to_char(now(), 'IYYY-IW')));
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END; $$;


